local function quote_console_string(value)
  return "\"" .. tostring(value or ""):gsub("\\", "\\\\"):gsub("\"", "\\\"") .. "\""
end

local function quote_console_token(value)
  local text = tostring(value or "")
  if text:match("^[A-Za-z0-9_%-]+$") then
    return text
  end
  return quote_console_string(text)
end

local function normalize_world_name(value)
  local name = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
  name = name:gsub("%.brdb$", "")
  if name == "" then
    return nil, "world name is required"
  end
  if name:match("[/\\]") or name:match("%.%.") then
    return nil, "world name must not contain path separators"
  end
  return name
end

local function finite_number(value, default)
  local number = tonumber(value)
  if number == nil or number ~= number or number == math.huge or number == -math.huge then
    return default
  end
  return number
end

local function format_number(value)
  local number = finite_number(value, 0)
  if math.floor(number) == number then
    return tostring(math.floor(number))
  end
  return string.format("%.6f", number)
end

local function normalize_integer(value, label)
  local number = tonumber(value)
  if number == nil or number ~= number or number == math.huge or number == -math.huge then
    return nil, label .. " must be a number"
  end
  number = math.floor(number)
  if number < 0 then
    return nil, label .. " must be zero or greater"
  end
  return number
end

local function trim_string(value)
  local text = tostring(value or ""):gsub("^\239\187\191", "")
  return (text:gsub("^%s+", ""):gsub("%s+$", ""))
end

function BMF_env_string(name)
  if type(os.getenv) ~= "function" then
    return ""
  end
  return trim_string(os.getenv(name) or "")
end

function BMF_env_bool(name, default_value)
  local value = BMF_env_string(name)
  if value == "" then
    return default_value == true
  end
  local normalized = value:lower()
  if normalized == "0" or normalized == "false" or normalized == "no" or normalized == "off" then
    return false
  end
  if normalized == "1" or normalized == "true" or normalized == "yes" or normalized == "on" then
    return true
  end
  return default_value == true
end

function BMF_env_number(name, default_value, minimum)
  local value = tonumber(BMF_env_string(name))
  if value == nil or value ~= value or value == math.huge or value == -math.huge then
    value = tonumber(default_value) or 0
  end
  if minimum ~= nil and value < minimum then
    value = minimum
  end
  return math.floor(value + 0.5)
end

function BMF_operation_attribution_configure_from_env()
  local attribution = state.operation_attribution
  local telemetry = state.telemetry.operations
  attribution.enabled = BMF_env_bool("BMF_OPERATION_ATTRIBUTION_ENABLED", true)
  telemetry.enabled = attribution.enabled == true
  telemetry.game_thread_slow_ms = math.max(1, math.min(1000, BMF_env_number(
    "BMF_OPERATION_SLOW_GAME_THREAD_MS",
    OPERATION_ATTRIBUTION_DEFAULT_GAME_THREAD_SLOW_MS,
    1)))
  telemetry.total_slow_ms = math.max(1, math.min(10000, BMF_env_number(
    "BMF_OPERATION_SLOW_TOTAL_MS",
    OPERATION_ATTRIBUTION_DEFAULT_TOTAL_SLOW_MS,
    1)))
end

function BMF_operation_class(value, fallback)
  local normalized = trim_string(tostring(value or "")):lower()
  normalized = normalized:gsub("^/", "")
  normalized = normalized:gsub("[^%w%._%-]", "_")
  normalized = normalized:gsub("_+", "_")
  normalized = normalized:sub(1, 96)
  if normalized == "" then
    normalized = tostring(fallback or "unknown")
  end
  if normalized == "cityrpgremote" then
    return "cityrpg.remote"
  end
  if normalized == "cityrpgroute" then
    return "cityrpg.route"
  end
  return normalized
end

function BMF_operation_class_from_text(text, fallback)
  local token = trim_string(tostring(text or "")):match("^(%S+)")
  return BMF_operation_class(token, fallback)
end

function BMF_join_correlation_phase(correlation_value, phase_value, started_clock, outcome_value, detail)
  local correlation_id = trim_string(tostring(correlation_value or ""))
  local phase = trim_string(tostring(phase_value or "")):lower()
  local outcome = trim_string(tostring(outcome_value or "ok")):lower()
  local allowed_phases = {
    bmf_snapshot_ingestion = true,
    bmf_readiness_transition = true,
  }
  local telemetry = state.telemetry.join_correlation
  if correlation_id == "" then
    return false
  end
  if not correlation_id:match("^join%-%w[%w%-]*$")
      or #correlation_id > 96
      or allowed_phases[phase] ~= true
      or (outcome ~= "ok" and outcome ~= "error" and outcome ~= "dropped") then
    telemetry.invalid = (tonumber(telemetry.invalid) or 0) + 1
    return false
  end
  local duration_ms = math.max(0, (os.clock() - (tonumber(started_clock) or os.clock())) * 1000)
  local frame = BMF_operation_frame_snapshot()
  local ended_at_ms = type(frame) == "table" and tonumber(frame.observed_at_unix_ms) or (os.time() * 1000)
  local started_at_ms = math.max(0, ended_at_ms - duration_ms)
  local item = telemetry.phases[phase]
  if type(item) ~= "table" then
    item = { count = 0, duration_ms_sum = 0, duration_ms_max = 0, duration_ms_last = 0 }
    telemetry.phases[phase] = item
  end
  item.count = (tonumber(item.count) or 0) + 1
  item.duration_ms_sum = (tonumber(item.duration_ms_sum) or 0) + duration_ms
  item.duration_ms_max = math.max(tonumber(item.duration_ms_max) or 0, duration_ms)
  item.duration_ms_last = duration_ms
  telemetry.total = (tonumber(telemetry.total) or 0) + 1
  telemetry.last = {
    correlationId = correlation_id,
    phase = phase,
    outcome = outcome,
    startedAtUnixMs = started_at_ms,
    endedAtUnixMs = ended_at_ms,
    durationMs = duration_ms,
    detail = type(detail) == "table" and detail or nil,
  }
  if type(BMF_socket_send_event_record) == "function" then
    local event = {
      ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
      level = outcome == "ok" and "info" or "warn",
      source = "join_correlation",
      message = "BMF_JOIN_PHASE",
      data = telemetry.last,
    }
    BMF_socket_send_event_record(event, json_encode(event))
  end
  return true
end

function BMF_operation_begin(operation_class, source, request)
  if state.operation_attribution.enabled ~= true then
    return nil
  end
  request = type(request) == "table" and request or {}
  local next_id = tonumber(state.operation_attribution.next_id) or 1
  state.operation_attribution.next_id = next_id + 1
  local accepted_clock = tonumber(request.acceptedClock) or os.clock()
  local accepted_at_ms = tonumber(request.acceptedAtMs) or (os.time() * 1000)
  local request_id = trim_string(tostring(request.operationRequestId or request.requestId or request.id or ""))
  if #request_id > 128 then request_id = request_id:sub(1, 128) end
  local sender_uuid = trim_string(tostring(request.senderUuid or request.senderUUID or "")):lower()
  if #sender_uuid > 128 then sender_uuid = sender_uuid:sub(1, 128) end
  local connection_generation = tonumber(request.connectionGeneration) or 0
  if connection_generation < 1 or connection_generation % 1 ~= 0 then
    connection_generation = 0
  end
  local context = {
    correlation_id = "bmf-" .. tostring(state.started_epoch or 0) .. "-" .. tostring(next_id),
    request_id = request_id,
    operation_class = BMF_operation_class(operation_class, "unknown"),
    source = BMF_operation_class(source, "unknown"),
    sender_uuid = sender_uuid,
    connection_generation = connection_generation,
    priority = request.serviceClass == "bulk" and "bulk" or "interactive",
    current_stage = "accepted",
    issued_at_ms = tonumber(request.issuedAtMs) or accepted_at_ms,
    accepted_at_ms = accepted_at_ms,
    accepted_clock = accepted_clock,
    deadline_ms = tonumber(request.deadlineMs) or 0,
    queue_wait_ms = 0,
    admission_defer_ms = 0,
    admission_defer_count = 0,
    game_thread_ms = 0,
    off_thread_ms = math.max(0, tonumber(request.offThreadMs) or 0),
    total_ms = 0,
    deadline_state = "accepted",
    cache_result = "none",
    controller_resolution_count = 0,
    global_scan_count = 0,
    global_scan_duration_ms = 0,
    repair_count = 0,
    repair_duration_ms = 0,
    lifetime_guard_rejections = 0,
    start_timestamp_ms = 0,
    finish_timestamp_ms = 0,
    frame_sample_near_completion = 0,
    frame_observed_at_ms = 0,
    frame_duration_ms_near_completion = 0,
    outcome = "accepted",
    budget_exceeded = false,
    finished = false,
  }
  local telemetry = state.telemetry.operations
  telemetry.active = (tonumber(telemetry.active) or 0) + 1
  telemetry.active_peak = math.max(tonumber(telemetry.active_peak) or 0, telemetry.active)
  return context
end

function BMF_operation_update_class(context, operation_class)
  if type(context) == "table" and context.finished ~= true then
    context.operation_class = BMF_operation_class(operation_class, context.operation_class)
  end
end

function BMF_operation_update_stage(context, stage)
  if type(context) == "table" and context.finished ~= true then
    context.current_stage = BMF_operation_class(stage, context.current_stage or "unknown")
  end
end

function BMF_operation_note_private_identity(request_id, sender_uuid, connection_generation)
  local context = state.operation_attribution.current
  if type(context) ~= "table" or context.finished == true then
    return
  end
  local normalized_request_id = trim_string(tostring(request_id or ""))
  local normalized_uuid = trim_string(tostring(sender_uuid or "")):lower()
  local normalized_generation = tonumber(connection_generation) or 0
  if normalized_request_id ~= "" and #normalized_request_id <= 128 then
    context.request_id = normalized_request_id
  end
  if normalized_uuid ~= "" and #normalized_uuid <= 128 then
    context.sender_uuid = normalized_uuid
  end
  if normalized_generation >= 1 and normalized_generation % 1 == 0 then
    context.connection_generation = normalized_generation
  end
  BMF_operation_update_stage(context, "private_identity_validated")
end

function BMF_operation_frame_snapshot()
  if type(BMFFrameTelemetryOperationSnapshot) ~= "function" then
    return nil
  end
  local ok, raw = pcall(BMFFrameTelemetryOperationSnapshot)
  if not ok or type(raw) ~= "string" then
    return nil
  end
  local decoded = json_decode(raw)
  if type(decoded) ~= "table" then
    return nil
  end
  return {
    sample = math.max(0, tonumber(decoded.sample) or 0),
    observed_at_unix_ms = math.max(0, tonumber(decoded.observed_at_unix_ms) or 0),
    delta_ms = math.max(0, tonumber(decoded.delta_ms) or 0),
  }
end

function BMF_operation_start_execution(context)
  if type(context) ~= "table" or context.finished == true then
    return
  end
  local now_clock = os.clock()
  context.execution_started_clock = now_clock
  context.queue_wait_ms = math.max(0, (now_clock - (tonumber(context.accepted_clock) or now_clock)) * 1000)
  if tonumber(context.defer_started_clock) ~= nil then
    context.admission_defer_ms = math.max(
      tonumber(context.admission_defer_ms) or 0,
      (now_clock - tonumber(context.defer_started_clock)) * 1000)
  end
  context.start_timestamp_ms = (tonumber(context.accepted_at_ms) or (os.time() * 1000))
    + context.queue_wait_ms
  context.deadline_state = "started"
  context.current_stage = "game_thread"
  if state.operation_attribution.current ~= context then
    context.previous_context = state.operation_attribution.current
  end
  state.operation_attribution.current = context
end

function BMF_operation_note_budget_defer(context)
  if type(context) ~= "table" or context.finished == true then
    return
  end
  context.admission_defer_count = (tonumber(context.admission_defer_count) or 0) + 1
  if tonumber(context.defer_started_clock) == nil then
    context.defer_started_clock = os.clock()
  end
end

function BMF_operation_current_deadline_expired()
  local context = state.operation_attribution.current
  if type(context) ~= "table" or (tonumber(context.deadline_ms) or 0) <= 0 then
    return false
  end
  if type(BMF_socket_scheduler_deadline_expired) == "function" then
    return BMF_socket_scheduler_deadline_expired(
      context.deadline_ms,
      context.issued_at_ms,
      context.accepted_clock)
  end
  return (os.time() * 1000) >= (tonumber(context.deadline_ms) or 0)
end

function BMF_operation_note_queued_budget_defer()
  if state.operation_attribution.enabled ~= true then
    return
  end
  local admission = state.socket_admission or {}
  local tunnel = state.game_command_tunnel or {}
  for _, request in ipairs({
    admission.direct_queues and admission.direct_queues.interactive and admission.direct_queues.interactive[1],
    admission.direct_queues and admission.direct_queues.bulk and admission.direct_queues.bulk[1],
    tunnel.queues and tunnel.queues.interactive and tunnel.queues.interactive[1],
    tunnel.queues and tunnel.queues.bulk and tunnel.queues.bulk[1],
  }) do
    if type(request) == "table" then
      BMF_operation_note_budget_defer(request.operationContext)
    end
  end
end

function BMF_operation_note_cache_result(cache_result)
  local context = state.operation_attribution.current
  if type(context) == "table" and context.finished ~= true then
    context.cache_result = BMF_operation_class(cache_result, "none")
  end
end

function BMF_operation_note_controller_resolution(ok)
  local context = state.operation_attribution.current
  if type(context) == "table" and context.finished ~= true then
    context.controller_resolution_count = (tonumber(context.controller_resolution_count) or 0) + 1
    if ok == false and context.cache_result == "none" then
      context.cache_result = "miss"
    elseif ok ~= false and context.cache_result == "none" then
      context.cache_result = "hit"
    end
  end
end

function BMF_operation_note_global_scan(duration_ms)
  local context = state.operation_attribution.current
  if type(context) == "table" and context.finished ~= true then
    local duration = math.max(0, tonumber(duration_ms) or 0)
    context.global_scan_count = (tonumber(context.global_scan_count) or 0) + 1
    context.global_scan_duration_ms = (tonumber(context.global_scan_duration_ms) or 0) + duration
    context.cache_result = "repair"
  end
end

function BMF_operation_find_all(class_name, operation_class, source)
  local owned_context = nil
  if state.operation_attribution.enabled == true
      and type(state.operation_attribution.current) ~= "table" then
    owned_context = BMF_operation_begin(
      operation_class or "uobject.global_scan",
      source or "diagnostic_scan",
      { serviceClass = "bulk" })
    BMF_operation_start_execution(owned_context)
  end
  local scan_started_clock = os.clock()
  local ok, found = pcall(FindAllOf, class_name)
  local duration_ms = BMF_telemetry_duration_ms(scan_started_clock)
  BMF_operation_note_global_scan(duration_ms)
  if owned_context ~= nil then
    BMF_operation_finish(owned_context, ok and "completed" or "known_failure")
  end
  return ok, found, duration_ms
end

function BMF_operation_note_repair(duration_ms)
  local context = state.operation_attribution.current
  if type(context) == "table" and context.finished ~= true then
    local duration = math.max(0, tonumber(duration_ms) or 0)
    context.repair_count = (tonumber(context.repair_count) or 0) + 1
    context.repair_duration_ms = (tonumber(context.repair_duration_ms) or 0) + duration
    context.cache_result = "repair"
  end
end

function BMF_operation_note_lifetime_guard_rejection()
  local telemetry = state.telemetry.operations
  telemetry.lifetime_guard_rejections_total =
    (tonumber(telemetry.lifetime_guard_rejections_total) or 0) + 1
  local context = state.operation_attribution.current
  if type(context) == "table" and context.finished ~= true then
    context.lifetime_guard_rejections = (tonumber(context.lifetime_guard_rejections) or 0) + 1
  end
end

function BMF_operation_series(map, key, fields, bounded_class)
  local telemetry = state.telemetry.operations
  local normalized = BMF_operation_class(key, "unknown")
  if bounded_class == true and type(map[normalized]) ~= "table" then
    if (tonumber(telemetry.class_count) or 0) >= OPERATION_ATTRIBUTION_MAX_CLASSES then
      telemetry.classes_dropped = (tonumber(telemetry.classes_dropped) or 0) + 1
      normalized = "other"
    else
      telemetry.class_count = (tonumber(telemetry.class_count) or 0) + 1
    end
  end
  return BMF_telemetry_series(map, normalized, fields)
end

function BMF_operation_observe_series(item, context)
  if type(item) ~= "table" or type(context) ~= "table" then
    return
  end
  BMF_telemetry_observe(item, context.game_thread_ms, context.outcome == "completed")
  BMF_telemetry_add(item, "queue_wait_ms_sum", context.queue_wait_ms)
  item.queue_wait_ms_max = math.max(tonumber(item.queue_wait_ms_max) or 0, tonumber(context.queue_wait_ms) or 0)
  BMF_telemetry_add(item, "admission_defer_ms_sum", context.admission_defer_ms)
  item.admission_defer_ms_max = math.max(
    tonumber(item.admission_defer_ms_max) or 0,
    tonumber(context.admission_defer_ms) or 0)
  BMF_telemetry_add(item, "admission_defer_count", context.admission_defer_count)
  BMF_telemetry_add(item, "game_thread_ms_sum", context.game_thread_ms)
  item.game_thread_ms_max = math.max(tonumber(item.game_thread_ms_max) or 0, tonumber(context.game_thread_ms) or 0)
  BMF_telemetry_add(item, "off_thread_ms_sum", context.off_thread_ms)
  item.off_thread_ms_max = math.max(tonumber(item.off_thread_ms_max) or 0, tonumber(context.off_thread_ms) or 0)
  BMF_telemetry_add(item, "total_ms_sum", context.total_ms)
  item.total_ms_max = math.max(tonumber(item.total_ms_max) or 0, tonumber(context.total_ms) or 0)
  BMF_telemetry_add(item, "controller_resolutions", context.controller_resolution_count)
  BMF_telemetry_add(item, "global_scans", context.global_scan_count)
  BMF_telemetry_add(item, "global_scan_duration_ms_sum", context.global_scan_duration_ms)
  item.global_scan_duration_ms_max = math.max(
    tonumber(item.global_scan_duration_ms_max) or 0,
    tonumber(context.global_scan_duration_ms) or 0)
  BMF_telemetry_add(item, "repairs", context.repair_count)
  if context.budget_exceeded == true then
    BMF_telemetry_add(item, "budget_overruns", 1)
  end
end

function BMF_operation_finish(context, outcome)
  if type(context) ~= "table" or context.finished == true then
    return context
  end
  local now_clock = os.clock()
  local accepted_clock = tonumber(context.accepted_clock) or now_clock
  local execution_clock = tonumber(context.execution_started_clock)
  context.game_thread_ms = execution_clock and math.max(0, (now_clock - execution_clock) * 1000) or 0
  context.total_ms = math.max(0, (now_clock - accepted_clock) * 1000)
  context.finish_timestamp_ms = (tonumber(context.accepted_at_ms) or (os.time() * 1000)) + context.total_ms
  context.outcome = BMF_operation_class(outcome, "known_failure")
  if context.outcome == "injected" then
    context.outcome = "completed"
  elseif context.outcome == "failed" then
    context.outcome = "known_failure"
  end
  local deadline_elapsed = false
  if (tonumber(context.deadline_ms) or 0) > 0
      and type(BMF_socket_scheduler_deadline_expired) == "function" then
    deadline_elapsed = BMF_socket_scheduler_deadline_expired(
      context.deadline_ms,
      context.issued_at_ms,
      context.accepted_clock)
  end
  if context.outcome == "expired" then
    context.deadline_state = "expired_before_execution"
  elseif deadline_elapsed then
    context.deadline_state = "elapsed_after_execution"
  elseif (tonumber(context.deadline_ms) or 0) > 0 then
    context.deadline_state = "within_deadline"
  else
    context.deadline_state = "not_set"
  end
  context.current_stage = "finished"
  local frame = BMF_operation_frame_snapshot()
  if type(frame) == "table" then
    context.frame_sample_near_completion = frame.sample
    context.frame_observed_at_ms = frame.observed_at_unix_ms
    context.frame_duration_ms_near_completion = frame.delta_ms
  end
  context.budget_exceeded = context.game_thread_ms > (tonumber(state.telemetry.socket_scheduler.budget_ms) or 3)
  context.finished = true
  local previous_context = context.previous_context
  context.previous_context = nil
  context.accepted_clock = nil
  context.execution_started_clock = nil
  context.defer_started_clock = nil

  local telemetry = state.telemetry.operations
  telemetry.active = math.max(0, (tonumber(telemetry.active) or 0) - 1)
  telemetry.total = (tonumber(telemetry.total) or 0) + 1
  telemetry.admission_defer_total = (tonumber(telemetry.admission_defer_total) or 0)
    + (tonumber(context.admission_defer_count) or 0)
  telemetry.controller_resolutions_total = (tonumber(telemetry.controller_resolutions_total) or 0)
    + (tonumber(context.controller_resolution_count) or 0)
  telemetry.global_scan_total = (tonumber(telemetry.global_scan_total) or 0)
    + (tonumber(context.global_scan_count) or 0)
  telemetry.global_scan_duration_ms_sum = (tonumber(telemetry.global_scan_duration_ms_sum) or 0)
    + (tonumber(context.global_scan_duration_ms) or 0)
  telemetry.global_scan_duration_ms_max = math.max(
    tonumber(telemetry.global_scan_duration_ms_max) or 0,
    tonumber(context.global_scan_duration_ms) or 0)
  telemetry.repair_total = (tonumber(telemetry.repair_total) or 0) + (tonumber(context.repair_count) or 0)
  telemetry.repair_duration_ms_sum = (tonumber(telemetry.repair_duration_ms_sum) or 0)
    + (tonumber(context.repair_duration_ms) or 0)
  telemetry.repair_duration_ms_max = math.max(
    tonumber(telemetry.repair_duration_ms_max) or 0,
    tonumber(context.repair_duration_ms) or 0)
  if context.budget_exceeded == true then
    telemetry.budget_overrun_total = (tonumber(telemetry.budget_overrun_total) or 0) + 1
  end
  if context.outcome == "expired" then
    telemetry.deadline_expired_total = (tonumber(telemetry.deadline_expired_total) or 0) + 1
  end

  local class_item = BMF_operation_series(telemetry.by_class, context.operation_class, {
    operation_class = context.operation_class,
  }, true)
  local source_item = BMF_operation_series(telemetry.by_source, context.source, {
    source = context.source,
  }, false)
  BMF_operation_observe_series(class_item, context)
  BMF_operation_observe_series(source_item, context)
  local outcome_item = BMF_operation_series(telemetry.by_outcome, context.outcome, {
    outcome = context.outcome,
  }, false)
  outcome_item.count = (tonumber(outcome_item.count) or 0) + 1
  local cache_item = BMF_operation_series(telemetry.by_cache_result, context.cache_result, {
    cache_result = context.cache_result,
  }, false)
  cache_item.count = (tonumber(cache_item.count) or 0) + 1

  local slow = context.game_thread_ms > (tonumber(telemetry.game_thread_slow_ms) or 3)
    or context.total_ms > (tonumber(telemetry.total_slow_ms) or 10)
    or (tonumber(context.frame_duration_ms_near_completion) or 0) >= 33.3
    or (tonumber(context.global_scan_count) or 0) > 0
    or (tonumber(context.repair_count) or 0) > 0
    or (tonumber(context.lifetime_guard_rejections) or 0) > 0
  if slow then
    telemetry.slow_total = (tonumber(telemetry.slow_total) or 0) + 1
    local slow_record = {
      correlation_id = context.correlation_id,
      request_id = context.request_id,
      operation_class = context.operation_class,
      source = context.source,
      sender_uuid = context.sender_uuid,
      connection_generation = context.connection_generation,
      current_stage = context.current_stage,
      queue_wait_ms = context.queue_wait_ms,
      admission_defer_ms = context.admission_defer_ms,
      admission_defer_count = context.admission_defer_count,
      game_thread_ms = context.game_thread_ms,
      off_thread_ms = context.off_thread_ms,
      total_ms = context.total_ms,
      deadline_state = context.deadline_state,
      priority = context.priority,
      cache_result = context.cache_result,
      controller_resolution_count = context.controller_resolution_count,
      global_scan_count = context.global_scan_count,
      global_scan_duration_ms = context.global_scan_duration_ms,
      repair_count = context.repair_count,
      repair_duration_ms = context.repair_duration_ms,
      lifetime_guard_rejections = context.lifetime_guard_rejections,
      start_timestamp_ms = context.start_timestamp_ms,
      finish_timestamp_ms = context.finish_timestamp_ms,
      frame_sample_near_completion = context.frame_sample_near_completion,
      frame_observed_at_ms = context.frame_observed_at_ms,
      frame_duration_ms_near_completion = context.frame_duration_ms_near_completion,
      outcome = context.outcome,
      budget_exceeded = context.budget_exceeded,
    }
    local slow_event = {
      ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
      level = "warn",
      source = "operation",
      message = "BMF_SLOW_OPERATION",
      data = slow_record,
    }
    if type(BMF_socket_send_event_record) == "function" then
      BMF_socket_send_event_record(slow_event, json_encode(slow_event))
    end
  end
  -- copy_table is declared later in this file, so calling it here resolves to
  -- a nil global in Lua. Keep the last-operation snapshot explicit.
  telemetry.last = {
    correlation_id = context.correlation_id,
    operation_class = context.operation_class,
    source = context.source,
    current_stage = context.current_stage,
    queue_wait_ms = context.queue_wait_ms,
    admission_defer_ms = context.admission_defer_ms,
    admission_defer_count = context.admission_defer_count,
    game_thread_ms = context.game_thread_ms,
    off_thread_ms = context.off_thread_ms,
    total_ms = context.total_ms,
    deadline_state = context.deadline_state,
    priority = context.priority,
    cache_result = context.cache_result,
    controller_resolution_count = context.controller_resolution_count,
    global_scan_count = context.global_scan_count,
    global_scan_duration_ms = context.global_scan_duration_ms,
    repair_count = context.repair_count,
    repair_duration_ms = context.repair_duration_ms,
    lifetime_guard_rejections = context.lifetime_guard_rejections,
    start_timestamp_ms = context.start_timestamp_ms,
    finish_timestamp_ms = context.finish_timestamp_ms,
    frame_sample_near_completion = context.frame_sample_near_completion,
    frame_observed_at_ms = context.frame_observed_at_ms,
    frame_duration_ms_near_completion = context.frame_duration_ms_near_completion,
    outcome = context.outcome,
    budget_exceeded = context.budget_exceeded,
  }
  if state.operation_attribution.current == context then
    state.operation_attribution.current = previous_context
  end
  return context
end

local function join_path(base, child)
  local left = tostring(base or ""):gsub("\\", "/"):gsub("/+$", "")
  local right = tostring(child or ""):gsub("\\", "/"):gsub("^/+", "")
  if left == "" then
    return right
  end
  if right == "" then
    return left
  end
  return left .. "/" .. right
end

local function first_string(...)
  for index = 1, select("#", ...) do
    local value = select(index, ...)
    if type(value) == "string" and trim_string(value) ~= "" then
      return value
    end
  end
  return nil
end

local function is_uuid(value)
  if type(value) ~= "string" then
    return false
  end
  return value:match("^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$") ~= nil
end

local function copy_table(value)
  if type(value) ~= "table" then
    return value
  end
  local out = {}
  for key, child in pairs(value) do
    out[key] = copy_table(child)
  end
  return out
end

local function table_count(values)
  local count = 0
  if type(values) == "table" then
    for _ in pairs(values) do
      count = count + 1
    end
  end
  return count
end

function BMF_socket_env(name)
  return BMF_env_string(name)
end

function BMF_socket_enabled_from_env()
  local explicit = BMF_socket_env("OMEGGA_BMF_SOCKET_ENABLED")
  if explicit == "0" or explicit:lower() == "false" then
    return false
  end
  return explicit == "1" or explicit:lower() == "true" or BMF_socket_env("OMEGGA_BMF_SOCKET_PORT") ~= ""
end

function BMF_socket_native_available()
  return type(BMFSocketStart) == "function"
    and type(BMFSocketSend) == "function"
    and type(BMFSocketReceive) == "function"
end

function BMF_socket_poll_age_ms()
  local epoch = tonumber(state.socket.last_poll_epoch or 0) or 0
  if epoch <= 0 then
    epoch = tonumber(state.socket.last_started_epoch or 0) or 0
  end
  if epoch <= 0 then
    return 0
  end
  return math.max(0, (os.time() - epoch) * 1000)
end

function BMF_socket_watchdog_enabled()
  return BMF_env_bool("BMF_SOCKET_WORKER_WATCHDOG", true)
end

function BMF_socket_watchdog_interval_ms()
  return math.max(1000, math.min(60000, BMF_env_number(
    "BMF_SOCKET_WORKER_WATCHDOG_MS",
    BMF_env_number("BMF_SOCKET_WATCHDOG_MS", 5000, 1000),
    1000)))
end

function BMF_socket_watchdog_stale_ms()
  local poll_interval = tonumber(state.socket.poll_interval_ms) or SOCKET_DEFAULT_POLL_MS
  local default_stale = math.max(5000, poll_interval * 25)
  return math.max(1000, math.min(120000, BMF_env_number(
    "BMF_SOCKET_WORKER_STALE_MS",
    BMF_env_number("BMF_SOCKET_WATCHDOG_STALE_MS", default_stale, 1000),
    1000)))
end

function BMF_socket_watchdog_delayed_after_restarts()
  return math.max(1, math.min(20, BMF_env_number(
    "BMF_SOCKET_WORKER_DELAYED_AFTER_RESTARTS",
    2,
    1)))
end

local function BMF_socket_write_metadata()
  if type(BMF_socket_scheduler_refresh_queue_telemetry) == "function" then
    BMF_socket_scheduler_refresh_queue_telemetry()
  end
  local tunnel = state.game_command_tunnel
  local tunnel_ready = tunnel.enabled == true
    and tunnel.worker_started == true
    and state.socket_worker_started == true
    and state.socket_worker_mode == "EngineTickOneShotChain"
  state.socket.metadata_last_write_epoch = os.time()
  write_file(RUNTIME_DIR .. "/socket.json", json_encode({
    provenance = BMF_runtime_provenance("bmf.lua.socket_metadata"),
    enabled = state.socket.enabled,
    available = state.socket.available,
    started = state.socket.started,
    host = state.socket.host,
    port = state.socket.port,
    token = state.socket.token,
    pollIntervalMs = state.socket.poll_interval_ms,
    currentPollIntervalMs = state.telemetry.socket_scheduler.current_poll_interval_ms,
    pollTier = state.telemetry.socket_scheduler.poll_tier,
    pollPassesTotal = state.telemetry.socket_scheduler.poll_passes_total,
    idlePassesTotal = state.telemetry.socket_scheduler.idle_passes_total,
    activePassesTotal = state.telemetry.socket_scheduler.active_passes_total,
    backoffTransitionsTotal = state.telemetry.socket_scheduler.backoff_transitions_total,
    workWakeupsTotal = state.telemetry.socket_scheduler.work_wakeups_total,
    configuredIngressPerPump = state.telemetry.socket_scheduler.configured_ingress_per_pump,
    effectiveIngressPerPump = state.telemetry.socket_scheduler.effective_ingress_per_pump,
    directIngressCapEnabled = state.telemetry.socket_scheduler.direct_ingress_cap_enabled,
    directIngressCapPerPump = state.telemetry.socket_scheduler.direct_ingress_cap_per_pump,
    pumpBudgetMs = state.telemetry.socket_scheduler.budget_ms,
    pumpBudgetEnforced = state.telemetry.socket_scheduler.budget_enforced,
    pumpBudgetAdmissionStopped = state.telemetry.socket_scheduler.budget_admission_stopped_total,
    pumpBudgetAdmissionStoppedLast = state.telemetry.socket_scheduler.budget_admission_stopped_last,
    pumpBudgetTunnelDispatchSkipped = state.telemetry.socket_scheduler.budget_tunnel_dispatch_skipped_total,
    pumpBudgetTunnelDispatchSkippedLast = state.telemetry.socket_scheduler.budget_tunnel_dispatch_skipped_last,
    tunnelEnabled = tunnel_ready,
    protocols = tunnel_ready and { "bmf-tunnel/1" } or {},
    tunnelProtocolVersion = tunnel.protocol_version,
    tunnelChannel = tunnel.channel,
    maxPendingTunnelRequests = tunnel.max_queue,
    maxTunnelLineBytes = tunnel.max_line_bytes,
    tunnelCompletedRetention = tunnel.completed_retention,
    directCompletedRetention = state.socket_admission.completed_retention,
    directCompletedMaxBytes = state.socket_admission.completed_max_bytes,
    directCompletedRetainedBytes = state.socket_admission.completed_retained_bytes,
    directCompletedEvicted = state.socket_admission.completed_evicted,
    tunnelCompletedMaxBytes = tunnel.completed_max_bytes,
    tunnelCompletedRetainedBytes = tunnel.completed_retained_bytes,
    tunnelCompletedEvicted = tunnel.completed_evicted,
    tunnelWorkerStarted = tunnel.worker_started,
    tunnelWorkerMode = tunnel.worker_mode,
    tunnelWorkerTicks = tunnel.worker_ticks,
    tunnelWorkerIdleTicks = tunnel.worker_idle_ticks,
    tunnelWorkerErrors = tunnel.worker_errors,
    tunnelLastWorkerTickAt = tunnel.last_worker_tick_at,
    tunnelLastWorkerError = tunnel.last_worker_error,
    metadataHeartbeatIntervalSeconds = state.socket.metadata_heartbeat_interval_seconds,
    workerStarted = state.socket_worker_started,
    workerMode = state.socket_worker_mode,
    workerGeneration = state.socket_worker_generation,
    workerWatchdogStarted = state.socket_worker_watchdog_started,
    workerWatchdogMode = state.socket_worker_watchdog_mode,
    sentEvents = state.socket.sent_events,
    sentResponses = state.socket.sent_responses,
    receivedCommands = state.socket.received_commands,
    receivedMessages = state.socket.received_messages,
    pollCount = state.socket.poll_count,
    lastPollAt = state.socket.last_poll_at,
    lastPollAgeMs = BMF_socket_poll_age_ms(),
    lastDrainCount = state.socket.last_drain_count,
    lastDirectAdmitted = state.telemetry.socket_scheduler.direct_admitted_last,
    tunnelQueueOldestAgeMs = state.telemetry.socket_scheduler.queues.tunnel_oldest_age_ms,
    lastError = state.socket.last_error,
    lastStatus = state.socket.last_status,
    lastStartedAt = state.socket.last_started_at,
    watchdogIntervalMs = state.socket.watchdog_interval_ms,
    watchdogStaleMs = state.socket.watchdog_stale_ms,
    watchdogChecks = state.socket.watchdog_checks,
    watchdogRestarts = state.socket.watchdog_restarts,
    watchdogConsecutiveStale = state.socket.watchdog_consecutive_stale,
    watchdogForcedDelayedRecoveries = state.socket.watchdog_forced_delayed_recoveries,
    lastWatchdogAt = state.socket.last_watchdog_at,
    lastWatchdogRestartAt = state.socket.last_watchdog_restart_at,
    lastWatchdogError = state.socket.last_watchdog_error,
    updatedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
  }))
end

local function BMF_socket_metadata_heartbeat(force)
  local interval = tonumber(state.socket.metadata_heartbeat_interval_seconds) or BMF_STATUS_HEARTBEAT_DEFAULT_SECONDS
  local last_write_epoch = tonumber(state.socket.metadata_last_write_epoch or 0) or 0
  local now_epoch = os.time()
  if not force and last_write_epoch > 0 and (now_epoch - last_write_epoch) < interval then
    return false
  end

  BMF_socket_write_metadata()
  if type(BMF_telemetry_write) == "function" then
    BMF_telemetry_write(false)
  end
  if type(write_status) == "function" then
    write_status()
  end
  return true
end

function BMF_command_output_configure_from_env()
  local output = state.telemetry.command_output
  output.max_lines = math.max(8, math.min(2048, BMF_env_number(
    "BMF_COMMAND_OUTPUT_MAX_LINES",
    COMMAND_OUTPUT_DEFAULT_MAX_LINES,
    8)))
  output.max_bytes = math.max(1024, math.min(262144, BMF_env_number(
    "BMF_COMMAND_OUTPUT_MAX_BYTES",
    COMMAND_OUTPUT_DEFAULT_MAX_BYTES,
    1024)))
end

function BMF_game_command_tunnel_configure_from_env()
  local tunnel = state.game_command_tunnel
  tunnel.enabled = BMF_env_bool("BMF_GAME_COMMAND_TUNNEL_ENABLED", true)
  tunnel.interval_ms = math.max(10, math.min(1000, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_INTERVAL_MS",
    GAME_COMMAND_TUNNEL_DEFAULT_INTERVAL_MS,
    10)))
  tunnel.max_queue = math.max(1, math.min(512, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_MAX_QUEUE",
    GAME_COMMAND_TUNNEL_DEFAULT_MAX_QUEUE,
    1)))
  tunnel.max_interactive_queue = math.max(1, math.min(tunnel.max_queue, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_MAX_INTERACTIVE_QUEUE",
    GAME_COMMAND_TUNNEL_DEFAULT_MAX_INTERACTIVE_QUEUE,
    1)))
  tunnel.max_bulk_queue = math.max(1, math.min(tunnel.max_queue, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_MAX_BULK_QUEUE",
    GAME_COMMAND_TUNNEL_DEFAULT_MAX_BULK_QUEUE,
    1)))
  tunnel.max_bytes = math.max(1024, math.min(1048576, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_MAX_BYTES",
    GAME_COMMAND_TUNNEL_DEFAULT_MAX_BYTES,
    1024)))
  tunnel.max_line_bytes = math.max(64, math.min(tunnel.max_bytes, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_MAX_LINE_BYTES",
    GAME_COMMAND_TUNNEL_DEFAULT_MAX_LINE_BYTES,
    64)))
  tunnel.interactive_burst = math.max(1, math.min(64, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_INTERACTIVE_BURST",
    GAME_COMMAND_TUNNEL_DEFAULT_INTERACTIVE_BURST,
    1)))
  tunnel.readiness_retry_base_ms = math.max(100, math.min(5000, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_READINESS_RETRY_BASE_MS",
    GAME_COMMAND_TUNNEL_DEFAULT_READINESS_RETRY_BASE_MS,
    100)))
  tunnel.readiness_retry_max_ms = math.max(
    tunnel.readiness_retry_base_ms,
    math.min(30000, BMF_env_number(
      "BMF_GAME_COMMAND_TUNNEL_READINESS_RETRY_MAX_MS",
      GAME_COMMAND_TUNNEL_DEFAULT_READINESS_RETRY_MAX_MS,
      tunnel.readiness_retry_base_ms)))
  tunnel.completed_retention = math.max(64, math.min(8192, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_COMPLETED_RETENTION",
    GAME_COMMAND_TUNNEL_COMPLETED_RETENTION,
    64)))
  tunnel.completed_max_bytes = math.max(65536, math.min(16777216, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_COMPLETED_MAX_BYTES",
    GAME_COMMAND_TUNNEL_COMPLETED_DEFAULT_MAX_BYTES,
    65536)))
end

function BMF_socket_configure_from_env()
  local socket_scheduler = state.telemetry.socket_scheduler
  local admission = state.socket_admission
  BMF_command_output_configure_from_env()
  BMF_operation_attribution_configure_from_env()
  state.socket.enabled = BMF_socket_enabled_from_env()
  state.socket.available = BMF_socket_native_available()
  state.socket.host = BMF_socket_env("OMEGGA_BMF_SOCKET_HOST")
  if state.socket.host == "" then
    state.socket.host = "127.0.0.1"
  end
  state.socket.port = tonumber(BMF_socket_env("OMEGGA_BMF_SOCKET_PORT")) or 0
  state.socket.token = BMF_socket_env("OMEGGA_BMF_SOCKET_TOKEN")
  state.socket.poll_interval_ms = math.max(5, tonumber(BMF_socket_env("OMEGGA_BMF_SOCKET_POLL_MS")) or SOCKET_DEFAULT_POLL_MS)
  socket_scheduler.current_poll_interval_ms = 25
  socket_scheduler.poll_tier = "active"
  socket_scheduler.consecutive_empty_passes = 0
  socket_scheduler.recent_work_passes_remaining = 4
  socket_scheduler.budget_ms = math.max(1, math.min(1000, BMF_env_number(
    "BMF_GAME_THREAD_PUMP_BUDGET_MS",
    3,
    1)))
  socket_scheduler.budget_enforced = BMF_env_bool(
    "BMF_GAME_THREAD_PUMP_BUDGET_ENFORCED",
    true)
  socket_scheduler.native_drains.budget_enabled = BMF_env_bool(
    "BMF_SOCKET_NATIVE_DRAIN_BUDGET_ENABLED",
    true)
  admission.enabled = BMF_env_bool(
    "BMF_UNIFIED_SOCKET_ADMISSION_ENABLED",
    true)
  socket_scheduler.unified_enabled = admission.enabled == true
  admission.max_queue = math.max(1, math.min(512, BMF_env_number(
    "BMF_UNIFIED_SOCKET_MAX_QUEUE",
    SOCKET_ADMISSION_DEFAULTS.max_queue,
    1)))
  admission.max_bytes = math.max(1024, math.min(1048576, BMF_env_number(
    "BMF_UNIFIED_SOCKET_MAX_BYTES",
    SOCKET_ADMISSION_DEFAULTS.max_bytes,
    1024)))
  admission.max_direct_queue = math.max(1, math.min(admission.max_queue, BMF_env_number(
    "BMF_UNIFIED_SOCKET_MAX_DIRECT_QUEUE",
    SOCKET_ADMISSION_DEFAULTS.max_direct_queue,
    1)))
  admission.max_direct_interactive_queue = math.max(1, math.min(admission.max_direct_queue, BMF_env_number(
    "BMF_UNIFIED_SOCKET_MAX_DIRECT_INTERACTIVE_QUEUE",
    SOCKET_ADMISSION_DEFAULTS.max_direct_interactive_queue,
    1)))
  admission.max_direct_bulk_queue = math.max(1, math.min(admission.max_direct_queue, BMF_env_number(
    "BMF_UNIFIED_SOCKET_MAX_DIRECT_BULK_QUEUE",
    SOCKET_ADMISSION_DEFAULTS.max_direct_bulk_queue,
    1)))
  admission.max_command_bytes = math.max(64, math.min(admission.max_bytes, BMF_env_number(
    "BMF_UNIFIED_SOCKET_MAX_COMMAND_BYTES",
    SOCKET_ADMISSION_DEFAULTS.max_command_bytes,
    64)))
  admission.default_deadline_ms = math.max(100, math.min(300000, BMF_env_number(
    "BMF_UNIFIED_SOCKET_DEFAULT_DEADLINE_MS",
    SOCKET_ADMISSION_DEFAULTS.default_deadline_ms,
    100)))
  admission.completed_retention = math.max(16, math.min(4096, BMF_env_number(
    "BMF_UNIFIED_SOCKET_COMPLETED_RETENTION",
    SOCKET_ADMISSION_DEFAULTS.completed_retention,
    16)))
  admission.completed_max_bytes = math.max(65536, math.min(16777216, BMF_env_number(
    "BMF_UNIFIED_SOCKET_COMPLETED_MAX_BYTES",
    SOCKET_ADMISSION_DEFAULTS.completed_max_bytes,
    65536)))
  socket_scheduler.configured_ingress_per_pump = math.max(1, math.min(16, BMF_env_number(
    "BMF_GAME_COMMAND_TUNNEL_INGRESS_PER_TICK",
    16,
    1)))
  socket_scheduler.direct_ingress_cap_enabled = BMF_env_bool(
    "BMF_DIRECT_SOCKET_INGRESS_CAP_ENABLED",
    true)
  socket_scheduler.direct_ingress_cap_per_pump = math.max(1, math.min(16, BMF_env_number(
    "BMF_DIRECT_SOCKET_INGRESS_PER_PUMP",
    2,
    1)))
  socket_scheduler.effective_ingress_per_pump = socket_scheduler.configured_ingress_per_pump
  if socket_scheduler.direct_ingress_cap_enabled then
    socket_scheduler.effective_ingress_per_pump = math.min(
      socket_scheduler.effective_ingress_per_pump,
      socket_scheduler.direct_ingress_cap_per_pump)
  end
  state.socket.watchdog_interval_ms = BMF_socket_watchdog_interval_ms()
  state.socket.watchdog_stale_ms = BMF_socket_watchdog_stale_ms()
  if type(BMF_status_heartbeat_interval_seconds) == "function" then
    state.socket.metadata_heartbeat_interval_seconds = BMF_status_heartbeat_interval_seconds()
  end
  BMF_game_command_tunnel_configure_from_env()
  BMF_socket_write_metadata()
end

function BMF_socket_send_json(record)
  if not state.socket.started or type(BMFSocketSend) ~= "function" then
    return false
  end
  local ok, sent_or_error = pcall(BMFSocketSend, json_encode(record or {}))
  if ok and sent_or_error ~= false then
    return true
  end
  state.socket.last_error = tostring(sent_or_error or "BMFSocketSend failed")
  return false
end

function BMF_socket_send_event_record(event, encoded)
  if not state.socket.started then
    return false
  end
  local sent = BMF_socket_send_json({
    type = "event",
    source = "bmf",
    ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    record = event,
    record_json = encoded,
  })
  if sent then
    state.socket.sent_events = state.socket.sent_events + 1
  end
  return sent
end

function BMF_socket_status_snapshot()
  local native_status = ""
  if type(BMFSocketStatus) == "function" then
    local ok, value = pcall(BMFSocketStatus)
    native_status = ok and tostring(value or "") or ("status error: " .. tostring(value))
  end
  return {
    enabled = state.socket.enabled,
    available = state.socket.available,
    started = state.socket.started,
    host = state.socket.host,
    port = state.socket.port,
    pollIntervalMs = state.socket.poll_interval_ms,
    currentPollIntervalMs = state.telemetry.socket_scheduler.current_poll_interval_ms,
    pollTier = state.telemetry.socket_scheduler.poll_tier,
    pollPassesTotal = state.telemetry.socket_scheduler.poll_passes_total,
    idlePassesTotal = state.telemetry.socket_scheduler.idle_passes_total,
    activePassesTotal = state.telemetry.socket_scheduler.active_passes_total,
    backoffTransitionsTotal = state.telemetry.socket_scheduler.backoff_transitions_total,
    workWakeupsTotal = state.telemetry.socket_scheduler.work_wakeups_total,
    configuredIngressPerPump = state.telemetry.socket_scheduler.configured_ingress_per_pump,
    effectiveIngressPerPump = state.telemetry.socket_scheduler.effective_ingress_per_pump,
    directIngressCapEnabled = state.telemetry.socket_scheduler.direct_ingress_cap_enabled,
    directIngressCapPerPump = state.telemetry.socket_scheduler.direct_ingress_cap_per_pump,
    pumpBudgetMs = state.telemetry.socket_scheduler.budget_ms,
    pumpBudgetEnforced = state.telemetry.socket_scheduler.budget_enforced,
    pumpBudgetAdmissionStopped = state.telemetry.socket_scheduler.budget_admission_stopped_total,
    pumpBudgetAdmissionStoppedLast = state.telemetry.socket_scheduler.budget_admission_stopped_last,
    pumpBudgetTunnelDispatchSkipped = state.telemetry.socket_scheduler.budget_tunnel_dispatch_skipped_total,
    pumpBudgetTunnelDispatchSkippedLast = state.telemetry.socket_scheduler.budget_tunnel_dispatch_skipped_last,
    sentEvents = state.socket.sent_events,
    sentResponses = state.socket.sent_responses,
    receivedCommands = state.socket.received_commands,
    receivedMessages = state.socket.received_messages,
    pollCount = state.socket.poll_count,
    lastPollAt = state.socket.last_poll_at,
    lastPollAgeMs = BMF_socket_poll_age_ms(),
    lastDrainCount = state.socket.last_drain_count,
    lastDirectAdmitted = state.telemetry.socket_scheduler.direct_admitted_last,
    tunnelQueueOldestAgeMs = state.telemetry.socket_scheduler.queues.tunnel_oldest_age_ms,
    workerStarted = state.socket_worker_started,
    workerMode = state.socket_worker_mode,
    workerGeneration = state.socket_worker_generation,
    workerWatchdogStarted = state.socket_worker_watchdog_started,
    workerWatchdogMode = state.socket_worker_watchdog_mode,
    lastError = state.socket.last_error,
    lastStatus = state.socket.last_status,
    lastStartedAt = state.socket.last_started_at,
    watchdogIntervalMs = state.socket.watchdog_interval_ms,
    watchdogStaleMs = state.socket.watchdog_stale_ms,
    watchdogChecks = state.socket.watchdog_checks,
    watchdogRestarts = state.socket.watchdog_restarts,
    watchdogConsecutiveStale = state.socket.watchdog_consecutive_stale,
    watchdogForcedDelayedRecoveries = state.socket.watchdog_forced_delayed_recoveries,
    lastWatchdogAt = state.socket.last_watchdog_at,
    lastWatchdogRestartAt = state.socket.last_watchdog_restart_at,
    lastWatchdogError = state.socket.last_watchdog_error,
    nativeStatus = native_status,
  }
end

local function permission_state_to_bool(value)
  if type(value) == "boolean" then
    return value
  end
  if type(value) == "string" then
    local lower = value:lower()
    if lower == "allowed" or lower == "allow" or lower == "true" then
      return true
    end
    if lower == "forbidden" or lower == "deny" or lower == "denied" or lower == "false" then
      return false
    end
  end
  return nil
end

local function exec_console(command)
  if type(OmeggaExecuteKismetConsoleCommand) == "function" then
    local ok, success, output = pcall(OmeggaExecuteKismetConsoleCommand, command)
    if ok and success then
      return result(true, "OK", "Command executed", { executor = "kismet", output = output or "" })
    end
    return result(false, "CONSOLE_EXEC_FAILED", tostring(output or success), { executor = "kismet" })
  end

  if type(OmeggaExecuteCachedConsoleExec) == "function" then
    local ok, success, output = pcall(OmeggaExecuteCachedConsoleExec, command)
    if ok and success then
      return result(true, "OK", "Command executed", { executor = "cached_console", output = output or "" })
    end
    return result(false, "CONSOLE_EXEC_FAILED", tostring(output or success), { executor = "cached_console" })
  end

  return result(false, "CONSOLE_EXEC_UNAVAILABLE", "No supported console executor is available.")
end

local function exec_console_manager(command)
  if type(OmeggaExecuteConsoleManagerInput) == "function" then
    local ok, success, output = pcall(OmeggaExecuteConsoleManagerInput, command)
    if ok and success then
      return result(true, "OK", "Command executed", { executor = "console_manager", output = output or "" })
    end
    return result(false, "CONSOLE_EXEC_FAILED", tostring(output or success), { executor = "console_manager" })
  end

  return exec_console(command)
end

local function BMF_scheduler_retained_callback_count()
  return (tonumber(state.game_thread_callback_count) or 0)
    + (tonumber(state.delayed_callback_count) or 0)
    + (tonumber(state.game_thread_loop_count) or 0)
end

local function BMF_scheduler_update_retained_callbacks()
  local retained = BMF_scheduler_retained_callback_count()
  state.telemetry.scheduler.retained_callbacks = retained
  state.telemetry.scheduler.retained_callbacks_peak = math.max(
    tonumber(state.telemetry.scheduler.retained_callbacks_peak) or 0,
    retained)
  state.telemetry.scheduler.active_loops = tonumber(state.game_thread_loop_count) or 0
  state.telemetry.scheduler.active_loops_peak = math.max(
    tonumber(state.telemetry.scheduler.active_loops_peak) or 0,
    state.telemetry.scheduler.active_loops)
  return retained
end

local function BMF_scheduler_game_thread_guard(key)
  local scheduler = state.telemetry.scheduler
  scheduler.thread_checks = (tonumber(scheduler.thread_checks) or 0) + 1
  if type(IsInGameThread) ~= "function" then
    scheduler.thread_check_unavailable = (tonumber(scheduler.thread_check_unavailable) or 0) + 1
    return true
  end

  local checked, on_game_thread = pcall(IsInGameThread)
  if not checked then
    scheduler.thread_check_errors = (tonumber(scheduler.thread_check_errors) or 0) + 1
  end
  if not checked or on_game_thread ~= true then
    scheduler.thread_violations = (tonumber(scheduler.thread_violations) or 0) + 1
    scheduler.dispatch_error = (tonumber(scheduler.dispatch_error) or 0) + 1
    local violations = scheduler.thread_violations
    if violations <= 5 or violations % 100 == 0 then
      log(
        "error",
        "scheduler callback refused outside the game thread key=" .. tostring(key or "unknown")
          .. " violations=" .. tostring(violations))
    end
    return false
  end
  return true
end

local function run_on_game_thread(callback)
  if type(callback) ~= "function" then
    return false
  end

  if state.game_thread_callback_count >= state.game_thread_callback_retention_limit then
    state.telemetry.scheduler.dispatch_error = (tonumber(state.telemetry.scheduler.dispatch_error) or 0) + 1
    state.telemetry.scheduler.dispatch_rejected = (tonumber(state.telemetry.scheduler.dispatch_rejected) or 0) + 1
    local rejected = state.telemetry.scheduler.dispatch_rejected
    if rejected <= 5 or rejected % 100 == 0 then
      log("error", "game-thread callback rejected: retained callback limit reached count=" .. tostring(rejected))
    end
    return false
  end

  local id = state.next_game_thread_callback_id
  state.next_game_thread_callback_id = state.next_game_thread_callback_id + 1
  state.game_thread_callback_count = state.game_thread_callback_count + 1
  BMF_scheduler_update_retained_callbacks()

  local function release()
    callback = nil
    if state.game_thread_callbacks[id] ~= nil then
      state.game_thread_callbacks[id] = nil
      state.game_thread_callback_count = math.max(0, state.game_thread_callback_count - 1)
      BMF_scheduler_update_retained_callbacks()
    end
  end

  local wrapped = function(...)
    local retained_callback = callback
    if state.game_thread_callbacks[id] == nil or type(retained_callback) ~= "function" then
      return
    end
    release()
    local started_clock = os.clock()
    if not BMF_scheduler_game_thread_guard("dispatch:game_thread") then
      BMF_telemetry_record_scheduler("dispatch", "game_thread", BMF_telemetry_duration_ms(started_clock), false)
      return
    end
    local ok, err = pcall(retained_callback, ...)
    BMF_telemetry_record_scheduler("dispatch", "game_thread", BMF_telemetry_duration_ms(started_clock), ok)
    if not ok then
      log("error", "game-thread callback failed: " .. tostring(err))
    end
  end
  state.game_thread_callbacks[id] = wrapped
  state.telemetry.scheduler.dispatch_total = (tonumber(state.telemetry.scheduler.dispatch_total) or 0) + 1

  if type(ExecuteInGameThread) == "function" and type(EGameThreadMethod) == "table" and EGameThreadMethod.EngineTick ~= nil then
    local called, result_or_error = pcall(ExecuteInGameThread, wrapped, EGameThreadMethod.EngineTick)
    if called and result_or_error ~= false then
      return true
    end
  end

  release()
  state.telemetry.scheduler.dispatch_error = (tonumber(state.telemetry.scheduler.dispatch_error) or 0) + 1
  log("error", "game-thread callback rejected: EngineTick scheduler unavailable")
  return false
end

function BMF_retain_delayed_callback(prefix, callback, on_refused)
  if type(callback) ~= "function" then
    return nil, nil
  end
  if state.delayed_callback_count >= state.delayed_callback_retention_limit then
    state.telemetry.scheduler.delayed_rejected = (tonumber(state.telemetry.scheduler.delayed_rejected) or 0) + 1
    local rejected = state.telemetry.scheduler.delayed_rejected
    if rejected <= 5 or rejected % 100 == 0 then
      log("error", "delayed callback rejected: retained callback limit reached count=" .. tostring(rejected))
    end
    return nil, nil
  end

  local key = tostring(prefix or "delay") .. ":" .. tostring(state.next_delayed_callback_id)
  state.next_delayed_callback_id = state.next_delayed_callback_id + 1
  state.delayed_callback_count = state.delayed_callback_count + 1
  BMF_scheduler_update_retained_callbacks()

  local function release()
    callback = nil
    on_refused = nil
    if state.delayed_callbacks[key] ~= nil then
      state.delayed_callbacks[key] = nil
      state.delayed_callback_count = math.max(0, state.delayed_callback_count - 1)
      BMF_scheduler_update_retained_callbacks()
    end
  end

  local wrapped
  wrapped = function(...)
    local retained_callback = callback
    local retained_refusal = on_refused
    if state.delayed_callbacks[key] == nil or type(retained_callback) ~= "function" then
      return
    end
    release()
    local started_clock = os.clock()
    if not BMF_scheduler_game_thread_guard("delayed:" .. tostring(prefix or "delay")) then
      BMF_telemetry_record_scheduler("delayed", tostring(prefix or "delay"), BMF_telemetry_duration_ms(started_clock), false)
      if type(retained_refusal) == "function" then
        local refusal_ok, refusal_error = pcall(retained_refusal, "NOT_GAME_THREAD")
        if not refusal_ok then
          log("error", "delayed callback refusal handler failed: " .. tostring(refusal_error))
        end
      end
      return
    end
    local ok, err = pcall(retained_callback, ...)
    state.telemetry.scheduler.delayed_completed = (tonumber(state.telemetry.scheduler.delayed_completed) or 0) + 1
    BMF_telemetry_record_scheduler("delayed", tostring(prefix or "delay"), BMF_telemetry_duration_ms(started_clock), ok)
    if not ok then
      log("error", "delayed callback failed: " .. tostring(err))
    end
  end
  state.delayed_callbacks[key] = wrapped
  return wrapped, key, release
end

function BMF_schedule_delayed_callback(prefix, delay_ms, callback, on_refused)
  if type(callback) ~= "function" then
    return false
  end

  local delay = finite_number(delay_ms, 0)
  if delay < 0 then
    delay = 0
  end
  -- A native delayed callback must not register its successor while UE4SS is
  -- traversing the delayed-action vector. Dispatch the application callback
  -- through the simple EngineTick queue first; self-rescheduling then happens
  -- on the following tick, outside the delayed traversal on old and new DLLs.
  local wrapped, _, release = BMF_retain_delayed_callback(prefix, function()
    if run_on_game_thread(callback) then
      return
    end
    if type(on_refused) == "function" then
      local refusal_ok, refusal_error = pcall(on_refused, "ENGINE_TICK_DISPATCH_FAILED")
      if not refusal_ok then
        log("error", "delayed callback refusal handler failed: " .. tostring(refusal_error))
      end
    end
  end, on_refused)
  if wrapped == nil then
    return false
  end
  state.telemetry.scheduler.dispatch_total = (tonumber(state.telemetry.scheduler.dispatch_total) or 0) + 1

  if type(ExecuteInGameThreadAfterFrames) == "function" and EngineTickAvailable == true then
    local frames = math.max(1, math.floor((delay / 16) + 0.5))
    local called, result_or_error = pcall(ExecuteInGameThreadAfterFrames, frames, wrapped)
    if called and type(result_or_error) == "number" then
      state.telemetry.scheduler.delayed_scheduled = (tonumber(state.telemetry.scheduler.delayed_scheduled) or 0) + 1
      return true, result_or_error, release
    end
  end

  release()
  state.telemetry.scheduler.dispatch_error = (tonumber(state.telemetry.scheduler.dispatch_error) or 0) + 1
  log("error", "delayed callback rejected: EngineTick frame scheduler unavailable")
  return false
end

function BMF_start_game_thread_loop(prefix, interval_ms, callback, default_enabled)
  -- Native LoopInGameThread* is retired. Callers fall through to the
  -- cancellable EngineTick one-shot chains implemented above.
  return false, "NativeLoopRetired"
end
function BMF_allow_delayed_worker_fallback()
  return BMF_env_bool("BMF_ALLOW_DELAYED_WORKER_FALLBACK", true)
end

