local function brick_runtime_parse_tag_arg(options)
  options = type(options) == "table" and options or {}
  local positional = type(options._positional) == "table" and options._positional or {}
  return trim_string(options.tag or options.consoleTag or options.consoletag or positional[2] or "")
end

local function brick_runtime_parse_lookup_purpose_arg(options)
  options = type(options) == "table" and options or {}
  return trim_string(
    options.purpose or
    options.lookupPurpose or
    options.lookuppurpose or
    options.lookup_purpose or
    options.resourcePurpose or
    options.resourcepurpose or
    options.role or
    options.kind or
    ""
  )
end

local function brick_runtime_lookup_segment_valid(value, allow_colon)
  if type(value) ~= "string" then return false end
  if value == "" or #value > 128 then return false end
  if allow_colon then
    return value:match("^[A-Za-z0-9_:%-%.]+$") ~= nil
  end
  return value:match("^[A-Za-z0-9_%-%.]+$") ~= nil
end

local function brick_runtime_lookup_tag_valid(tag)
  if type(tag) ~= "string" then return false end
  return tag:match("^lookup:[A-Za-z0-9_%-]+:[A-Za-z0-9_%-%.]+$") ~= nil
end

local function brick_runtime_normalize_lookup_tag(tag)
  tag = trim_string(tag or "")
  if tag == "" then return "" end
  if brick_runtime_lookup_tag_valid(tag) then
    return tag:lower()
  end
  return tag
end

local function brick_runtime_format_lookup_tag(id, purpose)
  id = trim_string(id or "")
  purpose = trim_string(purpose or "")
  if not brick_runtime_lookup_segment_valid(id, false) then return "" end
  if not brick_runtime_lookup_segment_valid(purpose, false) then return "" end
  return "lookup:" .. id:lower() .. ":" .. purpose:lower()
end

BMF_brick_runtime_parse_guid_arg = function(options)
  options = type(options) == "table" and options or {}
  local raw = options.guid
  if raw == nil then raw = options.uuid end
  if raw == nil then raw = options.UUID end
  if raw == nil then raw = options.lookupId end
  if raw == nil then raw = options.lookupid end
  if raw == nil then raw = options.runtimeGuid end
  if raw == nil then raw = options.runtimeguid end
  if raw == nil then raw = options.resourceGuid end
  if raw == nil then raw = options.resourceguid end
  if raw == nil then raw = options.logicalId end
  if raw == nil then raw = options.logicalid end
  if raw == nil then raw = options.resourceId end
  if raw == nil then raw = options.resourceid end
  return trim_string(raw or "")
end

local function brick_runtime_canonical_guid_arg(options)
  local guid = BMF_brick_runtime_parse_guid_arg(options)
  local tag = brick_runtime_normalize_lookup_tag(brick_runtime_parse_tag_arg(options))
  if guid == "" and tag ~= "" then
    return tag
  end
  local purpose = brick_runtime_parse_lookup_purpose_arg(options)
  if purpose ~= "" then
    local lookup = brick_runtime_format_lookup_tag(guid, purpose)
    if lookup ~= "" then
      return lookup
    end
  end
  return brick_runtime_normalize_lookup_tag(guid)
end

local function brick_runtime_canonical_tag_arg(options, guid)
  local tag = brick_runtime_normalize_lookup_tag(brick_runtime_parse_tag_arg(options))
  if tag ~= "" then return tag end
  if brick_runtime_lookup_tag_valid(guid or "") then
    return tostring(guid):lower()
  end
  local purpose = brick_runtime_parse_lookup_purpose_arg(options)
  return brick_runtime_format_lookup_tag(guid, purpose)
end

BMF_brick_runtime_guid_valid = function(guid)
  if type(guid) ~= "string" then return false end
  if guid == "" or #guid > 128 then return false end
  return guid:match("^[A-Za-z0-9_:%-%.]+$") ~= nil
end

BMF_brick_runtime_guid_max_bindings = function()
  return math.max(1, math.min(1024, math.floor(BMF_env_number("BMF_BRICK_RUNTIME_GUID_MAX_BRICKS", 256, 1) or 256)))
end

BMF_brick_runtime_guid_cache_max_guids = function()
  return math.max(1, math.min(4096, math.floor(BMF_env_number("BMF_BRICK_RUNTIME_GUID_CACHE_MAX_GUIDS", 1024, 1) or 1024)))
end

BMF_brick_runtime_guid_binding = function(guid, create)
  local runtime = state.tools.brick_runtime
  runtime.guid_bindings = runtime.guid_bindings or {}
  runtime.guid_binding_order = runtime.guid_binding_order or {}
  local binding = runtime.guid_bindings[guid]
  if binding or not create then
    return binding
  end

  local max_guids = BMF_brick_runtime_guid_cache_max_guids()
  while #runtime.guid_binding_order >= max_guids do
    local oldest = table.remove(runtime.guid_binding_order, 1)
    if oldest then
      runtime.guid_bindings[oldest] = nil
    end
  end

  binding = {
    guid = guid,
    ids = {},
    by_id = {},
    verified_by_id = {},
    source_by_id = {},
    created_at = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    updated_at = os.date("!%Y-%m-%dT%H:%M:%SZ"),
  }
  runtime.guid_bindings[guid] = binding
  runtime.guid_binding_order[#runtime.guid_binding_order + 1] = guid
  return binding
end

BMF_brick_runtime_bind_guid = function(guid, brick_id, source)
  if not BMF_brick_runtime_guid_valid(guid) then
    return false, "BRICK_RUNTIME_GUID_INVALID"
  end
  brick_id = math.floor(tonumber(brick_id) or 0)
  if brick_id <= 0 then
    return false, "BRICK_RUNTIME_ID_REQUIRED"
  end

  local binding = BMF_brick_runtime_guid_binding(guid, true)
  local normalized_source = tostring(source or "")
  local verified = normalized_source == "native-resolve" or normalized_source == "resource-native" or normalized_source == "verified"
  if binding.by_id[brick_id] then
    if verified then
      binding.verified_by_id = binding.verified_by_id or {}
      binding.source_by_id = binding.source_by_id or {}
      binding.verified_by_id[brick_id] = true
      binding.source_by_id[brick_id] = normalized_source
    end
    binding.updated_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
    return true, "OK"
  end

  local max_bricks = BMF_brick_runtime_guid_max_bindings()
  while #binding.ids >= max_bricks do
    local removed = table.remove(binding.ids, 1)
    if removed then
      binding.by_id[removed] = nil
      if binding.verified_by_id then binding.verified_by_id[removed] = nil end
      if binding.source_by_id then binding.source_by_id[removed] = nil end
    end
  end

  binding.ids[#binding.ids + 1] = brick_id
  binding.by_id[brick_id] = true
  if verified then
    binding.verified_by_id = binding.verified_by_id or {}
    binding.source_by_id = binding.source_by_id or {}
    binding.verified_by_id[brick_id] = true
    binding.source_by_id[brick_id] = normalized_source
  end
  binding.updated_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  return true, "OK"
end

BMF_brick_runtime_guid_id_verified = function(guid, brick_id)
  local binding = BMF_brick_runtime_guid_binding(guid, false)
  if not binding then return false end
  brick_id = math.floor(tonumber(brick_id) or 0)
  if brick_id <= 0 then return false end
  return binding.verified_by_id and binding.verified_by_id[brick_id] == true
end

BMF_brick_runtime_parse_brick_ids = function(options)
  options = type(options) == "table" and options or {}
  local ids = {}
  local seen = {}
  local function add_id(raw)
    local id = math.floor(tonumber(raw) or 0)
    if id > 0 and not seen[id] then
      ids[#ids + 1] = id
      seen[id] = true
    end
  end

  add_id(tree_cut_parse_brick_id(options))
  local raw_list = options.brickids or options.brickIds or options.ids or options.runtimeids or options.runtimeIds
  if raw_list ~= nil then
    for entry in tostring(raw_list):gmatch("[^,%s]+") do
      add_id(entry)
    end
  end
  return ids
end

local function brick_runtime_inspect_fields(brick_id)
  if type(BMFSocketBrickPhysicalInspect) ~= "function" then
    return false, {}, {}, "BMFSocketBrickPhysicalInspect unavailable", "BRICK_RUNTIME_UNAVAILABLE"
  end
  local ok, response = pcall(BMFSocketBrickPhysicalInspect, brick_id)
  local text = ok and response or tostring(response)
  local lines, fields = tree_cut_native_status_lines(text)
  local code = tostring(fields.code or (ok and "" or "LUA_ERROR"))
  local native_ok = ok == true and tostring(fields.ok or "") == "true" and code == "OK"
  return native_ok, fields, lines, tostring(text or ""), code
end

local function brick_runtime_clear_guid_binding(guid)
  local runtime = state.tools.brick_runtime
  runtime.guid_bindings = runtime.guid_bindings or {}
  runtime.guid_binding_order = runtime.guid_binding_order or {}
  runtime.guid_bindings[guid] = nil
  for index = #runtime.guid_binding_order, 1, -1 do
    if runtime.guid_binding_order[index] == guid then
      table.remove(runtime.guid_binding_order, index)
    end
  end
end

local function brick_runtime_bind_cell_max_span(options)
  options = type(options) == "table" and options or {}
  local configured = option_number(options, "maxspan", option_number(options, "maxSpan", BMF_env_number("BMF_BRICK_RUNTIME_BIND_CELL_MAX_SPAN", 512, 1)))
  return math.max(0, math.min(4096, math.floor(tonumber(configured) or 512)))
end

BMF_brick_runtime_format_guid_binding_lines = function(guid, binding)
  local lines = {
    "ok=true",
    "code=OK",
    "guid=" .. guid,
    "bound_bricks=" .. tostring(binding and #binding.ids or 0),
  }
  if binding then
    lines[#lines + 1] = "created_at=" .. tostring(binding.created_at or "")
    lines[#lines + 1] = "updated_at=" .. tostring(binding.updated_at or "")
    for index, brick_id in ipairs(binding.ids or {}) do
      lines[#lines + 1] = "brick_id." .. tostring(index) .. "=" .. tostring(brick_id)
      lines[#lines + 1] = "brick_id." .. tostring(index) .. ".verified=" .. tostring(binding.verified_by_id and binding.verified_by_id[brick_id] == true)
      lines[#lines + 1] = "brick_id." .. tostring(index) .. ".source=" .. tostring(binding.source_by_id and binding.source_by_id[brick_id] or "")
    end
  end
  return lines
end

local function brick_runtime_store_result(sequence, operation, brick_id, tag, guid, ok, response_or_error)
  local runtime = state.tools.brick_runtime
  local text = tostring(response_or_error or "")
  local lines, fields = tree_cut_native_status_lines(text)
  local native_ok = ok == true and tostring(fields.ok or "") == "true"
  local stored_brick_id = tonumber(brick_id) or 0
  if tostring(operation or "") == "resolve" then
    stored_brick_id = tonumber(fields.best_brick_id or fields.brick_id) or stored_brick_id
  end
  guid = tostring(guid or fields.guid or "")
  if native_ok and guid ~= "" and stored_brick_id > 0 and tostring(operation or "") == "resolve" then
    BMF_brick_runtime_bind_guid(guid, stored_brick_id, "native-resolve")
  end
  runtime.last_result = {
    sequence = sequence,
    operation = tostring(operation or ""),
    brickId = stored_brick_id,
    tag = tostring(tag or ""),
    guid = guid,
    ok = native_ok,
    code = tostring(fields.code or (ok and "" or "LUA_ERROR")),
    fields = fields,
    lines = lines,
    response = text,
    at = os.date("!%Y-%m-%dT%H:%M:%SZ"),
  }
  if not native_ok then
    runtime.last_error = tostring(fields.detail or fields.code or text or "")
  else
    runtime.last_error = ""
  end
  state.tools.tree_cut_native.last_physical_result = runtime.last_result
  write_status()
  return runtime.last_result
end

local function brick_runtime_parse_visible_arg(options, default_value)
  options = type(options) == "table" and options or {}
  local raw = options.visible
  if raw == nil then raw = options.visibility end
  if raw == nil then raw = options.isVisible end
  if raw == nil then
    return default_value or -1
  end
  if type(raw) == "boolean" then
    return raw and 1 or 0
  end
  local text = trim_string(raw)
  local lower = text:lower()
  if lower == "" or lower == "unchanged" or lower == "skip" or lower == "same" then
    return -1
  end
  if lower == "restore" or lower == "captured" then
    return -2
  end
  if lower == "1" or lower == "true" or lower == "yes" or lower == "on" or lower == "visible" then
    return 1
  end
  return 0
end

local function brick_runtime_parse_collision_arg(options, default_value)
  options = type(options) == "table" and options or {}
  local raw = options.collision
  if raw == nil then raw = options.collisionchannels end
  if raw == nil then raw = options.collisionChannels end
  if raw == nil then raw = options.channels end
  if raw == nil then
    return default_value or -2
  end
  local text = trim_string(raw)
  local lower = text:lower()
  if lower == "" or lower == "restore" or lower == "captured" then
    return -1
  end
  if lower == "unchanged" or lower == "skip" or lower == "same" then
    return -2
  end
  local value = tonumber(text) or 0
  if value < -2 then
    value = -2
  elseif value > 255 then
    value = 255
  end
  return math.floor(value)
end

local function brick_runtime_parse_context_arg(options)
  options = type(options) == "table" and options or {}
  local raw = options.context
  if raw == nil then raw = options.gridcontext end
  if raw == nil then raw = options.grid_context end
  if raw == nil then raw = options.gridcontextaddress end
  if raw == nil then raw = options.grid_context_address end
  local text = trim_string(raw or "")
  if text == "" or text:lower() == "none" then
    return ""
  end
  return text
end

local function brick_runtime_parse_action_source_arg(options)
  options = type(options) == "table" and options or {}
  local raw = options.actionsource
  if raw == nil then raw = options.actionSource end
  if raw == nil then raw = options.action_source end
  if raw == nil then raw = options.actionsourceaddress end
  if raw == nil then raw = options.actionSourceAddress end
  if raw == nil then raw = options.action_source_address end
  local text = trim_string(raw or "")
  if text ~= "" and text:lower() ~= "none" then
    return text, "explicit"
  end

  if options.autosource == false or options.autoSource == false or options.auto_action_source == false then
    return "", "disabled"
  end

  local candidates = applicator_process_event_context_candidates()
  for _, candidate in ipairs(candidates or {}) do
    local address = trim_string(candidate.address or "")
    if address ~= "" and address ~= "0x0" and address ~= "0x0000000000000000" then
      return candidate.address, tostring(candidate.source or candidate.className or "BRTool_Applicator")
    end
  end
  return "", "not-found"
end

local function brick_runtime_collision_restore_enabled()
  return BMF_env_bool("BMF_BRICK_RUNTIME_COLLISION_RESTORE_ENABLED", false)
end

local function brick_runtime_resolve_unsafe_native_enabled()
  return BMF_env_bool("BMF_BRICK_RUNTIME_RESOLVE_UNSAFE_NATIVE_ENABLED", false)
end

local function brick_runtime_resolve_lookup_fallback_enabled()
  return BMF_env_bool("BMF_BRICK_RUNTIME_RESOLVE_LOOKUP_FALLBACK_ENABLED", false)
    and BMF_env_bool("BMF_BRICK_RUNTIME_RESOLVE_UNSAFE_LOOKUP_SCAN_ENABLED", false)
end

local function brick_runtime_resolve_hint_lookup_enabled()
  return BMF_env_bool("BMF_BRICK_RUNTIME_RESOLVE_HINT_LOOKUP_ENABLED", false)
    and BMF_env_bool("BMF_BRICK_RUNTIME_UNSAFE_LOOKUP_ENABLED", false)
end

local function brick_runtime_resolve_direct_array_enabled()
  return BMF_env_bool("BMF_BRICK_RUNTIME_RESOLVE_DIRECT_ARRAY_ENABLED", false)
    and brick_runtime_resolve_unsafe_native_enabled()
end

local function brick_runtime_direct_lookup_enabled()
  return BMF_env_bool("BMF_BRICK_RUNTIME_UNSAFE_LOOKUP_ENABLED", false)
end

local function brick_runtime_inline_operations_enabled()
  return BMF_env_bool("BMF_BRICK_RUNTIME_INLINE_OPERATIONS_ENABLED", false)
end

local function brick_runtime_resolve_native_path_enabled()
  return brick_runtime_resolve_lookup_fallback_enabled()
    or brick_runtime_resolve_hint_lookup_enabled()
    or brick_runtime_resolve_direct_array_enabled()
end

local function brick_runtime_parse_resolve_position_arg(options, allow_positional)
  options = type(options) == "table" and options or {}
  local positional = allow_positional and type(options._positional) == "table" and options._positional or {}
  local x = tonumber(options.x or options.worldx or options.worldX or positional[1])
  local y = tonumber(options.y or options.worldy or options.worldY or positional[2])
  local z = tonumber(options.z or options.worldz or options.worldZ or positional[3])
  if not (x and y and z) then
    return nil, nil, nil
  end
  return math.floor(x), math.floor(y), math.floor(z)
end

local function brick_runtime_lookup_tag_position_on_game_thread(tag, options)
  tag = brick_runtime_normalize_lookup_tag(tag)
  local lines = {
    "lookup_tag=" .. tostring(tag or ""),
  }
  if tag == "" then
    lines[#lines + 1] = "lookup_tag_code=BRICK_RUNTIME_TAG_REQUIRED"
    return nil, nil, nil, lines
  end
  if not tree_cut_tag_lookup_available() then
    lines[#lines + 1] = "lookup_tag_code=TREE_CUT_TAG_LOOKUP_UNAVAILABLE"
    return nil, nil, nil, lines
  end

  local max_scan = option_number(options, "tagmaxscan", option_number(options, "tagMaxScan", 0))
  max_scan = math.max(0, math.floor(tonumber(max_scan) or 0))
  local ok, response = pcall(BMFSocketResourceNativeFindTag or BMFSocketTreeCutFindTag, tag, 1, max_scan)
  local _, fields = tree_cut_native_status_lines(ok and response or tostring(response))
  lines[#lines + 1] = "lookup_tag_ok=" .. tostring(ok == true and tostring(fields.ok or "") == "true")
  lines[#lines + 1] = "lookup_tag_code=" .. tostring(fields.code or (ok and "" or "LUA_ERROR"))
  lines[#lines + 1] = "lookup_tag_matches=" .. tostring(fields.matches or "")
  if not ok or tostring(fields.ok or "") ~= "true" or tostring(fields.code or "") ~= "OK" then
    return nil, nil, nil, lines
  end

  local x = tonumber(fields.best_x or fields.x)
  local y = tonumber(fields.best_y or fields.y)
  local z = tonumber(fields.best_z or fields.z)
  if not (x and y and z) then
    lines[#lines + 1] = "lookup_tag_position=false"
    return nil, nil, nil, lines
  end
  lines[#lines + 1] = "lookup_tag_position=true"
  lines[#lines + 1] = "lookup_tag_source=" .. tostring(fields.best_source or fields.console_tag_source or "")
  lines[#lines + 1] = "lookup_tag_target=" .. tostring(fields.best_target_name or fields.best_name or "")
  return math.floor(x), math.floor(y), math.floor(z), lines
end

local function brick_runtime_resolve_id_on_game_thread(options, guid, tag)
  options = type(options) == "table" and options or {}
  local lines = {
    "source=BMF",
    "operation=resolve-guid",
    "guid=" .. tostring(guid or ""),
    "tag=" .. tostring(tag or ""),
  }

  local x, y, z = brick_runtime_parse_resolve_position_arg(options, false)
  if not x then
    local tag_x, tag_y, tag_z, tag_lines = brick_runtime_lookup_tag_position_on_game_thread(tag, options)
    for _, line in ipairs(tag_lines or {}) do
      lines[#lines + 1] = tostring(line)
    end
    x, y, z = tag_x, tag_y, tag_z
  end

  if not (x and y and z) then
    lines[#lines + 1] = "ok=false"
    lines[#lines + 1] = "code=BRICK_RUNTIME_GUID_LOOKUP_MISS"
    lines[#lines + 1] = "detail=no bound runtime ids and no cached tag/position candidate was available"
    return nil, lines
  end
  if type(BMFSocketBrickPhysicalResolveNear) ~= "function" then
    lines[#lines + 1] = "ok=false"
    lines[#lines + 1] = "code=BRICK_RUNTIME_RESOLVE_UNAVAILABLE"
    lines[#lines + 1] = "detail=BMFSocket brick runtime resolve helper is unavailable"
    return nil, lines
  end
  if not BMF_env_bool("BMF_BRICK_RUNTIME_RESOLVE_ENABLED", false) then
    lines[#lines + 1] = "ok=false"
    lines[#lines + 1] = "code=BRICK_RUNTIME_RESOLVE_DISABLED"
    lines[#lines + 1] = "detail=runtime brick resolve is disabled"
    return nil, lines
  end
  if not brick_runtime_resolve_native_path_enabled() then
    lines[#lines + 1] = "ok=false"
    lines[#lines + 1] = "code=BRICK_RUNTIME_RESOLVE_NATIVE_PATH_DISABLED"
    lines[#lines + 1] = "detail=native runtime brick resolve has no supported path enabled; use socket object-address physical state or enable a bounded resolver mode only for isolated validation"
    return nil, lines
  end

  local radius = option_number(options, "radius", 512)
  local max_scan = option_number(options, "maxscan", option_number(options, "max", 120000))
  local hint = option_number(options, "hint", option_number(options, "hintslot", option_number(options, "slot", 0)))
  local hint_window = option_number(options, "hintwindow", option_number(options, "window", 256))
  local hint_only = option_boolean(options, "hintonly", option_boolean(options, "hint_only", false))
  local prefer_visible = option_boolean(options, "prefervisible", option_boolean(options, "prefer_visible", false))
  local prefer_collidable = option_boolean(options, "prefercollidable", option_boolean(options, "prefer_collidable", false))
  radius = math.max(1, math.floor(tonumber(radius) or 512))
  max_scan = math.max(1, math.floor(tonumber(max_scan) or 120000))
  hint = math.max(0, math.floor(tonumber(hint) or 0))
  hint_window = math.max(0, math.floor(tonumber(hint_window) or 256))

  local ok, response = pcall(BMFSocketBrickPhysicalResolveNear, x, y, z, radius, max_scan, hint, hint_window, hint_only, prefer_visible, prefer_collidable)
  local _, fields = tree_cut_native_status_lines(ok and response or tostring(response))
  local resolved = tonumber(fields.best_brick_id or fields.brick_id) or 0
  local native_ok = ok == true and tostring(fields.ok or "") == "true" and resolved > 0
  lines[#lines + 1] = "resolve_ok=" .. tostring(native_ok)
  lines[#lines + 1] = "resolve_code=" .. tostring(fields.code or (ok and "" or "LUA_ERROR"))
  lines[#lines + 1] = "x=" .. tostring(x)
  lines[#lines + 1] = "y=" .. tostring(y)
  lines[#lines + 1] = "z=" .. tostring(z)
  lines[#lines + 1] = "radius=" .. tostring(radius)
  lines[#lines + 1] = "max_scan=" .. tostring(max_scan)
  lines[#lines + 1] = "best_brick_id=" .. tostring(resolved > 0 and resolved or "")
  if not native_ok then
    lines[#lines + 1] = "ok=false"
    lines[#lines + 1] = "code=" .. tostring(fields.code or (ok and "BRICK_RUNTIME_RESOLVE_FAILED" or "LUA_ERROR"))
    return nil, lines
  end

  lines[#lines + 1] = "ok=true"
  lines[#lines + 1] = "code=OK"
  lines[#lines + 1] = "brick_id=" .. tostring(resolved)
  BMF_brick_runtime_bind_guid(guid, resolved, "native-resolve")
  return resolved, lines
end

function BMF.bricks.resolveRuntimeState(options)
  options = type(options) == "table" and options or {}
  local runtime = state.tools.brick_runtime
  local guid = brick_runtime_canonical_guid_arg(options)
  local tag = brick_runtime_canonical_tag_arg(options, guid)
  local positional = type(options._positional) == "table" and options._positional or {}
  local x = tonumber(options.x or options.worldx or positional[1])
  local y = tonumber(options.y or options.worldy or positional[2])
  local z = tonumber(options.z or options.worldz or positional[3])

  if guid ~= "" and not BMF_brick_runtime_guid_valid(guid) then
    return result(false, "BRICK_RUNTIME_GUID_INVALID", "guid must be an opaque identifier without spaces", {
      tag = tag,
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_GUID_INVALID",
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if type(BMFSocketBrickPhysicalResolveNear) ~= "function" then
    runtime.last_error = "BMFSocket brick runtime resolve helper is unavailable"
    return result(false, "BRICK_RUNTIME_RESOLVE_UNAVAILABLE", runtime.last_error, {
      tag = tag,
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_RESOLVE_UNAVAILABLE",
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if not BMF_env_bool("BMF_BRICK_RUNTIME_RESOLVE_ENABLED", false) then
    runtime.last_error = "runtime brick resolve is disabled"
    return result(false, "BRICK_RUNTIME_RESOLVE_DISABLED", runtime.last_error, {
      tag = tag,
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_RESOLVE_DISABLED",
        "tag=" .. tag,
        "guid=" .. guid,
        "detail=runtime brick resolve is disabled",
      },
    })
  end
  if not brick_runtime_resolve_native_path_enabled() then
    runtime.last_error = "native runtime brick resolve is disabled"
    return result(false, "BRICK_RUNTIME_RESOLVE_NATIVE_PATH_DISABLED", runtime.last_error, {
      tag = tag,
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_RESOLVE_NATIVE_PATH_DISABLED",
        "tag=" .. tag,
        "guid=" .. guid,
        "detail=native runtime brick resolve has no supported path enabled; use socket object-address physical state or enable a bounded resolver mode only for isolated validation",
      },
    })
  end

  local radius = option_number(options, "radius", 512)
  local max_scan = option_number(options, "maxscan", option_number(options, "max", 120000))
  local hint = option_number(options, "hint", option_number(options, "hintslot", option_number(options, "slot", 0)))
  local hint_window = option_number(options, "hintwindow", option_number(options, "window", 256))
  local hint_only = option_boolean(options, "hintonly", option_boolean(options, "hint_only", false))
  local prefer_visible = option_boolean(options, "prefervisible", option_boolean(options, "prefer_visible", false))
  local prefer_collidable = option_boolean(options, "prefercollidable", option_boolean(options, "prefer_collidable", false))
  if x and y and z then
    x = math.floor(x)
    y = math.floor(y)
    z = math.floor(z)
  else
    x, y, z = nil, nil, nil
  end
  radius = math.max(1, math.floor(tonumber(radius) or 512))
  max_scan = math.max(1, math.floor(tonumber(max_scan) or 120000))
  hint = math.max(0, math.floor(tonumber(hint) or 0))
  hint_window = math.max(0, math.floor(tonumber(hint_window) or 256))

  local sequence = brick_runtime_next_sequence()
  local operation = function()
    if x and y and z then
      local ok, response = pcall(BMFSocketBrickPhysicalResolveNear, x, y, z, radius, max_scan, hint, hint_window, hint_only, prefer_visible, prefer_collidable)
      brick_runtime_store_result(sequence, "resolve", 0, tag, guid, ok, ok and response or tostring(response))
      return
    end

    local resolved, resolve_lines = brick_runtime_resolve_id_on_game_thread(options, guid, tag)
    brick_runtime_store_result(
      sequence,
      "resolve",
      tonumber(resolved) or 0,
      tag,
      guid,
      true,
      table.concat(resolve_lines or {}, "\n"))
  end
  if brick_runtime_inline_operations_enabled() then
    operation()
  else
    run_on_game_thread(operation)
  end

  return result(true, "OK", "Runtime brick-state resolve queued on the game thread", {
    queued = true,
    sequence = sequence,
    tag = tag,
    guid = guid,
    lines = {
      "ok=true",
      "code=OK",
      "queued=true",
      "operation=resolve",
      "execution=" .. (brick_runtime_inline_operations_enabled() and "inline" or "game-thread"),
      "sequence=" .. tostring(sequence),
      "tag=" .. tag,
      "guid=" .. guid,
      "x=" .. tostring(x or ""),
      "y=" .. tostring(y or ""),
      "z=" .. tostring(z or ""),
      "tag_lookup=" .. tostring(not (x and y and z)),
      "radius=" .. tostring(radius),
      "max_scan=" .. tostring(max_scan),
      "hint_slot=" .. tostring(hint),
      "hint_window=" .. tostring(hint_window),
      "hint_only=" .. tostring(hint_only == true),
      "prefer_visible=" .. tostring(prefer_visible == true),
      "prefer_collidable=" .. tostring(prefer_collidable == true),
    },
  })
end

function BMF.bricks.scanRuntimeRegion(options)
  options = type(options) == "table" and options or {}
  local runtime = state.tools.brick_runtime
  local guid = brick_runtime_canonical_guid_arg(options)
  local tag = brick_runtime_canonical_tag_arg(options, guid)
  local positional = type(options._positional) == "table" and options._positional or {}

  local confirm = tostring(options.confirm or options.confirmation or "")
  if confirm ~= "brick-runtime-region" and confirm ~= "brick-runtime" then
    return result(false, "BRICK_RUNTIME_REGION_CONFIRM_REQUIRED", "confirm=brick-runtime-region is required for runtime region diagnostics", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_REGION_CONFIRM_REQUIRED",
        "required_confirm=brick-runtime-region",
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if guid ~= "" and not BMF_brick_runtime_guid_valid(guid) then
    return result(false, "BRICK_RUNTIME_GUID_INVALID", "guid must be an opaque identifier without spaces", {
      tag = tag,
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_GUID_INVALID",
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if not brick_runtime_region_scan_available() then
    runtime.last_error = "BMFSocket brick runtime region scan helper is unavailable"
    return result(false, "BRICK_RUNTIME_REGION_SCAN_UNAVAILABLE", runtime.last_error, {
      tag = tag,
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_REGION_SCAN_UNAVAILABLE",
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if not BMF_env_bool("BMF_BRICK_RUNTIME_REGION_SCAN_ENABLED", false) then
    runtime.last_error = "runtime brick region scan is disabled"
    return result(false, "BRICK_RUNTIME_REGION_SCAN_DISABLED", runtime.last_error, {
      tag = tag,
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_REGION_SCAN_DISABLED",
        "tag=" .. tag,
        "guid=" .. guid,
        "required_env=BMF_BRICK_RUNTIME_REGION_SCAN_ENABLED=1",
      },
    })
  end

  local x = tonumber(options.x or options.centerx or options.centerX or positional[1])
  local y = tonumber(options.y or options.centery or options.centerY or positional[2])
  local z = tonumber(options.z or options.centerz or options.centerZ or positional[3])
  local extent_x = tonumber(options.ex or options.extentx or options.extentX or options.halfx or options.halfX or positional[4])
  local extent_y = tonumber(options.ey or options.extenty or options.extentY or options.halfy or options.halfY or positional[5])
  local extent_z = tonumber(options.ez or options.extentz or options.extentZ or options.halfz or options.halfZ or positional[6])
  if not (x and y and z and extent_x and extent_y and extent_z) then
    return result(false, "BRICK_RUNTIME_REGION_ARGUMENTS_REQUIRED", "x y z ex ey ez are required for runtime region scans", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_REGION_ARGUMENTS_REQUIRED",
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end

  x = math.floor(x)
  y = math.floor(y)
  z = math.floor(z)
  extent_x = math.max(0, math.floor(extent_x))
  extent_y = math.max(0, math.floor(extent_y))
  extent_z = math.max(0, math.floor(extent_z))
  local max_scan = option_number(options, "maxscan", option_number(options, "maxScan", BMF_env_number("BMF_BRICK_RUNTIME_REGION_SCAN_MAX_SCAN", 500000, 1)))
  local limit = option_number(options, "limit", option_number(options, "maxresults", option_number(options, "maxResults", BMF_env_number("BMF_BRICK_RUNTIME_REGION_SCAN_LIMIT", 512, 1))))
  local max_ms = option_number(options, "maxms", option_number(options, "maxMs", option_number(options, "budgetms", BMF_env_number("BMF_BRICK_RUNTIME_REGION_SCAN_MAX_MS", 250, 1))))
  max_scan = math.max(1, math.floor(tonumber(max_scan) or 500000))
  limit = math.max(1, math.min(4096, math.floor(tonumber(limit) or 512)))
  max_ms = math.max(1, math.floor(tonumber(max_ms) or 250))

  local sequence = brick_runtime_next_sequence()
  local operation = function()
    local ok, response = pcall(
      BMFSocketBrickPhysicalScanRegion,
      x,
      y,
      z,
      extent_x,
      extent_y,
      extent_z,
      max_scan,
      limit,
      max_ms)
    brick_runtime_store_result(sequence, "scan-region", 0, tag, guid, ok, ok and response or tostring(response))
  end
  if brick_runtime_inline_operations_enabled() then
    operation()
  else
    run_on_game_thread(operation)
  end

  return result(true, "OK", "Runtime brick region scan queued on the game thread", {
    queued = true,
    sequence = sequence,
    tag = tag,
    guid = guid,
    lines = {
      "ok=true",
      "code=OK",
      "queued=true",
      "operation=scan-region",
      "execution=" .. (brick_runtime_inline_operations_enabled() and "inline" or "game-thread"),
      "sequence=" .. tostring(sequence),
      "tag=" .. tag,
      "guid=" .. guid,
      "x=" .. tostring(x),
      "y=" .. tostring(y),
      "z=" .. tostring(z),
      "extent_x=" .. tostring(extent_x),
      "extent_y=" .. tostring(extent_y),
      "extent_z=" .. tostring(extent_z),
      "max_scan=" .. tostring(max_scan),
      "limit=" .. tostring(limit),
      "max_ms=" .. tostring(max_ms),
    },
  })
end

local function brick_world_region_file_exists(path)
  local handle = io.open(path, "rb")
  if not handle then
    return false
  end
  handle:close()
  return true
end

local function brick_world_region_shell_arg(value)
  local text = tostring(value or "")
  if text:match("[\r\n\"]") then
    return nil
  end
  return "\"" .. text .. "\""
end

local function brick_world_region_shell_command_arg(value)
  local text = tostring(value or "")
  if text == "" then
    return nil
  end
  if text:match("[\r\n\"]") then
    return nil
  end
  if text:match("[%s/\\:]") then
    return brick_world_region_shell_arg(text)
  end
  return text
end

local function brick_world_region_builds_dir()
  local configured = first_string(
    BMF_env_string("BMF_BRICK_WORLD_REGION_SCAN_BUILDS_DIR"),
    BMF_env_string("BMF_BRICKADIA_BUILDS_DIR"))
  if configured then
    return configured:gsub("\\", "/"):gsub("/+$", "")
  end

  local saved_dir = first_string(
    BMF_env_string("BMF_BRICKADIA_SAVED_DIR"),
    state.config and state.config.brickadiaSavedDir or "")
  if saved_dir then
    return join_path(saved_dir:gsub("\\", "/"), "Builds")
  end

  return ""
end

local function brick_world_region_valid_expected_key(key)
  local text = tostring(key or ""):lower()
  return text:match("^lookup:[a-z0-9_%-]+:treecut$") ~= nil
    or text:match("^legacy%-tree:[a-z0-9_%-]+:[%-0-9]+,[%-0-9]+,[%-0-9]+$") ~= nil
end

local function brick_world_region_helper_path()
  return join_path(ROOT, "tools/world-region-proof.js")
end

local function brick_world_region_run_helper(save_path, expected_key, builds_dir, x, y, z, extent_x, extent_y, extent_z)
  local node = BMF_env_string("BMF_NODE_PATH")
  if node == "" then
    node = "node"
  end

  local node_arg = brick_world_region_shell_command_arg(node)
  local script_arg = brick_world_region_shell_arg(brick_world_region_helper_path())
  local save_arg = brick_world_region_shell_arg(save_path)
  local key_arg = brick_world_region_shell_arg(expected_key)
  local builds_arg = brick_world_region_shell_arg(builds_dir)
  if not (node_arg and script_arg and save_arg and key_arg and builds_arg) then
    return "ok=false\ncode=WORLD_REGION_PROOF_SHELL_ARG_INVALID\ndetail=world-region proof command contained an unsafe shell argument\nsource=BMFWorldRegionProof\noperation=world-scan-region\ncoordinate_space=world\nclear_region_safe=false\nexact_target_only=false"
  end

  local command = table.concat({
    node_arg,
    script_arg,
    "--save",
    save_arg,
    "--expected-key",
    key_arg,
    "--builds-dir",
    builds_arg,
    "--x",
    tostring(x),
    "--y",
    tostring(y),
    "--z",
    tostring(z),
    "--ex",
    tostring(extent_x),
    "--ey",
    tostring(extent_y),
    "--ez",
    tostring(extent_z),
  }, " ") .. " 2>&1"

  local handle = io.popen(command)
  if not handle then
    return "ok=false\ncode=WORLD_REGION_PROOF_PROCESS_FAILED\ndetail=failed to start world-region proof helper\nsource=BMFWorldRegionProof\noperation=world-scan-region\ncoordinate_space=world\nclear_region_safe=false\nexact_target_only=false"
  end
  local output = handle:read("*a") or ""
  handle:close()
  if trim_string(output) == "" then
    return "ok=false\ncode=WORLD_REGION_PROOF_EMPTY_RESPONSE\ndetail=world-region proof helper returned no output\nsource=BMFWorldRegionProof\noperation=world-scan-region\ncoordinate_space=world\nclear_region_safe=false\nexact_target_only=false"
  end
  return output
end

local function brick_world_region_timeout_response(save_path, expected_key, builds_dir, attempts, poll_ms)
  return table.concat({
    "ok=false",
    "code=WORLD_REGION_SAVE_FILE_TIMEOUT",
    "detail=Bricks.SaveRegion did not produce the expected proof file before timeout",
    "source=BMFWorldRegionProof",
    "operation=world-scan-region",
    "coordinate_space=world",
    "clear_region_safe=false",
    "exact_target_only=false",
    "expected_key=" .. tostring(expected_key or ""),
    "save_path=" .. tostring(save_path or ""),
    "builds_dir=" .. tostring(builds_dir or ""),
    "attempts=" .. tostring(attempts or 0),
    "poll_ms=" .. tostring(poll_ms or 0),
  }, "\n")
end

function BMF.bricks.scanWorldRegion(options)
  options = type(options) == "table" and options or {}
  local positional = type(options._positional) == "table" and options._positional or {}
  local guid = brick_runtime_canonical_guid_arg(options)
  local expected_key = trim_string(
    options.expectedkey or
    options.key or
    options.tag or
    options.consoletag or
    options.guid or
    positional[7] or
    "")
  expected_key = expected_key:lower()

  local confirm = tostring(options.confirm or options.confirmation or "")
  if confirm ~= "brick-world-region" and confirm ~= "tree-clear-region" then
    return result(false, "BRICK_WORLD_REGION_CONFIRM_REQUIRED", "confirm=brick-world-region is required for world-region proof scans", {
      lines = {
        "ok=false",
        "code=BRICK_WORLD_REGION_CONFIRM_REQUIRED",
        "required_confirm=brick-world-region",
        "expected_key=" .. expected_key,
      },
    })
  end
  if not BMF_env_bool("BMF_BRICK_WORLD_REGION_SCAN_ENABLED", false) then
    return result(false, "BRICK_WORLD_REGION_SCAN_DISABLED", "world-region proof scans are disabled", {
      lines = {
        "ok=false",
        "code=BRICK_WORLD_REGION_SCAN_DISABLED",
        "required_env=BMF_BRICK_WORLD_REGION_SCAN_ENABLED=1",
        "expected_key=" .. expected_key,
      },
    })
  end
  if expected_key == "" or not brick_world_region_valid_expected_key(expected_key) then
    return result(false, "BRICK_WORLD_REGION_EXPECTED_KEY_INVALID", "expected tree key must be lookup:<id>:treecut or a legacy-tree anchor key", {
      lines = {
        "ok=false",
        "code=BRICK_WORLD_REGION_EXPECTED_KEY_INVALID",
        "expected_key=" .. expected_key,
      },
    })
  end

  local x = tonumber(options.x or options.centerx or options.centerX or positional[1])
  local y = tonumber(options.y or options.centery or options.centerY or positional[2])
  local z = tonumber(options.z or options.centerz or options.centerZ or positional[3])
  local extent_x = tonumber(options.ex or options.extentx or options.extentX or options.halfx or options.halfX or positional[4])
  local extent_y = tonumber(options.ey or options.extenty or options.extentY or options.halfy or options.halfY or positional[5])
  local extent_z = tonumber(options.ez or options.extentz or options.extentZ or options.halfz or options.halfZ or positional[6])
  if not (x and y and z and extent_x and extent_y and extent_z) then
    return result(false, "BRICK_WORLD_REGION_ARGUMENTS_REQUIRED", "x y z ex ey ez are required for world-region proof scans", {
      lines = {
        "ok=false",
        "code=BRICK_WORLD_REGION_ARGUMENTS_REQUIRED",
        "expected_key=" .. expected_key,
      },
    })
  end

  x = math.floor(x)
  y = math.floor(y)
  z = math.floor(z)
  extent_x = math.max(0, math.floor(extent_x))
  extent_y = math.max(0, math.floor(extent_y))
  extent_z = math.max(0, math.floor(extent_z))

  local max_extent = BMF_env_number("BMF_BRICK_WORLD_REGION_SCAN_MAX_EXTENT", 512, 1)
  local max_extent_z = BMF_env_number("BMF_BRICK_WORLD_REGION_SCAN_MAX_EXTENT_Z", max_extent, 1)
  if extent_x > max_extent or extent_y > max_extent or extent_z > max_extent_z then
    return result(false, "BRICK_WORLD_REGION_EXTENT_TOO_LARGE", "world-region proof extent exceeds configured maximum", {
      lines = {
        "ok=false",
        "code=BRICK_WORLD_REGION_EXTENT_TOO_LARGE",
        "expected_key=" .. expected_key,
        "extent_x=" .. tostring(extent_x),
        "extent_y=" .. tostring(extent_y),
        "extent_z=" .. tostring(extent_z),
        "max_extent=" .. tostring(max_extent),
        "max_extent_z=" .. tostring(max_extent_z),
      },
    })
  end

  local builds_dir = brick_world_region_builds_dir()
  if builds_dir == "" then
    return result(false, "BRICK_WORLD_REGION_BUILDS_DIR_REQUIRED", "BMF_BRICK_WORLD_REGION_SCAN_BUILDS_DIR or BMF_BRICKADIA_BUILDS_DIR is required", {
      lines = {
        "ok=false",
        "code=BRICK_WORLD_REGION_BUILDS_DIR_REQUIRED",
        "expected_key=" .. expected_key,
      },
    })
  end

  local sequence = brick_runtime_next_sequence()
  local save_name = "BMFRegionProof_" .. tostring(sequence) .. "_" .. tostring(os.time())
  local save_path = join_path(builds_dir, save_name .. ".brs")
  os.remove(save_path)

  local command = table.concat({
    "Bricks.SaveRegion",
    quote_console_string(save_name),
    tostring(x),
    tostring(y),
    tostring(z),
    tostring(extent_x),
    tostring(extent_y),
    tostring(extent_z),
  }, " ")

  local response = exec_console_manager(command)
  if not response.ok then
    brick_runtime_store_result(sequence, "world-scan-region", 0, expected_key, guid, true, table.concat({
      "ok=false",
      "code=BRICK_WORLD_REGION_SAVE_COMMAND_FAILED",
      "detail=" .. tostring(response.message or "SaveRegion command failed"),
      "source=BMFWorldRegionProof",
      "operation=world-scan-region",
      "coordinate_space=world",
      "clear_region_safe=false",
      "exact_target_only=false",
      "expected_key=" .. expected_key,
      "save_command=" .. command,
    }, "\n"))
    return result(false, "BRICK_WORLD_REGION_SAVE_COMMAND_FAILED", "Bricks.SaveRegion command failed", {
      sequence = sequence,
      lines = {
        "ok=false",
        "code=BRICK_WORLD_REGION_SAVE_COMMAND_FAILED",
        "sequence=" .. tostring(sequence),
        "expected_key=" .. expected_key,
      },
    })
  end

  local poll_ms = math.max(50, BMF_env_number("BMF_BRICK_WORLD_REGION_SCAN_POLL_MS", 100, 50))
  local timeout_ms = math.max(poll_ms, BMF_env_number("BMF_BRICK_WORLD_REGION_SCAN_TIMEOUT_MS", 3000, poll_ms))
  local max_attempts = math.max(1, math.floor((timeout_ms + poll_ms - 1) / poll_ms))
  local attempts = 0

  local function finish(text)
    os.remove(save_path)
    brick_runtime_store_result(sequence, "world-scan-region", 0, expected_key, guid, true, text)
  end

  local function attempt()
    attempts = attempts + 1
    if brick_world_region_file_exists(save_path) then
      finish(brick_world_region_run_helper(save_path, expected_key, builds_dir, x, y, z, extent_x, extent_y, extent_z))
      return
    end
    if attempts >= max_attempts then
      finish(brick_world_region_timeout_response(save_path, expected_key, builds_dir, attempts, poll_ms))
      return
    end
    if not BMF.timers.after(poll_ms, attempt) then
      finish(brick_world_region_timeout_response(save_path, expected_key, builds_dir, attempts, poll_ms))
    end
  end

  if not BMF.timers.after(poll_ms, attempt) then
    attempt()
  end

  return result(true, "OK", "World-space brick region proof queued", {
    queued = true,
    sequence = sequence,
    tag = expected_key,
    guid = guid,
    lines = {
      "ok=true",
      "code=OK",
      "queued=true",
      "operation=world-scan-region",
      "sequence=" .. tostring(sequence),
      "expected_key=" .. expected_key,
      "guid=" .. guid,
      "x=" .. tostring(x),
      "y=" .. tostring(y),
      "z=" .. tostring(z),
      "extent_x=" .. tostring(extent_x),
      "extent_y=" .. tostring(extent_y),
      "extent_z=" .. tostring(extent_z),
      "coordinate_space=world",
      "save_name=" .. save_name,
      "save_path=" .. save_path,
      "builds_dir=" .. builds_dir,
      "poll_ms=" .. tostring(poll_ms),
      "timeout_ms=" .. tostring(timeout_ms),
    },
  })
end

function BMF.bricks.inspectRuntimeState(options)
  options = type(options) == "table" and options or {}
  local runtime = state.tools.brick_runtime
  local brick_id = tree_cut_parse_brick_id(options)
  local guid = brick_runtime_canonical_guid_arg(options)
  local tag = brick_runtime_canonical_tag_arg(options, guid)
  if guid ~= "" and not BMF_brick_runtime_guid_valid(guid) then
    return result(false, "BRICK_RUNTIME_GUID_INVALID", "guid must be an opaque identifier without spaces", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_GUID_INVALID",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if brick_id <= 0 then
    return result(false, "BRICK_RUNTIME_ID_REQUIRED", "brickid is required for runtime brick-state inspect", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_ID_REQUIRED",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if not brick_runtime_available() then
    runtime.last_error = "BMFSocket brick runtime helpers are unavailable"
    return result(false, "BRICK_RUNTIME_UNAVAILABLE", runtime.last_error, {
      brickId = brick_id,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_UNAVAILABLE",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if not brick_runtime_direct_lookup_enabled() then
    return result(false, "BRICK_RUNTIME_LOOKUP_DISABLED", "explicit runtime brick id inspect is disabled unless unsafe direct lookup is enabled", {
      brickId = brick_id,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_LOOKUP_DISABLED",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
        "required_env=BMF_BRICK_RUNTIME_UNSAFE_LOOKUP_ENABLED=1",
        "detail=saved BRS brickIndex values are not safe runtime ids; inspect requires a verified live runtime id",
      },
    })
  end

  local sequence = brick_runtime_next_sequence()
  local operation = function()
    local ok, response = pcall(BMFSocketBrickPhysicalInspect, brick_id)
    brick_runtime_store_result(sequence, "inspect", brick_id, tag, guid, ok, ok and response or tostring(response))
  end
  if brick_runtime_inline_operations_enabled() then
    operation()
  else
    run_on_game_thread(operation)
  end

  return result(true, "OK", "Runtime brick-state inspect queued on the game thread", {
    queued = true,
    sequence = sequence,
    brickId = brick_id,
    lines = {
      "ok=true",
      "code=OK",
      "queued=true",
      "operation=inspect",
      "execution=" .. (brick_runtime_inline_operations_enabled() and "inline" or "game-thread"),
      "sequence=" .. tostring(sequence),
      "brick_id=" .. tostring(brick_id),
      "tag=" .. tag,
      "guid=" .. guid,
    },
  })
end

function BMF.bricks.setRuntimeState(options)
  options = type(options) == "table" and options or {}
  local runtime = state.tools.brick_runtime
  local brick_id = tree_cut_parse_brick_id(options)
  local guid = brick_runtime_canonical_guid_arg(options)
  local tag = brick_runtime_canonical_tag_arg(options, guid)
  if guid ~= "" and not BMF_brick_runtime_guid_valid(guid) then
    return result(false, "BRICK_RUNTIME_GUID_INVALID", "guid must be an opaque identifier without spaces", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_GUID_INVALID",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if brick_id <= 0 then
    if guid ~= "" or tag ~= "" then
      local forwarded = copy_table(options)
      if guid ~= "" then forwarded.guid = guid end
      if tag ~= "" then forwarded.tag = tag end
      return BMF.bricks.setRuntimeStateByGuid(forwarded)
    end
    return result(false, "BRICK_RUNTIME_ID_OR_GUID_REQUIRED", "brickid, guid, uuid+purpose, or tag is required for runtime brick-state set", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_ID_OR_GUID_REQUIRED",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end

  local confirm = tostring(options.confirm or "")
  local legacy_tree_confirm = options.legacyTreePhysical == true
  local required_confirm = legacy_tree_confirm and "tree-physical" or "brick-runtime"
  if confirm ~= required_confirm then
    return result(false, "BRICK_RUNTIME_CONFIRM_REQUIRED", "confirm=" .. required_confirm .. " is required for runtime brick-state set", {
      brickId = brick_id,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_CONFIRM_REQUIRED",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
        "required_confirm=" .. required_confirm,
      },
    })
  end
  if not brick_runtime_available() then
    runtime.last_error = "BMFSocket brick runtime helpers are unavailable"
    return result(false, "BRICK_RUNTIME_UNAVAILABLE", runtime.last_error, {
      brickId = brick_id,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_UNAVAILABLE",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
      },
    })
  end
  if not brick_runtime_direct_lookup_enabled() then
    return result(false, "BRICK_RUNTIME_LOOKUP_DISABLED", "explicit runtime brick id set is disabled unless unsafe direct lookup is enabled", {
      brickId = brick_id,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_LOOKUP_DISABLED",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
        "required_env=BMF_BRICK_RUNTIME_UNSAFE_LOOKUP_ENABLED=1",
        "detail=saved BRS brickIndex values are not safe runtime ids; set by GUID or tag requires a live verified runtime binding",
      },
    })
  end

  local visible = brick_runtime_parse_visible_arg(options, legacy_tree_confirm and 0 or -1)
  local collision = brick_runtime_parse_collision_arg(options, legacy_tree_confirm and -1 or -2)
  local context = brick_runtime_parse_context_arg(options)
  local action_source, action_source_source = brick_runtime_parse_action_source_arg(options)
  if collision == -1 and not brick_runtime_collision_restore_enabled() then
    return result(false, "BRICK_RUNTIME_COLLISION_RESTORE_DISABLED", "collision=restore is disabled by default for runtime brick-state set", {
      brickId = brick_id,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_COLLISION_RESTORE_DISABLED",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
        "visible_arg=" .. tostring(visible),
        "collision_channels=" .. tostring(collision),
        "required_env=BMF_BRICK_RUNTIME_COLLISION_RESTORE_ENABLED=1",
        "detail=use collision=unchanged or an explicit numeric collision channel unless captured restore has been live-validated for this server build",
      },
    })
  end
  if context ~= "" and tostring(options.contextconfirm or options.context_confirm or "") ~= "brick-runtime-context" then
    return result(false, "BRICK_RUNTIME_CONTEXT_CONFIRM_REQUIRED", "contextConfirm=brick-runtime-context is required for explicit diagnostic grid contexts", {
      brickId = brick_id,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_CONTEXT_CONFIRM_REQUIRED",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
        "required_context_confirm=brick-runtime-context",
      },
    })
  end
  if visible == -1 and collision == -2 then
    return result(false, "BRICK_RUNTIME_STATE_NOOP", "Provide visible or collision to change runtime brick state", {
      brickId = brick_id,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_STATE_NOOP",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
        "visible_arg=" .. tostring(visible),
        "collision_channels=" .. tostring(collision),
      },
    })
  end

  local unsafe_direct_set = BMF_env_bool("BMF_BRICK_RUNTIME_UNSAFE_SET_DIRECT_ENABLED", false)
    or BMF_env_bool("BMF_BRICK_RUNTIME_UNSAFE_LOOKUP_ENABLED", false)
  local verified_direct_set = guid ~= "" and BMF_brick_runtime_guid_id_verified(guid, brick_id)
  if not unsafe_direct_set and not verified_direct_set then
    return result(false, "BRICK_RUNTIME_ID_UNVERIFIED", "Direct runtime brick-state set requires a BMF-verified runtime id.", {
      brickId = brick_id,
      guid = guid,
      tag = tag,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_ID_UNVERIFIED",
        "brick_id=" .. tostring(brick_id),
        "tag=" .. tag,
        "guid=" .. guid,
        "required_env=BMF_BRICK_RUNTIME_UNSAFE_SET_DIRECT_ENABLED=1",
        "detail=explicit saved brick ids are not safe live runtime ids; direct set requires a BMF-verified runtime id",
      },
    })
  end

  local sequence = brick_runtime_next_sequence()
  local operation = function()
    local ok, response = pcall(BMFSocketBrickPhysicalSet, brick_id, visible, collision, context, action_source)
    brick_runtime_store_result(sequence, "set", brick_id, tag, guid, ok, ok and response or tostring(response))
  end
  if brick_runtime_inline_operations_enabled() then
    operation()
  else
    run_on_game_thread(operation)
  end
  if guid ~= "" then
    BMF_brick_runtime_bind_guid(guid, brick_id)
  end

  return result(true, "OK", "Runtime brick-state set queued on the game thread", {
    queued = true,
    sequence = sequence,
    brickId = brick_id,
    visible = visible,
    collision = collision,
    context = context,
    actionSource = action_source,
    guid = guid,
    lines = {
      "ok=true",
      "code=OK",
      "queued=true",
      "operation=set",
      "execution=" .. (brick_runtime_inline_operations_enabled() and "inline" or "game-thread"),
      "sequence=" .. tostring(sequence),
      "brick_id=" .. tostring(brick_id),
      "tag=" .. tag,
      "guid=" .. guid,
      "visible_arg=" .. tostring(visible),
      "collision_channels=" .. tostring(collision),
      "grid_context_override=" .. tostring(context),
      "action_source_override=" .. tostring(action_source),
      "action_source_source=" .. tostring(action_source_source),
    },
  })
end

function BMF.bricks.bindRuntimeGuidCell(options)
  options = type(options) == "table" and options or {}
  local runtime = state.tools.brick_runtime
  local guid = brick_runtime_canonical_guid_arg(options)
  local tag = brick_runtime_canonical_tag_arg(options, guid)
  local anchor_brick_id = tree_cut_parse_brick_id(options)
  if not BMF_brick_runtime_guid_valid(guid) then
    return result(false, "BRICK_RUNTIME_GUID_INVALID", "guid is required and must be an opaque identifier without spaces", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_GUID_INVALID",
        "guid=" .. tostring(guid or ""),
        "tag=" .. tag,
      },
    })
  end
  if anchor_brick_id <= 0 then
    return result(false, "BRICK_RUNTIME_ID_REQUIRED", "brickid is required for runtime cell binding", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_ID_REQUIRED",
        "guid=" .. guid,
        "tag=" .. tag,
      },
    })
  end
  if tostring(options.confirm or "") ~= "brick-runtime" then
    return result(false, "BRICK_RUNTIME_CONFIRM_REQUIRED", "confirm=brick-runtime is required for runtime cell binding", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_CONFIRM_REQUIRED",
        "guid=" .. guid,
        "tag=" .. tag,
        "anchor_brick_id=" .. tostring(anchor_brick_id),
        "required_confirm=brick-runtime",
      },
    })
  end
  if not brick_runtime_available() then
    runtime.last_error = "BMFSocket brick runtime helpers are unavailable"
    return result(false, "BRICK_RUNTIME_UNAVAILABLE", runtime.last_error, {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_UNAVAILABLE",
        "guid=" .. guid,
        "tag=" .. tag,
        "anchor_brick_id=" .. tostring(anchor_brick_id),
      },
    })
  end
  if not brick_runtime_direct_lookup_enabled() then
    return result(false, "BRICK_RUNTIME_LOOKUP_DISABLED", "runtime cell binding requires unsafe direct lookup to inspect neighboring live ids", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_LOOKUP_DISABLED",
        "guid=" .. guid,
        "tag=" .. tag,
        "anchor_brick_id=" .. tostring(anchor_brick_id),
        "required_env=BMF_BRICK_RUNTIME_UNSAFE_LOOKUP_ENABLED=1",
      },
    })
  end

  local anchor_ok, anchor_fields, _, _, anchor_code = brick_runtime_inspect_fields(anchor_brick_id)
  if not anchor_ok then
    return result(false, anchor_code ~= "" and anchor_code or "BRICK_RUNTIME_ANCHOR_INSPECT_FAILED", "runtime cell anchor inspect failed", {
      lines = {
        "ok=false",
        "code=" .. (anchor_code ~= "" and anchor_code or "BRICK_RUNTIME_ANCHOR_INSPECT_FAILED"),
        "guid=" .. guid,
        "tag=" .. tag,
        "anchor_brick_id=" .. tostring(anchor_brick_id),
        "detail=anchor runtime brick could not be inspected",
      },
    })
  end

  local anchor_cell_index = tonumber(anchor_fields.brick_cell_index)
  if not anchor_cell_index then
    return result(false, "BRICK_RUNTIME_CELL_UNAVAILABLE", "anchor runtime brick did not report a cell index", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_CELL_UNAVAILABLE",
        "guid=" .. guid,
        "tag=" .. tag,
        "anchor_brick_id=" .. tostring(anchor_brick_id),
      },
    })
  end

  local max_span = brick_runtime_bind_cell_max_span(options)
  local ids = {}
  local seen = {}
  local inspected = 0
  local inspect_failed = 0
  local left_boundary = anchor_brick_id
  local right_boundary = anchor_brick_id

  local function add_candidate(brick_id)
    if brick_id > 0 and not seen[brick_id] then
      ids[#ids + 1] = brick_id
      seen[brick_id] = true
    end
  end

  add_candidate(anchor_brick_id)
  inspected = inspected + 1

  for step = 1, max_span do
    local brick_id = anchor_brick_id - step
    if brick_id <= 0 then break end
    local ok, fields = brick_runtime_inspect_fields(brick_id)
    inspected = inspected + 1
    if not ok then
      inspect_failed = inspect_failed + 1
      break
    end
    if tonumber(fields.brick_cell_index) ~= anchor_cell_index then
      break
    end
    left_boundary = brick_id
    add_candidate(brick_id)
  end

  for step = 1, max_span do
    local brick_id = anchor_brick_id + step
    local ok, fields = brick_runtime_inspect_fields(brick_id)
    inspected = inspected + 1
    if not ok then
      inspect_failed = inspect_failed + 1
      break
    end
    if tonumber(fields.brick_cell_index) ~= anchor_cell_index then
      break
    end
    right_boundary = brick_id
    add_candidate(brick_id)
  end

  table.sort(ids)
  local max_bindings = BMF_brick_runtime_guid_max_bindings()
  local truncated = false
  if #ids > max_bindings then
    table.sort(ids, function(a, b)
      local da = math.abs(a - anchor_brick_id)
      local db = math.abs(b - anchor_brick_id)
      if da == db then return a < b end
      return da < db
    end)
    while #ids > max_bindings do
      table.remove(ids)
      truncated = true
    end
    table.sort(ids)
  end

  local replace = option_boolean(options, "replace", true)
  if replace then
    brick_runtime_clear_guid_binding(guid)
  end

  local bound = 0
  local failed = 0
  for _, brick_id in ipairs(ids) do
    local ok = BMF_brick_runtime_bind_guid(guid, brick_id, "verified")
    if ok then
      bound = bound + 1
    else
      failed = failed + 1
    end
  end

  local binding = BMF_brick_runtime_guid_binding(guid, false)
  local lines = BMF_brick_runtime_format_guid_binding_lines(guid, binding)
  lines[1] = "ok=" .. tostring(failed == 0 and bound > 0)
  lines[2] = "code=" .. (failed == 0 and bound > 0 and "OK" or "BRICK_RUNTIME_CELL_BIND_FAILED")
  lines[#lines + 1] = "operation=bind-cell"
  lines[#lines + 1] = "guid=" .. guid
  lines[#lines + 1] = "tag=" .. tag
  lines[#lines + 1] = "anchor_brick_id=" .. tostring(anchor_brick_id)
  lines[#lines + 1] = "anchor_cell_index=" .. tostring(math.floor(anchor_cell_index))
  lines[#lines + 1] = "anchor_runtime_x=" .. tostring(anchor_fields.runtime_x or "")
  lines[#lines + 1] = "anchor_runtime_y=" .. tostring(anchor_fields.runtime_y or "")
  lines[#lines + 1] = "anchor_runtime_z=" .. tostring(anchor_fields.runtime_z or "")
  lines[#lines + 1] = "left_boundary_brick_id=" .. tostring(left_boundary)
  lines[#lines + 1] = "right_boundary_brick_id=" .. tostring(right_boundary)
  lines[#lines + 1] = "max_span=" .. tostring(max_span)
  lines[#lines + 1] = "inspected=" .. tostring(inspected)
  lines[#lines + 1] = "inspect_failed=" .. tostring(inspect_failed)
  lines[#lines + 1] = "bound_requested=" .. tostring(#ids)
  lines[#lines + 1] = "bound_added=" .. tostring(bound)
  lines[#lines + 1] = "bind_failed=" .. tostring(failed)
  lines[#lines + 1] = "replace=" .. tostring(replace == true)
  lines[#lines + 1] = "truncated=" .. tostring(truncated == true)
  lines[#lines + 1] = "max_bindings=" .. tostring(max_bindings)
  write_status()
  return result(failed == 0 and bound > 0, failed == 0 and bound > 0 and "OK" or "BRICK_RUNTIME_CELL_BIND_FAILED", failed == 0 and bound > 0 and "Runtime brick cell binding updated" or "Runtime brick cell binding failed", {
    guid = guid,
    bound = bound,
    failed = failed,
    lines = lines,
  })
end

function BMF.bricks.bindRuntimeGuid(options)
  options = type(options) == "table" and options or {}
  local runtime = state.tools.brick_runtime
  local guid = brick_runtime_canonical_guid_arg(options)
  local tag = brick_runtime_canonical_tag_arg(options, guid)
  if not BMF_brick_runtime_guid_valid(guid) then
    return result(false, "BRICK_RUNTIME_GUID_INVALID", "guid is required and must be an opaque identifier without spaces", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_GUID_INVALID",
        "guid=" .. guid,
        "tag=" .. tag,
      },
    })
  end

  local ids = BMF_brick_runtime_parse_brick_ids(options)
  if #ids == 0 then
    if not brick_runtime_available() then
      runtime.last_error = "BMFSocket brick runtime helpers are unavailable"
      return result(false, "BRICK_RUNTIME_UNAVAILABLE", runtime.last_error, {
        guid = guid,
        lines = {
          "ok=false",
          "code=BRICK_RUNTIME_UNAVAILABLE",
          "guid=" .. guid,
          "tag=" .. tag,
        },
      })
    end

    local sequence = brick_runtime_next_sequence()
    local operation = function()
      local resolved, lines = brick_runtime_resolve_id_on_game_thread(options, guid, tag)
      if resolved and resolved > 0 then
        lines[#lines + 1] = "operation=bind-guid"
        lines[#lines + 1] = "bound_requested=1"
        lines[#lines + 1] = "bound_added=1"
        lines[#lines + 1] = "bind_failed=0"
      else
        lines[#lines + 1] = "operation=bind-guid"
        lines[#lines + 1] = "bound_requested=1"
        lines[#lines + 1] = "bound_added=0"
        lines[#lines + 1] = "bind_failed=1"
      end
      brick_runtime_store_result(sequence, "bind-guid", resolved or 0, tag, guid, true, table.concat(lines, "\n"))
    end
    if brick_runtime_inline_operations_enabled() then
      operation()
    else
      run_on_game_thread(operation)
    end

    return result(true, "OK", "Runtime brick GUID lookup/bind queued on the game thread", {
      queued = true,
      sequence = sequence,
      guid = guid,
      tag = tag,
      lines = {
        "ok=true",
        "code=OK",
        "queued=true",
        "operation=bind-guid",
        "execution=" .. (brick_runtime_inline_operations_enabled() and "inline" or "game-thread"),
        "sequence=" .. tostring(sequence),
        "guid=" .. guid,
        "tag=" .. tag,
      },
    })
  end

  local bound = 0
  local failed = 0
  local rejected_unverified = 0
  local unsafe_explicit_bind = BMF_env_bool("BMF_BRICK_RUNTIME_UNSAFE_BIND_ENABLED", false)
    or BMF_env_bool("BMF_BRICK_RUNTIME_UNSAFE_LOOKUP_ENABLED", false)
  for _, brick_id in ipairs(ids) do
    if not unsafe_explicit_bind and not BMF_brick_runtime_guid_id_verified(guid, brick_id) then
      failed = failed + 1
      rejected_unverified = rejected_unverified + 1
    else
      local ok = BMF_brick_runtime_bind_guid(guid, brick_id, unsafe_explicit_bind and "unsafe-explicit" or "verified")
      if ok then
        bound = bound + 1
      else
        failed = failed + 1
      end
    end
  end

  local binding = BMF_brick_runtime_guid_binding(guid, false)
  local lines = BMF_brick_runtime_format_guid_binding_lines(guid, binding)
  local code = failed == 0 and "OK" or rejected_unverified > 0 and "BRICK_RUNTIME_GUID_BIND_UNVERIFIED" or "BRICK_RUNTIME_GUID_BIND_PARTIAL"
  lines[1] = "ok=" .. tostring(failed == 0)
  lines[2] = "code=" .. code
  lines[#lines + 1] = "operation=bind-guid"
  lines[#lines + 1] = "bound_requested=" .. tostring(#ids)
  lines[#lines + 1] = "bound_added=" .. tostring(bound)
  lines[#lines + 1] = "bind_failed=" .. tostring(failed)
  lines[#lines + 1] = "rejected_unverified=" .. tostring(rejected_unverified)
  if rejected_unverified > 0 and not unsafe_explicit_bind then
    lines[#lines + 1] = "required_env=BMF_BRICK_RUNTIME_UNSAFE_BIND_ENABLED=1"
    lines[#lines + 1] = "detail=explicit saved brick ids are not safe live runtime ids; bind requires a BMF-verified runtime id"
  end
  return result(failed == 0, code, failed == 0 and "Runtime brick GUID binding updated" or "Runtime brick GUID binding rejected unverified brick ids", {
    guid = guid,
    bound = bound,
    failed = failed,
    lines = lines,
  })
end

function BMF.bricks.runtimeGuidStatus(options)
  options = type(options) == "table" and options or {}
  local guid = brick_runtime_canonical_guid_arg(options)
  local runtime = state.tools.brick_runtime
  runtime.guid_bindings = runtime.guid_bindings or {}
  runtime.guid_binding_order = runtime.guid_binding_order or {}

  if guid ~= "" then
    if not BMF_brick_runtime_guid_valid(guid) then
      return result(false, "BRICK_RUNTIME_GUID_INVALID", "guid must be an opaque identifier without spaces", {
        guid = guid,
        lines = {
          "ok=false",
          "code=BRICK_RUNTIME_GUID_INVALID",
          "guid=" .. guid,
        },
      })
    end
    local binding = BMF_brick_runtime_guid_binding(guid, false)
    if not binding then
      return result(false, "BRICK_RUNTIME_GUID_NOT_BOUND", "No runtime bricks are bound for this GUID.", {
        guid = guid,
        lines = {
          "ok=false",
          "code=BRICK_RUNTIME_GUID_NOT_BOUND",
          "guid=" .. guid,
          "bound_bricks=0",
        },
      })
    end
    return result(true, "OK", "Runtime brick GUID binding collected", {
      guid = guid,
      lines = BMF_brick_runtime_format_guid_binding_lines(guid, binding),
    })
  end

  local lines = {
    "ok=true",
    "code=OK",
    "guid_count=" .. tostring(#runtime.guid_binding_order),
  }
  for index, value in ipairs(runtime.guid_binding_order) do
    local binding = runtime.guid_bindings[value]
    lines[#lines + 1] = "guid." .. tostring(index) .. "=" .. tostring(value)
    lines[#lines + 1] = "guid." .. tostring(index) .. ".bound_bricks=" .. tostring(binding and #binding.ids or 0)
  end
  return result(true, "OK", "Runtime brick GUID bindings collected", {
    lines = lines,
  })
end

function BMF.bricks.forgetRuntimeGuid(options)
  options = type(options) == "table" and options or {}
  local guid = brick_runtime_canonical_guid_arg(options)
  local runtime = state.tools.brick_runtime
  runtime.guid_bindings = runtime.guid_bindings or {}
  runtime.guid_binding_order = runtime.guid_binding_order or {}

  if not BMF_brick_runtime_guid_valid(guid) then
    return result(false, "BRICK_RUNTIME_GUID_INVALID", "guid must be an opaque identifier without spaces", {
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_GUID_INVALID",
        "guid=" .. tostring(guid or ""),
      },
    })
  end

  local existed = runtime.guid_bindings[guid] ~= nil
  runtime.guid_bindings[guid] = nil
  for index = #runtime.guid_binding_order, 1, -1 do
    if runtime.guid_binding_order[index] == guid then
      table.remove(runtime.guid_binding_order, index)
    end
  end

  return result(true, "OK", existed and "Runtime brick GUID binding cleared" or "Runtime brick GUID binding was not present", {
    guid = guid,
    existed = existed,
    lines = {
      "ok=true",
      "code=OK",
      "guid=" .. guid,
      "existed=" .. tostring(existed),
      "bound_bricks=0",
      "operation=forget-guid",
    },
  })
end

function BMF.bricks.setRuntimeStateByGuid(options)
  options = type(options) == "table" and options or {}
  local runtime = state.tools.brick_runtime
  local guid = brick_runtime_canonical_guid_arg(options)
  if not BMF_brick_runtime_guid_valid(guid) then
    return result(false, "BRICK_RUNTIME_GUID_INVALID", "guid is required and must be an opaque identifier without spaces", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_GUID_INVALID",
        "guid=" .. guid,
      },
    })
  end

  local confirm = tostring(options.confirm or "")
  if confirm ~= "brick-runtime" then
    return result(false, "BRICK_RUNTIME_CONFIRM_REQUIRED", "confirm=brick-runtime is required for runtime brick-state set", {
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_CONFIRM_REQUIRED",
        "guid=" .. guid,
        "required_confirm=brick-runtime",
      },
    })
  end
  if not brick_runtime_available() then
    runtime.last_error = "BMFSocket brick runtime helpers are unavailable"
    return result(false, "BRICK_RUNTIME_UNAVAILABLE", runtime.last_error, {
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_UNAVAILABLE",
        "guid=" .. guid,
      },
    })
  end

  local visible = brick_runtime_parse_visible_arg(options, -1)
  local collision = brick_runtime_parse_collision_arg(options, -2)
  local context = brick_runtime_parse_context_arg(options)
  local action_source, action_source_source = brick_runtime_parse_action_source_arg(options)
  if collision == -1 and not brick_runtime_collision_restore_enabled() then
    return result(false, "BRICK_RUNTIME_COLLISION_RESTORE_DISABLED", "collision=restore is disabled by default for runtime brick-state set", {
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_COLLISION_RESTORE_DISABLED",
        "guid=" .. guid,
        "visible_arg=" .. tostring(visible),
        "collision_channels=" .. tostring(collision),
        "required_env=BMF_BRICK_RUNTIME_COLLISION_RESTORE_ENABLED=1",
        "detail=use collision=unchanged or an explicit numeric collision channel unless captured restore has been live-validated for this server build",
      },
    })
  end
  if context ~= "" and tostring(options.contextconfirm or options.context_confirm or "") ~= "brick-runtime-context" then
    return result(false, "BRICK_RUNTIME_CONTEXT_CONFIRM_REQUIRED", "contextConfirm=brick-runtime-context is required for explicit diagnostic grid contexts", {
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_CONTEXT_CONFIRM_REQUIRED",
        "guid=" .. guid,
        "required_context_confirm=brick-runtime-context",
      },
    })
  end
  if visible == -1 and collision == -2 then
    return result(false, "BRICK_RUNTIME_STATE_NOOP", "Provide visible or collision to change runtime brick state", {
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_STATE_NOOP",
        "guid=" .. guid,
        "visible_arg=" .. tostring(visible),
        "collision_channels=" .. tostring(collision),
      },
    })
  end

  local tag = brick_runtime_canonical_tag_arg(options, guid)
  local binding = BMF_brick_runtime_guid_binding(guid, false)
  if not binding or #binding.ids == 0 then
    if not brick_runtime_resolve_native_path_enabled() then
      return result(false, "BRICK_RUNTIME_GUID_UNBOUND", "No runtime bricks are bound for this GUID and native runtime resolve is disabled", {
        guid = guid,
        tag = tag,
        lines = {
          "ok=false",
          "code=BRICK_RUNTIME_GUID_UNBOUND",
          "guid=" .. guid,
          "tag=" .. tag,
          "bound_bricks=0",
          "lookup_queued=false",
          "detail=native runtime brick resolve is disabled; bind this GUID from a verified native hit or enable unsafe resolve only for isolated validation",
        },
      })
    end

    local sequence = brick_runtime_next_sequence()
    local operation = function()
      local resolved, resolve_lines = brick_runtime_resolve_id_on_game_thread(options, guid, tag)
      if not resolved or resolved <= 0 then
        brick_runtime_store_result(sequence, "set-guid", 0, tag, guid, true, table.concat(resolve_lines, "\n"))
        return
      end

      local lines = {
        "Brick runtime GUID state",
        "source=BMF",
        "operation=set-guid",
        "guid=" .. guid,
        "tag=" .. tag,
        "requested_visible_arg=" .. tostring(visible),
        "requested_collision_channels=" .. tostring(collision),
        "requested_grid_context_override=" .. tostring(context),
        "requested_action_source_override=" .. tostring(action_source),
        "action_source_source=" .. tostring(action_source_source),
        "bound_bricks=1",
      }
      for index, line in ipairs(resolve_lines or {}) do
        lines[#lines + 1] = "lookup." .. tostring(index) .. "=" .. tostring(line)
      end

      if brick_runtime_batch_available() then
        local ok, response = pcall(BMFSocketBrickPhysicalSetMany, tostring(resolved), visible, collision, context, action_source)
        brick_runtime_store_result(sequence, "set-guid", resolved, tag, guid, ok, ok and response or tostring(response))
        return
      end

      local ok, response = pcall(BMFSocketBrickPhysicalSet, resolved, visible, collision, context, action_source)
      local item_lines, fields = tree_cut_native_status_lines(ok and response or tostring(response))
      local item_ok = ok == true and tostring(fields.ok or "") == "true"
      local code = tostring(fields.code or (ok and "" or "LUA_ERROR"))
      lines[#lines + 1] = "item.1.brick_id=" .. tostring(resolved)
      lines[#lines + 1] = "item.1.ok=" .. tostring(item_ok == true)
      lines[#lines + 1] = "item.1.code=" .. code
      lines[#lines + 1] = "item.1.visibility_set_method=" .. tostring(fields.visibility_set_method or "")
      lines[#lines + 1] = "item.1.collision_set_method=" .. tostring(fields.collision_set_method or "")
      lines[#lines + 1] = "item.1.after_visible=" .. tostring(fields.after_visible or "")
      lines[#lines + 1] = "item.1.after_collision_channels=" .. tostring(fields.after_collision_channels or "")
      if not item_ok and #item_lines > 0 then
        lines[#lines + 1] = "item.1.detail=" .. tostring(fields.detail or code)
      end
      lines[#lines + 1] = "ok=" .. tostring(item_ok == true)
      lines[#lines + 1] = "code=" .. (item_ok and "OK" or code ~= "" and code or "BRICK_RUNTIME_GUID_SET_FAILED")
      lines[#lines + 1] = "attempted=1"
      lines[#lines + 1] = "succeeded=" .. tostring(item_ok and 1 or 0)
      lines[#lines + 1] = "failed=" .. tostring(item_ok and 0 or 1)
      lines[#lines + 1] = "pending=" .. tostring(code == "BRICK_GRID_CONTEXT_SCAN_PENDING" and 1 or 0)
      brick_runtime_store_result(sequence, "set-guid", resolved, tag, guid, true, table.concat(lines, "\n"))
    end
    if brick_runtime_inline_operations_enabled() then
      operation()
    else
      run_on_game_thread(operation)
    end

    return result(true, "OK", "Runtime brick-state GUID lookup/set queued on the game thread", {
      queued = true,
      sequence = sequence,
      guid = guid,
      tag = tag,
      visible = visible,
      collision = collision,
      context = context,
      lines = {
        "ok=true",
        "code=OK",
        "queued=true",
        "operation=set-guid",
        "execution=" .. (brick_runtime_inline_operations_enabled() and "inline" or "game-thread"),
        "sequence=" .. tostring(sequence),
        "guid=" .. guid,
        "tag=" .. tag,
        "bound_bricks=0",
        "lookup_queued=true",
        "visible_arg=" .. tostring(visible),
        "collision_channels=" .. tostring(collision),
        "grid_context_override=" .. tostring(context),
        "action_source_override=" .. tostring(action_source),
        "action_source_source=" .. tostring(action_source_source),
      },
    })
  end

  local ids = {}
  local skipped_unverified = 0
  local unsafe_bound_set = BMF_env_bool("BMF_BRICK_RUNTIME_UNSAFE_SET_BOUND_ENABLED", false)
    or BMF_env_bool("BMF_BRICK_RUNTIME_UNSAFE_LOOKUP_ENABLED", false)
  for _, brick_id in ipairs(binding.ids) do
    if unsafe_bound_set or BMF_brick_runtime_guid_id_verified(guid, brick_id) then
      ids[#ids + 1] = brick_id
    else
      skipped_unverified = skipped_unverified + 1
    end
  end
  if #ids == 0 then
    return result(false, "BRICK_RUNTIME_GUID_UNVERIFIED", "No BMF-verified runtime bricks are bound for this GUID.", {
      guid = guid,
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_GUID_UNVERIFIED",
        "guid=" .. guid,
        "tag=" .. tag,
        "bound_bricks=" .. tostring(#binding.ids),
        "verified_bricks=0",
        "skipped_unverified=" .. tostring(skipped_unverified),
        "required_env=BMF_BRICK_RUNTIME_UNSAFE_SET_BOUND_ENABLED=1",
        "detail=explicit saved brick ids are not safe live runtime ids; set requires a BMF-verified runtime id",
      },
    })
  end
  local sequence = brick_runtime_next_sequence()
  local operation = function()
    if brick_runtime_batch_available() then
      local ids_csv = table.concat(ids, ",")
      local ok, response = pcall(BMFSocketBrickPhysicalSetMany, ids_csv, visible, collision, context, action_source)
      brick_runtime_store_result(sequence, "set-guid", 0, tag, guid, ok, ok and response or tostring(response))
      return
    end

    if #ids > 1 then
        local lines = {
          "Brick runtime GUID state",
          "source=BMF",
          "operation=set-guid",
          "guid=" .. guid,
          "tag=" .. tag,
          "requested_visible_arg=" .. tostring(visible),
          "requested_collision_channels=" .. tostring(collision),
          "requested_grid_context_override=" .. tostring(context),
          "requested_action_source_override=" .. tostring(action_source),
          "action_source_source=" .. tostring(action_source_source),
          "bound_bricks=" .. tostring(#ids),
          "skipped_unverified=" .. tostring(skipped_unverified),
          "ok=false",
          "code=BRICK_RUNTIME_BATCH_UNAVAILABLE",
          "attempted=0",
          "succeeded=0",
          "failed=" .. tostring(#ids),
          "pending=0",
          "detail=BMFSocketBrickPhysicalSetMany is required for multi-brick runtime GUID mutation",
        }
        brick_runtime_store_result(sequence, "set-guid", 0, tag, guid, true, table.concat(lines, "\n"))
        return
    end

    local lines = {
      "Brick runtime GUID state",
      "source=BMF",
      "operation=set-guid",
      "guid=" .. guid,
      "tag=" .. tag,
      "requested_visible_arg=" .. tostring(visible),
      "requested_collision_channels=" .. tostring(collision),
      "requested_grid_context_override=" .. tostring(context),
      "requested_action_source_override=" .. tostring(action_source),
      "action_source_source=" .. tostring(action_source_source),
      "bound_bricks=" .. tostring(#ids),
      "skipped_unverified=" .. tostring(skipped_unverified),
    }
    local attempted = 0
    local succeeded = 0
    local failed = 0
    local pending = 0
    for index, brick_id in ipairs(ids) do
      attempted = attempted + 1
      local ok, response = pcall(BMFSocketBrickPhysicalSet, brick_id, visible, collision, context, action_source)
      local item_lines, fields = tree_cut_native_status_lines(ok and response or tostring(response))
      local item_ok = ok == true and tostring(fields.ok or "") == "true"
      local code = tostring(fields.code or (ok and "" or "LUA_ERROR"))
      if item_ok then
        succeeded = succeeded + 1
      else
        failed = failed + 1
        if code == "BRICK_GRID_CONTEXT_SCAN_PENDING" then
          pending = pending + 1
        end
      end
      lines[#lines + 1] = "item." .. tostring(index) .. ".brick_id=" .. tostring(brick_id)
      lines[#lines + 1] = "item." .. tostring(index) .. ".ok=" .. tostring(item_ok == true)
      lines[#lines + 1] = "item." .. tostring(index) .. ".code=" .. code
      lines[#lines + 1] = "item." .. tostring(index) .. ".visibility_set_method=" .. tostring(fields.visibility_set_method or "")
      lines[#lines + 1] = "item." .. tostring(index) .. ".collision_set_method=" .. tostring(fields.collision_set_method or "")
      lines[#lines + 1] = "item." .. tostring(index) .. ".after_visible=" .. tostring(fields.after_visible or "")
      lines[#lines + 1] = "item." .. tostring(index) .. ".after_collision_channels=" .. tostring(fields.after_collision_channels or "")
      if not item_ok and #item_lines > 0 then
        lines[#lines + 1] = "item." .. tostring(index) .. ".detail=" .. tostring(fields.detail or code)
      end
    end
    local code = failed == 0 and "OK" or pending > 0 and "BRICK_GRID_CONTEXT_SCAN_PENDING" or succeeded > 0 and "BRICK_RUNTIME_GUID_SET_PARTIAL" or "BRICK_RUNTIME_GUID_SET_FAILED"
    lines[#lines + 1] = "ok=" .. tostring(failed == 0)
    lines[#lines + 1] = "code=" .. code
    lines[#lines + 1] = "attempted=" .. tostring(attempted)
    lines[#lines + 1] = "succeeded=" .. tostring(succeeded)
    lines[#lines + 1] = "failed=" .. tostring(failed)
    lines[#lines + 1] = "pending=" .. tostring(pending)
    brick_runtime_store_result(sequence, "set-guid", 0, tag, guid, true, table.concat(lines, "\n"))
  end
  if brick_runtime_inline_operations_enabled() then
    operation()
  else
    run_on_game_thread(operation)
  end

  return result(true, "OK", "Runtime brick-state set by GUID queued on the game thread", {
    queued = true,
    sequence = sequence,
    guid = guid,
    visible = visible,
    collision = collision,
    context = context,
    lines = {
      "ok=true",
      "code=OK",
      "queued=true",
      "operation=set-guid",
      "execution=" .. (brick_runtime_inline_operations_enabled() and "inline" or "game-thread"),
      "sequence=" .. tostring(sequence),
      "guid=" .. guid,
      "tag=" .. tag,
      "bound_bricks=" .. tostring(#ids),
      "visible_arg=" .. tostring(visible),
      "collision_channels=" .. tostring(collision),
      "grid_context_override=" .. tostring(context),
      "action_source_override=" .. tostring(action_source),
      "action_source_source=" .. tostring(action_source_source),
    },
  })
end

function BMF.bricks.runtimeStateStatus()
  local last = state.tools.brick_runtime.last_result
  if type(last) ~= "table" then
    return result(false, "BRICK_RUNTIME_NO_RESULT", "No runtime brick-state operation has completed yet.", {
      lines = {
        "ok=false",
        "code=BRICK_RUNTIME_NO_RESULT",
      },
    })
  end
  local lines = {
    "sequence=" .. tostring(last.sequence or ""),
    "operation=" .. tostring(last.operation or ""),
    "brick_id=" .. tostring(last.brickId or ""),
    "tag=" .. tostring(last.tag or ""),
    "guid=" .. tostring(last.guid or ""),
    "completed_at=" .. tostring(last.at or ""),
  }
  for _, line in ipairs(last.lines or {}) do
    lines[#lines + 1] = tostring(line)
  end
  return result(last.ok == true, last.ok == true and "OK" or tostring(last.code or "BRICK_RUNTIME_FAILED"), "Last runtime brick-state operation result", {
    last = copy_table(last),
    fields = copy_table(last.fields or {}),
    lines = lines,
  })
end

function BMF.tools.treeCutNative.start(options)
  options = type(options) == "table" and options or {}
  local native = state.tools.tree_cut_native
  native.available = tree_cut_native_available()
  if not native.available then
    native.last_error = "BMFSocket resource native helpers are unavailable"
    return result(false, "TREE_CUT_NATIVE_UNAVAILABLE", native.last_error, {
      lines = {
        "available=false",
        "enabled=false",
        "started=false",
        "last_error=" .. native.last_error,
      },
    })
  end

  local ok, started_or_error, status = pcall(BMFSocketResourceNativeStart or BMFSocketTreeCutStart)
  if not ok or started_or_error == false then
    native.last_error = tostring(status or started_or_error or "BMFSocketResourceNativeStart failed")
    return result(false, "TREE_CUT_NATIVE_START_FAILED", native.last_error, {
      lines = {
        "available=true",
        "enabled=false",
        "started=false",
        "last_error=" .. native.last_error,
      },
    })
  end

  native.last_started_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  local lines, fields = tree_cut_native_update_status(status or "")
  local auto_refresh = options.refreshTargets ~= false and BMF_env_bool("BMF_RESOURCE_TARGET_AUTO_REFRESH", BMF_env_bool("BMF_TREECUT_TARGET_AUTO_REFRESH", false))
  if auto_refresh and tree_cut_target_resolver_available() then
    local delay_ms = BMF_env_number("BMF_RESOURCE_TARGET_REFRESH_DELAY_MS", BMF_env_number("BMF_TREECUT_TARGET_REFRESH_DELAY_MS", 3000, 0), 0)
    local scheduled = BMF_schedule_delayed_callback("tree_cut_target_refresh", delay_ms, function()
      run_on_game_thread(function()
        local refresh_ok, refresh_result = pcall(BMF.tools.resourceNative.refreshTargets, {
          reason = tostring(options.reason or "start") .. "-auto",
        })
        if not refresh_ok or not refresh_result or refresh_result.ok ~= true then
          local detail = refresh_ok and tostring(refresh_result and refresh_result.message or "unknown") or tostring(refresh_result)
          log("warn", "resource target auto-refresh failed: " .. detail)
        else
          log("info", "resource target cache auto-refreshed")
        end
      end)
      return true
    end)
    if not scheduled then
      log("warn", "resource target auto-refresh was not scheduled")
    end
  end
  log("info", "resource native capture started reason=" .. tostring(options.reason or "manual"))
  write_status()
  return result(true, "OK", "Resource native capture started", {
    fields = fields,
    lines = lines,
  })
end

function BMF.tools.treeCutNative.stop(options)
  options = type(options) == "table" and options or {}
  local native = state.tools.tree_cut_native
  if not tree_cut_native_available() then
    native.available = false
    native.enabled = false
    native.last_error = "BMFSocket resource native helpers are unavailable"
    return result(false, "TREE_CUT_NATIVE_UNAVAILABLE", native.last_error, {
      lines = {
        "available=false",
        "enabled=false",
        "started=false",
      },
    })
  end

  local ok, stopped_or_error, status = pcall(BMFSocketResourceNativeStop or BMFSocketTreeCutStop)
  if not ok or stopped_or_error == false then
    native.last_error = tostring(status or stopped_or_error or "BMFSocketResourceNativeStop failed")
    return result(false, "TREE_CUT_NATIVE_STOP_FAILED", native.last_error, {
      lines = {
        "available=true",
        "last_error=" .. native.last_error,
      },
    })
  end

  local lines, fields = tree_cut_native_update_status(status or "")
  log("info", "resource native capture stopped reason=" .. tostring(options.reason or "manual"))
  write_status()
  return result(true, "OK", "Resource native capture stopped", {
    fields = fields,
    lines = lines,
  })
end

function BMF.tools.treeCutNative.status()
  local native = state.tools.tree_cut_native
  native.available = tree_cut_native_available()
  if not native.available then
    return result(false, "TREE_CUT_NATIVE_UNAVAILABLE", "BMFSocket resource native helpers are unavailable", {
      lines = {
        "available=false",
        "enabled=false",
        "started=false",
      },
    })
  end

  local ok, status_or_error = pcall(BMFSocketResourceNativeStatus or BMFSocketTreeCutStatus)
  if not ok then
    native.last_error = tostring(status_or_error or "BMFSocketResourceNativeStatus failed")
    return result(false, "TREE_CUT_NATIVE_STATUS_FAILED", native.last_error, {
      lines = {
        "available=true",
        "last_error=" .. native.last_error,
      },
    })
  end

  local lines, fields = tree_cut_native_update_status(status_or_error or "")
  return result(true, "OK", "Resource native status collected", {
    fields = fields,
    lines = lines,
  })
end

function BMF.tools.treeCutNative.refreshTargets(options)
  options = type(options) == "table" and options or {}
  local native = state.tools.tree_cut_native
  native.available = tree_cut_native_available()
  if not native.available or not tree_cut_target_resolver_available() then
    native.last_error = "BMFSocket resource target resolver helpers are unavailable"
    return result(false, "TREE_CUT_TARGET_RESOLVER_UNAVAILABLE", native.last_error, {
      lines = {
        "available=" .. tostring(native.available == true),
        "target_resolver_available=" .. tostring(tree_cut_target_resolver_available()),
        "last_error=" .. native.last_error,
      },
    })
  end

  local ok, refreshed_or_error, status = pcall(BMFSocketResourceNativeRefreshTargets or BMFSocketTreeCutRefreshTargets)
  if not ok or refreshed_or_error == false then
    local lines, fields = tree_cut_native_update_status(status or "")
    native.last_error = fields.last_error or tostring(status or refreshed_or_error or "BMFSocketResourceNativeRefreshTargets failed")
    if native.last_error == "" then
      native.last_error = "BMFSocket resource target refresh failed"
    end
    return result(false, "TREE_CUT_TARGET_REFRESH_FAILED", native.last_error, {
      fields = fields,
      lines = {
        "available=true",
        "target_resolver_available=true",
        "last_error=" .. native.last_error,
      },
    })
  end

  native.last_target_refresh_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  local lines, fields = tree_cut_native_update_status(status or "")
  write_status()
  return result(true, "OK", "Resource target cache refreshed", {
    fields = fields,
    lines = lines,
  })
end

function BMF.tools.treeCutNative.findTag(options)
  options = type(options) == "table" and options or {}
  local positional = type(options._positional) == "table" and options._positional or {}
  local tag = trim_string(options.tag or options.lookup or options.resourceId or options.resourceid or options.treeId or options.treeid or options.mineId or options.mineid or positional[1] or "")
  if tag == "" then
    return result(false, "TREE_CUT_FIND_TAG_REQUIRED", "lookup ConsoleTag is required", {
      lines = {
        "available=" .. tostring(tree_cut_tag_lookup_available()),
        "code=TREE_CUT_FIND_TAG_REQUIRED",
        "tag=",
      },
    })
  end

  local native = state.tools.tree_cut_native
  native.available = tree_cut_native_available()
  if not tree_cut_tag_lookup_available() then
    native.last_error = "BMFSocket resource tag lookup helper is unavailable"
    return result(false, "TREE_CUT_TAG_LOOKUP_UNAVAILABLE", native.last_error, {
      tag = tag,
      lines = {
        "available=" .. tostring(native.available == true),
        "tag_lookup_available=false",
        "tag=" .. tag,
        "last_error=" .. native.last_error,
      },
    })
  end

  local limit = tonumber(options.limit or options.maxResults or options.maxresults or 8) or 8
  if limit < 1 then
    limit = 1
  elseif limit > 32 then
    limit = 32
  end
  local max_scan = tonumber(options.maxScan or options.maxscan or options.max or 250000) or 250000
  if max_scan < 1 then
    max_scan = 250000
  end

  local ok, response = pcall(BMFSocketResourceNativeFindTag or BMFSocketTreeCutFindTag, tag, limit, max_scan)
  if not ok then
    native.last_error = tostring(response or "BMFSocketResourceNativeFindTag failed")
    return result(false, "TREE_CUT_TAG_LOOKUP_FAILED", native.last_error, {
      tag = tag,
      lines = {
        "available=true",
        "tag_lookup_available=true",
        "tag=" .. tag,
        "last_error=" .. native.last_error,
      },
    })
  end

  local lines, fields = tree_cut_native_status_lines(response or "")
  local matches = tonumber(fields.matches or 0) or 0
  return result(true, "OK", "Resource ConsoleTag lookup completed", {
    tag = tag,
    matches = matches,
    fields = fields,
    lines = lines,
  })
end

function BMF.tools.treeCutNative.inspectPhysical(options)
  return BMF.bricks.inspectRuntimeState(options)
end

function BMF.tools.treeCutNative.setPhysical(options)
  options = type(options) == "table" and options or {}
  local forwarded = copy_table(options)
  forwarded.legacyTreePhysical = true
  return BMF.bricks.setRuntimeState(forwarded)
end

function BMF.tools.treeCutNative.physicalStatus()
  return BMF.bricks.runtimeStateStatus()
end

function BMF.tools.treeCutNative.resolveHandaxe(options)
  options = type(options) == "table" and options or {}
  local native = state.tools.tree_cut_native
  native.available = tree_cut_native_available()
  if not native.available or not tree_cut_handaxe_resolver_available() then
    native.last_error = "BMFSocket resource tool resolver helpers are unavailable"
    return result(false, "TREE_CUT_HANDAXE_RESOLVER_UNAVAILABLE", native.last_error, {
      lines = {
        "available=" .. tostring(native.available == true),
        "resolver_available=" .. tostring(tree_cut_handaxe_resolver_available()),
        "last_error=" .. native.last_error,
      },
    })
  end

  local detail_lines = {
    "available=true",
    "resolver_available=true",
    "reason=" .. tostring(options.reason or "command"),
  }

  local loaded = 0
  local load_errors = 0
  local load_assets = options.loadAsset == true or tostring(options.loadAsset or options.loadasset or ""):lower() == "true" or tostring(options.loadasset or "") == "1"
  if load_assets and type(LoadAsset) == "function" then
    for _, asset_path in ipairs(TREE_CUT_HANDAXE_ASSET_CANDIDATES) do
      local ok, err = pcall(LoadAsset, asset_path)
      if ok then
        loaded = loaded + 1
        detail_lines[#detail_lines + 1] = "load_asset_ok=" .. tostring(asset_path)
      else
        load_errors = load_errors + 1
        detail_lines[#detail_lines + 1] = "load_asset_error=" .. tostring(asset_path) .. "|" .. tostring(err)
      end
    end
  elseif load_assets then
    detail_lines[#detail_lines + 1] = "load_asset_error=LoadAsset unavailable"
  else
    detail_lines[#detail_lines + 1] = "load_asset_skipped=true"
  end

  local static_hits = 0
  local set_attempts = 0
  local set_errors = 0
  if type(StaticFindObject) == "function" then
    for _, candidate in ipairs(TREE_CUT_HANDAXE_CLASS_CANDIDATES) do
      local find_ok, object = pcall(StaticFindObject, candidate)
      if find_ok and tree_cut_native_object_valid(object) then
        static_hits = static_hits + 1
        local address = tree_cut_native_object_address(object)
        detail_lines[#detail_lines + 1] = "static_find_hit=" .. tostring(candidate) .. "|address=" .. tostring(address)
        if address ~= "" then
          set_attempts = set_attempts + 1
          local set_ok, accepted_or_error, status = pcall(
            BMFSocketTreeCutSetHandaxeClass,
            address,
            "StaticFindObject(" .. tostring(candidate) .. ")"
          )
          if set_ok then
            local status_lines, fields = tree_cut_native_update_status(status or "")
            for _, line in ipairs(status_lines) do
              detail_lines[#detail_lines + 1] = line
            end
            if accepted_or_error == true then
              native.last_error = ""
              native.last_handaxe_resolved_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
              write_status()
              return result(true, "OK", "Resource tool class resolved", {
                fields = fields,
                loaded = loaded,
                loadErrors = load_errors,
                staticFindHits = static_hits,
                setAttempts = set_attempts,
                lines = detail_lines,
              })
            end
          else
            set_errors = set_errors + 1
            detail_lines[#detail_lines + 1] = "set_handaxe_class_error=" .. tostring(candidate) .. "|" .. tostring(accepted_or_error)
          end
        end
      elseif not find_ok then
        detail_lines[#detail_lines + 1] = "static_find_error=" .. tostring(candidate) .. "|" .. tostring(object)
      end
    end
  else
    detail_lines[#detail_lines + 1] = "static_find_error=StaticFindObject unavailable"
  end

  local find_objects_hits = 0
  if type(FindObjects) == "function" and type(EObjectFlags) == "table" then
    local no_flags = EObjectFlags.RF_NoFlags
    for _, spec in ipairs(TREE_CUT_HANDAXE_FIND_OBJECT_SPECS) do
      local find_ok, objects = pcall(FindObjects, 8, spec.class, spec.name, no_flags, no_flags, false)
      if find_ok and type(objects) == "table" then
        for index, object in ipairs(objects) do
          if tree_cut_native_object_valid(object) then
            find_objects_hits = find_objects_hits + 1
            local address = tree_cut_native_object_address(object)
            detail_lines[#detail_lines + 1] = "find_objects_hit=" .. tostring(spec.class or "*") .. "|" .. tostring(spec.name) .. "|" .. tostring(index) .. "|address=" .. tostring(address)
            if address ~= "" then
              set_attempts = set_attempts + 1
              local set_ok, accepted_or_error, status = pcall(
                BMFSocketTreeCutSetHandaxeClass,
                address,
                "FindObjects(" .. tostring(spec.class or "*") .. "," .. tostring(spec.name) .. ")"
              )
              if set_ok then
                local status_lines, fields = tree_cut_native_update_status(status or "")
                for _, line in ipairs(status_lines) do
                  detail_lines[#detail_lines + 1] = line
                end
                if accepted_or_error == true then
                  native.last_error = ""
                  native.last_handaxe_resolved_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
                  write_status()
                  return result(true, "OK", "Resource tool class resolved", {
                    fields = fields,
                    loaded = loaded,
                    loadErrors = load_errors,
                    staticFindHits = static_hits,
                    findObjectsHits = find_objects_hits,
                    setAttempts = set_attempts,
                    lines = detail_lines,
                  })
                end
              else
                set_errors = set_errors + 1
                detail_lines[#detail_lines + 1] = "set_handaxe_class_error=" .. tostring(spec.class or "*") .. "|" .. tostring(spec.name) .. "|" .. tostring(accepted_or_error)
              end
            end
          end
        end
      elseif not find_ok then
        detail_lines[#detail_lines + 1] = "find_objects_error=" .. tostring(spec.class or "*") .. "|" .. tostring(spec.name) .. "|" .. tostring(objects)
      end
    end
  else
    detail_lines[#detail_lines + 1] = "find_objects_error=FindObjects or EObjectFlags unavailable"
  end

  local resolve_ok, resolved_or_error, status = pcall(BMFSocketResourceNativeResolveTools or BMFSocketTreeCutResolveHandaxe)
  if not resolve_ok then
    native.last_error = tostring(resolved_or_error or "BMFSocketResourceNativeResolveTools failed")
    detail_lines[#detail_lines + 1] = "native_resolve_error=" .. native.last_error
    return result(false, "TREE_CUT_HANDAXE_RESOLVE_FAILED", native.last_error, {
      loaded = loaded,
      loadErrors = load_errors,
      staticFindHits = static_hits,
      findObjectsHits = find_objects_hits,
      setAttempts = set_attempts,
      setErrors = set_errors,
      lines = detail_lines,
    })
  end

  local status_lines, fields = tree_cut_native_update_status(status or "")
  for _, line in ipairs(status_lines) do
    detail_lines[#detail_lines + 1] = line
  end
  if resolved_or_error == true then
    native.last_handaxe_resolved_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  end
  write_status()

  return result(resolved_or_error == true, resolved_or_error == true and "OK" or "TREE_CUT_HANDAXE_UNRESOLVED", "Resource tool class resolve attempted", {
    fields = fields,
    loaded = loaded,
    loadErrors = load_errors,
    staticFindHits = static_hits,
    findObjectsHits = find_objects_hits,
    setAttempts = set_attempts,
    setErrors = set_errors,
    lines = detail_lines,
  })
end

function BMF_tree_cut_native_normalize_drain_limit(value)
  local limit = tonumber(value or 64) or 64
  if limit < 1 then
    limit = 1
  elseif limit > 256 then
    limit = 256
  end
  return limit
end

function BMF_tree_cut_native_drain_raw(limit)
  local native = state.tools.tree_cut_native
  native.available = tree_cut_native_available()
  if not native.available then
    native.last_error = "BMFSocket resource native helpers are unavailable"
    return false, "TREE_CUT_NATIVE_UNAVAILABLE", native.last_error, {}
  end

  local ok, events_or_error = pcall(BMFSocketResourceNativeDrain or BMFSocketTreeCutDrain, BMF_tree_cut_native_normalize_drain_limit(limit))
  if not ok or type(events_or_error) ~= "table" then
    native.last_error = tostring(events_or_error or "BMFSocketResourceNativeDrain failed")
    return false, "TREE_CUT_NATIVE_DRAIN_FAILED", native.last_error, {}
  end

  local raw_events = {}
  for _, raw in ipairs(events_or_error) do
    if trim_string(raw) ~= "" then
      raw_events[#raw_events + 1] = raw
    end
  end

  return true, "OK", "Resource native queue drained", raw_events
end

function BMF_tree_cut_native_emit_raw(raw_events, options)
  options = type(options) == "table" and options or {}
  raw_events = type(raw_events) == "table" and raw_events or {}
  local native = state.tools.tree_cut_native
  local drained = 0
  local emitted = 0
  local decode_errors = 0
  for _, raw in ipairs(raw_events) do
    if trim_string(raw) ~= "" then
      drained = drained + 1
      local decoded, err = json_decode(raw)
      if type(decoded) == "table" then
        decoded._bmf = decoded._bmf or {}
        decoded._bmf.emittedAt = os.date("!%Y-%m-%dT%H:%M:%SZ")
        decoded._bmf.source = "BMFSocketResourceNative"
        local event_name = tostring(decoded.event or "cityrpg.treecut.hit")
        BMF.events.emit(event_name, decoded)
        emitted = emitted + 1
        native.last_event = copy_table(decoded)
      else
        decode_errors = decode_errors + 1
        native.last_error = tostring(err or "native resource event decode failed")
      end
    end
  end

  native.drained_events = (tonumber(native.drained_events) or 0) + drained
  native.emitted_events = (tonumber(native.emitted_events) or 0) + emitted
  native.decode_errors = (tonumber(native.decode_errors) or 0) + decode_errors
  if drained > 0 and options.silent ~= true then
    log("info", "resource native drained events=" .. tostring(drained) .. " emitted=" .. tostring(emitted))
  end
  return result(decode_errors == 0, decode_errors == 0 and "OK" or "TREE_CUT_NATIVE_DECODE_ERRORS", "Resource native queue drained", {
    drained = drained,
    emitted = emitted,
    decodeErrors = decode_errors,
    lines = {
      "available=true",
      "drained=" .. tostring(drained),
      "emitted=" .. tostring(emitted),
      "decode_errors=" .. tostring(decode_errors),
      "total_drained=" .. tostring(native.drained_events or 0),
      "total_emitted=" .. tostring(native.emitted_events or 0),
    },
  })
end

function BMF.tools.treeCutNative.drain(options)
  options = type(options) == "table" and options or {}
  local ok, code, message, raw_events = BMF_tree_cut_native_drain_raw(options.limit or options.max or 64)
  if not ok then
    local available = code ~= "TREE_CUT_NATIVE_UNAVAILABLE"
    return result(false, code, message, {
      drained = 0,
      emitted = 0,
      lines = {
        "available=" .. tostring(available),
        "drained=0",
        "emitted=0",
        "last_error=" .. tostring(message or ""),
      },
    })
  end

  return BMF_tree_cut_native_emit_raw(raw_events, options)
end

local function zone_native_option_bool(options, camel_key, lower_key, default_value)
  options = type(options) == "table" and options or {}
  local value = options[camel_key]
  if value == nil then
    value = options[lower_key]
  end
  if value == nil then
    return option_boolean(options, lower_key, default_value)
  end
  if type(value) == "boolean" then
    return value
  end
  if type(value) == "number" then
    return value ~= 0
  end
  if type(value) == "string" then
    local normalized = trim_string(value):lower()
    if normalized == "1" or normalized == "true" or normalized == "yes" or normalized == "on" then
      return true
    end
    if normalized == "0" or normalized == "false" or normalized == "no" or normalized == "off" then
      return false
    end
  end
  return default_value == true
end

function BMF.tools.zoneNative.start(options)
  options = type(options) == "table" and options or {}
  local native = state.tools.zone_native
  native.available = zone_native_available()
  if not native.available then
    native.last_error = "BMFSocket zone native helpers are unavailable"
    return result(false, "ZONE_NATIVE_UNAVAILABLE", native.last_error, {
      lines = {
        "available=false",
        "enabled=false",
        "started=false",
        "last_error=" .. native.last_error,
      },
    })
  end

  local capture_all = zone_native_option_bool(options, "captureAll", "captureall", false)
  local scan_local_objects = zone_native_option_bool(options, "scanLocalObjects", "scanlocalobjects", false)
  local ok, started_or_error, status = pcall(BMFSocketZoneNativeStart, capture_all, scan_local_objects)
  if not ok or started_or_error == false then
    native.last_error = tostring(status or started_or_error or "BMFSocketZoneNativeStart failed")
    return result(false, "ZONE_NATIVE_START_FAILED", native.last_error, {
      lines = {
        "available=true",
        "enabled=false",
        "started=false",
        "last_error=" .. native.last_error,
      },
    })
  end

  native.last_started_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  local lines, fields = zone_native_update_status(status or "")
  log(
    "info",
    "zone native capture started reason="
      .. tostring(options.reason or "manual")
      .. " capture_all="
      .. tostring(capture_all)
      .. " scan_local_objects="
      .. tostring(scan_local_objects)
  )
  write_status()
  return result(true, "OK", "Zone native capture started", {
    fields = fields,
    lines = lines,
  })
end

function BMF.tools.zoneNative.stop(options)
  options = type(options) == "table" and options or {}
  local native = state.tools.zone_native
  if not zone_native_available() then
    native.available = false
