function minigame_terminal_name(value)
  local text = trim_string(value or "")
  if text == "" then
    return ""
  end
  text = text:gsub("^Function%s+", ""):gsub("^Class%s+", ""):gsub("^ObjectProperty%s+", "")
  return text:match("([^%.:/%s]+)$") or text
end

function minigame_get_fname_string(object)
  if object == nil or type(object.GetFName) ~= "function" then
    return ""
  end
  local ok, fname = pcall(function()
    return object:GetFName()
  end)
  if not ok or fname == nil then
    return ""
  end
  if type(fname.ToString) == "function" then
    local string_ok, rendered = pcall(function()
      return fname:ToString()
    end)
    if string_ok and rendered ~= nil and tostring(rendered) ~= "" then
      return tostring(rendered)
    end
  end
  return ""
end

function minigame_property_name(property)
  if property == nil then
    return "unknown"
  end
  if type(property.GetName) == "function" then
    local ok, name = pcall(function()
      return property:GetName()
    end)
    if ok and name ~= nil and tostring(name) ~= "" then
      return tostring(name)
    end
  end
  local fname = minigame_get_fname_string(property)
  if fname ~= "" and not fname:match("^FName#%d+$") then
    return fname
  end
  local full_name = minigame_object_full_name(property)
  local terminal = minigame_terminal_name(full_name)
  if terminal ~= "" then
    return terminal
  end
  return "unknown"
end

function minigame_object_class_name(object)
  if not minigame_object_valid(object) or type(object.GetClass) ~= "function" then
    return ""
  end
  local ok, class_object = pcall(function()
    return object:GetClass()
  end)
  if not ok or not minigame_object_valid(class_object) then
    return ""
  end
  local fname = minigame_get_fname_string(class_object)
  if fname ~= "" and not fname:match("^FName#%d+$") then
    return fname
  end
  return minigame_terminal_name(minigame_object_full_name(class_object))
end

function minigame_property_type(property)
  return minigame_object_class_name(property)
end

function minigame_try_property_detail(object, name)
  if not minigame_object_valid(object) then
    return nil, "", "invalid object"
  end
  local last_error = ""
  if type(object.GetPropertyValue) == "function" then
    local ok, value = pcall(function()
      return object:GetPropertyValue(name)
    end)
    if ok and value ~= nil then
      return value, "GetPropertyValue", ""
    end
    if not ok then
      last_error = tostring(value)
    end
  end
  local ok, value = pcall(function()
    return object[name]
  end)
  if ok and value ~= nil then
    return value, "index", ""
  end
  if not ok and last_error == "" then
    last_error = tostring(value)
  end
  return nil, "", last_error
end

function minigame_value_debug_record(value, array_limit)
  local value_type = type(value)
  local record = {
    type = value_type,
    text = minigame_compact_value(minigame_value_to_string(value)),
  }

  if value_type == "userdata" then
    record.fullName = minigame_object_full_name(value)
    record.objectName = minigame_object_name(value)
    record.address = minigame_object_address(value)
    record.className = minigame_object_class_name(value)

    local count_ok, count = pcall(function()
      return #value
    end)
    if count_ok and type(count) == "number" and count > 0 then
      record.arrayCount = count
      record.items = {}
      local max_items = math.min(count, tonumber(array_limit) or 6)
      for index = 1, max_items do
        local item_ok, item = pcall(function()
          return value[index]
        end)
        if item_ok then
          record.items[#record.items + 1] = minigame_value_debug_record(item, 0)
        end
      end
    end
  end

  return record
end

function minigame_live_collect_property_values(object, property_names, array_limit, include_missing)
  local values = {}
  local missing = {}
  for _, property_name in ipairs(property_names or {}) do
    local value, source, err = minigame_try_property_detail(object, property_name)
    if value ~= nil then
      local record = minigame_value_debug_record(value, array_limit)
      record.source = source
      values[property_name] = record
    elseif include_missing == true then
      missing[property_name] = tostring(err or "")
    end
  end
  return values, missing
end

function minigame_live_name_matches_hints(name, hints)
  local lower = tostring(name or ""):lower()
  if lower == "" then
    return false
  end
  for _, hint in ipairs(hints or {}) do
    if lower:find(tostring(hint):lower(), 1, true) then
      return true
    end
  end
  return false
end

function minigame_live_reflected_properties(object, hints, limit, include_values, array_limit)
  local items = {}
  if not minigame_object_valid(object) or type(object.GetClass) ~= "function" then
    return items
  end
  local ok, class_object = pcall(function()
    return object:GetClass()
  end)
  if not ok or not minigame_object_valid(class_object) or type(class_object.ForEachProperty) ~= "function" then
    return items
  end

  local seen = {}
  local max_count = tonumber(limit) or 32
  local iter_ok, iter_err = pcall(function()
    class_object:ForEachProperty(function(property)
      local property_name = minigame_property_name(property)
      if seen[property_name] or not minigame_live_name_matches_hints(property_name, hints) then
        return false
      end
      seen[property_name] = true
      local item = {
        name = property_name,
        type = minigame_property_type(property),
      }
      if include_values == true then
        local value, source, err = minigame_try_property_detail(object, property_name)
        if value ~= nil then
          item.value = minigame_value_debug_record(value, array_limit)
          item.value.source = source
        elseif err ~= "" then
          item.error = tostring(err)
        end
      end
      items[#items + 1] = item
      return #items >= max_count
    end)
  end)
  if not iter_ok then
    items[#items + 1] = {
      name = "<reflection-error>",
      error = tostring(iter_err),
    }
  end
  return items
end

function minigame_live_reflected_functions(object, hints, limit)
  local items = {}
  if not minigame_object_valid(object) or type(object.GetClass) ~= "function" then
    return items
  end
  local ok, class_object = pcall(function()
    return object:GetClass()
  end)
  if not ok or not minigame_object_valid(class_object) or type(class_object.ForEachFunction) ~= "function" then
    return items
  end

  local seen = {}
  local max_count = tonumber(limit) or 32
  local iter_ok, iter_err = pcall(function()
    class_object:ForEachFunction(function(func)
      local function_name = minigame_property_name(func)
      if seen[function_name] or not minigame_live_name_matches_hints(function_name, hints) then
        return false
      end
      seen[function_name] = true
      items[#items + 1] = {
        name = function_name,
        fullName = minigame_object_full_name(func),
      }
      return #items >= max_count
    end)
  end)
  if not iter_ok then
    items[#items + 1] = {
      name = "<reflection-error>",
      error = tostring(iter_err),
    }
  end
  return items
end

function minigame_live_uehelpers()
  if os.getenv("BMF_MINIGAMES_LIVE_UEHELPERS") ~= "1" then
    return nil, "UEHelpers live minigame reads are disabled; set BMF_MINIGAMES_LIVE_UEHELPERS=1 to opt in"
  end
  local ok, helpers = pcall(require, "UEHelpers")
  if ok and type(helpers) == "table" then
    return helpers, ""
  end
  if type(UEHelpers) == "table" then
    return UEHelpers, ""
  end
  return nil, tostring(helpers or "UEHelpers unavailable")
end

function minigame_live_game_state()
  local helpers, helper_error = minigame_live_uehelpers()
  if type(helpers) ~= "table" or type(helpers.GetGameStateBase) ~= "function" then
    return nil, helper_error ~= "" and helper_error or "UEHelpers.GetGameStateBase unavailable"
  end
  local ok, game_state = pcall(helpers.GetGameStateBase)
  if ok and minigame_object_valid(game_state) then
    return game_state, ""
  end
  return nil, ok and "game state unavailable" or tostring(game_state)
end

function minigame_live_player_states(options)
  local opts = type(options) == "table" and options or {}
  local game_state, game_state_error = minigame_live_game_state()
  local records = {}
  local seen = {}
  local source = "game_state.PlayerArray"
  local player_array_count = 0
  local errors = {}

  local function add_player_state(player_state, index, item_source)
    if not minigame_object_valid(player_state) then
      return
    end
    local key = minigame_object_address(player_state)
    if key == "" then
      key = minigame_object_full_name(player_state)
    end
    if key == "" or seen[key] then
      return
    end
    seen[key] = true
    records[#records + 1] = {
      object = player_state,
      index = index or #records + 1,
      source = item_source or source,
    }
  end

  if minigame_object_valid(game_state) then
    local ok_array, player_array = pcall(function()
      return game_state.PlayerArray
    end)
    if ok_array and player_array ~= nil then
      local ok_count, count = pcall(function()
        return #player_array
      end)
      if ok_count and type(count) == "number" then
        player_array_count = count
        for index = 1, count do
          local ok_player, player_state = pcall(function()
            return player_array[index]
          end)
          if ok_player then
            add_player_state(player_state, index, source)
          else
            errors[#errors + 1] = "PlayerArray[" .. tostring(index) .. "]=" .. tostring(player_state)
          end
        end
      else
        errors[#errors + 1] = "PlayerArray count failed: " .. tostring(count)
      end
    else
      errors[#errors + 1] = "PlayerArray unavailable: " .. tostring(player_array)
    end
  end

  if #records == 0 and opts.fallbackFindAll == true and type(FindAllOf) == "function" then
    source = "FindAllOf"
    for _, class_name in ipairs({ "BP_PlayerState_C", "BRPlayerState", "PlayerState" }) do
      local ok, found = BMF_operation_find_all(
        class_name,
        "minigame.player_state_scan",
        "diagnostic_scan")
      if ok and type(found) == "table" then
        for index, player_state in ipairs(found) do
          add_player_state(player_state, index, "FindAllOf(" .. class_name .. ")")
        end
      elseif not ok then
        errors[#errors + 1] = "FindAllOf(" .. class_name .. ")=" .. tostring(found)
      end
    end
  end

  if #records == 0 and game_state_error ~= "" then
    errors[#errors + 1] = game_state_error
  end

  return records, {
    gameState = game_state,
    gameStateFullName = minigame_object_full_name(game_state),
    playerArrayCount = player_array_count,
    source = source,
    errors = errors,
  }
end

function minigame_live_first_property_text(values, names)
  for _, name in ipairs(names or {}) do
    local value = values[name]
    if type(value) == "table" and tostring(value.text or "") ~= "" then
      return tostring(value.text or ""), name
    end
  end
  return "", ""
end

function minigame_live_collect_candidates(values, pattern)
  local candidates = {}
  local lower_pattern = tostring(pattern or ""):lower()
  for name, value in pairs(values or {}) do
    local lower = tostring(name or ""):lower()
    if lower:find(lower_pattern, 1, true) and type(value) == "table" and tostring(value.text or "") ~= "" then
      candidates[#candidates + 1] = {
        property = name,
        text = tostring(value.text or ""),
        fullName = tostring(value.fullName or ""),
        objectName = tostring(value.objectName or ""),
        className = tostring(value.className or ""),
      }
    end
  end
  table.sort(candidates, function(a, b)
    return tostring(a.property or "") < tostring(b.property or "")
  end)
  return candidates
end

function minigame_live_player_matches(record, query)
  local needle = trim_string(query or ""):lower()
  if needle == "" then
    return true
  end
  local haystacks = {
    record.playerName,
    record.playerStateFullName,
    record.playerStateObjectName,
    record.playerStateAddress,
    record.ownerFullName,
    record.ownerObjectName,
  }
  for _, candidate in ipairs(record.teamCandidates or {}) do
    haystacks[#haystacks + 1] = candidate.text
    haystacks[#haystacks + 1] = candidate.fullName
    haystacks[#haystacks + 1] = candidate.objectName
  end
  for _, candidate in ipairs(record.rulesetCandidates or {}) do
    haystacks[#haystacks + 1] = candidate.text
    haystacks[#haystacks + 1] = candidate.fullName
    haystacks[#haystacks + 1] = candidate.objectName
  end
  for _, value in ipairs(haystacks) do
    local text = trim_string(value or ""):lower()
    if text ~= "" and (text == needle or text:find(needle, 1, true) ~= nil) then
      return true
    end
  end
  return false
end

MINIGAME_LIVE_TEAM_STATE_TEAM_PROPERTIES = {
  "TeamName",
  "TeamId",
  "TeamID",
  "Id",
  "TeamIndex",
  "Name",
  "DisplayName",
  "bIsUnaffiliatedTeam",
  "bGameTypeTeam",
}

MINIGAME_LIVE_TEAM_STATE_RULESET_PROPERTIES = {
  "RulesetName",
  "Name",
  "DisplayName",
  "bInSession",
  "bRoundInProgress",
}

MINIGAME_LIVE_TEAM_STATE_PLAYER_TEAM_PROPERTIES = {
  "Team",
  "CurrentTeam",
  "CurrentRulesetTeam",
  "RulesetTeam",
  "ActiveTeam",
  "SelectedTeam",
  "BRTeam",
  "TeamState",
}

MINIGAME_LIVE_TEAM_STATE_PLAYER_RULESET_PROPERTIES = {
  "Ruleset",
  "CurrentRuleset",
  "BRRuleset",
  "MemberRuleset",
  "PlayerRuleset",
}

MINIGAME_LIVE_TEAM_STATE_OWNER_TEAM_PROPERTIES = {
  "Team",
  "CurrentTeam",
  "CurrentRulesetTeam",
  "RulesetTeam",
}

MINIGAME_LIVE_TEAM_STATE_OWNER_RULESET_PROPERTIES = {
  "Ruleset",
  "CurrentRuleset",
}

function minigame_live_add_referenced_object(list, seen, object, source)
  if not minigame_object_valid(object) then
    return
  end
  local key = minigame_object_address(object)
  if key == "" then
    key = minigame_object_full_name(object)
  end
  if key == "" then
    key = tostring(object or "")
  end
  if key == "" or seen[key] then
    return
  end
  seen[key] = true
  list[#list + 1] = {
    object = object,
    source = tostring(source or ""),
  }
end

function minigame_live_collect_references_from_properties(targets, seen, source_prefix, object, property_names)
  if not minigame_object_valid(object) then
    return
  end
  for _, property_name in ipairs(property_names or {}) do
    local value = minigame_try_property(object, property_name)
    minigame_live_add_referenced_object(targets, seen, value, tostring(source_prefix or "") .. "." .. tostring(property_name))
  end
end

function minigame_live_describe_referenced_object(reference, property_names, include_missing)
  local object = reference and reference.object or nil
  local values, missing = minigame_live_collect_property_values(object, property_names, 0, include_missing == true)
  return {
    source = tostring(reference and reference.source or ""),
    address = minigame_object_address(object),
    fullName = minigame_object_full_name(object),
    objectName = minigame_object_name(object),
    className = minigame_object_class_name(object),
    properties = values,
    missing = missing,
  }
end

function minigame_live_scalar_property_text(record, property_name)
  local value = record and record.properties and record.properties[property_name] or nil
  if type(value) == "table" then
    return tostring(value.text or "")
  end
  return ""
end

BMF.minigames.liveTeamState = function(options)
  local opts = type(options) == "table" and options or {}
  local query = trim_string(opts.player or opts.query or opts.name or "")
  local include_missing = opts.includeMissing == true
  local player_item, candidates, meta = minigame_live_resolve_player_state_for_assignment(query)
  if not player_item or not minigame_object_valid(player_item.object) then
    return result(false, "PLAYER_NOT_FOUND", "live player state was not found", {
      player = query,
      candidates = candidates or {},
      sourceMode = meta and meta.source or "",
      lines = {
        "code=PLAYER_NOT_FOUND",
        "source=bmf.liveTeamState",
        "player=" .. query,
        "source_mode=" .. tostring(meta and meta.source or ""),
        "candidates=" .. table.concat(candidates or {}, "|"),
      },
    })
  end

  local player_state = player_item.object
  local owner = minigame_try_property(player_state, "Owner")
  local team_refs = {}
  local team_seen = {}
  local ruleset_refs = {}
  local ruleset_seen = {}

  minigame_live_collect_references_from_properties(
    team_refs,
    team_seen,
    "player",
    player_state,
    MINIGAME_LIVE_TEAM_STATE_PLAYER_TEAM_PROPERTIES
  )
  minigame_live_collect_references_from_properties(
    ruleset_refs,
    ruleset_seen,
    "player",
    player_state,
    MINIGAME_LIVE_TEAM_STATE_PLAYER_RULESET_PROPERTIES
  )

  if minigame_object_valid(owner) then
    minigame_live_collect_references_from_properties(
      team_refs,
      team_seen,
      "owner",
      owner,
      MINIGAME_LIVE_TEAM_STATE_OWNER_TEAM_PROPERTIES
    )
    minigame_live_collect_references_from_properties(
      ruleset_refs,
      ruleset_seen,
      "owner",
      owner,
      MINIGAME_LIVE_TEAM_STATE_OWNER_RULESET_PROPERTIES
    )
  end

  local teams = {}
  for _, reference in ipairs(team_refs) do
    teams[#teams + 1] = minigame_live_describe_referenced_object(
      reference,
      MINIGAME_LIVE_TEAM_STATE_TEAM_PROPERTIES,
      include_missing
    )
  end

  local rulesets = {}
  for _, reference in ipairs(ruleset_refs) do
    rulesets[#rulesets + 1] = minigame_live_describe_referenced_object(
      reference,
      MINIGAME_LIVE_TEAM_STATE_RULESET_PROPERTIES,
      include_missing
    )
  end

  local lines = {
    "code=OK",
    "source=bmf.liveTeamState",
    "player=" .. query,
    "source_mode=" .. tostring(meta and meta.source or ""),
    "player_state=" .. minigame_object_address(player_state),
    "controller=" .. minigame_object_address(owner),
    "teams=" .. tostring(#teams),
    "rulesets=" .. tostring(#rulesets),
  }

  for index, team in ipairs(teams) do
    lines[#lines + 1] = "team_" .. tostring(index) .. "_source=" .. tostring(team.source or "")
    lines[#lines + 1] = "team_" .. tostring(index) .. "_address=" .. tostring(team.address or "")
    lines[#lines + 1] = "team_" .. tostring(index) .. "_class=" .. tostring(team.className or "")
    lines[#lines + 1] = "team_" .. tostring(index) .. "_object=" .. tostring(team.objectName or "")
    lines[#lines + 1] = "team_" .. tostring(index) .. "_full=" .. tostring(team.fullName or "")
    for _, property_name in ipairs(MINIGAME_LIVE_TEAM_STATE_TEAM_PROPERTIES) do
      local text = minigame_live_scalar_property_text(team, property_name)
      if text ~= "" then
        lines[#lines + 1] = "team_" .. tostring(index) .. "_property_" .. tostring(property_name) .. "=" .. text
      end
    end
  end

  for index, ruleset in ipairs(rulesets) do
    lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_source=" .. tostring(ruleset.source or "")
    lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_address=" .. tostring(ruleset.address or "")
    lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_class=" .. tostring(ruleset.className or "")
    lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_object=" .. tostring(ruleset.objectName or "")
    lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_full=" .. tostring(ruleset.fullName or "")
    for _, property_name in ipairs(MINIGAME_LIVE_TEAM_STATE_RULESET_PROPERTIES) do
      local text = minigame_live_scalar_property_text(ruleset, property_name)
      if text ~= "" then
        lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_property_" .. tostring(property_name) .. "=" .. text
      end
    end
  end

  local data = {
    source = "bmf.liveTeamState",
    checkedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    query = query,
    sourceMode = tostring(meta and meta.source or ""),
    playerState = minigame_object_address(player_state),
    controller = minigame_object_address(owner),
    teams = teams,
    rulesets = rulesets,
    counts = {
      teams = #teams,
      rulesets = #rulesets,
    },
    lines = lines,
  }
  lines[#lines + 1] = "snapshot_json=" .. json_encode(data)

  return result(true, "OK", "Live minigame team state collected", data)
end

function minigame_int32_le_hex(value)
  local number = tonumber(value) or 0
  if number < 0 then
    number = 0
  end
  number = math.floor(number)
  local b1 = number % 256
  local b2 = math.floor(number / 256) % 256
  local b3 = math.floor(number / 65536) % 256
  local b4 = math.floor(number / 16777216) % 256
  return string.format("%02X%02X%02X%02X", b1, b2, b3, b4)
end

function minigame_bool_byte_hex(value)
  return value == true and "01" or "00"
end

function minigame_uint64_le_hex(value)
  local number = tonumber(value) or 0
  if number < 0 then
    number = 0
  end
  number = math.floor(number)
  local bytes = {}
  for index = 1, 8 do
    bytes[index] = string.format("%02X", number % 256)
    number = math.floor(number / 256)
  end
  return table.concat(bytes, "")
end

function minigame_object_pointer_le_hex(object)
  local address = minigame_object_address(object)
  local number = nil
  if address ~= "" then
    number = tonumber(address)
    if number == nil and address:match("^0x") then
      number = tonumber(address:sub(3), 16)
    elseif number == nil then
      number = tonumber(address, 16)
    end
  end
  if number == nil or number <= 0 then
    return nil, "object address is unavailable"
  end
  return minigame_uint64_le_hex(number), ""
end

function minigame_live_resolve_ruleset_for_assignment(player_state)
  for _, property_name in ipairs({
    "Ruleset",
    "CurrentRuleset",
    "BRRuleset",
    "MemberRuleset",
    "PlayerRuleset",
  }) do
    local value = minigame_try_property(player_state, property_name)
    if minigame_object_valid(value) then
      return value, property_name
    end
  end
  return nil, ""
end

function minigame_team_lookup_key(value)
  return trim_string(value or ""):lower():gsub("[^a-z0-9]+", "")
end

function minigame_game_mode_team_candidate_text(record)
  return table.concat({
    tostring(record.name or ""),
    tostring(record.objectName or ""),
    tostring(record.fullName or ""),
    tostring(record.address or ""),
  }, "|")
end

function minigame_live_game_mode_team_candidates(limit)
  local objects = minigame_find_objects("BRGameModeTeam", limit or 64)
  local records = {}
  for index, object in ipairs(objects) do
    records[#records + 1] = {
      object = object,
      index = index - 1,
      findIndex = index,
      source = "FindAllOf(BRGameModeTeam)[" .. tostring(index) .. "]",
      address = minigame_object_address(object),
      objectName = minigame_object_name(object),
      fullName = minigame_object_full_name(object),
      name = minigame_object_property(object, "TeamName"),
      color = minigame_object_property(object, "TeamColor"),
    }
  end
  return records
end

function minigame_live_resolve_game_mode_team_for_assignment(team, team_name)
  local records = minigame_live_game_mode_team_candidates(64)
  local query = minigame_team_lookup_key(team_name or "")
  if query ~= "" then
    for _, record in ipairs(records) do
      if minigame_team_lookup_key(record.name) == query then
        return record, "BRGameModeTeam.TeamName.exact"
      end
    end
    for _, record in ipairs(records) do
      local candidate = minigame_team_lookup_key(minigame_game_mode_team_candidate_text(record))
      if candidate ~= "" and candidate:find(query, 1, true) ~= nil then
        return record, "BRGameModeTeam.lookup.partial"
      end
    end
  end

  local index = tonumber(team)
  if index ~= nil then
    index = math.floor(index)
    for _, record in ipairs(records) do
      if tonumber(record.index) == index then
        return record, "BRGameModeTeam.index"
      end
    end
  end

  local candidates = {}
  for _, record in ipairs(records) do
    candidates[#candidates + 1] = tostring(record.index)
      .. ":"
      .. tostring(record.name or "")
      .. ":"
      .. tostring(record.objectName or "")
      .. ":"
      .. tostring(record.address or "")
  end
  return nil, "no BRGameModeTeam matched team=" .. tostring(team or "") .. " teamName=" .. tostring(team_name or "") .. " candidates=" .. table.concat(candidates, "|")
end

function minigame_team_assignment_uses_game_mode_team(method)
  return method == "serverjoingamemodeteam" or method == "serverrequestjoingamemodeteam"
end

function minigame_native_assign_team_param_hex(team, method, first_flag, second_flag, player_state, game_mode_team)
  if method == "serverjoingamemodeteam" then
    return minigame_int32_le_hex(team), 4, "ServerJoinGameModeTeam", ""
  end

  if method == "serverrequestjoingamemodeteam" then
    return minigame_int32_le_hex(team), 4, "ServerRequestJoinGameModeTeam", ""
  end

  if method == "serverrpc" then
    return minigame_int32_le_hex(team), 4, "ServerJoinRulesetTeam", ""
  end

  if method == "handleplayerswitchteam" then
    local pointer_hex, pointer_error = minigame_object_pointer_le_hex(player_state)
    if not pointer_hex then
      return nil, 0, "HandlePlayerSwitchTeam", pointer_error
    end
    return
      pointer_hex
        .. minigame_int32_le_hex(team)
        .. minigame_bool_byte_hex(first_flag)
        .. minigame_bool_byte_hex(second_flag),
      14,
      "HandlePlayerSwitchTeam",
      ""
  end

  return
    minigame_int32_le_hex(team)
      .. minigame_bool_byte_hex(first_flag)
      .. minigame_bool_byte_hex(second_flag),
    6,
    "JoinRulesetTeam",
    ""
end

function minigame_live_player_assignment_candidates(player_state)
  local candidates = {}

  local function add(value)
    local text = trim_string(value)
    if text ~= "" then
      candidates[#candidates + 1] = text
    end
  end

  add(minigame_object_address(player_state))
  add(minigame_object_name(player_state))
  add(minigame_object_full_name(player_state))

  for _, property_name in ipairs({
    "UserName",
    "PlayerNamePrivate",
    "PlayerName",
    "DisplayName",
  }) do
    add(minigame_value_to_string(minigame_try_property(player_state, property_name)))
  end

  local owner = minigame_try_property(player_state, "Owner")
  if minigame_object_valid(owner) then
    add(minigame_object_address(owner))
    add(minigame_object_name(owner))
    add(minigame_object_full_name(owner))
  end

  return candidates
end

function BMF_minigame_player_cache_records()
  local cache = state.player_cache
  if type(cache) ~= "table" then
    return nil, "player_cache.missing"
  end
  local players = type(cache.players) == "table" and cache.players or cache
  if type(players) ~= "table" then
    return nil, "player_cache.invalid"
  end
  return players, "player_cache.memory"
end

local function minigame_cached_player_record(query)
  local needle = trim_string(query or ""):lower()
  if needle == "" then
    return nil, ""
  end
  local players = BMF_minigame_player_cache_records()
  if type(players) ~= "table" then
    return nil, ""
  end

  for _, player in ipairs(players) do
    if type(player) == "table" then
      for _, field in ipairs({
        "uuid", "id", "playerId", "playerID", "username", "userName",
        "displayName", "playerName", "originalName", "name",
        "controllerPath", "playerStatePath",
      }) do
        local text = trim_string(tostring(player[field] or "")):lower()
        if text ~= "" and (text == needle or text:find(needle, 1, true) ~= nil) then
          return player, field
        end
      end
    end
  end
  return nil, ""
end

local function minigame_find_cached_object(object_name, class_names)
  local name = trim_string(tostring(object_name or ""))
  if name == "" then
    return nil
  end

  if type(FindObject) == "function" then
    local ok, object = pcall(FindObject, nil, name, nil, nil)
    if ok and minigame_object_valid(object) then
      return object
    end
    for _, class_name in ipairs(class_names or {}) do
      ok, object = pcall(FindObject, class_name, name, nil, nil)
      if ok and minigame_object_valid(object) then
        return object
      end
    end
  end

  if type(StaticFindObject) == "function" then
    local ok, object = pcall(StaticFindObject, name)
    if ok and minigame_object_valid(object) then
      return object
    end
  end
  return nil
end

local minigame_player_state_path_by_controller_cache = {}

local function minigame_native_player_state_from_controller(controller)
  if not minigame_object_valid(controller) then
    return nil, ""
  end
  local controller_address = minigame_object_address(controller)
  if controller_address == "" then
    return nil, ""
  end

  local cached_path = minigame_player_state_path_by_controller_cache[controller_address]
  local cached = minigame_find_cached_object(
    cached_path,
    { "BP_PlayerState_C", "BRPlayerState", "PlayerState" }
  )
  if minigame_object_valid(cached) then
    return cached, "native.controller.PlayerState.path-cache"
  end
  minigame_player_state_path_by_controller_cache[controller_address] = nil

  if type(BMFSocketDescribeUObject) ~= "function" then
    return nil, ""
  end
  local ok, response = pcall(BMFSocketDescribeUObject, controller_address)
  if not ok or type(response) ~= "string" then
    return nil, ""
  end

  local function resolve_player_state_candidate(candidate)
    local value = trim_string(tostring(candidate or ""))
    if value == "" or not value:lower():find("playerstate", 1, true) then
      return nil
    end
    local player_state = minigame_find_cached_object(
      value,
      { "BP_PlayerState_C", "BRPlayerState", "PlayerState" }
    )
    if not minigame_object_valid(player_state) then
      return nil
    end
    minigame_player_state_path_by_controller_cache[controller_address] =
      minigame_object_full_name(player_state)
    return player_state
  end

  for line in response:gmatch("[^\r\n]+") do
    -- BMFSocketDescribeUObject emits the explicit player_state_* fields for
    -- controller objects. Retain memory_ref_* parsing for older native builds.
    local candidate = line:match("^player_state_full_name=(.+)$")
      or line:match("^player_state_name=(.+)$")
      or line:match("^memory_ref_%d+_full_name=(.+)$")
      or line:match("^memory_ref_%d+_name=(.+)$")
    local player_state = resolve_player_state_candidate(candidate)
    if player_state ~= nil then
      return player_state, "native.BMFSocketDescribeUObject.controller.PlayerState"
    end
  end
  return nil, ""
end

local function minigame_cached_player_state_for_assignment(query)
  local player, match_field = minigame_cached_player_record(query)
  if type(player) ~= "table" then
    return nil, {}, nil
  end

  local candidates = {}
  for _, field in ipairs({
    "uuid", "id", "username", "userName", "displayName", "playerName",
    "originalName", "name", "controllerPath", "playerStatePath",
  }) do
    local text = trim_string(tostring(player[field] or ""))
    if text ~= "" then
      candidates[#candidates + 1] = text
    end
  end

  local player_state = minigame_find_cached_object(
    player.playerStatePath,
    { "BP_PlayerState_C", "BRPlayerState", "PlayerState" }
  )
  local source = "player_cache.playerStatePath"
  if not minigame_object_valid(player_state) then
    local controller = minigame_find_cached_object(
      player.controllerPath,
      { "BP_PlayerController_C", "BRPlayerController", "PlayerController" }
    )
    if minigame_object_valid(controller) then
      player_state = minigame_try_property(controller, "PlayerState")
      source = "player_cache.controllerPath.PlayerState"
      if not minigame_object_valid(player_state) then
        player_state, source = minigame_native_player_state_from_controller(controller)
      end
    end
  end

  if not minigame_object_valid(player_state) then
    return nil, candidates, {
      source = "player_cache",
      fastPath = "player_cache." .. tostring(match_field or "") .. ".unresolved",
      errors = { "cached controller did not expose a valid PlayerState" },
    }
  end

  return {
    object = player_state,
    index = 1,
    source = source,
  }, candidates, {
    source = source,
    fastPath = "player_cache." .. tostring(match_field or "") .. ".controller_player_state",
    errors = {},
  }
end

function minigame_cached_single_player_match(query)
  local needle = trim_string(query or ""):lower()
  if needle == "" then
    return false, "player_cache.empty_query"
  end
  local players, cache_source = BMF_minigame_player_cache_records()
  if type(players) ~= "table" or #players ~= 1 then
    return false, tostring(cache_source or "player_cache.invalid")
      .. ".count=" .. tostring(type(players) == "table" and #players or 0)
  end

  local player = players[1]
  if type(player) ~= "table" then
    return false, "player_cache.invalid_player"
  end

  for _, field in ipairs({
    "uuid",
    "id",
    "playerId",
    "playerID",
    "username",
    "userName",
    "displayName",
    "playerName",
    "originalName",
    "name",
  }) do
    local text = trim_string(tostring(player[field] or "")):lower()
    if text ~= "" and (text == needle or text:find(needle, 1, true) ~= nil) then
      return true, "player_cache.single." .. field
    end
  end

  return false, "player_cache.single_no_match"
end

function minigame_live_controller_candidates_for_assignment()
  local candidates = {}
  local seen = {}
  local classes = { "BP_PlayerController_C", "BRPlayerController", "PlayerController" }

  local function add(controller, source)
    if not minigame_object_valid(controller) then
      return
    end
    local key = minigame_object_address(controller)
    if key == "" then
      key = minigame_object_full_name(controller)
    end
    if key == "" then
      key = tostring(controller or "")
    end
    if key == "" or seen[key] then
      return
    end
    seen[key] = true
    candidates[#candidates + 1] = {
      object = controller,
      source = tostring(source or ""),
      address = minigame_object_address(controller),
      name = minigame_object_name(controller),
      fullName = minigame_object_full_name(controller),
    }
  end

  if type(FindAllOf) == "function" then
    for _, class_name in ipairs(classes) do
      local ok, found = BMF_operation_find_all(
        class_name,
        "minigame.controller_scan",
        "diagnostic_scan")
      if ok and type(found) == "table" then
        for index, controller in ipairs(found) do
          add(controller, "FindAllOf(" .. class_name .. ")[" .. tostring(index) .. "]")
        end
      end
    end
  end

  if #candidates == 0 and type(FindFirstOf) == "function" then
    for _, class_name in ipairs(classes) do
      local ok, controller = pcall(FindFirstOf, class_name)
      if ok then
        add(controller, "FindFirstOf(" .. class_name .. ")")
      end
    end
  end

  return candidates
end

function minigame_live_resolve_controller_for_assignment(query)
  local single_cached_player, cache_source = minigame_cached_single_player_match(query)
  if not single_cached_player then
    return nil, "", cache_source
  end

  local candidates = minigame_live_controller_candidates_for_assignment()
  if #candidates == 1 then
    return candidates[1].object, "live_controller." .. tostring(candidates[1].source or ""), cache_source .. ".single_live_controller"
  end

  return nil, "", cache_source .. ".live_controllers=" .. tostring(#candidates)
end

function minigame_live_first_player_state_for_assignment(source_hint)
  local errors = {}
  local source = "FindFirstOf"
  if type(FindFirstOf) ~= "function" then
    return nil, {
      source = source,
      fastPath = tostring(source_hint or ""),
      errors = { "FindFirstOf unavailable" },
    }
  end

  for _, class_name in ipairs({ "BP_PlayerState_C", "BRPlayerState", "PlayerState" }) do
    local ok, player_state = pcall(FindFirstOf, class_name)
    if ok and minigame_object_valid(player_state) then
      local item_source = "FindFirstOf(" .. class_name .. ")"
      return {
        object = player_state,
        index = 1,
        source = item_source,
      }, {
        source = item_source,
        fastPath = tostring(source_hint or ""),
        errors = errors,
      }
    elseif not ok then
      errors[#errors + 1] = "FindFirstOf(" .. class_name .. ")=" .. tostring(player_state)
    end
  end

  return nil, {
    source = source,
    fastPath = tostring(source_hint or ""),
    errors = errors,
  }
end

function minigame_assignment_candidate_match_kind(candidates, needle)
  local query = trim_string(needle or ""):lower()
  if query == "" then
    return true, "empty"
  end

  local partial = false
  for _, candidate in ipairs(candidates or {}) do
    local lower = trim_string(candidate):lower()
    if lower ~= "" then
      if lower == query then
        return true, "exact"
      end
      if lower:find(query, 1, true) ~= nil then
        partial = true
      end
    end
  end

  return partial, partial and "partial" or ""
end

function minigame_assignment_player_state_score(item, candidates, match_kind)
  local player_state = item and item.object or nil
  local score = 0

  if match_kind == "exact" then
    score = score + 1000
  elseif match_kind == "partial" then
    score = score + 800
  elseif match_kind == "empty" then
    score = score + 100
  end

  local owner = minigame_try_property(player_state, "Owner")
  if minigame_object_valid(owner) then
    score = score + 250
  end

  for _, property_name in ipairs({ "Pawn", "PawnPrivate", "Character", "AcknowledgedPawn" }) do
    if minigame_object_valid(minigame_try_property(player_state, property_name)) then
      score = score + 50
      break
    end
  end

  local ruleset = minigame_live_resolve_ruleset_for_assignment(player_state)
  if minigame_object_valid(ruleset) then
    score = score + 50
  end

  if tostring(item and item.source or ""):find("PlayerArray", 1, true) then
    score = score + 25
  end

  if #(candidates or {}) > 0 then
    score = score + math.min(#candidates, 10)
  end

  return score
end

function minigame_assignment_better_candidate(candidate, current)
  if candidate == nil then
    return current
  end
  if current == nil then
    return candidate
  end
  if tonumber(candidate.score or 0) > tonumber(current.score or 0) then
    return candidate
  end
  return current
end

function minigame_live_resolve_player_state_for_assignment(query)
  local needle = trim_string(query or ""):lower()
  local cached_item, cached_candidates, cached_meta =
    minigame_cached_player_state_for_assignment(query)
  if cached_item and minigame_object_valid(cached_item.object) then
    return cached_item, cached_candidates, cached_meta
  end
  local single_cached_player, cache_source = minigame_cached_single_player_match(query)
  local player_states, meta = minigame_live_player_states({
    fallbackFindAll = true,
  })
  meta = type(meta) == "table" and meta or {}
  meta.fastPath = single_cached_player and cache_source or ""
  local fallback = nil
  local matched = nil

  for _, item in ipairs(player_states or {}) do
    local player_state = item.object
    local candidates = minigame_live_player_assignment_candidates(player_state)
    local matches, match_kind = minigame_assignment_candidate_match_kind(candidates, needle)
    local scored = {
      item = item,
      candidates = candidates,
      matchKind = match_kind,
      score = minigame_assignment_player_state_score(item, candidates, match_kind),
    }
    fallback = minigame_assignment_better_candidate(scored, fallback)
    if matches then
      matched = minigame_assignment_better_candidate(scored, matched)
    end
  end

  if matched ~= nil then
    meta.fastPath = tostring(meta.fastPath or "") .. ".filtered." .. tostring(matched.matchKind or "")
    return matched.item, matched.candidates, meta
  end

  if single_cached_player and fallback ~= nil then
    meta.fastPath = tostring(meta.fastPath or "") .. ".single_filtered"
    return fallback.item, fallback.candidates, meta
  end

  if single_cached_player and #(player_states or {}) == 0 then
    local first_item, first_meta = minigame_live_first_player_state_for_assignment(cache_source)
    if first_item and minigame_object_valid(first_item.object) then
      return first_item, { cache_source }, first_meta
    end
  end

  return nil, fallback and fallback.candidates or {}, meta
end

BMF.minigames.assignTeam = function(player_query, team_index, options)
  local assign_started_clock = os.clock()
  local opts = type(options) == "table" and options or {}
  local query = trim_string(player_query or "")
  if query == "" then
    return result(false, "INVALID_PLAYER", "player query is required", {
      lines = {
        "code=INVALID_PLAYER",
        "player=",
      },
    })
  end

  local team, team_error = normalize_integer(team_index, "team index")
  if team == nil then
    return result(false, "INVALID_TEAM_INDEX", team_error, {
      player = query,
      teamIndex = tostring(team_index or ""),
      lines = {
        "code=INVALID_TEAM_INDEX",
        "player=" .. query,
        "team_index=" .. tostring(team_index or ""),
        "error=" .. tostring(team_error or ""),
      },
    })
  end

  local resolve_started_clock = os.clock()
  local player_item, candidates, meta = minigame_live_resolve_player_state_for_assignment(query)
  local resolve_duration_ms = math.floor(((os.clock() - resolve_started_clock) * 1000) + 0.5)
  if not player_item or not minigame_object_valid(player_item.object) then
    return result(false, "PLAYER_NOT_FOUND", "live player state was not found", {
      player = query,
      teamIndex = team,
      candidates = candidates or {},
      sourceMode = meta and meta.source or "",
      lines = {
        "code=PLAYER_NOT_FOUND",
        "player=" .. query,
        "team_index=" .. tostring(team),
        "source_mode=" .. tostring(meta and meta.source or ""),
        "assign_resolve_ms=" .. tostring(resolve_duration_ms),
        "candidates=" .. table.concat(candidates or {}, "|"),
      },
    })
  end

  local player_state = player_item.object
  local controller = minigame_try_property(player_state, "Owner")
  local controller_source = "player_state.Owner"
  local controller_fallback = ""
  local ruleset, ruleset_source = minigame_live_resolve_ruleset_for_assignment(player_state)
  local team_name = trim_string(opts.teamName or opts.teamname or opts.teamLabel or opts.teamlabel or opts.teamQuery or opts.teamquery or "")
  local requested_method = trim_string(opts.method or opts.assignMethod or opts.nativeMethod or ""):lower()
  local method = requested_method
  if method == "" or method == "local" or method == "join" or method == "joinrulesetteam" or method == "join-ruleset-team" then
    method = "joinrulesetteam"
  elseif method == "gamemode" or method == "game-mode" or method == "servergamemode" or method == "server-game-mode" or method == "serverjoingamemodeteam" or method == "server-join-game-mode-team" or method == "joingamemodeteam" or method == "join-game-mode-team" then
    method = "serverjoingamemodeteam"
  elseif method == "requestgamemode" or method == "request-game-mode" or method == "serverrequestgamemode" or method == "server-request-game-mode" or method == "serverrequestjoingamemodeteam" or method == "server-request-join-game-mode-team" or method == "requestjoingamemodeteam" or method == "request-join-game-mode-team" then
    method = "serverrequestjoingamemodeteam"
  elseif method == "server" or method == "rpc" or method == "server-rpc" or method == "serverjoinrulesetteam" or method == "server-join-ruleset-team" then
    method = "serverrpc"
  elseif method == "handle" or method == "switch" or method == "ruleset" or method == "handleplayerswitchteam" or method == "handle-player-switch-team" then
    method = "handleplayerswitchteam"
  elseif method == "call" or method == "callbyname" or method == "servercall" or method == "servercallbyname" or method == "server-call-by-name" then
    method = "servercallbyname"
  elseif method == "joincall" or method == "joincallbyname" or method == "join-call-by-name" then
    method = "joincallbyname"
  else
    return result(false, "INVALID_ASSIGN_METHOD", "unsupported minigame team assignment method", {
      player = query,
      teamIndex = team,
      method = requested_method,
      lines = {
        "code=INVALID_ASSIGN_METHOD",
        "player=" .. query,
        "team_index=" .. tostring(team),
        "method=" .. tostring(requested_method),
        "supported_methods=serverjoingamemodeteam|serverrequestjoingamemodeteam|joinrulesetteam|serverrpc|handleplayerswitchteam|servercallbyname|joincallbyname",
      },
    })
  end

  if method ~= "handleplayerswitchteam" and not minigame_object_valid(controller) then
    local fallback_controller, fallback_source, fallback_detail = minigame_live_resolve_controller_for_assignment(query)
    controller_fallback = tostring(fallback_detail or fallback_source or "")
    if minigame_object_valid(fallback_controller) then
      controller = fallback_controller
      controller_source = tostring(fallback_source or "live_controller")
    end
  end

  local flag1 = opts.flag1
  if flag1 == nil then
    flag1 = true
  end
  local flag2 = opts.flag2
  if flag2 == nil then
    flag2 = true
  end
  local game_mode_team_record = nil
  local game_mode_team_source = ""
  if minigame_team_assignment_uses_game_mode_team(method) then
    game_mode_team_record, game_mode_team_source = minigame_live_resolve_game_mode_team_for_assignment(team, team_name)
  end
  local game_mode_team = game_mode_team_record and game_mode_team_record.object or nil
  local call_context = controller
  local call_context_kind = "controller"
  if method == "handleplayerswitchteam" then
    call_context = ruleset
    call_context_kind = "ruleset"
  end
  local is_call_by_name = method == "servercallbyname" or method == "joincallbyname"
  local call_by_name_command = ""
  local buffer_hex, param_bytes, function_name, param_error = nil, 0, "", ""
  if is_call_by_name then
    function_name = "CallFunctionByNameWithArguments"
    if method == "joincallbyname" then
      call_by_name_command = "JoinRulesetTeam "
        .. tostring(team)
        .. " "
        .. tostring(flag1 == true)
        .. " "
        .. tostring(flag2 == true)
    else
      call_by_name_command = "ServerJoinRulesetTeam " .. tostring(team)
    end
    buffer_hex = ""
  else
    buffer_hex, param_bytes, function_name, param_error = minigame_native_assign_team_param_hex(team, method, flag1 == true, flag2 == true, player_state, game_mode_team)
  end
  local dry_run = opts.dryRun == true
  local lines = {
    "code=OK",
    "player=" .. query,
    "team_index=" .. tostring(team),
    "team_name=" .. tostring(team_name or ""),
    "method=" .. method,
    "function=" .. function_name,
    "param_bytes=" .. tostring(param_bytes),
    "param_hex=" .. tostring(buffer_hex or ""),
    "flag1=" .. tostring(flag1 == true),
    "flag2=" .. tostring(flag2 == true),
    "dry_run=" .. tostring(dry_run),
    "source=" .. tostring(player_item.source or ""),
    "source_mode=" .. tostring(meta and meta.source or ""),
    "fast_path=" .. tostring(meta and meta.fastPath or ""),
    "assign_resolve_ms=" .. tostring(resolve_duration_ms),
    "player_state=" .. minigame_object_address(player_state),
    "player_state_name=" .. minigame_object_name(player_state),
    "controller=" .. minigame_object_address(controller),
    "controller_name=" .. minigame_object_name(controller),
    "controller_source=" .. tostring(controller_source or ""),
    "controller_fallback=" .. tostring(controller_fallback or ""),
    "ruleset=" .. minigame_object_address(ruleset),
    "ruleset_name=" .. minigame_object_name(ruleset),
    "ruleset_source=" .. tostring(ruleset_source or ""),
    "team_object=" .. minigame_object_address(game_mode_team),
    "team_object_name=" .. minigame_object_name(game_mode_team),
    "team_object_full=" .. minigame_object_full_name(game_mode_team),
    "team_object_label=" .. tostring(game_mode_team_record and game_mode_team_record.name or ""),
    "team_object_color=" .. tostring(game_mode_team_record and game_mode_team_record.color or ""),
    "team_object_index=" .. tostring(game_mode_team_record and game_mode_team_record.index or ""),
    "team_object_source=" .. tostring(game_mode_team_source or ""),
    "context_kind=" .. tostring(call_context_kind),
    "context=" .. minigame_object_address(call_context),
    "call_command=" .. tostring(call_by_name_command or ""),
  }

  if buffer_hex == nil then
    lines[1] = "code=INVALID_NATIVE_PARAMS"
    lines[#lines + 1] = "error=" .. tostring(param_error or "")
    return result(false, "INVALID_NATIVE_PARAMS", tostring(param_error or "native parameter packing failed"), {
      player = query,
      teamIndex = team,
      method = method,
      lines = lines,
    })
  end

  if not minigame_object_valid(call_context) then
    local code = method == "handleplayerswitchteam" and "RULESET_NOT_FOUND" or "PLAYER_CONTROLLER_NOT_FOUND"
    lines[1] = "code=" .. code
    lines[#lines + 1] = "candidates=" .. table.concat(candidates or {}, "|")
    return result(false, code, method == "handleplayerswitchteam" and "live player ruleset was not found" or "live player controller was not found", {
      player = query,
      teamIndex = team,
      playerState = minigame_object_address(player_state),
      method = method,
      lines = lines,
    })
  end

  if dry_run then
    lines[#lines + 1] = "ok=true"
    lines[#lines + 1] = "result=dry-run"
    lines[#lines + 1] = "assign_call_ms=0"
    lines[#lines + 1] = "assign_total_ms=" .. tostring(math.floor(((os.clock() - assign_started_clock) * 1000) + 0.5))
    return result(true, "OK", "Minigame team assignment dry run completed", {
      player = query,
      teamIndex = team,
      playerState = minigame_object_address(player_state),
      controller = minigame_object_address(controller),
      controllerSource = controller_source,
      controllerFallback = controller_fallback,
      ruleset = minigame_object_address(ruleset),
      teamObject = minigame_object_address(game_mode_team),
      teamObjectName = minigame_object_name(game_mode_team),
      teamObjectLabel = tostring(game_mode_team_record and game_mode_team_record.name or ""),
      teamObjectSource = tostring(game_mode_team_source or ""),
      context = minigame_object_address(call_context),
      contextKind = call_context_kind,
      method = method,
      functionName = function_name,
      paramHex = buffer_hex,
      paramBytes = param_bytes,
      flag1 = flag1 == true,
      flag2 = flag2 == true,
      dryRun = true,
      lines = lines,
    })
  end

  if is_call_by_name then
    if type(OmeggaCallFunctionByNameWithArguments) ~= "function" then
      lines[1] = "code=CALL_BY_NAME_HELPER_UNAVAILABLE"
      lines[#lines + 1] = "helper_available=false"
      return result(false, "CALL_BY_NAME_HELPER_UNAVAILABLE", "native CallFunctionByNameWithArguments helper is unavailable", {
        player = query,
        teamIndex = team,
        method = method,
        lines = lines,
      })
    end

    local call_started_clock = os.clock()
    local ok, call_result, detail = pcall(
      OmeggaCallFunctionByNameWithArguments,
      call_context,
      call_by_name_command,
      call_context
    )
    local call_duration_ms = math.floor(((os.clock() - call_started_clock) * 1000) + 0.5)
    local assigned = ok and call_result ~= false
    lines[1] = "code=" .. tostring(assigned and "OK" or "CALL_BY_NAME_FAILED")
    lines[#lines + 1] = "ok=" .. tostring(ok)
    lines[#lines + 1] = "result=" .. tostring(call_result)
    lines[#lines + 1] = "assign_call_ms=" .. tostring(call_duration_ms)
    lines[#lines + 1] = "assign_total_ms=" .. tostring(math.floor(((os.clock() - assign_started_clock) * 1000) + 0.5))
    if detail ~= nil then
      lines[#lines + 1] = "detail=" .. tostring(detail)
    end

    return result(assigned, assigned and "OK" or "CALL_BY_NAME_FAILED", assigned and "Minigame team assignment invoked" or "Minigame team assignment failed", {
      player = query,
      teamIndex = team,
      playerState = minigame_object_address(player_state),
      controller = minigame_object_address(controller),
      controllerSource = controller_source,
      controllerFallback = controller_fallback,
      ruleset = minigame_object_address(ruleset),
      teamObject = minigame_object_address(game_mode_team),
      teamObjectName = minigame_object_name(game_mode_team),
      teamObjectLabel = tostring(game_mode_team_record and game_mode_team_record.name or ""),
      teamObjectSource = tostring(game_mode_team_source or ""),
      context = minigame_object_address(call_context),
      contextKind = call_context_kind,
      method = method,
      functionName = function_name,
      callCommand = call_by_name_command,
      flag1 = flag1 == true,
      flag2 = flag2 == true,
      callByNameOk = ok,
      callByNameResult = call_result,
      callByNameDetail = detail,
      lines = lines,
    })
  end

  if type(OmeggaUnsafeProcessEventWithParamBytes) ~= "function" then
    lines[1] = "code=PROCESS_EVENT_HELPER_UNAVAILABLE"
    lines[#lines + 1] = "helper_available=false"
    return result(false, "PROCESS_EVENT_HELPER_UNAVAILABLE", "native ProcessEvent helper is unavailable", {
      player = query,
      teamIndex = team,
      lines = lines,
    })
  end

  local call_started_clock = os.clock()
  local ok, call_result, detail = pcall(
    OmeggaUnsafeProcessEventWithParamBytes,
    call_context,
    function_name,
    buffer_hex
  )
  local call_duration_ms = math.floor(((os.clock() - call_started_clock) * 1000) + 0.5)
  local assigned = ok and call_result ~= false
  lines[1] = "code=" .. tostring(assigned and "OK" or "PROCESS_EVENT_FAILED")
  lines[#lines + 1] = "ok=" .. tostring(ok)
  lines[#lines + 1] = "result=" .. tostring(call_result)
  lines[#lines + 1] = "assign_call_ms=" .. tostring(call_duration_ms)
  lines[#lines + 1] = "assign_total_ms=" .. tostring(math.floor(((os.clock() - assign_started_clock) * 1000) + 0.5))
  if detail ~= nil then
    lines[#lines + 1] = "detail=" .. tostring(detail)
  end

  return result(assigned, assigned and "OK" or "PROCESS_EVENT_FAILED", assigned and "Minigame team assignment invoked" or "Minigame team assignment failed", {
      player = query,
      teamIndex = team,
      playerState = minigame_object_address(player_state),
      controller = minigame_object_address(controller),
      controllerSource = controller_source,
      controllerFallback = controller_fallback,
      ruleset = minigame_object_address(ruleset),
      teamObject = minigame_object_address(game_mode_team),
      teamObjectName = minigame_object_name(game_mode_team),
      teamObjectLabel = tostring(game_mode_team_record and game_mode_team_record.name or ""),
      teamObjectSource = tostring(game_mode_team_source or ""),
      context = minigame_object_address(call_context),
      contextKind = call_context_kind,
    method = method,
    functionName = function_name,
    paramHex = buffer_hex,
    paramBytes = param_bytes,
    flag1 = flag1 == true,
    flag2 = flag2 == true,
    processEventOk = ok,
    processEventResult = call_result,
    processEventDetail = detail,
    lines = lines,
  })
end

BMF.minigames.livePlayerSnapshot = function(options)
  local opts = type(options) == "table" and options or {}
  local query = trim_string(opts.player or opts.query or opts.name or "")
  local limit = tonumber(opts.limit) or 16
  local array_limit = tonumber(opts.arrayLimit) or 6
  local include_missing = opts.includeMissing == true
  local include_reflection = opts.reflect == true
  local include_reflection_values = opts.reflectValues == true
  local include_functions = opts.functions == true
  local verbose = opts.verbose == true
  local player_states, meta = minigame_live_player_states({
    fallbackFindAll = opts.fallbackFindAll ~= false,
  })

  local players = {}
  for _, item in ipairs(player_states) do
    if #players >= limit then
      break
    end
    local player_state = item.object
    local property_values, missing = minigame_live_collect_property_values(
      player_state,
      MINIGAME_LIVE_PLAYER_PROPERTIES,
      array_limit,
      include_missing
    )
    local player_name = minigame_live_first_property_text(property_values, {
      "UserName",
      "PlayerNamePrivate",
      "PlayerName",
      "DisplayName",
    })
    local owner_value = property_values.Owner
    local owner = nil
    if type(owner_value) == "table" and owner_value.type == "userdata" then
      local raw_owner = minigame_try_property(player_state, "Owner")
      if minigame_object_valid(raw_owner) then
        owner = raw_owner
      end
    end

    local owner_properties = {}
    local owner_missing = {}
    if minigame_object_valid(owner) then
      owner_properties, owner_missing = minigame_live_collect_property_values(
        owner,
        MINIGAME_LIVE_OWNER_PROPERTIES,
        array_limit,
        include_missing
      )
    end

    local record = {
      index = item.index,
      source = item.source,
      playerName = player_name,
      playerStateFullName = minigame_object_full_name(player_state),
      playerStateObjectName = minigame_object_name(player_state),
      playerStateAddress = minigame_object_address(player_state),
      playerStateClass = minigame_object_class_name(player_state),
      ownerFullName = minigame_object_full_name(owner),
      ownerObjectName = minigame_object_name(owner),
      ownerAddress = minigame_object_address(owner),
      ownerClass = minigame_object_class_name(owner),
      properties = property_values,
      teamCandidates = minigame_live_collect_candidates(property_values, "team"),
      rulesetCandidates = minigame_live_collect_candidates(property_values, "ruleset"),
      minigameCandidates = minigame_live_collect_candidates(property_values, "minigame"),
    }
    if include_missing then
      record.missing = missing
      record.ownerMissing = owner_missing
    end
    if next(owner_properties) ~= nil then
      record.ownerProperties = owner_properties
      record.ownerTeamCandidates = minigame_live_collect_candidates(owner_properties, "team")
      record.ownerRulesetCandidates = minigame_live_collect_candidates(owner_properties, "ruleset")
      record.ownerMinigameCandidates = minigame_live_collect_candidates(owner_properties, "minigame")
    end
    if include_reflection then
      record.reflectedProperties = minigame_live_reflected_properties(
        player_state,
        MINIGAME_LIVE_REFLECTION_HINTS,
        tonumber(opts.reflectLimit) or 32,
        include_reflection_values,
        array_limit
      )
      if minigame_object_valid(owner) then
        record.ownerReflectedProperties = minigame_live_reflected_properties(
          owner,
          MINIGAME_LIVE_REFLECTION_HINTS,
          tonumber(opts.reflectLimit) or 32,
          include_reflection_values,
          array_limit
        )
      end
    end
    if include_functions then
      record.reflectedFunctions = minigame_live_reflected_functions(
        player_state,
        MINIGAME_LIVE_FUNCTION_HINTS,
        tonumber(opts.functionLimit) or 32
      )
      if minigame_object_valid(owner) then
        record.ownerReflectedFunctions = minigame_live_reflected_functions(
          owner,
          MINIGAME_LIVE_FUNCTION_HINTS,
          tonumber(opts.functionLimit) or 32
        )
      end
    end

    if minigame_live_player_matches(record, query) then
      players[#players + 1] = record
    end
  end

  local lines = {
    "source=bmf.livePlayerSnapshot",
    "query=" .. query,
    "game_state=" .. tostring(meta.gameStateFullName or ""),
    "source_mode=" .. tostring(meta.source or ""),
    "player_array_count=" .. tostring(meta.playerArrayCount or 0),
    "players=" .. tostring(#player_states),
    "returned=" .. tostring(#players),
    "reflect=" .. tostring(include_reflection),
    "reflect_values=" .. tostring(include_reflection_values),
    "functions=" .. tostring(include_functions),
  }

  for index, error_text in ipairs(meta.errors or {}) do
    lines[#lines + 1] = "error_" .. tostring(index) .. "=" .. tostring(error_text)
  end

  for index, player in ipairs(players) do
    local team = player.teamCandidates[1] or {}
    local ruleset = player.rulesetCandidates[1] or player.minigameCandidates[1] or {}
    lines[#lines + 1] =
      "player_" .. tostring(index) ..
      "=" .. tostring(player.playerName or "") ..
      "|state=" .. tostring(player.playerStateObjectName or "") ..
      "|team_candidate=" .. tostring(team.property or "") .. ":" .. tostring(team.text or "") ..
      "|ruleset_candidate=" .. tostring(ruleset.property or "") .. ":" .. tostring(ruleset.text or "") ..
      "|owner=" .. tostring(player.ownerObjectName or "")

    if verbose then
      for name, value in pairs(player.properties or {}) do
        lines[#lines + 1] = "player_" .. tostring(index) .. "_property_" .. tostring(name) .. "=" .. tostring(value.text or "")
      end
      for name, value in pairs(player.ownerProperties or {}) do
        lines[#lines + 1] = "player_" .. tostring(index) .. "_owner_property_" .. tostring(name) .. "=" .. tostring(value.text or "")
      end
    end
  end

  local data = {
    source = "bmf.livePlayerSnapshot",
    checkedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    query = query,
    gameState = tostring(meta.gameStateFullName or ""),
    playerArrayCount = tonumber(meta.playerArrayCount) or 0,
    sourceMode = tostring(meta.source or ""),
    players = players,
    counts = {
      observed = #player_states,
      returned = #players,
    },
    options = {
      fallbackFindAll = opts.fallbackFindAll == true,
      reflect = include_reflection,
      reflectValues = include_reflection_values,
      functions = include_functions,
      includeMissing = include_missing,
      verbose = verbose,
      limit = limit,
    },
    errors = meta.errors or {},
    lines = lines,
  }
  lines[#lines + 1] = "snapshot_json=" .. json_encode(data)

  return result(true, "OK", "Live minigame player snapshot collected", data)
end

BMF.minigames.objectSnapshot = function(options)
  local opts = type(options) == "table" and options or {}
  local targeted_read = opts.targeted == true or option_boolean(opts, "targeted", false)
  if state.config.allowUnsafeMinigameObjectSnapshot ~= true then
    return result(false, "UNSAFE_MINIGAME_OBJECT_SNAPSHOT_DISABLED", "Direct UE4SS minigame object snapshots are disabled by default.", {
      allowUnsafeMinigameObjectSnapshot = false,
      lines = {
        "code=UNSAFE_MINIGAME_OBJECT_SNAPSHOT_DISABLED",
        "allowUnsafeMinigameObjectSnapshot=false",
        "targeted=" .. tostring(targeted_read),
        "reason=global BP_Ruleset_C/BP_Team_C enumeration can abort the dedicated server",
        "use=bmf.minigames.live.team-state",
      },
    })
  end

  local limit = tonumber(opts.limit) or 64
  local include_properties = opts.includeProperties == true or option_boolean(opts, "includeproperties", false)
  local rulesets = minigame_find_objects("BP_Ruleset_C", limit)
  local teams = minigame_find_objects("BP_Team_C", limit)
  local snapshot = {
    source = "bmf.objectSnapshot",
    checkedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    unsafePropertiesIncluded = include_properties,
    rulesets = {},
    teams = {},
  }
  local lines = {
    "source=bmf.objectSnapshot",
    "targeted=" .. tostring(targeted_read),
    "unsafe_properties_included=" .. tostring(include_properties),
    "rulesets=" .. tostring(#rulesets),
    "teams=" .. tostring(#teams),
  }

  for index, object in ipairs(rulesets) do
    local item = {
      fullName = minigame_object_full_name(object),
      objectName = minigame_object_name(object),
      address = minigame_object_address(object),
    }
    if include_properties then
      item.name = minigame_object_property(object, "RulesetName")
      item.inSession = minigame_object_property(object, "bInSession")
      item.memberStates = minigame_object_property(object, "MemberStates")
      item.customTeams = minigame_object_property(object, "CustomTeams")
      item.unaffiliatedTeam = minigame_object_property(object, "UnaffiliatedTeam")
    end
    snapshot.rulesets[#snapshot.rulesets + 1] = item
    lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_full=" .. item.fullName
    lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_object=" .. item.objectName
    if include_properties then
      lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_name=" .. tostring(item.name or "")
      lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_in_session=" .. tostring(item.inSession or "")
      lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_members=" .. tostring(item.memberStates or "")
      lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_custom_teams=" .. tostring(item.customTeams or "")
      lines[#lines + 1] = "ruleset_" .. tostring(index) .. "_unaffiliated_team=" .. tostring(item.unaffiliatedTeam or "")
    end
  end

  for index, object in ipairs(teams) do
    local item = {
      fullName = minigame_object_full_name(object),
      objectName = minigame_object_name(object),
      address = minigame_object_address(object),
    }
    if include_properties then
      item.name = minigame_object_property(object, "TeamName")
      item.teamId = minigame_object_property(object, "TeamId")
      item.teamID = minigame_object_property(object, "TeamID")
      item.id = minigame_object_property(object, "Id")
      item.index = minigame_object_property(object, "TeamIndex")
      item.color = minigame_object_property(object, "TeamColor")
      item.memberStates = minigame_object_property(object, "MemberStates")
      item.ruleset = minigame_object_property(object, "Ruleset")
      item.isUnaffiliated = minigame_object_property(object, "bIsUnaffiliatedTeam")
      item.isGameTypeTeam = minigame_object_property(object, "bGameTypeTeam")
    end
    snapshot.teams[#snapshot.teams + 1] = item
    lines[#lines + 1] = "team_" .. tostring(index) .. "_full=" .. item.fullName
    lines[#lines + 1] = "team_" .. tostring(index) .. "_object=" .. item.objectName
    if include_properties then
      lines[#lines + 1] = "team_" .. tostring(index) .. "_name=" .. tostring(item.name or "")
      lines[#lines + 1] = "team_" .. tostring(index) .. "_team_id=" .. tostring(item.teamId or "")
      lines[#lines + 1] = "team_" .. tostring(index) .. "_team_ID=" .. tostring(item.teamID or "")
      lines[#lines + 1] = "team_" .. tostring(index) .. "_id=" .. tostring(item.id or "")
      lines[#lines + 1] = "team_" .. tostring(index) .. "_index=" .. tostring(item.index or "")
      lines[#lines + 1] = "team_" .. tostring(index) .. "_color=" .. tostring(item.color or "")
      lines[#lines + 1] = "team_" .. tostring(index) .. "_members=" .. tostring(item.memberStates or "")
      lines[#lines + 1] = "team_" .. tostring(index) .. "_ruleset=" .. tostring(item.ruleset or "")
      lines[#lines + 1] = "team_" .. tostring(index) .. "_unaffiliated=" .. tostring(item.isUnaffiliated or "")
      lines[#lines + 1] = "team_" .. tostring(index) .. "_gametype=" .. tostring(item.isGameTypeTeam or "")
    end
  end

  lines[#lines + 1] = "snapshot_json=" .. json_encode(snapshot)

  return result(true, "OK", "Minigame object snapshot collected", {
    source = snapshot.source,
    checkedAt = snapshot.checkedAt,
    targeted = targeted_read,
    unsafePropertiesIncluded = include_properties,
    rulesets = snapshot.rulesets,
    teams = snapshot.teams,
    counts = {
      rulesets = #rulesets,
      teams = #teams,
    },
    lines = lines,
  })
end

local MINIGAME_EVENT_NAMES = {
  snapshot = true,
  created = true,
  deleted = true,
  joinminigame = true,
  leaveminigame = true,
  teamchange = true,
  roundchange = true,
  roundend = true,
  leaderboardchange = true,
  score = true,
  kill = true,
  death = true,
}

local MINIGAME_EVENT_ALIASES = {
  create = "created",
  delete = "deleted",
  join = "joinminigame",
  leave = "leaveminigame",
  leaderboard = "leaderboardchange",
  round = "roundchange",
  roundstart = "roundchange",
  team = "teamchange",
}

local function normalize_minigame_event_name(value)
  local name = trim_string(value):lower()
  name = name:gsub("^minigames%.", "")
  name = MINIGAME_EVENT_ALIASES[name] or name
  if name == "" then
    return nil, "minigame event name is required"
  end
  if not MINIGAME_EVENT_NAMES[name] then
    return nil, "unsupported minigame event: " .. tostring(value or "")
  end
  return name
end

local function minigame_key(value)
  if type(value) ~= "table" then
    return ""
  end
  local ruleset = trim_string(value.ruleset or value.id or "")
  if ruleset ~= "" then
    return "ruleset:" .. ruleset
  end
  local name = trim_string(value.name or value.minigame or "")
  local index = value.index
  if name == "" and index == nil then
    return ""
  end
  return "name:" .. name .. "#" .. tostring(tonumber(index) or 0)
end

local function player_key(value)
  if type(value) ~= "table" then
    return trim_string(value or "")
  end
  return trim_string(value.id or value.uuid or value.state or value.controller or value.name or value.displayName or "")
end

local function team_key(value, minigame)
  if type(value) ~= "table" then
    return ""
  end
  local team = trim_string(value.team or value.id or value.name or "")
  if team == "" then
    return ""
  end
  local parent = minigame_key(minigame or value.minigame or {})
  if parent ~= "" and not team:match("^BP_Team") then
    return parent .. ":team:" .. team
  end
  return "team:" .. team
end

function minigame_definitions_state()
  state.minigame_definitions = state.minigame_definitions or {}
  local definitions = state.minigame_definitions
  definitions.records_by_key = definitions.records_by_key or {}
  definitions.updated_at = definitions.updated_at or ""
  definitions.source = definitions.source or ""
  definitions.total_updates = tonumber(definitions.total_updates) or 0
  definitions.last_error = tostring(definitions.last_error or "")
  return definitions
end

function normalize_minigame_definition_bool(value, label)
  if value == nil or value == "" then
    return nil, nil
  end
  if type(value) == "boolean" then
    return value, nil
  end
  local lower = trim_string(value):lower()
  if lower == "true" or lower == "1" or lower == "yes" or lower == "on" then
    return true, nil
  end
  if lower == "false" or lower == "0" or lower == "no" or lower == "off" then
    return false, nil
  end
  return nil, label .. " must be a boolean"
end

function minigame_definition_text_list(value)
  local items = {}
  if type(value) == "table" then
    for _, item in ipairs(value) do
      if type(item) == "table" then
        local name = trim_string(item.name or item.team or item.id or item.key or "")
        if name ~= "" then
          local copied = copy_table(item)
          copied.name = name
          items[#items + 1] = copied
        end
      else
        local text = trim_string(item)
        if text ~= "" then
          items[#items + 1] = text
        end
      end
    end
    return items
  end

  local text = trim_string(value or "")
  if text == "" then
    return items
  end
  for item in text:gmatch("[^,|]+") do
    local decoded = trim_string(percent_decode(item))
    if decoded ~= "" then
      items[#items + 1] = decoded
    end
  end
  return items
end

function normalize_minigame_definition_teams(value)
  local teams = {}
  for index, item in ipairs(minigame_definition_text_list(value)) do
    local team = {}
    if type(item) == "table" then
      team = copy_table(item)
      team.name = trim_string(team.name or team.team or team.id or team.key or "")
    else
      team.name = tostring(item)
    end
    if team.name ~= "" then
      team.index = tonumber(team.index) or index
      team.key = trim_string(team.key or team.id or team.team or team.name)
      teams[#teams + 1] = team
    end
  end
  return teams
end

function minigame_definition_counts(definitions)
  definitions = definitions or minigame_definitions_state()
  local team_count = 0
  for _, record in pairs(definitions.records_by_key or {}) do
    if type(record) == "table" and type(record.teams) == "table" then
      team_count = team_count + #record.teams
    end
  end
  return {
    definitions = table_count(definitions.records_by_key),
    teams = team_count,
  }
end

function load_minigame_definitions()
  local definitions = minigame_definitions_state()
  if definitions.loaded then
    return definitions
  end
  definitions.loaded = true
  definitions.records_by_key = definitions.records_by_key or {}

  local raw = read_file(MINIGAME_DEFINITIONS_PATH)
  if not raw or trim_string(raw) == "" then
    return definitions
  end

  local decoded, err = json_decode(raw)
  if err or type(decoded) ~= "table" then
    definitions.last_error = "definition JSON could not be parsed: " .. tostring(err or "not an object")
    return definitions
  end

  definitions.updated_at = tostring(decoded.updatedAt or decoded.updated_at or "")
  definitions.source = tostring(decoded.source or "")
  definitions.total_updates = tonumber(decoded.totalUpdates or decoded.total_updates) or 0
  definitions.records_by_key = {}
  local records = decoded.definitions or decoded.records or {}
  if type(records) == "table" then
    for key, record in pairs(records) do
      if type(record) == "table" then
        local copied = copy_table(record)
        copied.key = trim_string(copied.key or key)
        if copied.key ~= "" then
          definitions.records_by_key[copied.key] = copied
        end
      end
    end
  end
  definitions.last_error = ""
  return definitions
end

function save_minigame_definitions(definitions)
  definitions = definitions or minigame_definitions_state()
  local payload = {
    updatedAt = definitions.updated_at or "",
    source = definitions.source or "",
    totalUpdates = tonumber(definitions.total_updates) or 0,
    definitions = definitions.records_by_key or {},
    counts = minigame_definition_counts(definitions),
  }
  if not write_file(MINIGAME_DEFINITIONS_PATH, json_encode(payload) .. "\n") then
    definitions.last_error = "could not write minigame definitions"
    return false
  end
  definitions.last_error = ""
  return true
end

function normalize_minigame_definition(input)
  if type(input) ~= "table" then
    return nil, "definition options table is required"
  end

  local errors = {}
  local name = trim_string(input.name or input.minigame or input.displayName or "")
  if name ~= "" and name:match("[%c]") then
    errors[#errors + 1] = "name contains unsupported control characters"
  end
  local ruleset = trim_string(input.ruleset or input.id or input.minigameId or "")
  local index = tonumber(input.index or input.minigameIndex)
  if index == nil then
    index = 0
  else
    index = math.floor(index)
  end
  if name == "" and ruleset == "" then
    errors[#errors + 1] = "name or ruleset is required"
  end

  local persistent, persistent_error = normalize_minigame_definition_bool(input.persistent, "persistent")
  if persistent_error then
    errors[#errors + 1] = persistent_error
  end
  local owner_only, owner_only_error = normalize_minigame_definition_bool(input.ownerOnly or input.owneronly, "ownerOnly")
  if owner_only_error then
    errors[#errors + 1] = owner_only_error
  end

  local included_brick_mode = trim_string(input.includedBrickMode or input.includedbrickmode or input.brickMode or input.brickmode or "")
  if included_brick_mode ~= "" then
    included_brick_mode = included_brick_mode:lower()
    local valid_modes = {
      all = true,
      none = true,
      listed = true,
      include = true,
      exclude = true,
    }
    if not valid_modes[included_brick_mode] then
      errors[#errors + 1] = "includedBrickMode must be all, none, listed, include, or exclude"
    end
  end

  local max_players = tonumber(input.maxPlayers or input.maxplayers or "")
  if max_players ~= nil then
    max_players = math.floor(max_players)
    if max_players < 0 then
      errors[#errors + 1] = "maxPlayers must be zero or greater"
    end
  end

  if #errors > 0 then
    return nil, table.concat(errors, "; ")
  end

  local minigame = {
    name = name,
    index = index,
  }
  if ruleset ~= "" then
    minigame.ruleset = ruleset
  end
  local key = trim_string(input.key or "")
  if key == "" then
    key = minigame_key(minigame)
  end

  local teams = normalize_minigame_definition_teams(input.teams or input.teamNames or input.teamnames)
  local included_bricks = minigame_definition_text_list(input.includedBricks or input.includedbricks or input.bricks)
  local now = os.date("!%Y-%m-%dT%H:%M:%SZ")
  local definition = {
    key = key,
    name = name,
    index = index,
    ruleset = ruleset,
    owner = trim_string(input.owner or ""),
    mode = trim_string(input.mode or input.type or ""),
    persistent = persistent,
    ownerOnly = owner_only,
    includedBrickMode = included_brick_mode,
    includedBricks = included_bricks,
    maxPlayers = max_players,
    teams = teams,
    teamCount = #teams,
    source = trim_string(input.source or "bmf-definition"),
    updatedAt = now,
    liveEnforcement = "definition-only",
  }
  return definition, nil
end

function minigame_definition_matches(record, query)
  query = type(query) == "table" and query or {}
  record = type(record) == "table" and record or {}
  local direct = normalize_api_filter_value(minigame_query_value(query, "key") or "")
  local ruleset = normalize_api_filter_value(minigame_query_value(query, "ruleset", "minigameid", "id") or "")
  local name = normalize_api_filter_value(minigame_query_value(query, "name", "minigame", "displayName") or "")
  local index_value = minigame_query_value(query, "index", "minigameIndex")
  local wanted_index = tonumber(index_value)
  if direct ~= "" and normalize_api_filter_value(record.key) ~= direct then
    return false
  end
  if ruleset ~= "" and normalize_api_filter_value(record.ruleset) ~= ruleset then
    return false
  end
  if name ~= "" and normalize_api_filter_value(record.name) ~= name then
    return false
  end
  if index_value ~= nil and (wanted_index == nil or tonumber(record.index or 0) ~= wanted_index) then
    return false
  end
  return true
end

function minigame_definition_query_has_filter(query)
  return minigame_query_value(query, "key", "ruleset", "minigameid", "id", "name", "minigame", "displayName", "index", "minigameIndex") ~= nil
end

function minigame_definition_find(query)
  local definitions = load_minigame_definitions()
  local normalized = normalize_minigame_lookup_query(query, "key")
  local key = trim_string(minigame_query_value(normalized, "key") or "")
  if key ~= "" and definitions.records_by_key[key] then
    return key, definitions.records_by_key[key], normalized
  end
  for _, record_key in ipairs(minigame_sorted_keys(definitions.records_by_key)) do
    local record = definitions.records_by_key[record_key]
    if minigame_definition_matches(record, normalized) then
      return record_key, record, normalized
    end
  end
  return "", nil, normalized
end

function BMF.minigames.definitionStatus()
  local definitions = load_minigame_definitions()
  return result(true, "OK", "Minigame definition status collected", {
    path = MINIGAME_DEFINITIONS_PATH,
    updatedAt = definitions.updated_at or "",
    source = definitions.source or "",
    totalUpdates = tonumber(definitions.total_updates) or 0,
    loaded = definitions.loaded == true,
    lastError = tostring(definitions.last_error or ""),
    counts = minigame_definition_counts(definitions),
  })
end

function BMF.minigames.define(options)
  local definition, normalize_error = normalize_minigame_definition(options)
  if not definition then
    return result(false, "INVALID_MINIGAME_DEFINITION", normalize_error)
  end

  local definitions = load_minigame_definitions()
  local previous = definitions.records_by_key[definition.key]
  definition.revision = (previous and tonumber(previous.revision) or 0) + 1
  definitions.records_by_key[definition.key] = definition
  definitions.updated_at = definition.updatedAt
  definitions.source = definition.source
  definitions.total_updates = (tonumber(definitions.total_updates) or 0) + 1
  if not save_minigame_definitions(definitions) then
    return result(false, "MINIGAME_DEFINITION_WRITE_FAILED", definitions.last_error, {
      path = MINIGAME_DEFINITIONS_PATH,
      definition = definition,
    })
  end
  if write_status then
    write_status()
  end
  return result(true, "OK", "Minigame definition upserted", {
    definition = copy_table(definition),
    key = definition.key,
    updated = previous ~= nil,
    counts = minigame_definition_counts(definitions),
    path = MINIGAME_DEFINITIONS_PATH,
  })
end

function BMF.minigames.definitions(query)
  local definitions = load_minigame_definitions()
  local normalized = normalize_minigame_lookup_query(query, "key")
  local limit = minigame_query_limit(normalized, 50, 100)
  local has_filter = minigame_query_has_minigame_filter(normalized)
  local items = {}
  for _, key in ipairs(minigame_sorted_keys(definitions.records_by_key)) do
    if #items >= limit then
      break
    end
    local record = definitions.records_by_key[key]
    if type(record) == "table" and (not has_filter or minigame_definition_matches(record, normalized)) then
      items[#items + 1] = copy_table(record)
    end
  end
  return result(true, "OK", "Minigame definitions listed", {
    definitions = items,
    count = #items,
    total = table_count(definitions.records_by_key),
    query = normalized,
    counts = minigame_definition_counts(definitions),
    path = MINIGAME_DEFINITIONS_PATH,
    updatedAt = definitions.updated_at or "",
    source = definitions.source or "",
    totalUpdates = tonumber(definitions.total_updates) or 0,
    lastError = tostring(definitions.last_error or ""),
  })
end

function BMF.minigames.definition(query)
  local normalized = normalize_minigame_lookup_query(query, "key")
  if not minigame_definition_query_has_filter(normalized) then
    return result(false, "INVALID_MINIGAME_DEFINITION_QUERY", "Minigame definition key, name, ruleset, or index is required", {
      query = normalized,
      counts = minigame_definition_counts(load_minigame_definitions()),
    })
  end
  local key, record, normalized = minigame_definition_find(query)
  if not record then
    return result(false, "MINIGAME_DEFINITION_NOT_FOUND", "Minigame definition not found", {
      query = normalized,
      counts = minigame_definition_counts(load_minigame_definitions()),
    })
  end
  return result(true, "OK", "Minigame definition found", {
    key = key,
    definition = copy_table(record),
    query = normalized,
    counts = minigame_definition_counts(load_minigame_definitions()),
    path = MINIGAME_DEFINITIONS_PATH,
  })
end

function BMF.minigames.deleteDefinition(query, confirm)
  local token = confirm
  if type(query) == "table" then
    token = token or query.confirm or query.token
  end
  local normalized = normalize_minigame_lookup_query(query, "key")
  if not minigame_definition_query_has_filter(normalized) then
    return result(false, "INVALID_MINIGAME_DEFINITION_QUERY", "Minigame definition key, name, ruleset, or index is required", {
      query = normalized,
      counts = minigame_definition_counts(load_minigame_definitions()),
    })
  end
  if tostring(token or "") ~= "DELETE_MINIGAME_DEFINITION" then
    return result(false, "CONFIRMATION_REQUIRED", "Pass confirm=DELETE_MINIGAME_DEFINITION to delete a minigame definition.", {
      confirmRequired = "DELETE_MINIGAME_DEFINITION",
    })
  end

  local key, record, normalized = minigame_definition_find(query)
  if not record then
    return result(false, "MINIGAME_DEFINITION_NOT_FOUND", "Minigame definition not found", {
      query = normalized,
      counts = minigame_definition_counts(load_minigame_definitions()),
    })
  end
  local definitions = load_minigame_definitions()
  definitions.records_by_key[key] = nil
  definitions.updated_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  definitions.source = "definition-delete"
  definitions.total_updates = (tonumber(definitions.total_updates) or 0) + 1
  if not save_minigame_definitions(definitions) then
    return result(false, "MINIGAME_DEFINITION_WRITE_FAILED", definitions.last_error, {
      path = MINIGAME_DEFINITIONS_PATH,
      key = key,
    })
  end
  if write_status then
    write_status()
  end
  return result(true, "OK", "Minigame definition deleted", {
    key = key,
    definition = copy_table(record),
    deleted = true,
    counts = minigame_definition_counts(definitions),
    path = MINIGAME_DEFINITIONS_PATH,
  })
end

function minigame_definition_team_label(team)
  if type(team) == "table" then
    return trim_string(team.name or team.team or team.id or team.key or "")
  end
  return trim_string(team or "")
end

function minigame_definition_team_labels(teams)
  local labels = {}
  local by_normalized = {}
  if type(teams) ~= "table" then
    return labels, by_normalized
  end
  for _, team in ipairs(teams) do
    local label = minigame_definition_team_label(team)
    local normalized = normalize_api_filter_value(label)
    if label ~= "" and not by_normalized[normalized] then
      labels[#labels + 1] = label
      by_normalized[normalized] = label
    end
  end
  return labels, by_normalized
end

function minigame_definition_observed_minigame(data, definition)
  data = type(data) == "table" and data or new_minigame_data_state()
  definition = type(definition) == "table" and definition or {}
  local queries = {}
  local direct_key = trim_string(definition.key or "")
  local ruleset = trim_string(definition.ruleset or "")
  local name = trim_string(definition.name or "")
  if direct_key ~= "" then
    queries[#queries + 1] = { key = direct_key }
  end
  if ruleset ~= "" then
    queries[#queries + 1] = { ruleset = ruleset }
  end
  if name ~= "" then
    queries[#queries + 1] = { name = name, index = definition.index or 0 }
    queries[#queries + 1] = { name = name }
  end

  local last_matches = {}
  local last_query = {}
  for _, query in ipairs(queries) do
    local key, record, matches, _, normalized = minigame_find_by_query(data, query)
    last_matches = matches or last_matches
    last_query = normalized or query
    if record then
      return key, record, matches or {}, last_query
    end
  end
  return "", nil, last_matches, last_query
end

function minigame_definition_reconcile_item(data, definition)
  definition = type(definition) == "table" and definition or {}
  local key = trim_string(definition.key or "")
  local observed_key, observed, matches, lookup_query = minigame_definition_observed_minigame(data, definition)
  local context = nil
  if observed then
    context = minigame_context_for_key(data, observed_key, observed, matches)
  end

  local expected_teams = minigame_definition_team_labels(definition.teams or {})
  local observed_teams = {}
  local observed_map = {}
  if context then
    observed_teams, observed_map = minigame_definition_team_labels(context.teams or {})
  end

  local missing_teams = {}
  for _, team in ipairs(expected_teams) do
    if not observed_map[normalize_api_filter_value(team)] then
      missing_teams[#missing_teams + 1] = team
    end
  end

  local status = "missing"
  if observed then
    status = #missing_teams > 0 and "team-mismatch" or "present"
  end

  return {
    key = key,
    definition = copy_table(definition),
    status = status,
    present = observed ~= nil,
    observedKey = observed_key,
    observedMinigame = observed and copy_table(observed) or nil,
    expectedTeams = expected_teams,
    observedTeams = observed_teams,
    missingTeams = missing_teams,
    query = copy_table(lookup_query or {}),
    counts = {
      expectedTeams = #expected_teams,
      observedTeams = #observed_teams,
      missingTeams = #missing_teams,
      members = context and context.counts and context.counts.members or 0,
      teamMemberships = context and context.counts and context.counts.teamMemberships or 0,
      leaderboards = context and context.counts and context.counts.leaderboards or 0,
    },
  }
end

function BMF.minigames.reconcileDefinitions(query)
  local listed = BMF.minigames.definitions(query)
  if not listed.ok then
    return listed
  end
  local definitions_data = listed.data or {}
  local definitions = definitions_data.definitions or {}
  local data = state.minigame_data or new_minigame_data_state()
  local items = {}
  local summary = {
    definitions = #definitions,
    checked = 0,
    present = 0,
    missing = 0,
    teamMismatches = 0,
    expectedTeams = 0,
    observedTeams = 0,
  }

  for _, definition in ipairs(definitions) do
    local item = minigame_definition_reconcile_item(data, definition)
    items[#items + 1] = item
    summary.checked = summary.checked + 1
    summary.expectedTeams = summary.expectedTeams + ((item.counts and item.counts.expectedTeams) or 0)
    summary.observedTeams = summary.observedTeams + ((item.counts and item.counts.observedTeams) or 0)
    if item.status == "present" then
      summary.present = summary.present + 1
    elseif item.status == "team-mismatch" then
      summary.teamMismatches = summary.teamMismatches + 1
    else
      summary.missing = summary.missing + 1
    end
  end

  return result(true, "OK", "Minigame definitions reconciled", {
    items = items,
    count = #items,
    summary = summary,
    query = definitions_data.query or normalize_minigame_lookup_query(query, "key"),
    definitionCounts = definitions_data.counts or {},
    dataCounts = minigame_data_counts(data),
    definitionsPath = MINIGAME_DEFINITIONS_PATH,
    definitionsUpdatedAt = definitions_data.updatedAt or "",
    dataUpdatedAt = data.updated_at or "",
    dataSource = data.source or "",
    dataTotalUpdates = tonumber(data.total_updates) or 0,
  })
end

function minigame_event_metadata(legacy_name, event_name, payload, emitted_at, event_id)
  payload = type(payload) == "table" and payload or {}
  local minigame = type(payload.minigame) == "table" and payload.minigame or payload
  local player = type(payload.player) == "table" and payload.player or {}
  local team = type(payload.team) == "table" and payload.team or {}
  local mkey = minigame_key(minigame)
  local pkey = player_key(player)
  local tkey = team_key(team, minigame)
  local source = tostring(payload.source or "")
  return {
    event = event_name,
    legacyEvent = legacy_name,
    legacy_event = legacy_name,
    eventId = tostring(event_id or ""),
    event_id = tostring(event_id or ""),
    emittedAt = emitted_at,
    emitted_at = emitted_at,
    source = source,
    minigameKey = mkey,
    minigame_key = mkey,
    playerKey = pkey,
    player_key = pkey,
    teamKey = tkey,
    team_key = tkey,
  }
end

function minigame_enrich_event_payload(legacy_name, event_name, payload, emitted_at, event_id)
  local event_payload = type(payload) == "table" and copy_table(payload) or {}
  local metadata = minigame_event_metadata(legacy_name, event_name, event_payload, emitted_at, event_id)
  event_payload._bmf = type(event_payload._bmf) == "table" and event_payload._bmf or {}
  for key, value in pairs(metadata) do
    event_payload._bmf[key] = value
  end
  return event_payload
end

local function remember_minigame_player(data, player)
  local key = player_key(player)
  if key ~= "" then
    data.players_by_key[key] = copy_table(player or {})
  end
  return key
end

local function remember_minigame(data, minigame)
  local key = minigame_key(minigame)
  if key ~= "" then
    local next_value = copy_table(minigame or {})
    next_value.key = key
    data.minigames_by_key[key] = next_value
  end
  return key
end

local function remember_team(data, team, minigame)
  local key = team_key(team, minigame)
  if key ~= "" then
    local next_value = copy_table(team or {})
    next_value.key = key
    local minigame_parent = minigame_key(minigame or team.minigame or {})
    if minigame_parent ~= "" then
      next_value.minigameKey = minigame_parent
    end
    data.teams_by_key[key] = next_value
  end
  return key
end

local function remember_membership(data, player, minigame, team)
  local pkey = remember_minigame_player(data, player)
  local mkey = remember_minigame(data, minigame)
  if pkey ~= "" and mkey ~= "" then
    data.memberships_by_player[pkey] = {
      player = copy_table(player or {}),
      minigame = copy_table(minigame or {}),
      minigameKey = mkey,
    }
    local tkey = remember_team(data, team, minigame)
    if tkey ~= "" then
      data.team_memberships_by_player[pkey] = {
        player = copy_table(player or {}),
        minigame = copy_table(minigame or {}),
        minigameKey = mkey,
        team = copy_table(team or {}),
        teamKey = tkey,
      }
    else
      data.team_memberships_by_player[pkey] = nil
    end
  end
end

local function forget_membership(data, player, minigame)
  local pkey = player_key(player)
  if pkey == "" then
    return
  end
  local existing = data.memberships_by_player[pkey]
  local leaving = minigame_key(minigame)
  if not existing or leaving == "" or existing.minigameKey == leaving then
    data.memberships_by_player[pkey] = nil
    data.team_memberships_by_player[pkey] = nil
  end
end

function minigame_snapshot_records(payload)
  payload = type(payload) == "table" and payload or {}
  local minigames = payload.minigames
  if type(minigames) ~= "table" and type(payload.snapshot) == "table" then
    minigames = payload.snapshot.minigames
  end
  local records = {}
  if type(minigames) ~= "table" then
    return records
  end

  for _, minigame in ipairs(minigames) do
    if type(minigame) == "table" then
      records[#records + 1] = minigame
    end
  end
  if #records == 0 then
    for _, minigame in pairs(minigames) do
      if type(minigame) == "table" then
        records[#records + 1] = minigame
      end
    end
  end
  return records
end

local function remember_minigame_snapshot(data, payload)
  local minigames = minigame_snapshot_records(payload)
  if #minigames == 0 then
    return
  end

  local snapshot_data = {
    minigames_by_key = {},
    players_by_key = data.players_by_key or {},
    memberships_by_player = {},
    teams_by_key = {},
    team_memberships_by_player = {},
    leaderboards_by_player = data.leaderboards_by_player or {},
    rounds_by_key = data.rounds_by_key or {},
  }

  for _, minigame in ipairs(minigames) do
    local mkey = remember_minigame(snapshot_data, minigame)
    if mkey ~= "" then
      local members = type(minigame.members) == "table" and minigame.members or {}
      for _, player in ipairs(members) do
        remember_membership(snapshot_data, player, minigame, nil)
      end
      local teams = type(minigame.teams) == "table" and minigame.teams or {}
      for _, team in ipairs(teams) do
        remember_team(snapshot_data, team, minigame)
        local team_members = type(team.members) == "table" and team.members or {}
        for _, player in ipairs(team_members) do
          remember_membership(snapshot_data, player, minigame, team)
        end
      end
    end
  end

  data.minigames_by_key = snapshot_data.minigames_by_key
  data.players_by_key = snapshot_data.players_by_key
  data.memberships_by_player = snapshot_data.memberships_by_player
  data.teams_by_key = snapshot_data.teams_by_key
  data.team_memberships_by_player = snapshot_data.team_memberships_by_player
end

local function remember_minigame_data(name, payload, emitted_at)
  local data = state.minigame_data
  local event_payload = type(payload) == "table" and payload or {}
  local now = emitted_at or os.date("!%Y-%m-%dT%H:%M:%SZ")
  data.updated_at = now
  data.source = tostring(event_payload.source or data.source or "")
  data.total_updates = (tonumber(data.total_updates) or 0) + 1
  data.last_event = {
    name = name,
    event = "minigames." .. tostring(name or ""),
    emittedAt = now,
    source = event_payload.source,
  }

  if name == "snapshot" then
    remember_minigame_snapshot(data, event_payload)
  elseif name == "created" then
    remember_minigame(data, event_payload.minigame or event_payload)
  elseif name == "deleted" then
    local key = minigame_key(event_payload.minigame or event_payload)
    if key ~= "" then
      data.minigames_by_key[key] = nil
      data.rounds_by_key[key] = nil
      for player, membership in pairs(data.memberships_by_player or {}) do
        if type(membership) == "table" and membership.minigameKey == key then
          data.memberships_by_player[player] = nil
        end
      end
      for player, membership in pairs(data.team_memberships_by_player or {}) do
        if type(membership) == "table" and membership.minigameKey == key then
          data.team_memberships_by_player[player] = nil
        end
      end
      for team, value in pairs(data.teams_by_key or {}) do
        if type(value) == "table" and value.minigameKey == key then
          data.teams_by_key[team] = nil
        end
      end
      for player, value in pairs(data.leaderboards_by_player or {}) do
        if type(value) == "table" and value.minigameKey == key then
          data.leaderboards_by_player[player] = nil
        end
      end
    end
  elseif name == "joinminigame" then
    remember_membership(data, event_payload.player, event_payload.minigame, event_payload.team)
  elseif name == "leaveminigame" then
    forget_membership(data, event_payload.player, event_payload.minigame)
    if type(event_payload.newMinigame) == "table" then
      remember_membership(data, event_payload.player, event_payload.newMinigame, event_payload.newTeam)
    end
  elseif name == "teamchange" then
    remember_membership(data, event_payload.player, event_payload.minigame, event_payload.team)
  elseif name == "roundchange" or name == "roundend" then
    local minigame = event_payload.minigame or event_payload
    local key = remember_minigame(data, minigame)
    if key ~= "" then
      data.rounds_by_key[key] = {
        minigame = copy_table(minigame or {}),
        minigameKey = key,
        roundEnded = name == "roundend",
        event = name,
        updatedAt = now,
      }
    end
  elseif name == "leaderboardchange" or name == "score" or name == "kill" or name == "death" then
    local pkey = remember_minigame_player(data, event_payload.player)
    local mkey = remember_minigame(data, event_payload.minigame)
    if pkey ~= "" then
      data.leaderboards_by_player[pkey] = {
        player = copy_table(event_payload.player or {}),
        minigame = copy_table(event_payload.minigame or {}),
        minigameKey = mkey,
        leaderboard = copy_table(event_payload.leaderboard or {}),
        oldLeaderboard = copy_table(event_payload.oldLeaderboard or {}),
        updatedAt = now,
      }
    end
  end
end

local function record_minigame_event(name, event_name, payload)
  local now = payload and payload._bmf and payload._bmf.emittedAt or os.date("!%Y-%m-%dT%H:%M:%SZ")
  local stats = state.minigame_events
  stats.total = (tonumber(stats.total) or 0) + 1
  stats.by_event[name] = (tonumber(stats.by_event[name]) or 0) + 1
  local entry = {
    eventId = tostring(payload and payload._bmf and payload._bmf.eventId or stats.total),
    event = event_name,
    name = name,
    emittedAt = now,
    source = tostring(payload and payload.source or payload and payload._bmf and payload._bmf.source or ""),
    minigameKey = tostring(payload and payload._bmf and payload._bmf.minigameKey or ""),
    playerKey = tostring(payload and payload._bmf and payload._bmf.playerKey or ""),
    teamKey = tostring(payload and payload._bmf and payload._bmf.teamKey or ""),
    payload = copy_table(payload or {}),
  }
  stats.last = entry
  stats.recent[#stats.recent + 1] = entry
  while #stats.recent > (tonumber(stats.max_recent) or 50) do
    table.remove(stats.recent, 1)
  end
  if write_status then
    write_status()
  end
  return entry
end

local function register_minigame_event_handler(name, handler, owner)
  local legacy_name, name_error = normalize_minigame_event_name(name)
  if not legacy_name then
    return nil, name_error
  end
  if type(handler) ~= "function" then
    return nil, "handler function is required"
  end
  local event_name = "minigames." .. legacy_name
  return register_event_handler(event_name, function(payload, emitted_event_name)
    return handler(payload, legacy_name, emitted_event_name)
  end, owner)
end

BMF.minigames.on = function(name, handler)
  return register_minigame_event_handler(name, handler, nil)
end

BMF.minigames.off = function(id)
  return unregister_event_handler(id, nil)
end

BMF.minigames.listenerCount = function(name)
  local legacy_name = normalize_minigame_event_name(name)
  if not legacy_name then
    return 0
  end
  return BMF.events.listenerCount("minigames." .. legacy_name)
end

BMF.minigames.emitEvent = function(name, payload)
  local legacy_name, name_error = normalize_minigame_event_name(name)
  if not legacy_name then
    return result(false, "INVALID_MINIGAME_EVENT", name_error)
  end

  local event_name = "minigames." .. legacy_name
  local emitted_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  local event_id = tostring((tonumber(state.minigame_events.total) or 0) + 1)
  local event_payload = minigame_enrich_event_payload(legacy_name, event_name, payload, emitted_at, event_id)

  local emitted = BMF.events.emit(event_name, event_payload)
  remember_minigame_data(legacy_name, event_payload, event_payload._bmf.emittedAt)
  local entry = record_minigame_event(legacy_name, event_name, event_payload)
  return result(emitted.ok, emitted.ok and "OK" or emitted.code, "Minigame event emitted", {
    event = event_name,
    legacyEvent = legacy_name,
    payload = event_payload,
    handlers = emitted.data and emitted.data.handlers or 0,
    errors = emitted.data and emitted.data.errors or {},
    total = state.minigame_events.total,
    count = state.minigame_events.by_event[legacy_name] or 0,
    last = entry,
  })
end

BMF.minigames.eventStatus = function()
  return result(true, "OK", "Minigame event status collected", {
    total = state.minigame_events.total or 0,
    byEvent = copy_table(state.minigame_events.by_event or {}),
    recent = copy_table(state.minigame_events.recent or {}),
    recentCount = #(state.minigame_events.recent or {}),
    last = type(state.minigame_events.last) == "table" and copy_table(state.minigame_events.last) or nil,
    eventLogPath = EVENT_LOG_PATH,
    eventNames = {
      "joinminigame",
      "leaveminigame",
      "roundchange",
      "roundend",
      "leaderboardchange",
      "score",
      "kill",
      "death",
      "snapshot",
      "created",
      "deleted",
      "teamchange",
    },
  })
end

function new_minigame_data_state()
  return {
    updated_at = "",
    source = "",
    total_updates = 0,
    last_event = nil,
    minigames_by_key = {},
    players_by_key = {},
    memberships_by_player = {},
    teams_by_key = {},
    team_memberships_by_player = {},
    leaderboards_by_player = {},
    rounds_by_key = {},
  }
end

function minigame_data_counts(data)
  return {
    minigames = table_count(data.minigames_by_key),
    players = table_count(data.players_by_key),
    memberships = table_count(data.memberships_by_player),
    teams = table_count(data.teams_by_key),
    teamMemberships = table_count(data.team_memberships_by_player),
    leaderboards = table_count(data.leaderboards_by_player),
    rounds = table_count(data.rounds_by_key),
  }
end

function minigame_sorted_keys(values)
  local keys = {}
  if type(values) ~= "table" then
    return keys
  end
  for key in pairs(values) do
    keys[#keys + 1] = key
  end
  table.sort(keys, function(a, b)
    return tostring(a) < tostring(b)
  end)
  return keys
end

function minigame_query_value(query, ...)
  if type(query) ~= "table" then
    return nil
  end
  for index = 1, select("#", ...) do
    local key = select(index, ...)
    local value = query[key]
    if value ~= nil and trim_string(value) ~= "" then
      return value
    end
  end
  return nil
end

function normalize_minigame_lookup_query(query, default_key)
  local normalized = {}
  if type(query) == "table" then
    normalized = copy_table(query)
  elseif query ~= nil then
    normalized[default_key or "key"] = tostring(query)
  end
  local has_named_value = false
  for key, value in pairs(normalized) do
    if key ~= "_positional" and value ~= nil and trim_string(value) ~= "" then
      has_named_value = true
      break
    end
  end
  if not has_named_value and type(normalized._positional) == "table" and normalized._positional[1] then
    normalized[default_key or "key"] = normalized._positional[1]
  end
  return normalized
end

function minigame_record_summary(key, record)
  record = type(record) == "table" and record or {}
  return {
    key = key,
    name = record.name or record.minigame or record.displayName or "",
    ruleset = record.ruleset or record.id or "",
    index = record.index,
  }
end

function minigame_find_by_query(data, query)
  local normalized = normalize_minigame_lookup_query(query, "key")
  local minigames = data.minigames_by_key or {}
  local direct_key = trim_string(minigame_query_value(normalized, "key") or "")
  if direct_key ~= "" and minigames[direct_key] then
    return direct_key, minigames[direct_key], { minigame_record_summary(direct_key, minigames[direct_key]) }, nil, normalized
  end

  local ruleset = trim_string(minigame_query_value(normalized, "ruleset", "minigameid", "id") or "")
  if ruleset ~= "" then
    local ruleset_key = minigame_key({ ruleset = ruleset })
    if minigames[ruleset_key] then
      return ruleset_key, minigames[ruleset_key], { minigame_record_summary(ruleset_key, minigames[ruleset_key]) }, nil, normalized
    end
  end

  local name = trim_string(minigame_query_value(normalized, "name", "minigame", "displayName") or "")
  local index_value = minigame_query_value(normalized, "index", "minigameIndex")
  local wanted_index = tonumber(index_value)
  if name ~= "" and index_value ~= nil and wanted_index ~= nil then
    local name_key = minigame_key({ name = name, index = wanted_index })
    if minigames[name_key] then
      return name_key, minigames[name_key], { minigame_record_summary(name_key, minigames[name_key]) }, nil, normalized
    end
  end

  local has_filter = direct_key ~= "" or ruleset ~= "" or name ~= "" or index_value ~= nil
  if not has_filter then
    return "", nil, {}, "minigame key, ruleset, name, or index is required", normalized
  end

  local direct_filter = normalize_api_filter_value(direct_key)
  local ruleset_filter = normalize_api_filter_value(ruleset)
  local name_filter = normalize_api_filter_value(name)
  local matches = {}
  for _, key in ipairs(minigame_sorted_keys(minigames)) do
    local record = minigames[key]
    if type(record) == "table" then
      local ok = true
      if direct_filter ~= "" then
        ok = normalize_api_filter_value(key) == direct_filter
          or normalize_api_filter_value(record.key) == direct_filter
          or normalize_api_filter_value(record.ruleset or record.id) == direct_filter
          or normalize_api_filter_value(record.name or record.minigame or record.displayName) == direct_filter
      end
      if ok and ruleset_filter ~= "" then
        ok = normalize_api_filter_value(record.ruleset or record.id) == ruleset_filter
      end
      if ok and name_filter ~= "" then
        ok = normalize_api_filter_value(record.name or record.minigame or record.displayName) == name_filter
      end
      if ok and index_value ~= nil then
        ok = wanted_index ~= nil and tonumber(record.index or record.minigameIndex) == wanted_index
      end
      if ok then
        matches[#matches + 1] = minigame_record_summary(key, record)
      end
    end
  end

  if #matches == 0 then
    return "", nil, matches, "minigame not found", normalized
  end
  local first_key = matches[1].key
  return first_key, minigames[first_key], matches, nil, normalized
end

function minigame_context_for_key(data, key, record, matches)
  local members = {}
  local teams = {}
  local team_memberships = {}
  local leaderboards = {}

  for _, player_key_name in ipairs(minigame_sorted_keys(data.memberships_by_player)) do
    local membership = data.memberships_by_player[player_key_name]
    if type(membership) == "table" and membership.minigameKey == key then
      local item = copy_table(membership)
      item.playerKey = player_key_name
      members[#members + 1] = item
    end
  end

  for _, team_key_name in ipairs(minigame_sorted_keys(data.teams_by_key)) do
    local team = data.teams_by_key[team_key_name]
    if type(team) == "table" and team.minigameKey == key then
      local item = copy_table(team)
      item.key = item.key or team_key_name
      teams[#teams + 1] = item
    end
  end

  for _, player_key_name in ipairs(minigame_sorted_keys(data.team_memberships_by_player)) do
    local membership = data.team_memberships_by_player[player_key_name]
    if type(membership) == "table" and membership.minigameKey == key then
      local item = copy_table(membership)
      item.playerKey = player_key_name
      team_memberships[#team_memberships + 1] = item
    end
  end

  for _, player_key_name in ipairs(minigame_sorted_keys(data.leaderboards_by_player)) do
    local leaderboard = data.leaderboards_by_player[player_key_name]
    if type(leaderboard) == "table" and leaderboard.minigameKey == key then
      local item = copy_table(leaderboard)
      item.playerKey = player_key_name
      leaderboards[#leaderboards + 1] = item
    end
  end

  return {
    key = key,
    minigame = copy_table(record or {}),
    members = members,
    teams = teams,
    teamMemberships = team_memberships,
    leaderboards = leaderboards,
    round = type(data.rounds_by_key[key]) == "table" and copy_table(data.rounds_by_key[key]) or nil,
    matches = copy_table(matches or {}),
    updatedAt = data.updated_at or "",
    source = data.source or "",
    totalUpdates = data.total_updates or 0,
    lastEvent = type(data.last_event) == "table" and copy_table(data.last_event) or nil,
    counts = {
      members = #members,
      teams = #teams,
      teamMemberships = #team_memberships,
      leaderboards = #leaderboards,
      matches = #(matches or {}),
    },
  }
end

function player_matches_query(key, player, normalized)
  local direct = normalize_api_filter_value(minigame_query_value(normalized, "key", "player", "playerid", "uuid", "id") or "")
  local name = normalize_api_filter_value(minigame_query_value(normalized, "name", "displayName", "username") or "")
  local state_value = normalize_api_filter_value(minigame_query_value(normalized, "state") or "")
  local controller = normalize_api_filter_value(minigame_query_value(normalized, "controller") or "")
  if direct == "" and name == "" and state_value == "" and controller == "" then
    return false
  end

  player = type(player) == "table" and player or {}
  if direct ~= "" then
    return normalize_api_filter_value(key) == direct
      or normalize_api_filter_value(player.id or player.uuid) == direct
      or normalize_api_filter_value(player.name or player.displayName or player.username) == direct
      or normalize_api_filter_value(player.state) == direct
      or normalize_api_filter_value(player.controller) == direct
  end
  if name ~= "" and normalize_api_filter_value(player.name or player.displayName or player.username) ~= name then
    return false
  end
  if state_value ~= "" and normalize_api_filter_value(player.state) ~= state_value then
    return false
  end
  if controller ~= "" and normalize_api_filter_value(player.controller) ~= controller then
    return false
  end
  return true
end

function minigame_find_player_by_query(data, query)
  local normalized = normalize_minigame_lookup_query(query, "player")
  local players = data.players_by_key or {}
  local direct = trim_string(minigame_query_value(normalized, "key", "player", "playerid", "uuid", "id") or "")
  if direct ~= "" and players[direct] then
    return direct, players[direct], nil, normalized
  end

  for _, key in ipairs(minigame_sorted_keys(players)) do
    local player = players[key]
    if player_matches_query(key, player, normalized) then
      return key, player, nil, normalized
    end
  end

  for _, key in ipairs(minigame_sorted_keys(data.memberships_by_player)) do
    local membership = data.memberships_by_player[key]
    if type(membership) == "table" and player_matches_query(key, membership.player, normalized) then
      return key, membership.player, nil, normalized
    end
  end

  for _, key in ipairs(minigame_sorted_keys(data.leaderboards_by_player)) do
    local leaderboard = data.leaderboards_by_player[key]
    if type(leaderboard) == "table" and player_matches_query(key, leaderboard.player, normalized) then
      return key, leaderboard.player, nil, normalized
    end
  end

  if direct == "" and minigame_query_value(normalized, "name", "displayName", "username", "state", "controller") == nil then
    return "", nil, "player id, name, state, or controller is required", normalized
  end
  return "", nil, "minigame player not found", normalized
end

function minigame_player_context(data, player_key_name, player)
  local membership = type(data.memberships_by_player[player_key_name]) == "table" and copy_table(data.memberships_by_player[player_key_name]) or nil
  local team_membership = type(data.team_memberships_by_player[player_key_name]) == "table" and copy_table(data.team_memberships_by_player[player_key_name]) or nil
  local leaderboard = type(data.leaderboards_by_player[player_key_name]) == "table" and copy_table(data.leaderboards_by_player[player_key_name]) or nil
  local minigame_key_name = ""
  if membership and membership.minigameKey then
    minigame_key_name = membership.minigameKey
  elseif team_membership and team_membership.minigameKey then
    minigame_key_name = team_membership.minigameKey
  elseif leaderboard and leaderboard.minigameKey then
    minigame_key_name = leaderboard.minigameKey
  end

  local team_key_name = team_membership and team_membership.teamKey or ""
  return {
    playerKey = player_key_name,
    player = copy_table(player or {}),
    membership = membership,
    teamMembership = team_membership,
    leaderboard = leaderboard,
    minigameKey = minigame_key_name,
    minigame = minigame_key_name ~= "" and copy_table(data.minigames_by_key[minigame_key_name] or {}) or nil,
    teamKey = team_key_name,
    team = team_key_name ~= "" and copy_table(data.teams_by_key[team_key_name] or {}) or nil,
    updatedAt = data.updated_at or "",
    source = data.source or "",
    totalUpdates = data.total_updates or 0,
    lastEvent = type(data.last_event) == "table" and copy_table(data.last_event) or nil,
  }
end

function minigame_query_limit(query, fallback, max_limit)
  local raw = minigame_query_value(query, "limit", "max", "count")
  local limit = tonumber(raw) or fallback or 25
  if limit < 1 then
    limit = 1
  end
  max_limit = max_limit or 100
  if limit > max_limit then
    limit = max_limit
  end
  return limit
end

function minigame_query_has_player_filter(query)
  return minigame_query_value(query, "player", "playerid", "uuid", "id", "state", "controller", "displayName", "username") ~= nil
end

function minigame_query_has_minigame_filter(query)
  return minigame_query_value(query, "minigameKey", "minigamekey", "ruleset", "minigameid", "minigame", "name", "index", "minigameIndex", "key") ~= nil
end

function minigame_query_minigame_key(data, query)
  local normalized = normalize_minigame_lookup_query(query, "key")
  local explicit_key = minigame_query_value(normalized, "minigameKey", "minigamekey")
  if explicit_key ~= nil and trim_string(explicit_key) ~= "" then
    normalized.key = explicit_key
  end
  if not minigame_query_has_minigame_filter(normalized) then
    return "", nil, nil, normalized
  end
  local key, record, matches, lookup_error = minigame_find_by_query(data, normalized)
  if not record then
    return "", nil, lookup_error or "minigame not found", normalized, matches
  end
  return key, record, nil, normalized, matches
end

function minigame_list_item(data, key, record, matches)
  local context = minigame_context_for_key(data, key, record, matches or { minigame_record_summary(key, record) })
  return {
    key = key,
    minigame = context.minigame,
    members = context.counts.members or 0,
    teams = context.counts.teams or 0,
    teamMemberships = context.counts.teamMemberships or 0,
    leaderboards = context.counts.leaderboards or 0,
    round = context.round,
  }
end

function minigame_event_matches_minigame(entry, query)
  if not minigame_query_has_minigame_filter(query) then
    return true
  end
  local payload = type(entry) == "table" and type(entry.payload) == "table" and entry.payload or {}
  local minigame = type(payload.minigame) == "table" and payload.minigame or payload
  local direct = normalize_api_filter_value(minigame_query_value(query, "minigameKey", "minigamekey", "key") or "")
  local ruleset = normalize_api_filter_value(minigame_query_value(query, "ruleset", "minigameid") or "")
  local name = normalize_api_filter_value(minigame_query_value(query, "minigame", "name") or "")
  local index_value = minigame_query_value(query, "index", "minigameIndex")
  local wanted_index = tonumber(index_value)
  local key = minigame_key(minigame)
  if direct ~= "" and normalize_api_filter_value(key) ~= direct then
    return false
  end
  if ruleset ~= "" and normalize_api_filter_value(minigame.ruleset or minigame.id) ~= ruleset then
    return false
  end
  if name ~= "" and normalize_api_filter_value(minigame.name or minigame.minigame or minigame.displayName) ~= name then
    return false
  end
  if index_value ~= nil and (wanted_index == nil or tonumber(minigame.index or minigame.minigameIndex) ~= wanted_index) then
    return false
  end
  return true
end

BMF.minigames.dataList = function(query)
  local data = state.minigame_data
  local normalized = normalize_minigame_lookup_query(query, "key")
  local limit = minigame_query_limit(normalized, 50, 100)
  local items = {}

  if minigame_query_has_minigame_filter(normalized) then
    local key, record, lookup_error, _, matches = minigame_query_minigame_key(data, normalized)
    if not record then
      return result(false, "MINIGAME_NOT_FOUND", lookup_error or "Minigame not found", {
        query = normalized,
        matches = copy_table(matches or {}),
        counts = minigame_data_counts(data),
      })
    end
    for _, match in ipairs(matches or { minigame_record_summary(key, record) }) do
      if #items >= limit then
        break
      end
      local match_key = match.key or key
      local match_record = data.minigames_by_key[match_key]
      if type(match_record) == "table" then
        items[#items + 1] = minigame_list_item(data, match_key, match_record, matches)
      end
    end
  else
    for _, key in ipairs(minigame_sorted_keys(data.minigames_by_key)) do
      if #items >= limit then
        break
      end
      local record = data.minigames_by_key[key]
      if type(record) == "table" then
        items[#items + 1] = minigame_list_item(data, key, record)
      end
    end
  end

  return result(true, "OK", "Minigame data listed", {
    items = items,
    count = #items,
    total = table_count(data.minigames_by_key),
    counts = minigame_data_counts(data),
    query = normalized,
    updatedAt = data.updated_at or "",
    source = data.source or "",
    totalUpdates = data.total_updates or 0,
    lastEvent = type(data.last_event) == "table" and copy_table(data.last_event) or nil,
  })
end

BMF.minigames.players = function(query)
  local data = state.minigame_data
  local normalized = normalize_minigame_lookup_query(query, "player")
  local limit = minigame_query_limit(normalized, 50, 100)
  local minigame_key_name = ""
  local lookup_error = nil
  if minigame_query_has_minigame_filter(normalized) and minigame_query_value(normalized, "player", "playerid", "uuid", "state", "controller", "username") == nil then
    local found_key, _, err = minigame_query_minigame_key(data, normalized)
    if err ~= nil then
      lookup_error = err
    else
      minigame_key_name = found_key
    end
  elseif minigame_query_value(normalized, "minigameKey", "minigamekey", "ruleset", "minigame") ~= nil then
    local found_key, _, err = minigame_query_minigame_key(data, normalized)
    if err ~= nil then
      lookup_error = err
    else
      minigame_key_name = found_key
    end
  end
  if lookup_error ~= nil then
    return result(false, "MINIGAME_NOT_FOUND", lookup_error, {
      query = normalized,
      counts = minigame_data_counts(data),
    })
  end

  local keys = {}
  local seen = {}
  for _, source in ipairs({ data.players_by_key, data.memberships_by_player, data.team_memberships_by_player, data.leaderboards_by_player }) do
    for key in pairs(source or {}) do
      if not seen[key] then
        seen[key] = true
        keys[#keys + 1] = key
      end
    end
  end
  table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)

  local items = {}
  local player_filter = minigame_query_has_player_filter(normalized)
  for _, key in ipairs(keys) do
    if #items >= limit then
      break
    end
    local player = data.players_by_key[key] or (data.memberships_by_player[key] and data.memberships_by_player[key].player) or {}
    local context = minigame_player_context(data, key, player)
    local ok = true
    if minigame_key_name ~= "" and context.minigameKey ~= minigame_key_name then
      ok = false
    end
    if ok and player_filter and not player_matches_query(key, context.player or {}, normalized) then
      ok = false
    end
    if ok then
      items[#items + 1] = context
    end
  end

  return result(true, "OK", "Minigame players listed", {
    players = items,
    count = #items,
    total = #keys,
    minigameKey = minigame_key_name,
    query = normalized,
    counts = minigame_data_counts(data),
    updatedAt = data.updated_at or "",
    source = data.source or "",
    totalUpdates = data.total_updates or 0,
  })
end

BMF.minigames.teams = function(query)
  local data = state.minigame_data
  local normalized = normalize_minigame_lookup_query(query, "team")
  local limit = minigame_query_limit(normalized, 50, 100)
  local minigame_key_name = ""
  if minigame_query_value(normalized, "minigameKey", "minigamekey", "ruleset", "minigame") ~= nil then
    local found_key, _, lookup_error = minigame_query_minigame_key(data, normalized)
    if lookup_error ~= nil then
      return result(false, "MINIGAME_NOT_FOUND", lookup_error, {
        query = normalized,
        counts = minigame_data_counts(data),
      })
    end
    minigame_key_name = found_key
  end

  local team_filter = normalize_api_filter_value(minigame_query_value(normalized, "team", "teamKey", "teamkey", "id") or "")
  local items = {}
  for _, key in ipairs(minigame_sorted_keys(data.teams_by_key)) do
    if #items >= limit then
      break
    end
    local team = data.teams_by_key[key]
    if type(team) == "table" then
      local ok = true
      if minigame_key_name ~= "" and team.minigameKey ~= minigame_key_name then
        ok = false
      end
      if ok and team_filter ~= "" then
        ok = normalize_api_filter_value(key) == team_filter
          or normalize_api_filter_value(team.key) == team_filter
          or normalize_api_filter_value(team.team or team.id or team.name) == team_filter
      end
      if ok then
        local item = copy_table(team)
        item.key = item.key or key
        item.memberCount = 0
        for _, membership in pairs(data.team_memberships_by_player or {}) do
          if type(membership) == "table" and membership.teamKey == key then
            item.memberCount = item.memberCount + 1
          end
        end
        items[#items + 1] = item
      end
    end
  end

  return result(true, "OK", "Minigame teams listed", {
    teams = items,
    count = #items,
    total = table_count(data.teams_by_key),
    minigameKey = minigame_key_name,
    query = normalized,
    counts = minigame_data_counts(data),
    updatedAt = data.updated_at or "",
    source = data.source or "",
    totalUpdates = data.total_updates or 0,
  })
end

local function minigame_leaderboard_score(row)
  row = type(row) == "table" and row or {}
  local values = type(row.leaderboard) == "table" and row.leaderboard or {}
  if tonumber(values[1]) ~= nil then
    return tonumber(values[1])
  end
  if tonumber(values.score) ~= nil then
    return tonumber(values.score)
  end
  if tonumber(values.points) ~= nil then
    return tonumber(values.points)
  end
  return 0
end

BMF.minigames.leaderboard = function(query)
  local data = state.minigame_data
  local normalized = normalize_minigame_lookup_query(query, "player")
  local limit = minigame_query_limit(normalized, 50, 100)
  local minigame_key_name = ""
  local lookup_error = nil
  if minigame_query_has_minigame_filter(normalized) and minigame_query_value(normalized, "player", "playerid", "uuid", "state", "controller", "username") == nil then
    local found_key, _, err = minigame_query_minigame_key(data, normalized)
    if err ~= nil then
      lookup_error = err
    else
      minigame_key_name = found_key
    end
  elseif minigame_query_value(normalized, "minigameKey", "minigamekey", "ruleset", "minigame") ~= nil then
    local found_key, _, err = minigame_query_minigame_key(data, normalized)
    if err ~= nil then
      lookup_error = err
    else
      minigame_key_name = found_key
    end
  end
  if lookup_error ~= nil then
    return result(false, "MINIGAME_NOT_FOUND", lookup_error, {
      query = normalized,
      counts = minigame_data_counts(data),
    })
  end

  local player_filter = minigame_query_has_player_filter(normalized)
  local team_filter = normalize_api_filter_value(minigame_query_value(normalized, "team", "teamKey", "teamkey") or "")
  local collected = {}
  for _, player_key_name in ipairs(minigame_sorted_keys(data.leaderboards_by_player)) do
    local leaderboard = data.leaderboards_by_player[player_key_name]
    if type(leaderboard) == "table" then
      local player = type(leaderboard.player) == "table" and leaderboard.player or data.players_by_key[player_key_name] or {}
      local team_membership = type(data.team_memberships_by_player[player_key_name]) == "table" and data.team_memberships_by_player[player_key_name] or nil
      local ok = true
      if minigame_key_name ~= "" and leaderboard.minigameKey ~= minigame_key_name then
        ok = false
      end
      if ok and player_filter and not player_matches_query(player_key_name, player, normalized) then
        ok = false
      end
      if ok and team_filter ~= "" then
        if not team_membership then
          ok = false
        else
          local team = type(team_membership.team) == "table" and team_membership.team or {}
          ok = normalize_api_filter_value(team_membership.teamKey) == team_filter
            or normalize_api_filter_value(team.key) == team_filter
            or normalize_api_filter_value(team.team or team.id or team.name) == team_filter
        end
      end
      if ok then
        local item = copy_table(leaderboard)
        item.playerKey = player_key_name
        item.player = copy_table(player)
        item.minigame = copy_table(item.minigame or data.minigames_by_key[item.minigameKey] or {})
        item.teamKey = team_membership and tostring(team_membership.teamKey or "") or ""
        item.team = team_membership and copy_table(team_membership.team or data.teams_by_key[item.teamKey] or {}) or nil
        item.values = copy_table(type(item.leaderboard) == "table" and item.leaderboard or {})
        item.oldValues = copy_table(type(item.oldLeaderboard) == "table" and item.oldLeaderboard or {})
        item.valueCount = #(item.values or {})
        item.score = minigame_leaderboard_score(item)
        collected[#collected + 1] = item
      end
    end
  end

  table.sort(collected, function(a, b)
    local a_score = tonumber(a.score) or 0
    local b_score = tonumber(b.score) or 0
    if a_score ~= b_score then
      return a_score > b_score
    end
    return tostring(a.playerKey or "") < tostring(b.playerKey or "")
  end)

  local items = {}
  for index, item in ipairs(collected) do
    if #items >= limit then
      break
    end
    item.rank = index
    items[#items + 1] = item
  end

  return result(true, "OK", "Minigame leaderboard listed", {
    leaderboards = items,
    count = #items,
    total = #collected,
    minigameKey = minigame_key_name,
    query = normalized,
    counts = minigame_data_counts(data),
    updatedAt = data.updated_at or "",
    source = data.source or "",
    totalUpdates = data.total_updates or 0,
    lastEvent = type(data.last_event) == "table" and copy_table(data.last_event) or nil,
  })
end

BMF.minigames.membership = function(query)
  local found = BMF.minigames.getPlayer(query)
  if not found.ok then
    return found
  end
  local data = found.data or {}
  if type(data.membership) ~= "table" then
    return result(false, "MINIGAME_MEMBERSHIP_NOT_FOUND", "Player has no known minigame membership", data)
  end
  found.message = "Minigame membership found"
  return found
end

BMF.minigames.recentEvents = function(filter)
  local normalized = normalize_minigame_lookup_query(filter, "event")
  local limit = minigame_query_limit(normalized, 10, 50)
  local event_filter = trim_string(minigame_query_value(normalized, "event", "name", "type") or "")
  local legacy_filter = ""
  if event_filter ~= "" then
    local normalized_event, event_error = normalize_minigame_event_name(event_filter)
    if not normalized_event then
      return result(false, "INVALID_MINIGAME_EVENT", event_error, {
        query = normalized,
      })
    end
    legacy_filter = normalized_event
  end
  local source_filter = normalize_api_filter_value(minigame_query_value(normalized, "source") or "")
  local player_filter = minigame_query_has_player_filter(normalized)
  local items = {}
  local recent = state.minigame_events.recent or {}
  for index = #recent, 1, -1 do
    if #items >= limit then
      break
    end
    local entry = recent[index]
    if type(entry) == "table" then
      local ok = true
      if legacy_filter ~= "" and entry.name ~= legacy_filter then
        ok = false
      end
      local payload = type(entry.payload) == "table" and entry.payload or {}
      if ok and source_filter ~= "" and normalize_api_filter_value(payload.source or entry.source) ~= source_filter then
        ok = false
      end
      if ok and player_filter and not player_matches_query(player_key(payload.player), payload.player or {}, normalized) then
        ok = false
      end
      if ok and not minigame_event_matches_minigame(entry, normalized) then
        ok = false
      end
      if ok then
        items[#items + 1] = copy_table(entry)
      end
    end
  end

  return result(true, "OK", "Recent minigame events listed", {
    events = items,
    count = #items,
    total = state.minigame_events.total or 0,
    query = normalized,
    limit = limit,
    event = legacy_filter,
    counts = copy_table(state.minigame_events.by_event or {}),
    last = type(state.minigame_events.last) == "table" and copy_table(state.minigame_events.last) or nil,
  })
end

BMF.minigames.data = function()
  local data = state.minigame_data
  return result(true, "OK", "Minigame data snapshot collected", {
    updatedAt = data.updated_at or "",
    source = data.source or "",
    totalUpdates = data.total_updates or 0,
    lastEvent = type(data.last_event) == "table" and copy_table(data.last_event) or nil,
    minigames = copy_table(data.minigames_by_key or {}),
    players = copy_table(data.players_by_key or {}),
    memberships = copy_table(data.memberships_by_player or {}),
    teams = copy_table(data.teams_by_key or {}),
    teamMemberships = copy_table(data.team_memberships_by_player or {}),
    leaderboards = copy_table(data.leaderboards_by_player or {}),
    rounds = copy_table(data.rounds_by_key or {}),
    counts = minigame_data_counts(data),
  })
end

BMF.minigames.applySnapshot = function(payload)
  if type(payload) ~= "table" then
    return result(false, "INVALID_MINIGAME_SNAPSHOT", "snapshot payload table is required", {
      counts = minigame_data_counts(state.minigame_data or new_minigame_data_state()),
    })
  end

  local snapshot_payload = copy_table(payload)
  local minigames = minigame_snapshot_records(snapshot_payload)
  if #minigames == 0 then
    return result(false, "INVALID_MINIGAME_SNAPSHOT", "snapshot must include at least one minigame", {
      counts = minigame_data_counts(state.minigame_data or new_minigame_data_state()),
    })
  end

  if trim_string(snapshot_payload.source or "") == "" then
    snapshot_payload.source = "bmf-snapshot-import"
  end
  state.minigame_data = state.minigame_data or new_minigame_data_state()
  local applied_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  remember_minigame_data("snapshot", snapshot_payload, applied_at)
  if write_status then
    write_status()
  end

  local data = state.minigame_data
  return result(true, "OK", "Minigame data snapshot applied", {
    appliedAt = applied_at,
    source = data.source or "",
    snapshotMinigames = #minigames,
    updatedAt = data.updated_at or "",
    totalUpdates = data.total_updates or 0,
    lastEvent = type(data.last_event) == "table" and copy_table(data.last_event) or nil,
    counts = minigame_data_counts(data),
  })
end

BMF.minigames.get = function(query)
  local data = state.minigame_data
  local key, record, matches, lookup_error, normalized = minigame_find_by_query(data, query)
  if not record then
    return result(false, "MINIGAME_NOT_FOUND", lookup_error or "Minigame not found", {
      query = normalized,
      matches = copy_table(matches or {}),
      counts = minigame_data_counts(data),
    })
  end
  return result(true, "OK", "Minigame data found", minigame_context_for_key(data, key, record, matches))
end

BMF.minigames.getPlayer = function(query)
  local data = state.minigame_data
  local key, player, lookup_error, normalized = minigame_find_player_by_query(data, query)
  if not player then
    return result(false, "MINIGAME_PLAYER_NOT_FOUND", lookup_error or "Minigame player not found", {
      query = normalized,
      counts = minigame_data_counts(data),
    })
  end
  return result(true, "OK", "Minigame player data found", minigame_player_context(data, key, player))
end

BMF.minigames.playerState = function(query)
  local data = state.minigame_data
  local key, player, lookup_error, normalized = minigame_find_player_by_query(data, query)
  if not player then
    return result(false, "MINIGAME_PLAYER_NOT_FOUND", lookup_error or "Minigame player not found", {
      query = normalized,
      inMinigame = false,
      reason = "player-not-found",
      counts = minigame_data_counts(data),
    })
  end

  local context = minigame_player_context(data, key, player)
  local membership = type(context.membership) == "table" and context.membership or nil
  local team_membership = type(context.teamMembership) == "table" and context.teamMembership or nil
  local leaderboard = type(context.leaderboard) == "table" and context.leaderboard or nil
  local current_minigame_key = membership and tostring(membership.minigameKey or "") or ""
  local current_team_key = ""
  if current_minigame_key ~= "" and team_membership and team_membership.minigameKey == current_minigame_key then
    current_team_key = tostring(team_membership.teamKey or "")
  end
  local activity_minigame_key = tostring(context.minigameKey or "")

  local current_minigame = nil
  if current_minigame_key ~= "" then
    current_minigame = copy_table(data.minigames_by_key[current_minigame_key] or membership.minigame or {})
  end

  local current_team = nil
  if current_team_key ~= "" then
    current_team = copy_table(data.teams_by_key[current_team_key] or team_membership.team or {})
  end

  return result(true, "OK", "Minigame player state resolved", {
    playerKey = key,
    player = copy_table(player or {}),
    inMinigame = membership ~= nil,
    minigameKey = current_minigame_key,
    minigame = current_minigame,
    teamKey = current_team_key,
    team = current_team,
    membership = membership,
    teamMembership = team_membership,
    leaderboard = leaderboard,
    activityMinigameKey = activity_minigame_key,
    activityMinigame = activity_minigame_key ~= "" and copy_table(data.minigames_by_key[activity_minigame_key] or context.minigame or {}) or nil,
    hasTeam = current_team_key ~= "",
    hasLeaderboard = leaderboard ~= nil,
    reason = membership and "membership" or "known-player-no-membership",
    query = normalized,
    updatedAt = data.updated_at or "",
    source = data.source or "",
    totalUpdates = data.total_updates or 0,
    lastEvent = type(data.last_event) == "table" and copy_table(data.last_event) or nil,
    counts = minigame_data_counts(data),
  })
end

BMF.minigames.clearData = function(confirm)
  local token = confirm
  if type(confirm) == "table" then
    token = confirm.confirm or confirm.token
  end
  if token ~= true and tostring(token or "") ~= "CLEAR_MINIGAME_DATA" then
    return result(false, "CONFIRMATION_REQUIRED", "Pass confirm=CLEAR_MINIGAME_DATA to clear minigame data.", {
      confirmRequired = "CLEAR_MINIGAME_DATA",
    })
  end

  local cleared_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  state.minigame_data = new_minigame_data_state()
  state.minigame_data.updated_at = cleared_at
  state.minigame_data.source = "manual-clear"
  return result(true, "OK", "Minigame data cache cleared", {
    clearedAt = cleared_at,
    source = state.minigame_data.source,
    counts = minigame_data_counts(state.minigame_data),
  })
end

BMF.minigames.dataStatus = function()
  local snapshot = BMF.minigames.data()
  local data = snapshot.data or {}
  local counts = data.counts or {}
  data.lines = {
    "total_updates=" .. tostring(data.totalUpdates or 0),
    "updated_at=" .. tostring(data.updatedAt or ""),
    "source=" .. tostring(data.source or ""),
    "minigames=" .. tostring(counts.minigames or 0),
    "players=" .. tostring(counts.players or 0),
    "memberships=" .. tostring(counts.memberships or 0),
    "teams=" .. tostring(counts.teams or 0),
    "team_memberships=" .. tostring(counts.teamMemberships or 0),
    "leaderboards=" .. tostring(counts.leaderboards or 0),
    "rounds=" .. tostring(counts.rounds or 0),
  }
  if data.lastEvent then
    data.lines[#data.lines + 1] = "last_event=" .. tostring(data.lastEvent.event or "")
    data.lines[#data.lines + 1] = "last_emitted_at=" .. tostring(data.lastEvent.emittedAt or "")
  end
  return result(true, "OK", "Minigame data status collected", data)
end

BMF.minigames.syntheticFlow = function(options)
  local opts = type(options) == "table" and options or {}
  local persist_value = string.lower(trim_string(opts.persist or opts.keep or ""))
  local cleanup_value = string.lower(trim_string(opts.cleanup or ""))
  local restore_data_after_emit = persist_value ~= "true" and persist_value ~= "1" and persist_value ~= "yes" and cleanup_value ~= "false"
  local data_before_emit = restore_data_after_emit and copy_table(state.minigame_data or new_minigame_data_state()) or nil
  local source = trim_string(opts.source or "")
  if source == "" then
    source = "bmf-minigame-synthetic-flow"
  end

  local minigame = {
    name = trim_string(opts.minigame or opts.minigamename or opts.name or "SyntheticArena"),
    index = tonumber(opts.index or opts.minigameindex) or 0,
  }
  if trim_string(opts.ruleset or opts.id or "") ~= "" then
    minigame.ruleset = trim_string(opts.ruleset or opts.id)
  end

  local player = {
    name = trim_string(opts.player or opts.playername or "MinigameFlowPlayer"),
    id = trim_string(opts.playerid or opts.uuid or "44444444-4444-4444-8444-444444444444"),
  }
  local victim = {
    name = trim_string(opts.victim or opts.victimname or "MinigameFlowVictim"),
    id = trim_string(opts.victimid or "55555555-5555-4555-8555-555555555555"),
  }
  local team = {
    name = trim_string(opts.team or "Red"),
  }

  local mkey = minigame_key(minigame)
  local pkey = player_key(player)
  local tkey = team_key(team, minigame)
  local checkpoints = {}
  local emitted_events = {}
  local handler_counts = {}
  local handler_metadata = {}
  local handler_ids = {}
  local listener_counts_before = {}
  local listener_counts_after = {}
  local handler_calls = 0
  local removed_all = true
  local failed_code = ""

  local sequence = {
    { name = "created", payload = { source = source, minigame = minigame } },
    { name = "joinminigame", payload = { source = source, player = player, minigame = minigame } },
    { name = "teamchange", payload = { source = source, player = player, minigame = minigame, team = team } },
    { name = "roundchange", payload = { source = source, minigame = minigame, round = 1 } },
    { name = "leaderboardchange", payload = { source = source, player = player, minigame = minigame, leaderboard = { 5, 2, 1 }, oldLeaderboard = { 0, 0, 0 } } },
    { name = "kill", payload = { source = source, player = player, victim = victim, minigame = minigame, leaderboard = { 6, 2, 1 }, oldLeaderboard = { 5, 2, 1 } } },
    { name = "leaveminigame", payload = { source = source, player = player, minigame = minigame, team = team, reason = "synthetic-flow" } },
    { name = "deleted", payload = { source = source, minigame = minigame } },
  }

  for _, item in ipairs(sequence) do
    listener_counts_before[item.name] = BMF.minigames.listenerCount(item.name)
    local handler_id, subscribe_error = BMF.minigames.on(item.name, function(payload, legacy_name)
      handler_calls = handler_calls + 1
      handler_counts[legacy_name] = (tonumber(handler_counts[legacy_name]) or 0) + 1
      handler_metadata[legacy_name] = copy_table((payload and payload._bmf) or {})
    end)
    if not handler_id then
      for _, existing_id in ipairs(handler_ids) do
        BMF.minigames.off(existing_id)
      end
      if restore_data_after_emit and data_before_emit then
        state.minigame_data = data_before_emit
        if write_status then
          write_status()
        end
      end
      return result(false, "SUBSCRIBE_FAILED", subscribe_error or "Could not subscribe to minigame flow event", {
        event = item.name,
        error = subscribe_error,
        lines = {
          "code=SUBSCRIBE_FAILED",
          "event=" .. tostring(item.name),
          "error=" .. tostring(subscribe_error or ""),
        },
      })
    end
    handler_ids[#handler_ids + 1] = handler_id
  end

  local function capture_checkpoint(name)
    local data = state.minigame_data or new_minigame_data_state()
    checkpoints[name] = {
      minigame = type(data.minigames_by_key[mkey]) == "table",
      player = type(data.players_by_key[pkey]) == "table",
      membership = type(data.memberships_by_player[pkey]) == "table",
      team = type(data.teams_by_key[tkey]) == "table",
      teamMembership = type(data.team_memberships_by_player[pkey]) == "table",
      leaderboard = type(data.leaderboards_by_player[pkey]) == "table",
      round = type(data.rounds_by_key[mkey]) == "table",
      counts = minigame_data_counts(data),
    }
  end

  for _, item in ipairs(sequence) do
    local emitted = BMF.minigames.emitEvent(item.name, item.payload)
    if not emitted.ok and failed_code == "" then
      failed_code = tostring(emitted.code or "FLOW_EMIT_FAILED")
    end
    local data = emitted.data or {}
    local metadata = data.payload and data.payload._bmf or {}
    emitted_events[#emitted_events + 1] = {
      event = data.event or ("minigames." .. item.name),
      legacyEvent = data.legacyEvent or item.name,
      code = emitted.code or "",
      ok = emitted.ok == true,
      handlers = data.handlers or 0,
      eventId = metadata.eventId or metadata.event_id or "",
    }
    capture_checkpoint("after_" .. item.name)
  end

  for index, handler_id in ipairs(handler_ids) do
    local item = sequence[index]
    local removed = BMF.minigames.off(handler_id)
    if removed ~= true then
      removed_all = false
    end
    if item then
      listener_counts_after[item.name] = BMF.minigames.listenerCount(item.name)
    end
  end

  local flow_counts = minigame_data_counts(state.minigame_data or new_minigame_data_state())
  local ok = failed_code == ""
  local code = ok and "OK" or failed_code
  local lines = {
    "code=" .. tostring(code),
    "source=" .. tostring(source),
    "emitted=" .. tostring(#emitted_events),
    "handler_calls=" .. tostring(handler_calls),
    "listeners_removed=" .. tostring(removed_all == true),
    "data_restored=" .. tostring(restore_data_after_emit == true),
    "data_persisted=" .. tostring(restore_data_after_emit ~= true),
    "minigame_key=" .. tostring(mkey),
    "player_key=" .. tostring(pkey),
    "team_key=" .. tostring(tkey),
    "after_created_minigame=" .. tostring(checkpoints.after_created and checkpoints.after_created.minigame == true),
    "after_join_membership=" .. tostring(checkpoints.after_joinminigame and checkpoints.after_joinminigame.membership == true),
    "after_team_membership=" .. tostring(checkpoints.after_teamchange and checkpoints.after_teamchange.teamMembership == true),
    "after_round_found=" .. tostring(checkpoints.after_roundchange and checkpoints.after_roundchange.round == true),
    "after_leaderboard_found=" .. tostring(checkpoints.after_leaderboardchange and checkpoints.after_leaderboardchange.leaderboard == true),
    "after_kill_leaderboard=" .. tostring(checkpoints.after_kill and checkpoints.after_kill.leaderboard == true),
    "after_leave_membership=" .. tostring(checkpoints.after_leaveminigame and checkpoints.after_leaveminigame.membership == true),
    "after_delete_minigame=" .. tostring(checkpoints.after_deleted and checkpoints.after_deleted.minigame == true),
    "after_delete_team=" .. tostring(checkpoints.after_deleted and checkpoints.after_deleted.team == true),
    "after_delete_round=" .. tostring(checkpoints.after_deleted and checkpoints.after_deleted.round == true),
    "after_delete_leaderboard=" .. tostring(checkpoints.after_deleted and checkpoints.after_deleted.leaderboard == true),
    "flow_minigames=" .. tostring(flow_counts.minigames or 0),
    "flow_players=" .. tostring(flow_counts.players or 0),
    "flow_memberships=" .. tostring(flow_counts.memberships or 0),
    "flow_teams=" .. tostring(flow_counts.teams or 0),
    "flow_team_memberships=" .. tostring(flow_counts.teamMemberships or 0),
    "flow_leaderboards=" .. tostring(flow_counts.leaderboards or 0),
    "flow_rounds=" .. tostring(flow_counts.rounds or 0),
  }

  for index, entry in ipairs(emitted_events) do
    lines[#lines + 1] =
      "event_" .. tostring(index) ..
      "=" .. tostring(entry.event or "") ..
      "|legacy=" .. tostring(entry.legacyEvent or "") ..
      "|code=" .. tostring(entry.code or "") ..
      "|handlers=" .. tostring(entry.handlers or 0)
  end

  local response_data = {
    source = source,
    minigame = copy_table(minigame),
    player = copy_table(player),
    victim = copy_table(victim),
    team = copy_table(team),
    minigameKey = mkey,
    playerKey = pkey,
    teamKey = tkey,
    emitted = emitted_events,
    handlerCalls = handler_calls,
    handlerCounts = handler_counts,
    handlerMetadata = handler_metadata,
    listenerCountsBefore = listener_counts_before,
    listenerCountsAfter = listener_counts_after,
    listenersRemoved = removed_all == true,
    checkpoints = checkpoints,
    flowCounts = flow_counts,
    dataRestored = restore_data_after_emit == true,
    dataPersisted = restore_data_after_emit ~= true,
    lines = lines,
  }

  if restore_data_after_emit and data_before_emit then
    state.minigame_data = data_before_emit
    if write_status then
      write_status()
    end
  end

  return result(ok, code, ok and "Synthetic minigame flow emitted" or "Synthetic minigame flow had errors", response_data)
end

BMF.world = {}
BMF.world.loadAdditive = function(options)
  if type(options) == "string" then
    options = { name = options }
  end
  if type(options) ~= "table" then
    return result(false, "INVALID_OPTIONS", "options table is required")
  end

  local name, name_error = normalize_world_name(options.name or options.bundle or options.world)
  if not name then
    return result(false, "INVALID_WORLD_NAME", name_error)
  end

  local position = options.position
  if type(position) ~= "table" then
    position = {}
  end
  local x = finite_number(options.x or position.x or position.X, 0)
  local y = finite_number(options.y or position.y or position.Y, 0)
  local z = finite_number(options.z or position.z or position.Z, 0)
  local yaw = finite_number(options.yaw or options.orientation or options.rotation, 0)

  local command = table.concat({
    "BR.World.LoadAdditive",
    quote_console_token(name),
    format_number(x),
    format_number(y),
    format_number(z),
    format_number(yaw),
  }, " ")

  local limited = rate_limit_check("world.loadAdditive")
  if not limited.ok then
    return limited
  end

  local response = exec_console_manager(command)
  response.data.command = command
  response.data.world = name
  response.data.position = { x = x, y = y, z = z, yaw = yaw }
  audit_record("world.loadAdditive", {
    world = name,
    command = command,
    position = response.data.position,
  }, {
    source = "framework",
    severity = response.ok and "info" or "warn",
    ok = response.ok,
    code = response.code,
  })
  if response.ok then
    BMF.events.emit("worldLoaded", {
      mode = "additive",
      world = name,
      command = command,
      position = response.data.position,
    })
  end
  return response
end

BMF.world.saveAs = function(name)
  local world_name, name_error = normalize_world_name(name)
  if not world_name then
    return result(false, "INVALID_WORLD_NAME", name_error)
  end

  local command = "BR.World.SaveAs " .. quote_console_string(world_name)
  local limited = rate_limit_check("world.saveAs")
  if not limited.ok then
    return limited
  end
  local response = exec_console_manager(command)
  response.data.command = command
  response.data.world = world_name
  audit_record("world.saveAs", {
    world = world_name,
    command = command,
  }, {
    source = "framework",
    severity = response.ok and "info" or "warn",
    ok = response.ok,
    code = response.code,
  })
  if response.ok then
    BMF.events.emit("worldSaved", {
      world = world_name,
      command = command,
    })
  end
  return response
end

BMF.prefabs = {}

local function normalize_prefab_source(value)
  local source = trim_string(value)
  if source == "" then
    return nil, "prefab source is required"
  end
  if source:match("[%c]") or source:match("[/\\]") or source:match("%.%.") then
    return nil, "prefab source must not contain control characters or path separators"
  end
  local lower = source:lower()
  if lower:match("%.") and not lower:match("%.brz$") then
    return nil, "prefab source must be a .brz file"
  end
  return source
end

local function prefab_position_from_options(options)
  local position = options.position
  if type(position) ~= "table" then
    position = {}
  end
  return {
    x = finite_number(options.x or position.x or position.X, 0),
    y = finite_number(options.y or position.y or position.Y, 0),
    z = finite_number(options.z or position.z or position.Z, 0),
    yaw = finite_number(options.yaw or options.orientation or options.rotation, 0),
  }
end

local function normalize_staged_prefab_world(options)
  return normalize_world_name(options.stagedWorld or options.stage or options.name or options.bundle or options.world)
end

function has_staged_prefab_world_option(options)
  return options.stagedWorld ~= nil or options.stage ~= nil or options.name ~= nil or options.bundle ~= nil or options.world ~= nil
end

local function prefab_save_region_enabled()
  return BMF_env_bool("BMF_PREFAB_SAVE_REGION_ENABLED", BMF_env_bool("BMF_BRICK_WORLD_REGION_SCAN_ENABLED", false))
end

local function prefab_save_region_next_sequence()
  local store = state.tools.prefab_region
  store.sequence = (tonumber(store.sequence) or 0) + 1
  return store.sequence
end

local function prefab_save_region_prefabs_dir()
  local configured = first_string(
    BMF_env_string("BMF_PREFAB_SAVE_REGION_PREFABS_DIR"),
    BMF_env_string("BMF_BRICKADIA_PREFABS_DIR"))
  if configured then
    return configured:gsub("\\", "/"):gsub("/+$", "")
  end

  local saved_dir = first_string(
    BMF_env_string("BMF_BRICKADIA_SAVED_DIR"),
    state.config and state.config.brickadiaSavedDir or "")
  if saved_dir then
    return join_path(saved_dir:gsub("\\", "/"), "Prefabs")
  end

  local builds_dir = first_string(
    BMF_env_string("BMF_BRICK_WORLD_REGION_SCAN_BUILDS_DIR"),
    BMF_env_string("BMF_BRICKADIA_BUILDS_DIR"))
  if builds_dir then
    local parent = builds_dir:gsub("\\", "/"):gsub("/+$", ""):match("^(.*)/Builds$")
    if parent and parent ~= "" then
      return join_path(parent, "Prefabs")
    end
  end

  return ""
end

local function prefab_save_region_normalize_path(value, sequence)
  local text = trim_string(value or "")
  if text == "" then
    text = "BMFRegionProbe_" .. tostring(sequence) .. "_" .. tostring(os.time())
  end
  text = text:gsub("\\", "/")
  if text:lower():match("%.brz$") then
    text = text:sub(1, #text - 4)
  end

  local relative, relative_err = safe_relative_path(text, "prefab path")
  if not relative then
    return nil, relative_err
  end
  if not relative:match("^[A-Za-z0-9_/%-%.]+$") then
    return nil, "prefab path may only contain letters, numbers, slash, dash, underscore, and dot"
  end
  return relative
end

local function prefab_save_region_file_exists(path)
  local handle = io.open(path, "rb")
  if not handle then
    return false
  end
  handle:close()
  return true
end

local function prefab_save_region_exec_once(command, executor)
  if executor == "native" then
    if type(_G.BMFSocketPrefabSaveRegion) ~= "function" then
      return result(false, "EXECUTOR_UNAVAILABLE", "Native prefab save-region executor is unavailable", {
        executor = executor,
        required_native = "BMFSocketPrefabSaveRegion",
      })
    end
    return result(false, "NATIVE_EXEC_NOT_IMPLEMENTED", "Native prefab save-region executor has not been wired for this build", {
      executor = executor,
      required_native = "BMFSocketPrefabSaveRegion",
    })
  end

  if executor == "console_manager_probe" then
    if type(_G.BMFSocketConsoleManagerInputProbe) ~= "function" then
      return result(false, "EXECUTOR_UNAVAILABLE", "Native console-manager probe is unavailable", {
        executor = executor,
        required_native = "BMFSocketConsoleManagerInputProbe",
      })
    end
    local ok, output = pcall(_G.BMFSocketConsoleManagerInputProbe, command, "console-manager-input-probe", "0xE0", "world")
    if not ok then
      return result(false, "CONSOLE_EXEC_FAILED", tostring(output or "native console-manager probe failed"), {
        executor = executor,
      })
    end
    output = tostring(output or "")
    local success = output:match("\nok=true") ~= nil or output:match("^ok=true") ~= nil
    local detail = output:match("\ndetail=([^\r\n]*)") or output:match("^detail=([^\r\n]*)") or ""
    return result(success, success and "OK" or "CONSOLE_EXEC_FAILED", detail, {
      executor = executor,
      output = output,
    })
  end

  if executor == "console_manager" then
    if type(OmeggaExecuteConsoleManagerInput) ~= "function" then
      return result(false, "CONSOLE_EXEC_UNAVAILABLE", "OmeggaExecuteConsoleManagerInput is unavailable", { executor = executor })
    end
    local ok, success, output = pcall(OmeggaExecuteConsoleManagerInput, command)
    if ok and success then
      return result(true, "OK", "Command executed", { executor = executor, output = output or "" })
    end
    return result(false, "CONSOLE_EXEC_FAILED", tostring(output or success), { executor = executor })
  end

  if executor == "kismet" then
    if type(OmeggaExecuteKismetConsoleCommand) ~= "function" then
      return result(false, "CONSOLE_EXEC_UNAVAILABLE", "OmeggaExecuteKismetConsoleCommand is unavailable", { executor = executor })
    end
    local ok, success, output = pcall(OmeggaExecuteKismetConsoleCommand, command)
    if ok and success then
      return result(true, "OK", "Command executed", { executor = executor, output = output or "" })
    end
    return result(false, "CONSOLE_EXEC_FAILED", tostring(output or success), { executor = executor })
  end

  if executor == "cached_console" then
    if type(OmeggaExecuteCachedConsoleExec) ~= "function" then
      return result(false, "CONSOLE_EXEC_UNAVAILABLE", "OmeggaExecuteCachedConsoleExec is unavailable", { executor = executor })
    end
    local ok, success, output = pcall(OmeggaExecuteCachedConsoleExec, command)
    if ok and success then
      return result(true, "OK", "Command executed", { executor = executor, output = output or "" })
    end
    return result(false, "CONSOLE_EXEC_FAILED", tostring(output or success), { executor = executor })
  end

  return result(false, "CONSOLE_EXEC_UNAVAILABLE", "Unknown prefab save-region executor", { executor = executor })
end

local function prefab_save_region_exec_command(command, requested_executor)
  local requested = trim_string(requested_executor or ""):lower()
  requested = requested:gsub("%-", "_")
  if requested == "" or requested == "all" or requested == "auto" then
    requested = "all"
  elseif requested == "manager" or requested == "consolemanager" then
    requested = "console_manager"
  elseif requested == "probe" or requested == "consolemanagerprobe" or requested == "console_manager_input_probe" then
    requested = "console_manager_probe"
  elseif requested == "cached" or requested == "console" then
    requested = "cached_console"
  end

  local executors = {}
  if requested == "all" then
    executors = { "console_manager", "kismet", "cached_console" }
  else
    executors = { requested }
  end

  local attempts = {}
  local last_response = nil
  for _, executor in ipairs(executors) do
    local response = prefab_save_region_exec_once(command, executor)
    attempts[#attempts + 1] = {
      executor = executor,
      ok = response.ok,
      code = response.code,
      message = response.message,
    }
    if response.ok then
      response.data.attempts = attempts
      return response
    end
    last_response = response
  end

  if #executors == 1 and last_response and last_response.code == "EXECUTOR_UNAVAILABLE" then
    last_response.data = type(last_response.data) == "table" and last_response.data or {}
    last_response.data.attempts = attempts
    return last_response
  end

  local message = last_response and last_response.message or "No prefab save-region executor succeeded"
  return result(false, "CONSOLE_EXEC_FAILED", message, {
    executor = last_response and last_response.data and last_response.data.executor or requested,
    attempts = attempts,
  })
end

local function prefab_save_region_store_result(sequence, ok, code, message, lines, data)
  local store = state.tools.prefab_region
  store.last_result = {
    sequence = sequence,
    ok = ok and true or false,
    code = tostring(code or (ok and "OK" or "ERROR")),
    message = tostring(message or ""),
    updated_at = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    lines = copy_table(lines or {}),
    data = copy_table(data or {}),
  }
  store.last_error = ok and "" or store.last_result.message
  return store.last_result
end

BMF.prefabs.saveRegionStatus = function()
  local last = state.tools.prefab_region.last_result
  if not last then
    return result(false, "PREFAB_SAVE_REGION_NO_RESULT", "No prefab save-region probe has completed.", {
      lines = {
        "ok=false",
        "code=PREFAB_SAVE_REGION_NO_RESULT",
        "operation=prefab-save-region-status",
      },
    })
  end

  local data = copy_table(last.data or {})
  data.sequence = last.sequence
  data.updated_at = last.updated_at
  data.lines = copy_table(last.lines or {})
  return result(last.ok, last.code, last.message, data)
end

local function prefab_transfer_decode(value)
  return trim_string(percent_decode(value or ""))
end

local function prefab_transfer_store_result(transfer_id, ok, code, message, lines, data)
  local store = state.tools.prefab_region
  transfer_id = trim_string(transfer_id or "")
  if transfer_id == "" then
    transfer_id = "transfer_" .. tostring(prefab_save_region_next_sequence()) .. "_" .. tostring(os.time())
  end
  local record = {
    transfer_id = transfer_id,
    ok = ok and true or false,
    code = tostring(code or (ok and "OK" or "ERROR")),
    message = tostring(message or ""),
    updated_at = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    lines = copy_table(lines or {}),
    data = copy_table(data or {}),
  }
  store.transfers = type(store.transfers) == "table" and store.transfers or {}
  store.transfer_order = type(store.transfer_order) == "table" and store.transfer_order or {}
  store.transfers[transfer_id] = record
  store.transfer_order[#store.transfer_order + 1] = transfer_id
  store.last_transfer_id = transfer_id
  store.last_error = ok and "" or record.message
  local max_records = math.max(1, BMF_env_number("BMF_PREFAB_TRANSFER_STATUS_RETENTION", 20, 1))
  while #store.transfer_order > max_records do
    local removed = table.remove(store.transfer_order, 1)
    if removed and removed ~= transfer_id then
      store.transfers[removed] = nil
    end
  end
  return record
end

local function prefab_transfer_record_result(transfer_id, ok, code, message, data)
  data = type(data) == "table" and data or {}
  local lines = {
    "ok=" .. tostring(ok and true or false),
    "code=" .. tostring(code or (ok and "OK" or "ERROR")),
    "operation=property-prefab-transfer",
    "transfer_id=" .. tostring(transfer_id or ""),
    "stage=" .. tostring(data.stage or ""),
    "property_id=" .. tostring(data.propertyId or ""),
    "owner_id=" .. tostring(data.ownerId or ""),
    "source_prefab_path=" .. tostring(data.sourcePrefabPath or ""),
    "owned_prefab_path=" .. tostring(data.ownedPrefabPath or ""),
    "rollback_command=" .. tostring(data.rollbackCommand or ""),
    "brick_count=" .. tostring(data.brickCount or 0),
    "owner_count=" .. tostring(data.ownerCount or 0),
    "detail=" .. tostring(message or ""),
  }
  if type(data.requiredNative) == "table" then
    lines[#lines + 1] = "required_native=" .. table.concat(data.requiredNative, "|")
  end
  if data.nativeAvailable ~= nil then
    lines[#lines + 1] = "native_available=" .. tostring(data.nativeAvailable == true)
  end
  if data.center then
    lines[#lines + 1] = "x=" .. tostring(data.center.x or "")
    lines[#lines + 1] = "y=" .. tostring(data.center.y or "")
    lines[#lines + 1] = "z=" .. tostring(data.center.z or "")
  end
  if data.extent then
    lines[#lines + 1] = "extent_x=" .. tostring(data.extent.x or "")
    lines[#lines + 1] = "extent_y=" .. tostring(data.extent.y or "")
    lines[#lines + 1] = "extent_z=" .. tostring(data.extent.z or "")
  end
  data.lines = lines
  prefab_transfer_store_result(transfer_id, ok, code, message, lines, data)
  audit_record("prefabs.transferRegionOwnership", data, {
    source = "framework",
    severity = ok and "info" or "warn",
    ok = ok and true or false,
    code = tostring(code or ""),
  })
  return result(ok, code, message, data)
end

local function prefab_transfer_native_status()
  local required = {
    "BMFSocketPrefabSaveRegion",
    "BMFSocketWorldClearRegion",
    "BMFSocketPrefabLoad",
  }
  local missing = {}
  for _, name in ipairs(required) do
    if type(_G[name]) ~= "function" then
      missing[#missing + 1] = name
    end
  end
  return #missing == 0, required, missing
end

local function prefab_transfer_validate_region(options)
  local positional = type(options._positional) == "table" and options._positional or {}
  local x = tonumber(options.x or options.centerx or options.center_x or positional[1])
  local y = tonumber(options.y or options.centery or options.center_y or positional[2])
  local z = tonumber(options.z or options.centerz or options.center_z or positional[3])
  local extent_x = tonumber(options.ex or options.extentx or options.extent_x or positional[4])
  local extent_y = tonumber(options.ey or options.extenty or options.extent_y or positional[5])
  local extent_z = tonumber(options.ez or options.extentz or options.extent_z or positional[6])
  if not (x and y and z and extent_x and extent_y and extent_z) then
    return nil, "PREFAB_TRANSFER_REGION_REQUIRED", "x y z ex ey ez are required"
  end

  local max_extent = BMF_env_number("BMF_PREFAB_TRANSFER_MAX_EXTENT", 512, 1)
  local max_extent_z = BMF_env_number("BMF_PREFAB_TRANSFER_MAX_EXTENT_Z", 1024, 1)
  x = math.floor(x)
  y = math.floor(y)
  z = math.floor(z)
  extent_x = math.floor(extent_x)
  extent_y = math.floor(extent_y)
  extent_z = math.floor(extent_z)
  if extent_x <= 0 or extent_y <= 0 or extent_z <= 0 then
    return nil, "PREFAB_TRANSFER_REGION_INVALID", "lot extents must be positive"
  end
  if extent_x > max_extent or extent_y > max_extent or extent_z > max_extent_z then
    return nil, "PREFAB_TRANSFER_EXTENT_TOO_LARGE", "lot extents exceed configured maximum"
  end

  return {
    center = { x = x, y = y, z = z },
    extent = { x = extent_x, y = extent_y, z = extent_z },
  }
end

local function prefab_transfer_prefab_paths(property_id, path_prefix, sequence)
  local base_path = path_prefix
  if trim_string(base_path or "") == "" then
    base_path = "CityRPGTransfers/" .. tostring(property_id or "property") .. "/" .. tostring(sequence) .. "_" .. tostring(os.time())
  end
  local source_path, source_err = prefab_save_region_normalize_path(base_path .. "_source", sequence)
  if not source_path then
    return nil, nil, source_err
  end
  local owned_path, owned_err = prefab_save_region_normalize_path(base_path .. "_owned", sequence)
  if not owned_path then
    return nil, nil, owned_err
  end
  local prefabs_dir = prefab_save_region_prefabs_dir()
  return join_path(prefabs_dir, source_path .. ".brz"), join_path(prefabs_dir, owned_path .. ".brz"), nil, source_path, owned_path
end

BMF.prefabs.transferRegionStatus = function(options)
  options = type(options) == "table" and options or {}
  local transfer_id = prefab_transfer_decode(options.transferid or options.transfer_id or "")
  local store = state.tools.prefab_region
  if transfer_id == "" then
    transfer_id = trim_string(store.last_transfer_id or "")
  end
  local record = transfer_id ~= "" and store.transfers and store.transfers[transfer_id] or nil
  if type(record) ~= "table" then
    return result(false, "PREFAB_TRANSFER_NO_RESULT", "No property prefab transfer result is available.", {
      lines = {
        "ok=false",
        "code=PREFAB_TRANSFER_NO_RESULT",
        "operation=property-prefab-transfer-status",
        "transfer_id=" .. tostring(transfer_id or ""),
      },
    })
  end

  local data = copy_table(record.data or {})
  data.transferId = transfer_id
  data.updatedAt = record.updated_at
  data.lines = copy_table(record.lines or {})
  return result(record.ok, record.code, record.message, data)
end

BMF.prefabs.transferRegionRollback = function(options)
  options = type(options) == "table" and options or {}
  local transfer_id = prefab_transfer_decode(options.transferid or options.transfer_id or "")
  if tostring(options.confirm or options.confirmation or "") ~= "property-transfer" then
    return result(false, "PREFAB_TRANSFER_CONFIRM_REQUIRED", "confirm=property-transfer is required for prefab transfer rollback", {
      lines = {
        "ok=false",
        "code=PREFAB_TRANSFER_CONFIRM_REQUIRED",
        "operation=property-prefab-transfer-rollback",
        "transfer_id=" .. transfer_id,
        "required_confirm=property-transfer",
      },
    })
  end
  if transfer_id == "" then
    return result(false, "PREFAB_TRANSFER_ID_REQUIRED", "transfer_id is required for prefab transfer rollback", {
      lines = {
        "ok=false",
        "code=PREFAB_TRANSFER_ID_REQUIRED",
        "operation=property-prefab-transfer-rollback",
      },
    })
  end

  local native_available, required_native, missing_native = prefab_transfer_native_status()
  if not native_available then
    local message = "Native prefab rollback executor is unavailable."
    return prefab_transfer_record_result(transfer_id, false, "EXECUTOR_UNAVAILABLE", message, {
      stage = "rollback",
      transferId = transfer_id,
      nativeAvailable = false,
      requiredNative = required_native,
      missingNative = missing_native,
    })
  end

  return prefab_transfer_record_result(transfer_id, false, "ROLLBACK_NOT_IMPLEMENTED", "Native prefab rollback executor has not been wired for this build.", {
    stage = "rollback",
    transferId = transfer_id,
    nativeAvailable = true,
    requiredNative = required_native,
  })
end

BMF.prefabs.transferRegionOwnership = function(options)
  options = type(options) == "table" and options or {}
  local sequence = prefab_save_region_next_sequence()
  local property_id = prefab_transfer_decode(options.propertyid or options.property_id or options.lot or options.lotid or options.id)
  local owner_id = prefab_transfer_decode(options.ownerid or options.owner_id or options.userid or options.user_id)
  local owner_name = prefab_transfer_decode(options.ownername or options.owner_name or options.name)
  local owner_display_name = prefab_transfer_decode(options.ownerdisplayname or options.owner_display_name or options.displayname or options.display_name)
  local transfer_id = prefab_transfer_decode(options.transferid or options.transfer_id)
  if transfer_id == "" then
    transfer_id = tostring(property_id ~= "" and property_id or "property") .. "_" .. tostring(sequence) .. "_" .. tostring(os.time())
  end

  if tostring(options.confirm or options.confirmation or "") ~= "property-transfer" then
    return prefab_transfer_record_result(transfer_id, false, "PREFAB_TRANSFER_CONFIRM_REQUIRED", "confirm=property-transfer is required for property prefab transfers", {
      stage = "validate",
      propertyId = property_id,
      ownerId = owner_id,
      transferId = transfer_id,
    })
  end
  if property_id == "" then
    return prefab_transfer_record_result(transfer_id, false, "PREFAB_TRANSFER_PROPERTY_REQUIRED", "property_id is required for property prefab transfers", {
      stage = "validate",
      ownerId = owner_id,
      transferId = transfer_id,
    })
  end
  if owner_id == "" then
    return prefab_transfer_record_result(transfer_id, false, "PREFAB_TRANSFER_OWNER_REQUIRED", "owner_id is required for property prefab transfers", {
      stage = "validate",
      propertyId = property_id,
      transferId = transfer_id,
    })
  end

  local region, region_code, region_message = prefab_transfer_validate_region(options)
  if not region then
    return prefab_transfer_record_result(transfer_id, false, region_code, region_message, {
      stage = "validate",
      propertyId = property_id,
      ownerId = owner_id,
      transferId = transfer_id,
    })
  end

  local prefabs_dir = prefab_save_region_prefabs_dir()
  if prefabs_dir == "" then
    return prefab_transfer_record_result(transfer_id, false, "PREFAB_TRANSFER_PREFABS_DIR_REQUIRED", "BMF_PREFAB_SAVE_REGION_PREFABS_DIR or BMF_BRICKADIA_SAVED_DIR is required", {
      stage = "validate",
      propertyId = property_id,
      ownerId = owner_id,
      transferId = transfer_id,
      center = region.center,
      extent = region.extent,
    })
  end

  local source_file, owned_file, path_error, source_relative, owned_relative = prefab_transfer_prefab_paths(property_id, prefab_transfer_decode(options.pathprefix or options.path_prefix), sequence)
  if path_error then
    return prefab_transfer_record_result(transfer_id, false, "PREFAB_TRANSFER_PATH_INVALID", path_error, {
      stage = "validate",
      propertyId = property_id,
      ownerId = owner_id,
      transferId = transfer_id,
      center = region.center,
      extent = region.extent,
    })
  end

  local native_available, required_native, missing_native = prefab_transfer_native_status()
  if not native_available then
    local message = "Native prefab transfer executor is unavailable."
    return prefab_transfer_record_result(transfer_id, false, "EXECUTOR_UNAVAILABLE", message, {
      stage = "save_region",
      propertyId = property_id,
      ownerId = owner_id,
      ownerName = owner_name,
      ownerDisplayName = owner_display_name,
      transferId = transfer_id,
      sourcePrefabPath = source_file,
      ownedPrefabPath = owned_file,
      sourcePrefab = source_relative,
      ownedPrefab = owned_relative,
      center = region.center,
      extent = region.extent,
      includeEntities = option_boolean({ include_entities = options.includeentities or options.include_entities or options.entities }, "include_entities", false),
      nativeAvailable = false,
      requiredNative = required_native,
      missingNative = missing_native,
    })
  end

  if not BMF_env_bool("BMF_PREFAB_TRANSFER_ENABLED", false) then
    return prefab_transfer_record_result(transfer_id, false, "PREFAB_TRANSFER_DISABLED", "Set BMF_PREFAB_TRANSFER_ENABLED=1 after native prefab transfer helpers are validated.", {
      stage = "validate",
      propertyId = property_id,
      ownerId = owner_id,
      transferId = transfer_id,
      sourcePrefabPath = source_file,
      ownedPrefabPath = owned_file,
      center = region.center,
      extent = region.extent,
      nativeAvailable = true,
      requiredNative = required_native,
    })
  end

  return prefab_transfer_record_result(transfer_id, false, "TRANSFER_NOT_IMPLEMENTED", "Native prefab transfer executor exists but has not been wired for this build.", {
    stage = "save_region",
    propertyId = property_id,
    ownerId = owner_id,
    transferId = transfer_id,
    sourcePrefabPath = source_file,
    ownedPrefabPath = owned_file,
    center = region.center,
    extent = region.extent,
    nativeAvailable = true,
    requiredNative = required_native,
  })
end

BMF.prefabs.saveRegionProbe = function(options)
  options = type(options) == "table" and options or {}
  local positional = type(options._positional) == "table" and options._positional or {}
  local confirm = tostring(options.confirm or options.confirmation or positional[8] or "")
  if confirm ~= "prefab-save-region" then
    return result(false, "PREFAB_SAVE_REGION_CONFIRM_REQUIRED", "confirm=prefab-save-region is required for EA3 prefab save-region probes", {
      lines = {
        "ok=false",
        "code=PREFAB_SAVE_REGION_CONFIRM_REQUIRED",
        "required_confirm=prefab-save-region",
      },
    })
  end
  if not prefab_save_region_enabled() then
    return result(false, "PREFAB_SAVE_REGION_DISABLED", "EA3 prefab save-region probes are disabled", {
      lines = {
        "ok=false",
        "code=PREFAB_SAVE_REGION_DISABLED",
        "required_env=BMF_PREFAB_SAVE_REGION_ENABLED=1",
      },
    })
  end

  local x = tonumber(options.x or options.centerx or options.centerX or positional[1])
  local y = tonumber(options.y or options.centery or options.centerY or positional[2])
  local z = tonumber(options.z or options.centerz or options.centerZ or positional[3])
  local extent_x = tonumber(options.ex or options.extentx or options.extentX or options.halfx or options.halfX or positional[4])
  local extent_y = tonumber(options.ey or options.extenty or options.extentY or options.halfy or options.halfY or positional[5])
  local extent_z = tonumber(options.ez or options.extentz or options.extentZ or options.halfz or options.halfZ or positional[6])
  if not (x and y and z and extent_x and extent_y and extent_z) then
    return result(false, "PREFAB_SAVE_REGION_ARGUMENTS_REQUIRED", "x y z ex ey ez are required for EA3 prefab save-region probes", {
      lines = {
        "ok=false",
        "code=PREFAB_SAVE_REGION_ARGUMENTS_REQUIRED",
      },
    })
  end

  x = math.floor(x)
  y = math.floor(y)
  z = math.floor(z)
  extent_x = math.max(0, math.floor(extent_x))
  extent_y = math.max(0, math.floor(extent_y))
  extent_z = math.max(0, math.floor(extent_z))

  local max_extent = BMF_env_number("BMF_PREFAB_SAVE_REGION_MAX_EXTENT", 512, 1)
  local max_extent_z = BMF_env_number("BMF_PREFAB_SAVE_REGION_MAX_EXTENT_Z", 1024, 1)
  if extent_x > max_extent or extent_y > max_extent or extent_z > max_extent_z then
    return result(false, "PREFAB_SAVE_REGION_EXTENT_TOO_LARGE", "prefab save-region extent exceeds configured maximum", {
      lines = {
        "ok=false",
        "code=PREFAB_SAVE_REGION_EXTENT_TOO_LARGE",
        "extent_x=" .. tostring(extent_x),
        "extent_y=" .. tostring(extent_y),
        "extent_z=" .. tostring(extent_z),
        "max_extent=" .. tostring(max_extent),
        "max_extent_z=" .. tostring(max_extent_z),
      },
    })
  end

  local prefabs_dir = prefab_save_region_prefabs_dir()
  if prefabs_dir == "" then
    return result(false, "PREFAB_SAVE_REGION_PREFABS_DIR_REQUIRED", "BMF_PREFAB_SAVE_REGION_PREFABS_DIR or BMF_BRICKADIA_SAVED_DIR is required", {
      lines = {
        "ok=false",
        "code=PREFAB_SAVE_REGION_PREFABS_DIR_REQUIRED",
      },
    })
  end

  local sequence = prefab_save_region_next_sequence()
  local relative_path, relative_err = prefab_save_region_normalize_path(options.path or options.name or options.prefab or options.save or positional[7], sequence)
  if not relative_path then
    return result(false, "PREFAB_SAVE_REGION_PATH_INVALID", relative_err, {
      lines = {
        "ok=false",
        "code=PREFAB_SAVE_REGION_PATH_INVALID",
        "detail=" .. tostring(relative_err or ""),
      },
    })
  end

  local save_path = join_path(prefabs_dir, relative_path .. ".brz")
  os.remove(save_path)

  local include_entities = option_boolean({
    includeentities = options.includeentities or options.includeEntities or options.entities,
  }, "includeentities", false)
  local cleanup = option_boolean({ cleanup = options.cleanup or options.delete }, "cleanup", false)
  local command = table.concat({
    "br.Prefab.SaveRegion",
    quote_console_string(relative_path),
    tostring(x),
    tostring(y),
    tostring(z),
    tostring(extent_x),
    tostring(extent_y),
    tostring(extent_z),
    include_entities and "true" or "false",
  }, " ")

  local executor = options.executor or options.route or options.mode or "all"
  local response = prefab_save_region_exec_command(command, executor)
  audit_record("prefabs.saveRegionProbe", {
    command = command,
    path = relative_path,
    save_path = save_path,
    executor = tostring(executor or "all"),
  }, {
    source = "framework",
    severity = response.ok and "info" or "warn",
    ok = response.ok,
    code = response.code,
  })
  if not response.ok then
    local failure_code = response.code == "EXECUTOR_UNAVAILABLE" and "EXECUTOR_UNAVAILABLE" or "PREFAB_SAVE_REGION_COMMAND_FAILED"
    local failure_message = response.message or "br.Prefab.SaveRegion command failed"
    local lines = {
      "ok=false",
      "code=" .. failure_code,
      "operation=prefab-save-region",
      "sequence=" .. tostring(sequence),
      "executor=" .. tostring(response.data and response.data.executor or ""),
      "detail=" .. tostring(failure_message),
      "command=" .. command,
      "save_path=" .. save_path,
    }
    if response.data and response.data.required_native then
      lines[#lines + 1] = "required_native=" .. tostring(response.data.required_native)
    end
    for index, attempt in ipairs(response.data and response.data.attempts or {}) do
      lines[#lines + 1] = "executor_attempt_" .. tostring(index) .. "="
        .. tostring(attempt.executor or "")
        .. "|ok=" .. tostring(attempt.ok and true or false)
        .. "|code=" .. tostring(attempt.code or "")
        .. "|detail=" .. tostring(attempt.message or "")
    end
    prefab_save_region_store_result(sequence, false, failure_code, failure_message, lines, {
      command = command,
      path = relative_path,
      save_path = save_path,
      executor = response.data and response.data.executor or "",
      attempts = response.data and response.data.attempts or {},
      required_native = response.data and response.data.required_native or "",
    })
    return result(false, failure_code, failure_message, {
      sequence = sequence,
      lines = lines,
    })
  end

  local poll_ms = math.max(50, BMF_env_number("BMF_PREFAB_SAVE_REGION_POLL_MS", 100, 50))
  local timeout_ms = math.max(poll_ms, BMF_env_number("BMF_PREFAB_SAVE_REGION_TIMEOUT_MS", 5000, poll_ms))
  local max_attempts = math.max(1, math.floor((timeout_ms + poll_ms - 1) / poll_ms))
  local attempts = 0

  local function finish(ok, code, message)
    if cleanup and ok then
      os.remove(save_path)
    end
    local lines = {
      "ok=" .. tostring(ok and true or false),
      "code=" .. tostring(code),
      "operation=prefab-save-region",
      "sequence=" .. tostring(sequence),
      "path=" .. relative_path,
      "save_path=" .. save_path,
      "prefabs_dir=" .. prefabs_dir,
      "x=" .. tostring(x),
      "y=" .. tostring(y),
      "z=" .. tostring(z),
      "extent_x=" .. tostring(extent_x),
      "extent_y=" .. tostring(extent_y),
      "extent_z=" .. tostring(extent_z),
      "include_entities=" .. tostring(include_entities),
      "attempts=" .. tostring(attempts),
      "poll_ms=" .. tostring(poll_ms),
      "timeout_ms=" .. tostring(timeout_ms),
    }
    prefab_save_region_store_result(sequence, ok, code, message, lines, {
      command = command,
      path = relative_path,
      save_path = save_path,
      prefabs_dir = prefabs_dir,
      attempts = attempts,
      cleanup = cleanup,
    })
  end

  local function attempt()
    attempts = attempts + 1
    if prefab_save_region_file_exists(save_path) then
      finish(true, "OK", "Prefab save-region probe created the expected BRZ file.")
      return
    end
    if attempts >= max_attempts then
      finish(false, "PREFAB_SAVE_REGION_FILE_TIMEOUT", "br.Prefab.SaveRegion did not produce the expected BRZ file before timeout.")
      return
    end
    if not BMF.timers.after(poll_ms, attempt) then
      finish(false, "PREFAB_SAVE_REGION_TIMER_UNAVAILABLE", "BMF timer unavailable while waiting for prefab save-region output.")
    end
  end

  if not BMF.timers.after(poll_ms, attempt) then
    attempt()
  end

  return result(true, "OK", "Prefab save-region probe queued", {
    queued = true,
    sequence = sequence,
    path = relative_path,
    save_path = save_path,
    lines = {
      "ok=true",
      "code=OK",
      "queued=true",
      "operation=prefab-save-region",
      "sequence=" .. tostring(sequence),
      "path=" .. relative_path,
      "save_path=" .. save_path,
      "prefabs_dir=" .. prefabs_dir,
      "x=" .. tostring(x),
      "y=" .. tostring(y),
      "z=" .. tostring(z),
      "extent_x=" .. tostring(extent_x),
      "extent_y=" .. tostring(extent_y),
      "extent_z=" .. tostring(extent_z),
      "include_entities=" .. tostring(include_entities),
      "poll_ms=" .. tostring(poll_ms),
      "timeout_ms=" .. tostring(timeout_ms),
    },
  })
end

BMF.prefabs.planLoadBrz = function(options)
  if type(options) ~= "table" then
    return result(false, "INVALID_OPTIONS", "options table is required")
  end

  local source, source_error = normalize_prefab_source(options.source or options.brz or options.prefab)
  if not source then
    return result(false, "INVALID_PREFAB_SOURCE", source_error)
  end

  local staged_world = nil
  local staged_world_error = nil
  if has_staged_prefab_world_option(options) then
    staged_world, staged_world_error = normalize_staged_prefab_world(options)
    if not staged_world then
      return result(false, "INVALID_WORLD_NAME", staged_world_error)
    end
  end

  local position = prefab_position_from_options(options)
  local load_options = nil
  if staged_world then
    load_options = {
      name = staged_world,
      position = { x = position.x, y = position.y, z = position.z },
      yaw = position.yaw,
    }
  end

  return result(true, "OK", "BRZ prefab load planned", {
    source = source,
    stagedWorld = staged_world,
    requiresStaging = staged_world == nil,
    position = position,
    loadOptions = load_options,
  })
end

BMF.prefabs.loadBrdb = function(options)
  if type(options) == "string" then
    options = { name = options }
  end
  if type(options) ~= "table" then
    return result(false, "INVALID_OPTIONS", "options table is required")
  end

  local staged_world, staged_world_error = normalize_staged_prefab_world(options)
  if not staged_world then
    return result(false, "INVALID_WORLD_NAME", staged_world_error)
  end

  local position = prefab_position_from_options(options)
  local response = BMF.world.loadAdditive({
    name = staged_world,
    position = { x = position.x, y = position.y, z = position.z },
    yaw = position.yaw,
  })
  response.data.api = "BMF.prefabs.loadBrdb"
  response.data.prefab = {
    stagedWorld = staged_world,
  }
  return response
end

BMF.prefabs.loadBrz = function(options)
  local planned = BMF.prefabs.planLoadBrz(options)
  if not planned.ok then
    return planned
  end

  if planned.data.requiresStaging then
    return result(false, "PREFAB_STAGING_REQUIRED", "BRZ prefab must be staged as a BRDB world before runtime load", planned.data)
  end

  local response = BMF.world.loadAdditive(planned.data.loadOptions)
  response.data.api = "BMF.prefabs.loadBrz"
  response.data.prefab = {
    source = planned.data.source,
    stagedWorld = planned.data.stagedWorld,
  }
  return response
end

BMF.vehicles = {}

function vehicle_spawn_position(options, fallback)
  options = options or {}
  fallback = fallback or {}
  local position = options.position
  if type(position) ~= "table" then
    position = {}
  end

  return {
    x = finite_number(options.x or position.x or position.X, fallback.x or 0),
    y = finite_number(options.y or position.y or position.Y, fallback.y or 0),
    z = finite_number(options.z or position.z or position.Z, fallback.z or 0),
    yaw = finite_number(options.yaw or options.orientation or options.rotation, fallback.yaw or 0),
  }
end

function vehicle_spawn_load(name, position, index)
  local load_options = {
    name = name,
    position = { x = position.x, y = position.y, z = position.z },
    yaw = position.yaw,
  }
  local command = table.concat({
    "BR.World.LoadAdditive",
    quote_console_token(name),
    format_number(position.x),
    format_number(position.y),
    format_number(position.z),
    format_number(position.yaw),
  }, " ")

  return {
    index = index,
    worldName = name,
    position = position,
    command = command,
    loadOptions = load_options,
  }
end

BMF.vehicles.planSpawnSet = function(options)
  if type(options) ~= "table" then
    return result(false, "INVALID_OPTIONS", "options table is required")
  end

  local loads = {}
  local errors = {}
  local copies = options.copies or options.stagedWorlds or options.worlds

  if type(copies) == "table" then
    for index, copy in ipairs(copies) do
      local copy_options = copy
      if type(copy_options) == "string" then
        copy_options = { name = copy_options }
      end
      if type(copy_options) ~= "table" then
        errors[#errors + 1] = "copy " .. tostring(index) .. " must be a table or world name"
      else
        local world_name, name_error = normalize_world_name(copy_options.worldName or copy_options.stagedWorld or copy_options.name or copy_options.world or copy_options.bundle)
        if not world_name then
          errors[#errors + 1] = "copy " .. tostring(index) .. ": " .. name_error
        else
          local position = vehicle_spawn_position(copy_options, vehicle_spawn_position(options, {}))
          loads[#loads + 1] = vehicle_spawn_load(world_name, position, index)
        end
      end
    end
  else
    local count, count_error = normalize_integer(options.count or options.vehicleCount, "vehicle count")
    if count == nil then
      return result(false, "INVALID_VEHICLE_COUNT", count_error)
    end
    if count < 1 then
      return result(false, "INVALID_VEHICLE_COUNT", "vehicle count must be at least 1")
    end

    local prefix, prefix_error = normalize_world_name(options.worldNamePrefix or options.prefix)
    if not prefix then
      return result(false, "INVALID_WORLD_NAME", prefix_error)
    end

    local start = options.start or options.position or {}
    if type(start) ~= "table" then
      start = {}
    end
    local step = options.step or {}
    if type(step) ~= "table" then
      step = {}
    end

    local base = {
      x = finite_number(options.x or start.x or start.X, 0),
      y = finite_number(options.y or start.y or start.Y, 0),
      z = finite_number(options.z or start.z or start.Z, 0),
      yaw = finite_number(options.yaw or options.orientation or options.rotation, 0),
    }
    local delta = {
      x = finite_number(options.stepX or step.x or step.X, 0),
      y = finite_number(options.stepY or step.y or step.Y, 0),
      z = finite_number(options.stepZ or step.z or step.Z, 0),
      yaw = finite_number(options.stepYaw or step.yaw or step.Yaw, 0),
    }

    for index = 1, count do
      local world_name = string.format("%s_%02d", prefix, index)
      local position = {
        x = base.x + ((index - 1) * delta.x),
        y = base.y + ((index - 1) * delta.y),
        z = base.z + ((index - 1) * delta.z),
        yaw = base.yaw + ((index - 1) * delta.yaw),
      }
      loads[#loads + 1] = vehicle_spawn_load(world_name, position, index)
    end
  end

  if #errors > 0 then
    return result(false, "INVALID_VEHICLE_SPAWN_SET", table.concat(errors, "; "), {
      errors = errors,
    })
  end
  if #loads == 0 then
    return result(false, "INVALID_VEHICLE_SPAWN_SET", "at least one staged vehicle world is required")
  end

  return result(true, "OK", "Vehicle spawn set planned", {
    vehicleCount = #loads,
    loads = loads,
    requiresStaging = false,
  })
end

BMF.vehicles.spawnSet = function(options)
  local planned = BMF.vehicles.planSpawnSet(options)
  if not planned.ok then
    return planned
  end

  local responses = {}
  for _, spawn in ipairs(planned.data.loads) do
    local response = BMF.world.loadAdditive(spawn.loadOptions)
    response.data.api = "BMF.vehicles.spawnSet"
    response.data.vehicleIndex = spawn.index
    response.data.stagedWorld = spawn.worldName
    responses[#responses + 1] = response
    if not response.ok then
      return result(false, "VEHICLE_SPAWN_FAILED", "Vehicle spawn failed at copy " .. tostring(spawn.index), {
        planned = planned.data,
        responses = responses,
        failedIndex = spawn.index,
      })
    end
  end

  return result(true, "OK", "Vehicle spawn set loaded", {
    vehicleCount = #responses,
    planned = planned.data,
    responses = responses,
  })
end

BMF.chat = {}

local function BMF_player_message_implementation_probe(message, controller_hint, probe_options)
  probe_options = type(probe_options) == "table" and probe_options or {}
  local text = trim_string(message or "")
  local requested_controller = trim_string(controller_hint or "")
  local preferred_controller_address = trim_string(probe_options.controllerAddress or "")
  local native_resolver_only = probe_options.nativeResolverOnly == true
  if text == "" then
    return result(false, "INVALID_OPTIONS", "message is required", {
      lines = {
        "ok=false",
        "code=INVALID_OPTIONS",
      },
    })
  end
  if probe_options.skipRateLimit ~= true then
    local limited = rate_limit_check("chat.playerMessageImplementationProbe")
    if not limited.ok then
      return limited
    end
  end
  if type(BMFSocketPlayerChatMessageImplementationProbe) ~= "function" then
    return result(false, "NATIVE_PLAYER_CHAT_IMPL_UNAVAILABLE", "BMFSocketPlayerChatMessageImplementationProbe native helper is unavailable.", {
      message = text,
      lines = {
        "ok=false",
        "code=NATIVE_PLAYER_CHAT_IMPL_UNAVAILABLE",
        "message=" .. tostring(text),
      },
    })
  end

  local candidates = {}
  local seen_candidates = {}

  local function add_candidate(controller, label)
    if controller == nil or
        type(live_chat_is_valid_object) ~= "function" or
        not live_chat_is_valid_object(controller) then
      return
    end
    if type(live_chat_object_key) ~= "function" then
      return
    end

    local address = trim_string(live_chat_object_key(controller, ""))
    if address == "" or seen_candidates[address] then
      return
    end
    seen_candidates[address] = true
    candidates[#candidates + 1] = {
      address = address,
      label = tostring(label or address),
    }
  end

  if native_resolver_only then
    -- The native helper owns lookup and exception containment. This avoids
    -- touching Lua UObject wrappers that can outlive a disconnected player.
    candidates[1] = {
      address = "",
      label = "native-resolver",
    }
  else
    if preferred_controller_address ~= "" then
      seen_candidates[preferred_controller_address] = true
      candidates[#candidates + 1] = {
        address = preferred_controller_address,
        label = "cached-controller",
      }
    end

    if requested_controller ~= "" then
      local controller = nil
      if type(live_chat_find_controller_by_name) == "function" then
        controller = live_chat_find_controller_by_name(requested_controller)
      end
      if controller == nil or
          type(live_chat_is_valid_object) ~= "function" or
          not live_chat_is_valid_object(controller) then
        return result(false, "PLAYER_CONTROLLER_NOT_FOUND", "Requested live player controller was not found.", {
          message = text,
          controllerHint = requested_controller,
          lines = {
            "ok=false",
            "code=PLAYER_CONTROLLER_NOT_FOUND",
            "message=" .. tostring(text),
            "controller_hint=" .. tostring(requested_controller),
          },
        })
      end
      add_candidate(controller, requested_controller)
      if #candidates == 0 then
        return result(false, "PLAYER_CONTROLLER_NOT_FOUND", "Requested live player controller address was unavailable.", {
          message = text,
          controllerHint = requested_controller,
          lines = {
            "ok=false",
            "code=PLAYER_CONTROLLER_NOT_FOUND",
            "message=" .. tostring(text),
            "controller_hint=" .. tostring(requested_controller),
          },
        })
      end
    elseif preferred_controller_address == "" and type(FindAllOf) == "function" then
      -- FindAllOf returns controller instances in creation order. Trying the
      -- newest Brickadia controller first avoids the short window where a
      -- disconnected controller still passes UObject lifecycle checks.
      for _, class_name in ipairs({ "BP_PlayerController_C", "BRPlayerController" }) do
        local ok, controllers = BMF_operation_find_all(
          class_name,
          "chat.controller_scan",
          "diagnostic_scan")
        if ok and type(controllers) == "table" then
          for index = #controllers, 1, -1 do
            add_candidate(
              controllers[index],
              "FindAllOf(" .. class_name .. ")[" .. tostring(index) .. "]"
            )
            if #candidates >= 64 then
              break
            end
          end
        end
        if #candidates > 0 then
          break
        end
      end
    end
  end

  if #candidates == 0 then
    -- Preserve the native resolver as a bounded fallback for startup builds
    -- where FindAllOf is unavailable or no controller has been published yet.
    candidates[1] = {
      address = "",
      label = "native-fallback",
    }
  end

  local attempt_lines = {}
  local last_lines = {}
  local last_fields = {}
  local last_detail = "Native player chat implementation probe"
  local controller_strategy = native_resolver_only and "native-resolver-only"
    or (preferred_controller_address ~= "" and "cached-then-newest-live" or "newest-live-first")
  for index, candidate in ipairs(candidates) do
    local ok, response = pcall(
      BMFSocketPlayerChatMessageImplementationProbe,
      text,
      "player-chat-message-implementation-probe",
      candidate.address
    )
    if ok then
      local lines, fields = parse_key_value_lines(response)
      last_lines = lines
      last_fields = fields
      last_detail = tostring(fields.detail or last_detail)
      attempt_lines[#attempt_lines + 1] =
        "controller_attempt_" .. tostring(index) .. "=" .. tostring(candidate.label) ..
        "|ok=" .. tostring(fields.ok or "false") ..
        "|stage=" .. tostring(fields.stage or "") ..
        "|exception_code=" .. tostring(fields.exception_code or "")
      if tostring(fields.ok or "") == "true" then
        lines[#lines + 1] = "controller_strategy=" .. controller_strategy
        lines[#lines + 1] = "controller_candidate_count=" .. tostring(#candidates)
        lines[#lines + 1] = "controller_attempt_count=" .. tostring(index)
        for _, attempt_line in ipairs(attempt_lines) do
          lines[#lines + 1] = attempt_line
        end
        return result(true, "OK", last_detail, {
          message = text,
          controllerHint = requested_controller,
          controllerAddress = candidate.address,
          controllerStrategy = controller_strategy,
          controllerCandidateCount = #candidates,
          controllerAttemptCount = index,
          executor = "native.player_controller.server_push_chat_message_implementation",
          fields = fields,
          lines = lines,
        })
      end
    else
      last_detail = tostring(response or "native helper failed")
      attempt_lines[#attempt_lines + 1] =
        "controller_attempt_" .. tostring(index) .. "=" .. tostring(candidate.label) ..
        "|ok=false|stage=pcall|detail=" .. last_detail
    end
  end

  last_lines[#last_lines + 1] = "controller_strategy=" .. controller_strategy
  last_lines[#last_lines + 1] = "controller_candidate_count=" .. tostring(#candidates)
  last_lines[#last_lines + 1] = "controller_attempt_count=" .. tostring(#candidates)
  for _, attempt_line in ipairs(attempt_lines) do
    last_lines[#last_lines + 1] = attempt_line
  end
  return result(false, "NATIVE_PLAYER_CHAT_IMPL_FAILED", last_detail, {
    message = text,
    controllerHint = requested_controller,
    controllerAddress = "",
    controllerStrategy = controller_strategy,
    controllerCandidateCount = #candidates,
    controllerAttemptCount = #candidates,
    executor = "native.player_controller.server_push_chat_message_implementation",
    fields = last_fields,
    lines = last_lines,
  })
end

function BMF.chat.playerMessageImplementationProbe(message, controller_hint)
  return BMF_player_message_implementation_probe(message, controller_hint, {})
end

local LIVE_CHAT_CONTROLLER_CLASSES = { "BP_PlayerController_C", "BRPlayerController", "PlayerController" }
local LIVE_CHAT_MAX_CONTROLLER_TARGETS = 64

function live_chat_is_valid_object(object)
  if object == nil then
    return false
  end
  if type(object.IsValid) ~= "function" then
    return false
  end
  local ok, is_valid = pcall(function()
    return object:IsValid()
  end)
  return ok and is_valid == true
end

function live_chat_object_key(object, fallback)
  if live_chat_is_valid_object(object) and type(object.GetAddress) == "function" then
    local ok, address = pcall(function()
      return object:GetAddress()
    end)
    if ok and address ~= nil then
      return tostring(address)
    end
  end
  return tostring(fallback or object or "")
end

function live_chat_object_label(object, fallback)
  local address = live_chat_object_key(object, "")
  if address ~= "" then
    return tostring(fallback or "object") .. "@" .. address
  end
  return tostring(fallback or "object")
end

function live_chat_object_full_name(object)
  if live_chat_is_valid_object(object) and type(object.GetFullName) == "function" then
    local ok, full_name = pcall(function()
      return object:GetFullName()
    end)
    if ok and full_name ~= nil then
      return tostring(full_name)
    end
  end
  return ""
end

function live_chat_find_controller_by_name(object_name)
  local name = trim_string(tostring(object_name or ""))
  if name == "" then
    return nil
  end

  if type(FindObject) == "function" then
    local ok, object = pcall(FindObject, nil, name, nil, nil)
    if ok and live_chat_is_valid_object(object) then
      return object
    end

    for _, class_name in ipairs(LIVE_CHAT_CONTROLLER_CLASSES) do
      ok, object = pcall(FindObject, class_name, name, nil, nil)
      if ok and live_chat_is_valid_object(object) then
        return object
      end
    end
  end

  if type(StaticFindObject) == "function" then
    local ok, object = pcall(StaticFindObject, name)
    if ok and live_chat_is_valid_object(object) then
      return object
    end
  end

  return nil
end

function live_chat_first_property_text(values, names)
  values = type(values) == "table" and values or {}
  for _, name in ipairs(names or {}) do
    local record = values[name]
    if type(record) == "table" then
      local text = trim_string(record.text or "")
      if text ~= "" then
        return text
      end
      text = trim_string(record.objectName or "")
      if text ~= "" then
        return text
      end
    end
  end
  return ""
end

function live_chat_stable_uuid(value)
  local text = trim_string(tostring(value or "")):lower()
  return text:match("(%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x)") or ""
end

function live_chat_native_controller_binding_metadata(controller, expected_uuid)
  local metadata = {}
  local canonical_expected_uuid = live_chat_stable_uuid(expected_uuid)
  if not minigame_object_valid(controller)
      or canonical_expected_uuid == ""
      or type(BMFSocketDescribePlayerControllerBinding) ~= "function" then
    return metadata
  end
  local controller_address = minigame_object_address(controller)
  if controller_address == "" then
    return metadata
  end
  local ok, response = pcall(
    BMFSocketDescribePlayerControllerBinding,
    controller_address,
    canonical_expected_uuid)
  if not ok or type(response) ~= "string" then
    return metadata
  end

  local fields = {}
  for line in response:gmatch("[^\r\n]+") do
    local key, value = line:match("^([%w_]+)=(.*)$")
    if key ~= nil then
      fields[key] = trim_string(tostring(value or ""))
    end
  end
  if fields.ok ~= "true" then
    return metadata
  end

  local function identity_text(value)
    local text = trim_string(tostring(value or ""))
    if #text >= 2 and text:sub(1, 1) == '"' and text:sub(-1) == '"' then
      text = text:sub(2, -2)
    end
    return text
  end

  -- Persist the exact UObject instance name, not GetFullName(). This UE4SS
  -- build can resolve BP_PlayerController_C_<id> with FindObject but cannot
  -- round-trip the decorated "Class /Package:Level.Object" label. The native
  -- helper has already proven this specific controller owns expected_uuid,
  -- and every use re-proves that UUID before delivery.
  metadata.controllerPath = first_string(
    identity_text(fields.controller_name),
    identity_text(fields.controller_full_name)
  ) or ""
  metadata.controllerFullName = identity_text(fields.controller_full_name)
  metadata.controllerAddress = tostring(fields.controller_address or "")
  metadata.playerStatePath = first_string(
    identity_text(fields.player_state_name),
    identity_text(fields.player_state_full_name)
  ) or ""
  metadata.playerStateFullName = identity_text(fields.player_state_full_name)
  metadata.playerStateAddress = tostring(fields.player_state_address or "")
  metadata.playerStateSource = "native.BMFSocketDescribePlayerControllerBinding"
  metadata.bindingSource = tostring(fields.binding_source or "")
  metadata.uuidMatched = fields.identity_uuid_match == "true"

  local player_name = first_string(
    identity_text(fields.identity_user_name),
    identity_text(fields.identity_player_name_private),
    identity_text(fields.identity_player_name),
    identity_text(fields.identity_display_name)
  ) or ""
  if player_name ~= "" then
    metadata.name = player_name
    metadata.username = player_name
    metadata.userName = player_name
    metadata.playerName = player_name
    metadata.displayName = player_name
  end

  if metadata.uuidMatched == true then
    metadata.uuid = canonical_expected_uuid
    metadata.playerId = canonical_expected_uuid
  end
  return metadata
end

function live_chat_controller_metadata(controller, expected_uuid)
  local canonical_expected_uuid = live_chat_stable_uuid(expected_uuid)
  local metadata = live_chat_native_controller_binding_metadata(
    controller,
    canonical_expected_uuid)
  if not minigame_object_valid(controller) then
    return metadata
  end

  if trim_string(tostring(metadata.playerStatePath or "")) ~= ""
      and live_chat_stable_uuid(metadata.uuid or metadata.playerId) ~= "" then
    return metadata
  end

  -- An exact UUID request must never fall back to the broken generic UE4SS
  -- property wrappers or infer identity from another field. The bounded native
  -- reciprocal-object check either proves this controller owns that UUID or
  -- the caller fails closed.
  if canonical_expected_uuid ~= "" then
    return metadata
  end

  local player_state = minigame_try_property(controller, "PlayerState")
  local player_state_source = "controller.PlayerState"
  if not minigame_object_valid(player_state) then
    player_state, player_state_source =
      minigame_native_player_state_from_controller(controller)
  end
  if minigame_object_valid(player_state) then
    metadata.playerStatePath = minigame_object_full_name(player_state)
    metadata.playerStateAddress = minigame_object_address(player_state)
    metadata.playerStateSource = tostring(player_state_source or "")

    local values = minigame_live_collect_property_values(
      player_state,
      {
        "UserName",
        "PlayerNamePrivate",
        "PlayerName",
        "DisplayName",
        "UniqueId",
        "SessionId",
        "UserId",
      },
      0,
      false
    )
    local player_name = live_chat_first_property_text(values, {
      "UserName",
      "PlayerNamePrivate",
      "PlayerName",
      "DisplayName",
    })
    if player_name ~= "" then
      metadata.name = player_name
      metadata.username = player_name
      metadata.playerName = player_name
      metadata.displayName = player_name
    end
    local uuid = live_chat_stable_uuid(live_chat_first_property_text(values, {
      "UniqueId",
      "SessionId",
      "UserId",
    }))
    if uuid ~= "" then
      metadata.uuid = uuid
      metadata.playerId = uuid
    end
  end

  return metadata
end

function live_chat_cached_players()
  local registry = state.player_registry or {}
  if registry.cache_loaded ~= true and type(load_player_cache) == "function" then
    load_player_cache()
  end
  local cache = state.player_cache
  if type(cache) ~= "table" then
    return {}
  end
  if type(cache.players) == "table" then
    return cache.players
  end
  return cache
end

function live_chat_cached_controller(controller_path)
  local path = trim_string(tostring(controller_path or ""))
  if path == "" then
    return nil
  end
  local registry = state.player_registry or {}
  -- Keep only the stable controller path across requests. UE4SS UObject
  -- userdata can outlive its disconnected player and crash inside IsValid.
  registry.controller_handle_misses = (tonumber(registry.controller_handle_misses) or 0) + 1
  local controller = live_chat_find_controller_by_name(path)
  BMF_operation_note_controller_resolution(controller ~= nil)
  if controller ~= nil then
    registry.targeted_resolutions = (tonumber(registry.targeted_resolutions) or 0) + 1
    return controller
  end
  registry.targeted_failures = (tonumber(registry.targeted_failures) or 0) + 1
  return nil
end

function live_chat_exact_identity_values(record)
  local values = {}
  local seen = {}
  for _, value in ipairs({
    record and record.uuid,
    record and record.id,
    record and record.playerId,
    record and record.username,
    record and record.userName,
    record and record.playerName,
    record and record.displayName,
    record and record.originalName,
    record and record.name,
  }) do
    local normalized = trim_string(tostring(value or "")):lower()
    if normalized ~= "" and not seen[normalized] then
      seen[normalized] = true
      values[#values + 1] = normalized
    end
  end
  return values
end

function live_chat_match_cached_player(players, target)
  local target_uuid = live_chat_stable_uuid(
    target and (target.uuid or target.id or target.playerId) or "")
  if target_uuid == "" then
    return nil, nil
  end
  local match_index = nil
  local match_player = nil
  for index, player in ipairs(players or {}) do
    local player_uuid = live_chat_stable_uuid(
      player and (player.uuid or player.id or player.playerId) or "")
    if player_uuid ~= "" and player_uuid == target_uuid then
      if match_index ~= nil then
        return nil, nil
      end
      match_index = index
      match_player = player
    end
  end
  return match_index, match_player
end

function live_chat_repair_allowed(registry)
  if registry.repair_enabled ~= true or registry.repair_running == true then
    return false
  end
  local cooldown_ms = math.max(
    math.max(0, tonumber(registry.repair_cooldown_ms) or 0),
    math.max(0, tonumber(registry.repair_backoff_ms) or 0))
  local last_epoch = tonumber(registry.last_repair_epoch) or 0
  if last_epoch > 0 and cooldown_ms > 0 then
    local elapsed_ms = math.max(0, os.time() - last_epoch) * 1000
    if elapsed_ms < cooldown_ms then
      return false
    end
  end
  return true
end

function live_chat_collect_targets(options)
  local opts = type(options) == "table" and options or {}
  local expected_uuid = live_chat_stable_uuid(opts.expectedUuid or opts.uuid)
  local registry = state.player_registry or {}
  local targets = {}
  local seen = {}
  local cached_players = live_chat_cached_players()
  local repair_detail = {
    requested = opts.repair == true or option_boolean(opts, "repair", false),
    performed = false,
    skipped = false,
    matched = 0,
    globalScans = 0,
    error = "",
  }
  if repair_detail.requested then
    registry.repair_requests = (tonumber(registry.repair_requests) or 0) + 1
  end

  local function add_target(controller, source, metadata)
    if #targets >= LIVE_CHAT_MAX_CONTROLLER_TARGETS then
      return
    end
    if not live_chat_is_valid_object(controller) then
      return
    end
    local key = live_chat_object_key(controller, tostring(controller))
    if seen[key] then
      return
    end
    seen[key] = true

    metadata = type(metadata) == "table" and metadata or {}
    local full_name = live_chat_object_full_name(controller)
    local label = full_name ~= "" and full_name or live_chat_object_label(controller, source or "player_controller")
    local controller_path = tostring(metadata.controllerPath or "")
    if trim_string(controller_path) == "" then
      controller_path = full_name
    end

    targets[#targets + 1] = {
      controller = controller,
      name = tostring(metadata.name or metadata.playerName or metadata.username or ""),
      userName = tostring(metadata.userName or metadata.username or metadata.playerName or ""),
      displayName = tostring(metadata.displayName or metadata.name or metadata.username or ""),
      playerId = tostring(metadata.uuid or metadata.id or metadata.playerId or ""),
      controllerPath = controller_path,
      playerStatePath = tostring(metadata.playerStatePath or ""),
      label = label,
      source = tostring(source or ""),
    }
  end

  for _, player in ipairs(cached_players) do
    local controller_path = tostring(player.controllerPath or "")
    local controller = live_chat_cached_controller(controller_path)
    if controller ~= nil then
      add_target(controller, "player_cache.controllerPath", player)
    end
  end

  local unresolved_count = math.max(0, #cached_players - #targets)
  registry.unresolved_players = unresolved_count
  if #cached_players > 0 and unresolved_count == 0 then
    BMF_operation_note_cache_result("hit")
  elseif #cached_players > 0 then
    BMF_operation_note_cache_result("miss")
  end
  local repair_needed = repair_detail.requested and (#cached_players == 0 or unresolved_count > 0)
  if repair_needed and not live_chat_repair_allowed(registry) then
    registry.broad_repair_skipped = (tonumber(registry.broad_repair_skipped) or 0) + 1
    registry.repair_coalesced = (tonumber(registry.repair_coalesced) or 0) + 1
    repair_detail.skipped = true
  elseif repair_needed then
    local repair_started_clock = os.clock()
    registry.repair_running = true
    registry.last_repair_epoch = os.time()
    registry.last_repair_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
    registry.last_repair_error = ""
    registry.broad_repairs = (tonumber(registry.broad_repairs) or 0) + 1
    repair_detail.performed = true
    local repair_ok, repair_error = pcall(function()
      if type(FindAllOf) ~= "function" then
        error("FindAllOf is unavailable")
      end
      for _, class_name in ipairs(LIVE_CHAT_CONTROLLER_CLASSES) do
        if BMF_operation_current_deadline_expired() then
          error("repair deadline elapsed before global scan")
        end
        local target_count_before_scan = #targets
        registry.global_scans = (tonumber(registry.global_scans) or 0) + 1
        repair_detail.globalScans = repair_detail.globalScans + 1
        local ok, controllers, scan_duration_ms = BMF_operation_find_all(
          class_name,
          "player_registry.repair",
          "explicit_repair")
        registry.global_scan_duration_ms_sum =
          (tonumber(registry.global_scan_duration_ms_sum) or 0) + scan_duration_ms
        registry.global_scan_duration_ms_max = math.max(
          tonumber(registry.global_scan_duration_ms_max) or 0,
          scan_duration_ms)
        if ok and type(controllers) == "table" then
          for index, controller in ipairs(controllers) do
            add_target(
              controller,
              "repair.FindAllOf(" .. class_name .. ")[" .. tostring(index) .. "]",
              live_chat_controller_metadata(controller, expected_uuid)
            )
            if #targets >= LIVE_CHAT_MAX_CONTROLLER_TARGETS then
              break
            end
          end
        end
        if #targets >= LIVE_CHAT_MAX_CONTROLLER_TARGETS then
          break
        end
        if #targets > target_count_before_scan then
          break
        end
      end
    end)
    registry.repair_running = false
    local repair_duration_ms = BMF_telemetry_duration_ms(repair_started_clock)
    registry.repair_duration_ms_sum =
      (tonumber(registry.repair_duration_ms_sum) or 0) + repair_duration_ms
    registry.repair_duration_ms_max = math.max(
      tonumber(registry.repair_duration_ms_max) or 0,
      repair_duration_ms)
    BMF_operation_note_repair(repair_duration_ms)
    if not repair_ok then
      registry.broad_repair_failures = (tonumber(registry.broad_repair_failures) or 0) + 1
      registry.repair_failure_streak = (tonumber(registry.repair_failure_streak) or 0) + 1
      registry.repair_backoff_ms = math.min(
        60000,
        math.max(
          tonumber(registry.repair_cooldown_ms) or BMF_PLAYER_REGISTRY_DEFAULT_REPAIR_COOLDOWN_MS,
          (tonumber(registry.repair_cooldown_ms) or BMF_PLAYER_REGISTRY_DEFAULT_REPAIR_COOLDOWN_MS)
            * (2 ^ math.min(6, math.max(0, registry.repair_failure_streak - 1)))))
      registry.last_repair_error = tostring(repair_error or "controller repair failed")
      repair_detail.error = registry.last_repair_error
    else
      registry.repair_failure_streak = 0
      registry.repair_backoff_ms = tonumber(registry.repair_cooldown_ms)
        or BMF_PLAYER_REGISTRY_DEFAULT_REPAIR_COOLDOWN_MS
      local updated_cache = type(state.player_cache) == "table" and copy_table(state.player_cache) or {
        schemaVersion = 1,
        adapter = "live-controller-repair",
        source = "explicit-repair",
        players = {},
      }
      updated_cache.players = type(updated_cache.players) == "table" and updated_cache.players or {}
      for _, target in ipairs(targets) do
        if tostring(target.source or ""):find("repair.FindAllOf(", 1, true) == 1 then
          local match_index, matched_player = live_chat_match_cached_player(updated_cache.players, target)
          if match_index ~= nil and type(matched_player) == "table" then
            target.name = tostring(target.name ~= "" and target.name or matched_player.name or matched_player.playerName or matched_player.username or "")
            target.userName = tostring(target.userName ~= "" and target.userName or matched_player.userName or matched_player.username or matched_player.playerName or "")
            target.displayName = tostring(target.displayName ~= "" and target.displayName or matched_player.displayName or matched_player.name or matched_player.username or "")
            target.playerId = tostring(matched_player.uuid or matched_player.id or matched_player.playerId or target.playerId or "")
            matched_player.controllerPath = tostring(target.controllerPath or "")
            matched_player.playerStatePath = tostring(target.playerStatePath or matched_player.playerStatePath or "")
            matched_player.controllerAvailable = trim_string(matched_player.controllerPath) ~= ""
            repair_detail.matched = repair_detail.matched + 1
          end
        end
      end
      registry.broad_repair_matches = (tonumber(registry.broad_repair_matches) or 0) + repair_detail.matched
      if repair_detail.matched > 0 and type(publish_player_cache) == "function" then
        updated_cache.source = "explicit-live-controller-repair"
        updated_cache.updatedAt = registry.last_repair_at
        publish_player_cache(updated_cache)
      end
    end
  end

  return targets, repair_detail
end

function live_chat_target_summary(target)
  return {
    name = tostring(target.name or ""),
    userName = tostring(target.userName or ""),
    displayName = tostring(target.displayName or ""),
    playerId = tostring(target.playerId or ""),
    controllerPath = tostring(target.controllerPath or ""),
    controllerName = live_chat_object_label(target.controller, ""),
    controllerFullName = live_chat_object_full_name(target.controller),
    playerStatePath = tostring(target.playerStatePath or ""),
    label = tostring(target.label or ""),
    source = tostring(target.source or ""),
  }
end

function live_chat_target_matches(target, query)
  local normalized = trim_string(tostring(query or "")):lower()
  if normalized == "" then
    return false
  end
  for _, value in ipairs({
    target.name,
    target.userName,
    target.displayName,
    target.playerId,
    target.controllerPath,
    target.playerStatePath,
    target.label,
  }) do
    local text = trim_string(tostring(value or "")):lower()
    if text ~= "" and (text == normalized or text:find(normalized, 1, true) ~= nil) then
      return true
    end
  end
  return false
end

function live_chat_query_text(player)
  if type(player) == "table" then
    return first_string(
      player.uuid,
      player.id,
      player.userId,
      player.userID,
      player.playerId,
      player.playerID,
      player.username,
      player.userName,
      player.displayName,
      player.playerName,
      player.originalName,
      player.name,
      player.query
    ) or ""
  end
  return tostring(player or "")
end

function live_chat_resolve_strict_target(identity)
  local registry = state.player_registry or {}
  local expected_uuid = trim_string(tostring(identity.uuid or "")):lower()
  local expected_generation = tonumber(identity.connectionGeneration) or 0
  if expected_uuid == ""
      or expected_generation < 1
      or expected_generation % 1 ~= 0 then
    BMF_operation_note_cache_result("miss")
    return nil, {}, "invalid_identity"
  end

  local cached_player = nil
  for _, candidate in ipairs(live_chat_cached_players()) do
    local candidate_uuid = trim_string(tostring(
      candidate.uuid or candidate.id or candidate.playerId or "")):lower()
    if candidate_uuid == expected_uuid then
      if cached_player ~= nil then
        return nil, {}, "ambiguous_uuid"
      end
      cached_player = candidate
    end
  end
  if cached_player == nil then
    BMF_operation_note_cache_result("miss")
    return nil, {}, "uuid_not_found"
  end

  local cached_generation = tonumber(cached_player.connectionGeneration) or 0
  if cached_generation ~= expected_generation then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    BMF_operation_note_cache_result("generation_mismatch")
    return nil, {}, "connection_generation_mismatch"
  end
  local expected_controller_path =
    trim_string(tostring(cached_player.controllerPath or ""))
  local expected_player_state_path =
    trim_string(tostring(cached_player.playerStatePath or ""))
  if expected_controller_path == "" or expected_player_state_path == "" then
    BMF_operation_note_cache_result("miss")
    return nil, {}, "current_paths_unavailable"
  end

  local snapshot_generation = tonumber(cached_player.snapshotGeneration) or 0
  local current_generation = tonumber(registry.generation) or 0
  if snapshot_generation > 0
      and current_generation > 0
      and snapshot_generation ~= current_generation then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    BMF_operation_note_cache_result("generation_mismatch")
    return nil, {}, "snapshot_generation_mismatch"
  end

  local controller = live_chat_cached_controller(expected_controller_path)
  if controller == nil then
    BMF_operation_note_cache_result("miss")
    return nil, {}, "controller_unavailable"
  end
  local live_metadata = live_chat_controller_metadata(controller, expected_uuid)
  if trim_string(tostring(live_metadata.playerStatePath or ""))
      ~= expected_player_state_path then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    BMF_operation_note_cache_result("generation_mismatch")
    return nil, {}, "live_player_state_mismatch"
  end

  local live_uuid = live_chat_stable_uuid(
    live_metadata.uuid or live_metadata.playerId or "")
  if live_uuid == "" or live_uuid ~= live_chat_stable_uuid(expected_uuid) then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    BMF_operation_note_cache_result("generation_mismatch")
    return nil, {}, "live_uuid_mismatch"
  end

  local cached_names = {}
  for _, value in ipairs({
    cached_player.username,
    cached_player.playerName,
    cached_player.displayName,
    cached_player.originalName,
  }) do
    local normalized = trim_string(tostring(value or "")):lower()
    if normalized ~= "" then cached_names[normalized] = true end
  end
  local live_name = trim_string(tostring(first_string(
    live_metadata.username,
    live_metadata.playerName,
    live_metadata.displayName,
    live_metadata.name) or "")):lower()
  if live_name ~= "" and
      (next(cached_names) == nil or cached_names[live_name] ~= true) then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    BMF_operation_note_cache_result("generation_mismatch")
    return nil, {}, "live_name_mismatch"
  end

  BMF_operation_note_cache_result("hit")
  local target = {
    controller = controller,
    name = tostring(cached_player.name or cached_player.playerName or cached_player.username or ""),
    userName = tostring(cached_player.userName or cached_player.username or cached_player.playerName or ""),
    displayName = tostring(cached_player.displayName or cached_player.name or cached_player.username or ""),
    playerId = tostring(cached_player.uuid or cached_player.id or cached_player.playerId or ""),
    controllerPath = expected_controller_path,
    playerStatePath = expected_player_state_path,
    label = expected_controller_path,
    source = "player_cache.strict_uuid_generation",
  }
  return target, { target }, "ok"
end

-- Validate the immutable Omegga-authored identity envelope using plain player
-- snapshot data only. UUID and connection generation remain authoritative;
-- senderName is the current, exact runtime address used only when a fresh
-- controller path must be repaired.
function live_chat_validate_authoritative_identity(identity)
  local registry = state.player_registry or {}
  local expected_uuid = trim_string(tostring(identity and identity.uuid or "")):lower()
  local expected_name = trim_string(tostring(identity and identity.senderName or ""))
  local expected_generation = tonumber(identity and identity.connectionGeneration) or 0
  if expected_uuid == "" or expected_name == ""
      or #expected_uuid > 128 or #expected_name > 128
      or expected_name:find("[%c]") ~= nil
      or expected_generation < 1 or expected_generation % 1 ~= 0 then
    return nil, "invalid_authoritative_identity"
  end

  local cached_player = nil
  for _, candidate in ipairs(live_chat_cached_players()) do
    local candidate_uuid = trim_string(tostring(
      candidate.uuid or candidate.id or candidate.playerId or "")):lower()
    if candidate_uuid == expected_uuid then
      if cached_player ~= nil then
        registry.authoritative_name_ambiguities =
          (tonumber(registry.authoritative_name_ambiguities) or 0) + 1
        return nil, "ambiguous_uuid"
      end
      cached_player = candidate
    end
  end
  if cached_player == nil then
    return nil, "uuid_not_found"
  end
  if (tonumber(cached_player.connectionGeneration) or 0) ~= expected_generation then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    return nil, "connection_generation_mismatch"
  end

  local expected_name_normalized = expected_name:lower()
  local current_name_matches = false
  for _, value in ipairs({
    tostring(cached_player.name or ""),
    tostring(cached_player.username or ""),
    tostring(cached_player.userName or ""),
    tostring(cached_player.playerName or ""),
    tostring(cached_player.displayName or ""),
    tostring(cached_player.originalName or ""),
  }) do
    if trim_string(tostring(value or "")):lower() == expected_name_normalized then
      current_name_matches = true
      break
    end
  end
  if not current_name_matches then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    return nil, "sender_name_mismatch"
  end
  return cached_player, "ok"
end

function live_chat_controller_exact_name_matches(controller, expected_name)
  if not live_chat_is_valid_object(controller) then
    return false, {}
  end
  local normalized = trim_string(tostring(expected_name or "")):lower()
  if normalized == "" then
    return false, {}
  end
  local metadata = live_chat_controller_metadata(controller)
  for _, value in ipairs({
    tostring(metadata.name or ""),
    tostring(metadata.username or ""),
    tostring(metadata.userName or ""),
    tostring(metadata.playerName or ""),
    tostring(metadata.displayName or ""),
  }) do
    if trim_string(tostring(value or "")):lower() == normalized then
      return true, metadata
    end
  end
  return false, metadata
end

function live_chat_controller_authoritative_identity_matches(
    controller,
    expected_uuid,
    expected_name)
  local metadata = live_chat_controller_metadata(controller, expected_uuid)
  local live_uuid = live_chat_stable_uuid(
    metadata.uuid or metadata.playerId or "")
  local expected_name_normalized = trim_string(
    tostring(expected_name or "")):lower()
  if expected_name_normalized == "" or live_uuid == ""
      or live_uuid ~= live_chat_stable_uuid(expected_uuid) then
    return false, metadata
  end

  -- The name is already required to match the current Omegga UUID/generation
  -- snapshot before this function is reached. If the build exposes a readable
  -- live name, retain it as an additional assertion; otherwise the reciprocal
  -- PlayerState UUID match remains the authoritative native proof.
  local live_name = trim_string(tostring(first_string(
    metadata.name,
    metadata.username,
    metadata.userName,
    metadata.playerName,
    metadata.displayName) or "")):lower()
  if live_name ~= "" and live_name ~= expected_name_normalized then
    return false, metadata
  end
  return true, metadata
end

function live_chat_invalidate_cached_paths(cached_player, identity, reason)
  if type(cached_player) == "table" then
    cached_player.controllerPath = ""
    cached_player.playerStatePath = ""
    cached_player.controllerAvailable = false
    cached_player.bmfControllerPathPreserved = false
  end
  BMFConnectionReadiness.invalidate_paths(
    state.connection_readiness,
    identity and identity.uuid,
    identity and identity.connectionGeneration,
    reason,
    os.time() * 1000)
end

-- Resolve a controller without ever inferring identity from controller count,
-- array order, a previous recipient, or a partial name. A broad scan is only
-- allowed as a bounded repair after the UUID+generation+name envelope matches
-- the current Omegga snapshot. The resulting UObject wrapper is never stored.
function live_chat_resolve_authoritative_name_target(identity)
  local registry = state.player_registry or {}
  local cached_player, identity_reason = live_chat_validate_authoritative_identity(identity)
  if cached_player == nil then
    registry.authoritative_name_failures =
      (tonumber(registry.authoritative_name_failures) or 0) + 1
    return nil, {}, identity_reason
  end
  local expected_uuid = live_chat_stable_uuid(identity.uuid)
  local expected_name = trim_string(tostring(identity.senderName or ""))

  local strict_target, strict_targets, strict_reason = live_chat_resolve_strict_target({
    uuid = identity.uuid,
    connectionGeneration = identity.connectionGeneration,
  })
  if strict_target ~= nil then
    local exact = live_chat_controller_authoritative_identity_matches(
      strict_target.controller,
      expected_uuid,
      expected_name)
    if exact then
      if BMFConnectionReadiness.note_path_reuse(
          state.connection_readiness,
          identity.uuid,
          identity.connectionGeneration,
          os.time() * 1000) then
        registry.controller_path_reuses =
          (tonumber(registry.controller_path_reuses) or 0) + 1
        cached_player.bmfControllerPathPreserved = false
      end
      registry.authoritative_name_resolutions =
        (tonumber(registry.authoritative_name_resolutions) or 0) + 1
      return strict_target, strict_targets, "ok"
    end
    registry.authoritative_name_failures =
      (tonumber(registry.authoritative_name_failures) or 0) + 1
    live_chat_invalidate_cached_paths(cached_player, identity, "live_sender_name_mismatch")
    return nil, {}, "live_sender_name_mismatch"
  end
  if strict_reason ~= "current_paths_unavailable"
      and strict_reason ~= "controller_unavailable" then
    if strict_reason == "live_player_state_mismatch"
        or strict_reason == "live_uuid_mismatch"
        or strict_reason == "live_name_mismatch"
        or strict_reason == "snapshot_generation_mismatch" then
      live_chat_invalidate_cached_paths(cached_player, identity, strict_reason)
    end
    registry.authoritative_name_failures =
      (tonumber(registry.authoritative_name_failures) or 0) + 1
    return nil, {}, strict_reason
  end

  if strict_reason == "controller_unavailable" then
    live_chat_invalidate_cached_paths(cached_player, identity, strict_reason)
  end

  local repair_now_ms = os.time() * 1000
  local repair_window_ms = math.max(
    tonumber(registry.repair_cooldown_ms) or BMF_PLAYER_REGISTRY_DEFAULT_REPAIR_COOLDOWN_MS,
    tonumber(registry.repair_backoff_ms) or 0)
  local repair_allowed, repair_decision, repair_next_at_ms =
    BMFConnectionReadiness.repair_decision(
      state.connection_readiness,
      identity.uuid,
      identity.connectionGeneration,
      repair_now_ms,
      repair_window_ms,
      strict_reason)
  if not repair_allowed then
    registry.session_repair_deferrals =
      (tonumber(registry.session_repair_deferrals) or 0) + 1
    registry.authoritative_name_failures =
      (tonumber(registry.authoritative_name_failures) or 0) + 1
    if repair_decision == "deferred" then
      return nil, {}, "exact_name_repair_deferred", {
        retryAfterMs = math.max(0, repair_next_at_ms - repair_now_ms),
        repairNextAtMs = repair_next_at_ms,
      }
    end
    return nil, {}, "repair_session_invalid"
  end
  registry.session_repair_attempts =
    (tonumber(registry.session_repair_attempts) or 0) + 1

  local targets, repair_detail = live_chat_collect_targets({
    repair = true,
    expectedUuid = expected_uuid,
  })
  registry.authoritative_name_scans =
    (tonumber(registry.authoritative_name_scans) or 0)
      + (tonumber(repair_detail and repair_detail.globalScans) or 0)
  local matches = {}
  for _, target in ipairs(targets or {}) do
    local exact, metadata = live_chat_controller_authoritative_identity_matches(
      target.controller,
      expected_uuid,
      expected_name)
    local controller_path = trim_string(tostring(
      metadata.controllerPath or target.controllerPath or ""))
    local player_state_path = trim_string(tostring(
      metadata.playerStatePath or target.playerStatePath or ""))
    if exact and controller_path ~= "" and player_state_path ~= "" then
      target.controllerPath = controller_path
      target.playerStatePath = player_state_path
      matches[#matches + 1] = target
    end
  end

  if #matches ~= 1 then
    registry.authoritative_name_failures =
      (tonumber(registry.authoritative_name_failures) or 0) + 1
    if #matches > 1 then
      registry.authoritative_name_ambiguities =
        (tonumber(registry.authoritative_name_ambiguities) or 0) + 1
      return nil, matches, "exact_name_ambiguous"
    end
    if repair_detail and repair_detail.skipped == true then
      return nil, {}, "exact_name_repair_deferred", {
        retryAfterMs = math.max(0, repair_next_at_ms - repair_now_ms),
        repairNextAtMs = repair_next_at_ms,
      }
    end
    return nil, {}, "exact_name_not_found"
  end

  local repaired = matches[1]
  -- Persist plain paths only. Never retain `repaired.controller` or any other
  -- UObject wrapper beyond this synchronous resolution.
  cached_player.controllerPath = repaired.controllerPath
  cached_player.playerStatePath = repaired.playerStatePath
  cached_player.controllerAvailable = true

  local verified, verified_targets, verified_reason = live_chat_resolve_strict_target({
    uuid = identity.uuid,
    connectionGeneration = identity.connectionGeneration,
  })
  local verified_exact = verified ~= nil
    and live_chat_controller_authoritative_identity_matches(
      verified.controller,
      expected_uuid,
      expected_name)
  if verified == nil or not verified_exact then
    cached_player.controllerPath = ""
    cached_player.playerStatePath = ""
    cached_player.controllerAvailable = false
    registry.authoritative_name_failures =
      (tonumber(registry.authoritative_name_failures) or 0) + 1
    return nil, {}, verified_reason ~= "ok" and verified_reason or "live_sender_name_mismatch"
  end

  verified.source = "player_cache.authoritative_name_repair"
  registry.authoritative_name_resolutions =
    (tonumber(registry.authoritative_name_resolutions) or 0) + 1
  return verified, verified_targets, "ok"
end

function live_chat_resolve_target(player)
  if type(player) == "table" and player.strictPrivateIdentity == true then
    if trim_string(tostring(player.senderName or "")) ~= "" then
      return live_chat_resolve_authoritative_name_target(player)
    end
    return live_chat_resolve_strict_target(player)
  end
  local registry = state.player_registry or {}
  local resolved = BMF.players.find(player)
  if not resolved.ok or type(resolved.data) ~= "table" or type(resolved.data.player) ~= "table" then
    BMF_operation_note_cache_result("miss")
    registry.unresolved_players = math.max(1, tonumber(registry.unresolved_players) or 0)
    return nil, {}
  end

  local cached_player = resolved.data.player
  local snapshot_generation = tonumber(cached_player.snapshotGeneration) or 0
  local current_generation = tonumber(registry.generation) or 0
  if snapshot_generation > 0 and current_generation > 0 and snapshot_generation ~= current_generation then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    BMF_operation_note_cache_result("generation_mismatch")
    return nil, {}
  end

  local controller = live_chat_cached_controller(cached_player.controllerPath)
  if controller == nil then
    BMF_operation_note_cache_result("miss")
    registry.unresolved_players = math.max(1, tonumber(registry.unresolved_players) or 0)
    return nil, {}
  end

  -- Validate the freshly resolved controller against the current plain-data
  -- snapshot. The wrapper exists only for this dispatch and is discarded when
  -- this function returns to the caller.
  local expected_uuid = live_chat_stable_uuid(
    cached_player.uuid or cached_player.id or cached_player.playerId or "")
  local live_metadata = live_chat_controller_metadata(controller, expected_uuid)
  local live_uuid = live_chat_stable_uuid(
    live_metadata.uuid or live_metadata.playerId or "")
  if expected_uuid == "" or live_uuid ~= expected_uuid then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    BMF_operation_note_cache_result("generation_mismatch")
    return nil, {}
  end
  local cached_names = {}
  for _, value in ipairs({
    cached_player.username,
    cached_player.playerName,
    cached_player.displayName,
    cached_player.originalName,
  }) do
    local normalized = trim_string(tostring(value or "")):lower()
    if normalized ~= "" then
      cached_names[normalized] = true
    end
  end
  local live_name = trim_string(tostring(first_string(
    live_metadata.username,
    live_metadata.playerName,
    live_metadata.displayName,
    live_metadata.name) or "")):lower()
  if live_name ~= "" and next(cached_names) ~= nil and cached_names[live_name] ~= true then
    registry.connection_generation_mismatches =
      (tonumber(registry.connection_generation_mismatches) or 0) + 1
    BMF_operation_note_cache_result("generation_mismatch")
    return nil, {}
  end

  BMF_operation_note_cache_result("hit")
  registry.unresolved_players = math.max(0, (tonumber(registry.unresolved_players) or 0) - 1)
  local target = {
    controller = controller,
    name = tostring(cached_player.name or cached_player.playerName or cached_player.username or ""),
    userName = tostring(cached_player.userName or cached_player.username or cached_player.playerName or ""),
    displayName = tostring(cached_player.displayName or cached_player.name or cached_player.username or ""),
    playerId = tostring(cached_player.uuid or cached_player.id or cached_player.playerId or ""),
    controllerPath = tostring(cached_player.controllerPath or ""),
    playerStatePath = tostring(cached_player.playerStatePath or ""),
    label = tostring(cached_player.controllerPath or "player_controller"),
    source = "player_cache.targeted_controller",
  }
  return target, { target }
end

function live_chat_send_to_controller(controller, message)
  if type(OmeggaCallFunctionByNameWithArguments) ~= "function" then
    return false, "OmeggaCallFunctionByNameWithArguments is unavailable"
  end
  if not live_chat_is_valid_object(controller) then
    return false, "target controller is unavailable"
  end

  local command = "ClientPushChatMessage " .. quote_console_string(message)
  local ok, success, output = pcall(OmeggaCallFunctionByNameWithArguments, controller, command, controller)
  if ok and success ~= false then
    return true, tostring(output or ""), command
  end
  if ok then
    return false, tostring(output or "native call returned false"), command
  end
  return false, tostring(success), command
end

function live_chat_send_to_targets(targets, message)
  local delivered = {}
  local failed = {}
  local command = ""
  for _, target in ipairs(targets or {}) do
    local ok, detail, used_command = live_chat_send_to_controller(target.controller, message)
    command = used_command or command
    if ok then
      delivered[#delivered + 1] = live_chat_target_summary(target)
    else
      local failure = live_chat_target_summary(target)
      failure.error = detail
      failed[#failed + 1] = failure
    end
  end
  return delivered, failed, command
end

BMF.chat.broadcast = function(message)
  if tostring(message or "") == "" then
    return result(false, "INVALID_OPTIONS", "message is required")
  end
  local limited = rate_limit_check("chat.broadcast")
  if not limited.ok then
    return limited
  end

  local live_targets = live_chat_collect_targets()
  if #live_targets > 0 and type(OmeggaCallFunctionByNameWithArguments) == "function" then
    local delivered, failed, command = live_chat_send_to_targets(live_targets, message)
    local response = result(#delivered > 0, #delivered > 0 and "OK" or "PLAYER_DELIVERY_UNAVAILABLE", #delivered > 0 and "Message delivered to live player controllers" or "No live player controller accepted the message", {
      message = tostring(message or ""),
      delivered = #delivered > 0,
      deliveredCount = #delivered,
      attemptedCount = #live_targets,
      failedCount = #failed,
      targets = delivered,
      failures = failed,
      command = command,
      executor = "player_controller.client_push_chat_message",
      deliveryMode = "player-controller-client-push-chat-message",
      validation = "L3 Live Player UI confirmed",
    })
    audit_record("chat.broadcast", {
      command = command,
      message = tostring(message or ""),
      deliveredCount = #delivered,
      attemptedCount = #live_targets,
      deliveryMode = response.data.deliveryMode,
    }, {
      source = "framework",
      severity = response.ok and "info" or "warn",
      ok = response.ok,
      code = response.code,
    })
    return response
  end

  local command = "Chat.Broadcast " .. quote_console_string(message)
  local response = exec_console(command)
  if not response.ok and response.code == "CONSOLE_EXEC_UNAVAILABLE" then
    response = exec_console_manager(command)
  end
  response.data.command = command
  response.data.message = tostring(message or "")
  response.data.delivered = false
  response.data.deliveredCount = 0
  response.data.attemptedCount = #live_targets
  response.data.deliveryMode = "legacy-console-fallback"
  response.data.validation = "L2 command acceptance only; visible delivery not implied"
  audit_record("chat.broadcast", {
    command = command,
    message = tostring(message or ""),
    deliveredCount = 0,
    attemptedCount = #live_targets,
    deliveryMode = response.data.deliveryMode,
  }, {
    source = "framework",
    severity = response.ok and "info" or "warn",
    ok = response.ok,
    code = response.code,
  })
  return response
end

(function()

BMF.players = {}

function external_player_record(record)
  if type(record) ~= "table" then
    return record
  end

  if record[1] ~= nil or record[2] ~= nil or record[3] ~= nil then
    return {
      username = tostring(record[1] or ""),
      playerName = tostring(record[1] or ""),
      originalName = tostring(record[1] or ""),
      displayName = tostring(record[2] or record[1] or ""),
      id = tostring(record[3] or ""),
      uuid = tostring(record[3] or ""),
      controllerPath = tostring(record[4] or ""),
      playerStatePath = tostring(record[5] or ""),
      controllerAvailable = trim_string(record[4] or "") ~= "",
    }
  end

  return record
end

function BMF_player_registry_configure_from_env()
  local registry = state.player_registry
  registry.cache_first_enabled = BMF_env_bool(
    "BMF_PLAYER_REGISTRY_CACHE_FIRST_ENABLED",
    true)
  registry.repair_enabled = BMF_env_bool(
    "BMF_PLAYER_REGISTRY_REPAIR_ENABLED",
    true)
  registry.legacy_discovery_enabled = BMF_env_bool(
    "BMF_PLAYER_REGISTRY_LEGACY_DISCOVERY_ENABLED",
    false)
  registry.repair_cooldown_ms = math.max(1000, math.min(300000, BMF_env_number(
    "BMF_PLAYER_REGISTRY_REPAIR_COOLDOWN_MS",
    BMF_PLAYER_REGISTRY_DEFAULT_REPAIR_COOLDOWN_MS,
    1000)))
end

function publish_player_cache(cache, options)
  if type(cache) ~= "table" then
    BMFConnectionReadiness.sync(state.connection_readiness, {}, os.time() * 1000)
    return nil
  end
  options = type(options) == "table" and options or {}
  local registry = state.player_registry
  local requested_generation = tonumber(cache.generation or cache.snapshotGeneration) or 0
  local current_generation = tonumber(registry.generation) or 0
  local next_generation = current_generation + 1
  if options.preserveGeneration == true and requested_generation > 0 then
    next_generation = math.max(current_generation, requested_generation)
  end
  cache.generation = next_generation
  cache.snapshotGeneration = next_generation
  local players = type(cache.players) == "table" and cache.players or cache
  if type(players) == "table" then
    for _, player in ipairs(players) do
      if type(player) == "table" then
        player.snapshotGeneration = next_generation
      end
    end
  end
  registry.cache_loaded = true
  registry.generation = next_generation
  registry.entries = type(players) == "table" and #players or 0
  state.player_cache = cache
  state.player_cache_error = ""
  local readiness_started_clock = os.clock()
  local readiness_transitions_before = tonumber(state.connection_readiness.transitions) or 0
  local path_preservations_before = tonumber(state.connection_readiness.pathPreservations) or 0
  local path_replacements_before = tonumber(state.connection_readiness.pathReplacements) or 0
  local path_clears_before = tonumber(state.connection_readiness.pathClears) or 0
  BMFConnectionReadiness.sync(state.connection_readiness, players, os.time() * 1000)
  if type(BMF_game_command_tunnel_wake_sessions) == "function" then
    BMF_game_command_tunnel_wake_sessions(players)
  end
  BMF_join_correlation_phase(
    cache.correlationId,
    "bmf_readiness_transition",
    readiness_started_clock,
    "ok",
    {
      transitions = math.max(
        0,
        (tonumber(state.connection_readiness.transitions) or 0) - readiness_transitions_before),
      pathPreservations = math.max(
        0,
        (tonumber(state.connection_readiness.pathPreservations) or 0) - path_preservations_before),
      pathReplacements = math.max(
        0,
        (tonumber(state.connection_readiness.pathReplacements) or 0) - path_replacements_before),
      pathClears = math.max(
        0,
        (tonumber(state.connection_readiness.pathClears) or 0) - path_clears_before),
    })
  return cache
end

function load_player_cache(options)
  options = type(options) == "table" and options or {}
  local registry = state.player_registry
  if registry.cache_loaded == true and options.force ~= true then
    return state.player_cache, state.player_cache_error
  end
  registry.disk_loads = (tonumber(registry.disk_loads) or 0) + 1
  local raw = read_file(PLAYER_CACHE_PATH)
  if raw == nil or trim_string(raw) == "" then
    state.player_cache = nil
    state.player_cache_error = ""
    registry.cache_loaded = true
    registry.entries = 0
    BMFConnectionReadiness.sync(state.connection_readiness, {}, os.time() * 1000)
    return nil, ""
  end

  local decoded, err = json_decode(raw)
  if err ~= nil or type(decoded) ~= "table" then
    state.player_cache = nil
    state.player_cache_error = tostring(err or "invalid player cache")
    registry.cache_loaded = true
    registry.entries = 0
    registry.disk_load_failures = (tonumber(registry.disk_load_failures) or 0) + 1
    BMFConnectionReadiness.sync(state.connection_readiness, {}, os.time() * 1000)
    return nil, state.player_cache_error
  end

  return publish_player_cache(decoded, { preserveGeneration = true }), ""
end

function write_player_cache(cache)
  local ok = write_file(PLAYER_CACHE_PATH, json_encode(cache or {}) .. "\n")
  if ok then
    publish_player_cache(cache)
  end
  return ok
end

function configured_saved_dir()
  local saved_dir = trim_string(state.config.brickadiaSavedDir or "")
  if saved_dir == "" then
    return ""
  end
  return saved_dir:gsub("\\", "/"):gsub("/+$", "")
end

function load_player_name_cache(saved_dir)
  local path = join_path(saved_dir, "Server/PlayerNameCache.json")
  local raw = read_file(path)
  if not raw or trim_string(raw) == "" then
    return {}, path, "missing"
  end

  local decoded, err = json_decode(raw)
  if err ~= nil or type(decoded) ~= "table" or type(decoded.savedPlayerNames) ~= "table" then
    return {}, path, tostring(err or "invalid name cache")
  end
  return decoded.savedPlayerNames, path, ""
end

function player_name_cache_lookup(name_cache, uuid)
  if type(name_cache) ~= "table" then
    return ""
  end
  return tostring(name_cache[tostring(uuid or "")] or "")
end

function record_from_pending_login(pending, name_cache)
  if type(pending) ~= "table" or not is_uuid(pending.uuid) then
    return nil
  end
  local original_name = player_name_cache_lookup(name_cache, pending.uuid)
  local username = first_string(pending.username, original_name, pending.displayName) or ""
  local display_name = first_string(pending.displayName, username, original_name) or ""
  return {
    id = pending.uuid,
    uuid = pending.uuid,
    username = username,
    playerName = username,
    displayName = display_name,
    originalName = first_string(original_name, username) or "",
    controllerAvailable = false,
    source = "brickadia-log",
  }
end

function remove_active_player_by_name(active, order, player_name)
  local lowered = trim_string(player_name):lower()
  if lowered == "" then
    return
  end
  for uuid, player in pairs(active) do
    for _, value in ipairs({ player.username, player.playerName, player.displayName, player.originalName }) do
      if trim_string(value):lower() == lowered then
        active[uuid] = nil
        for index = #order, 1, -1 do
          if order[index] == uuid then
            table.remove(order, index)
          end
        end
        return
      end
    end
  end
end

function parse_brickadia_log_players(saved_dir)
  local path = join_path(saved_dir, "Logs/Brickadia.log")
  local raw = read_file(path)
  if not raw or trim_string(raw) == "" then
    return {}, {
      adapter = "brickadia-log",
      path = path,
      error = "missing",
    }
  end

  local name_cache = load_player_name_cache(saved_dir)
  local active = {}
  local order = {}
  local pending = nil

  local function upsert_player(player)
    if not player or not is_uuid(player.uuid) then
      return
    end
    if active[player.uuid] == nil then
      order[#order + 1] = player.uuid
    end
    active[player.uuid] = player
  end

  for line in raw:gmatch("[^\r\n]+") do
    if line:find("LogServerList:%s+Auth payload valid%. Result:") then
      pending = {}
    elseif pending ~= nil then
      local username = line:match("LogServerList:%s+UserName:%s*(.-)%s*$")
      local display_name = line:match("LogServerList:%s+DisplayName:%s*(.-)%s*$")
      local user_id = line:match("LogServerList:%s+UserId:%s*([0-9a-fA-F%-]+)")
      if username then
        pending.username = username
      elseif display_name then
        pending.displayName = display_name
      elseif user_id then
        pending.uuid = user_id:lower()
      end
    end

    local joined = line:match("LogChat:%s*(.-)%s+joined the game%.")
    if joined then
      local player = record_from_pending_login(pending, name_cache)
      if player ~= nil then
        upsert_player(player)
      end
      pending = nil
    end

    local left = line:match("LogChat:%s*(.-)%s+left the game%.")
    if left then
      remove_active_player_by_name(active, order, left)
    end
  end

  local players = {}
  for _, uuid in ipairs(order) do
    if active[uuid] ~= nil then
      players[#players + 1] = active[uuid]
    end
  end

  return players, {
    adapter = "brickadia-log",
    path = path,
    error = "",
  }
end

function native_player_records()
  local saved_dir = configured_saved_dir()
  if saved_dir == "" then
    return {}, {
      adapter = "none",
      source = "native-disabled",
      error = "brickadiaSavedDir is not configured",
    }
  end

  local players, detail = parse_brickadia_log_players(saved_dir)
  detail = type(detail) == "table" and detail or {}
  detail.source = "brickadia-log"
  detail.savedDir = saved_dir
  return players, detail
end

function live_player_controller_count(options)
  local targets, repair_detail = live_chat_collect_targets(options)
  return #targets, targets, repair_detail
end

function player_cache_records(cache)
  if type(cache) ~= "table" then
    return {}
  end
  if type(cache.players) == "table" then
    return cache.players
  end
  return cache
end

BMF.players.list = function(options)
  local opts = type(options) == "table" and options or {}
  local registry = state.player_registry
  local cache, cache_err = load_player_cache()
  local legacy_requested = opts.legacyDiscovery == true
    or option_boolean(opts, "legacydiscovery", false)
    or option_boolean(opts, "diagnostic", false)
  local use_legacy_discovery = registry.cache_first_enabled ~= true
    or (legacy_requested and registry.legacy_discovery_enabled == true)
  local native_records = {}
  local native_detail = {
    adapter = "player-registry-cache",
    source = "memory-cache",
    error = "",
    skipped = true,
  }
  if use_legacy_discovery then
    native_records, native_detail = native_player_records()
    native_detail.skipped = false
  end
  local cached_records = player_cache_records(cache)
  local raw_records = use_legacy_discovery and #native_records > 0 and native_records or cached_records
  if type(cache) == "table" then
    registry.cache_hits = (tonumber(registry.cache_hits) or 0) + 1
    BMF_operation_note_cache_result("hit")
  else
    registry.cache_misses = (tonumber(registry.cache_misses) or 0) + 1
    BMF_operation_note_cache_result("miss")
  end
  local adapter = "headless-empty"
  local source = ""
  local updated_at = ""
  local cache_path = PLAYER_CACHE_PATH
  local cache_error = cache_err
  if use_legacy_discovery and #native_records > 0 then
    adapter = tostring(native_detail.adapter or "brickadia-log")
    source = tostring(native_detail.source or "brickadia-log")
    cache_path = tostring(native_detail.path or "")
    cache_error = tostring(native_detail.error or "")
    updated_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  elseif type(cache) == "table" and type(cache.players) == "table" then
    adapter = tostring(cache.adapter or "external-cache")
    source = tostring(cache.source or "")
    updated_at = tostring(cache.updatedAt or "")
  elseif type(raw_records) == "table" and #raw_records > 0 then
    adapter = "external-cache"
  end

  local normalized = BMF.players.normalizeList(raw_records)
  local players = {}
  local invalid = {}
  if normalized.ok and normalized.data then
    players = normalized.data.players or {}
    invalid = normalized.data.invalid or {}
  end
  if #players == 0 then
    adapter = "headless-empty"
  end

  local include_live_controllers =
    opts.liveControllers == true or
    opts.includeLiveControllers == true or
    option_boolean(opts, "livecontrollers", false) or
    option_boolean(opts, "includelivecontrollers", false) or
    os.getenv("BMF_PLAYERS_LIST_LIVE_CONTROLLERS") == "1"
  local repair_requested = opts.repair == true or option_boolean(opts, "repair", false)
  if repair_requested then
    include_live_controllers = true
  end
  local live_count = 0
  local live_targets = {}
  local live_controllers = {}
  local repair_detail = {
    requested = repair_requested,
    performed = false,
    skipped = false,
    matched = 0,
    globalScans = 0,
    error = "",
  }
  if include_live_controllers then
    live_count, live_targets, repair_detail = live_player_controller_count({
      repair = repair_requested,
    })
    for _, target in ipairs(live_targets or {}) do
      live_controllers[#live_controllers + 1] = live_chat_target_summary(target)
    end
  end
  return result(true, "OK", #players > 0 and "Known player records listed" or "No cached player identity records are available", {
    players = players,
    invalid = invalid,
    playerCount = #players,
    knownPlayerCount = #players,
    invalidCount = #invalid,
    liveControllerCount = live_count,
    liveControllers = live_controllers,
    liveControllersIncluded = include_live_controllers,
    adapter = adapter,
    source = source,
    updatedAt = updated_at,
    cachePath = cache_path,
    cacheError = cache_error,
    cacheFirst = registry.cache_first_enabled == true,
    cacheGeneration = tonumber(registry.generation) or 0,
    legacyDiscoveryUsed = use_legacy_discovery,
    repair = repair_detail,
    native = native_detail,
  })
end

function player_position_axis_from_value(value, names, index)
  if type(value) == "number" then
    return finite_number(value, nil)
  end
  if type(value) == "table" then
    local direct = finite_number(value[index], nil)
    if direct ~= nil then
      return direct
    end
    for _, name in ipairs(names or {}) do
      local number = finite_number(value[name], nil)
      if number ~= nil then
        return number
      end
    end
    return nil
  end
  if type(value) ~= "userdata" then
    return nil
  end

  for _, name in ipairs(names or {}) do
    local raw = minigame_try_property(value, name)
    local number = finite_number(raw, nil)
    if number ~= nil then
      return number
    end
  end
  return nil
end

function player_position_from_text(value)
  local text = minigame_value_to_string(value)
  if trim_string(text) == "" then
    text = tostring(value or "")
  end
  local x = text:match("[Xx]%s*=%s*([%-%+]?%d+%.?%d*)")
  local y = text:match("[Yy]%s*=%s*([%-%+]?%d+%.?%d*)")
  local z = text:match("[Zz]%s*=%s*([%-%+]?%d+%.?%d*)")
  if x and y and z then
    return {
      x = finite_number(x, 0),
      y = finite_number(y, 0),
      z = finite_number(z, 0),
    }
  end

  local a, b, c = text:match("^%s*%(%s*([%-%+]?%d+%.?%d*)%s*,%s*([%-%+]?%d+%.?%d*)%s*,%s*([%-%+]?%d+%.?%d*)%s*%)%s*$")
  if not a then
    a, b, c = text:match("^%s*([%-%+]?%d+%.?%d*)%s*,%s*([%-%+]?%d+%.?%d*)%s*,%s*([%-%+]?%d+%.?%d*)%s*$")
  end
  if a and b and c then
    return {
      x = finite_number(a, 0),
      y = finite_number(b, 0),
      z = finite_number(c, 0),
    }
  end
  return nil
end

function player_position_from_vector(value)
  if value == nil then
    return nil
  end

  local x = player_position_axis_from_value(value, { "X", "x" }, 1)
  local y = player_position_axis_from_value(value, { "Y", "y" }, 2)
  local z = player_position_axis_from_value(value, { "Z", "z" }, 3)
  if x ~= nil and y ~= nil and z ~= nil then
    return { x = x, y = y, z = z }
  end

  return player_position_from_text(value)
end

function player_position_call_vector(object, method_name)
  if not minigame_object_valid(object) then
    return nil, "invalid object"
  end

  local method = minigame_userdata_method(object, method_name)
  if type(method) ~= "function" then
    return nil, "method unavailable"
  end

  local ok, value = pcall(function()
    return method(object)
  end)
  if not ok then
    return nil, tostring(value)
  end

  local position = player_position_from_vector(value)
  if position ~= nil then
    return position, ""
  end
  return nil, "method returned non-vector " .. minigame_compact_value(minigame_value_to_string(value))
end

function player_position_property_vector(object, property_name)
  if not minigame_object_valid(object) then
    return nil, "invalid object"
  end
  local value = minigame_try_property(object, property_name)
  if value == nil then
    return nil, "property unavailable"
  end
  local position = player_position_from_vector(value)
  if position ~= nil then
    return position, ""
  end
  return nil, "property returned non-vector " .. minigame_compact_value(minigame_value_to_string(value))
end

function player_position_component_vector(object, component_property, vector_property)
  if not minigame_object_valid(object) then
    return nil, "invalid object"
  end
  local component = minigame_try_property(object, component_property)
  if not minigame_object_valid(component) then
    return nil, "component unavailable"
  end
  return player_position_property_vector(component, vector_property)
end

function player_position_add_candidate(candidates, seen, object, source)
  if not minigame_object_valid(object) then
    return
  end
  local key = minigame_object_address(object)
  if key == "" then
    key = minigame_object_full_name(object)
  end
  if key == "" then
    key = tostring(object or "")
  end
  if key == "" or seen[key] then
    return
  end
  seen[key] = true
  candidates[#candidates + 1] = {
    object = object,
    source = tostring(source or ""),
    address = minigame_object_address(object),
    objectName = minigame_object_name(object),
    fullName = minigame_object_full_name(object),
    className = minigame_object_class_name(object),
  }
end

function player_position_candidate_pawns(player_state)
  local candidates = {}
  local seen = {}
  local controller = minigame_try_property(player_state, "Owner")

  for _, property_name in ipairs({ "PawnPrivate", "Pawn", "Character", "DefaultPawn" }) do
    player_position_add_candidate(
      candidates,
      seen,
      minigame_try_property(player_state, property_name),
      "player_state." .. property_name
    )
  end

  if minigame_object_valid(controller) then
    for _, property_name in ipairs({ "AcknowledgedPawn", "Pawn", "Character", "ControlledPawn" }) do
      player_position_add_candidate(
        candidates,
        seen,
        minigame_try_property(controller, property_name),
        "controller." .. property_name
      )
    end
  end

  return candidates, controller
end

function player_position_read_from_pawn(pawn, options)
  local attempts = {}
  local opts = type(options) == "table" and options or {}
  local allow_method_calls =
    opts.callMethods == true or
    option_boolean(opts, "callmethods", false) or
    option_boolean(opts, "methods", false)

  if allow_method_calls then
    for _, method_name in ipairs({
      "K2_GetActorLocation",
      "GetActorLocation",
      "GetTransform",
    }) do
      local position, err = player_position_call_vector(pawn, method_name)
      attempts[#attempts + 1] = {
        source = "pawn." .. method_name,
        ok = position ~= nil,
        error = tostring(err or ""),
      }
      if position ~= nil then
        return position, "pawn." .. method_name, attempts
      end
    end
  else
    for _, method_name in ipairs({
      "K2_GetActorLocation",
      "GetActorLocation",
      "GetTransform",
    }) do
      attempts[#attempts + 1] = {
        source = "pawn." .. method_name,
        ok = false,
        error = "skipped-unsafe-struct-return",
      }
    end
  end

  for _, chain in ipairs({
    { component = "RootComponent", vector = "RelativeLocation" },
    { component = "CollisionCylinder", vector = "RelativeLocation" },
    { component = "CapsuleComponent", vector = "RelativeLocation" },
    { component = "Mesh", vector = "RelativeLocation" },
  }) do
    local position, err = player_position_component_vector(pawn, chain.component, chain.vector)
    attempts[#attempts + 1] = {
      source = "pawn." .. chain.component .. "." .. chain.vector,
      ok = position ~= nil,
      error = tostring(err or ""),
    }
    if position ~= nil then
      return position, "pawn." .. chain.component .. "." .. chain.vector, attempts
    end
  end

  for _, property_name in ipairs({
    "Location",
    "RelativeLocation",
    "ReplicatedMovement",
    "ActorLocation",
    "K2Node_ComponentBoundEvent_Location",
  }) do
    local position, err = player_position_property_vector(pawn, property_name)
    attempts[#attempts + 1] = {
      source = "pawn." .. property_name,
      ok = position ~= nil,
      error = tostring(err or ""),
    }
    if position ~= nil then
      return position, "pawn." .. property_name, attempts
    end
  end

  return nil, "", attempts
end

function player_position_identity_from_cache(players, player_name, candidates)
  local lowered_name = trim_string(player_name or ""):lower()
  local candidate_map = {}
  for _, candidate in ipairs(candidates or {}) do
    local lowered = trim_string(candidate):lower()
    if lowered ~= "" then
      candidate_map[lowered] = true
    end
  end

  for _, player in ipairs(players or {}) do
    local values = {
      player.uuid,
      player.id,
      player.username,
      player.playerName,
      player.displayName,
      player.originalName,
      player.playerStatePath,
      player.controllerPath,
    }
    for _, value in ipairs(values) do
      local lowered = trim_string(value or ""):lower()
      if lowered ~= "" and (candidate_map[lowered] or lowered == lowered_name) then
        return player, lowered == lowered_name and "cache.name" or "cache.candidate"
      end
    end
  end

  return nil, ""
end

function player_position_candidate_pawns_from_controller(controller)
  local candidates = {}
  local seen = {}
  if not minigame_object_valid(controller) then
    return candidates
  end

  for _, property_name in ipairs({ "AcknowledgedPawn", "Pawn", "Character", "ControlledPawn" }) do
    player_position_add_candidate(
      candidates,
      seen,
      minigame_try_property(controller, property_name),
      "controller." .. property_name
    )
  end

  return candidates
end

function player_position_identity_from_live_target(known_players, target, target_count)
  target = type(target) == "table" and target or {}
  known_players = type(known_players) == "table" and known_players or {}

  local candidates = {
    target.playerId,
    target.name,
    target.userName,
    target.displayName,
    target.controllerPath,
    target.playerStatePath,
    target.label,
  }
  local identity, identity_source = player_position_identity_from_cache(known_players, target.name, candidates)
  if identity ~= nil then
    return identity, identity_source
  end

  if tonumber(target_count) == 1 and #known_players == 1 then
    return known_players[1], "cache.single-live-controller"
  end

  return nil, ""
end

function player_position_parse_native_lines(text)
  local fields = {}
  for line in tostring(text or ""):gmatch("[^\r\n]+") do
    local key, value = line:match("^([A-Za-z0-9_]+)=(.*)$")
    if key ~= nil then
      fields[key] = value or ""
    end
  end
  return fields
end

function player_position_parse_pipe_fields(text)
  local fields = {}
  for part in tostring(text or ""):gmatch("[^|]+") do
    local key, value = part:match("^([A-Za-z0-9_]+)=(.*)$")
    if key ~= nil then
      fields[key] = value or ""
    end
  end
  return fields
end

function player_position_native_attempt(fields, source_value, source_label, raw)
  fields = type(fields) == "table" and fields or {}
  local detail = tostring(fields.detail or "native helper returned ok=false")
  return {
    source = "native.BMFSocketPlayerLocation." .. tostring(source_label or "source"),
    ok = tostring(fields.ok or "") == "true",
    address = tostring(source_value or ""),
    sourceKind = tostring(fields.source_kind or ""),
    sourceAddress = tostring(fields.source_address or ""),
    source_address = tostring(fields.source_address or ""),
    sourceObject = tostring(fields.source_object or ""),
    sourceFullName = tostring(fields.source_full_name or ""),
    controllerAddress = tostring(fields.controller_address or ""),
    controller_address = tostring(fields.controller_address or ""),
    controller = tostring(fields.controller or ""),
    controllerFullName = tostring(fields.controller_full_name or ""),
    pawnAddress = tostring(fields.pawn_address or ""),
    pawn_address = tostring(fields.pawn_address or ""),
    pawn = tostring(fields.pawn or ""),
    pawnFullName = tostring(fields.pawn_full_name or ""),
    rootComponentAddress = tostring(fields.root_component_address or ""),
    root_component_address = tostring(fields.root_component_address or ""),
    rootComponent = tostring(fields.root_component or ""),
    rootComponentFullName = tostring(fields.root_component_full_name or ""),
    detail = detail,
    raw = tostring(raw or ""),
  }
end

function player_position_native_observed_memory_source_is_usable(attempt, fields)
  fields = type(fields) == "table" and fields or {}
  local source_kind = tostring(
    (attempt and (attempt.sourceKind or attempt.source_kind)) or
    fields.source_kind or
    fields.sourceKind or
    ""
  )
  local source_kind_lower = source_kind:lower()
  if source_kind_lower:find("observed_memory", 1, true) == nil then
    return true
  end

  local root_component = tostring(
    (attempt and (attempt.rootComponent or attempt.root_component)) or
    fields.root_component or
    fields.rootComponent or
    ""
  ):lower()
  local root_component_full_name = tostring(
    (attempt and (attempt.rootComponentFullName or attempt.root_component_full_name)) or
    fields.root_component_full_name or
    fields.rootComponentFullName or
    ""
  ):lower()

  local known_component_root =
    root_component:find("collisioncylinder", 1, true) ~= nil or
    root_component_full_name:find("capsulecomponent", 1, true) ~= nil
  local measured_component_vector =
    source_kind_lower:find("root_component.memberoffset.observed_memory.vector3d", 1, true) ~= nil

  return known_component_root and measured_component_vector
end

function player_position_native_attempt_is_usable(attempt, fields)
  if not (attempt and attempt.ok == true) then
    return false
  end
  fields = type(fields) == "table" and fields or {}
  local source_kind = tostring(attempt.sourceKind or attempt.source_kind or fields.source_kind or "")
  if source_kind:lower():find("observed_memory", 1, true) ~= nil and
      not player_position_native_observed_memory_source_is_usable(attempt, fields) then
    attempt.ok = false
    attempt.detail = "observed-memory vector is diagnostic-only"
    return false
  end
  return true
end

function player_position_native_position_from_attempt(attempt, fields)
  if not player_position_native_attempt_is_usable(attempt, fields) then
    return nil
  end
  local position = {
    x = finite_number(fields.x, nil),
    y = finite_number(fields.y, nil),
    z = finite_number(fields.z, nil),
  }
  if position.x ~= nil and position.y ~= nil and position.z ~= nil then
    attempt.detail = "ok"
    return position
  end
  attempt.ok = false
  attempt.detail = "native helper returned incomplete coordinates"
  return nil
end

function player_position_native_from_source(source_value, query, source_label)
  if type(BMFSocketPlayerLocation) ~= "function" then
    return nil, "BMFSocketPlayerLocation unavailable", {
      source = "native.BMFSocketPlayerLocation." .. tostring(source_label or "source"),
      ok = false,
      address = tostring(source_value or ""),
      detail = "native helper unavailable",
    }
  end

  local ok, response = pcall(BMFSocketPlayerLocation, tostring(source_value or ""), tostring(query or ""))
  if not ok then
    return nil, tostring(response or "native helper failed"), {
      source = "native.BMFSocketPlayerLocation." .. tostring(source_label or "source"),
      ok = false,
      address = tostring(source_value or ""),
      detail = tostring(response or "native helper failed"),
    }
  end

  local fields = player_position_parse_native_lines(response)
  local attempt = player_position_native_attempt(fields, source_value, source_label, response)
  local position = player_position_native_position_from_attempt(attempt, fields)
  if position ~= nil then
    return position, attempt.source, attempt
  end

  return nil, attempt.detail, attempt
end

function player_position_native_from_controller(controller, query)
  if type(BMFSocketPlayerLocation) ~= "function" then
    return nil, "BMFSocketPlayerLocation unavailable", {
      source = "native.BMFSocketPlayerLocation",
      ok = false,
      address = "",
      detail = "native helper unavailable",
    }
  end
  if not minigame_object_valid(controller) then
    return nil, "controller unavailable", {
      source = "native.BMFSocketPlayerLocation",
      ok = false,
      address = "",
      detail = "controller unavailable",
    }
  end

  local sources = {}
  local seen = {}
  local function add_source(object, source)
    if not minigame_object_valid(object) then
      return
    end
    local address = minigame_object_address(object)
    if address == "" then
      address = live_chat_object_key(object, "")
    end
    if address == "" or seen[address] then
      return
    end
    seen[address] = true
    sources[#sources + 1] = {
      address = address,
      source = tostring(source or ""),
      objectName = minigame_object_name(object),
      fullName = minigame_object_full_name(object),
    }
  end

  add_source(controller, "controller")
  for _, property_name in ipairs({ "Pawn", "AcknowledgedPawn", "Character", "ControlledPawn" }) do
    add_source(minigame_try_property(controller, property_name), "controller." .. property_name)
  end

  if #sources == 0 then
    return nil, "controller address unavailable", {
      source = "native.BMFSocketPlayerLocation",
      ok = false,
      address = "",
      detail = "controller address unavailable",
    }
  end

  local attempts = {}
  local last_detail = "native helper returned no position"
  for _, source in ipairs(sources) do
    local ok, response = pcall(BMFSocketPlayerLocation, source.address, tostring(query or ""))
    if not ok then
      last_detail = tostring(response or "native helper failed")
      attempts[#attempts + 1] = {
        source = "native.BMFSocketPlayerLocation." .. source.source,
        ok = false,
        address = source.address,
        objectName = source.objectName,
        fullName = source.fullName,
        detail = last_detail,
      }
    else
      local fields = player_position_parse_native_lines(response)
      local detail = tostring(fields.detail or "native helper returned ok=false")
      local attempt = {
        source = "native.BMFSocketPlayerLocation." .. source.source,
        ok = tostring(fields.ok or "") == "true",
        address = source.address,
        objectName = source.objectName,
        fullName = source.fullName,
        sourceKind = tostring(fields.source_kind or ""),
        sourceAddress = tostring(fields.source_address or ""),
        source_address = tostring(fields.source_address or ""),
        sourceObject = tostring(fields.source_object or ""),
        sourceFullName = tostring(fields.source_full_name or ""),
        controllerAddress = tostring(fields.controller_address or ""),
        controller_address = tostring(fields.controller_address or ""),
        controller = tostring(fields.controller or ""),
        controllerFullName = tostring(fields.controller_full_name or ""),
        pawnAddress = tostring(fields.pawn_address or ""),
        pawn_address = tostring(fields.pawn_address or ""),
        pawn = tostring(fields.pawn or ""),
        pawnFullName = tostring(fields.pawn_full_name or ""),
        rootComponentAddress = tostring(fields.root_component_address or ""),
        root_component_address = tostring(fields.root_component_address or ""),
        rootComponent = tostring(fields.root_component or ""),
        rootComponentFullName = tostring(fields.root_component_full_name or ""),
        detail = detail,
        raw = tostring(response or ""),
      }
      attempts[#attempts + 1] = attempt

      if attempt.ok and not player_position_native_attempt_is_usable(attempt, fields) then
        last_detail = attempt.detail
      elseif attempt.ok then
        local position = {
          x = finite_number(fields.x, nil),
          y = finite_number(fields.y, nil),
          z = finite_number(fields.z, nil),
        }
        if position.x ~= nil and position.y ~= nil and position.z ~= nil then
          attempt.detail = "ok"
          attempt.attempts = attempts
          return position, attempt.source, attempt
        end
        last_detail = "native helper returned incomplete coordinates"
        attempt.ok = false
        attempt.detail = last_detail
      else
        last_detail = detail
      end
    end
  end

  return nil, last_detail, {
    source = "native.BMFSocketPlayerLocation",
    ok = false,
    address = sources[1].address,
    detail = last_detail,
    attempts = attempts,
  }
end

function player_position_native_scan_enabled(opts)
  opts = type(opts) == "table" and opts or {}
  if os.getenv("BMF_PLAYERS_POSITIONS_NATIVE_SCAN_UNSAFE_GAME_THREAD") ~= "1" then
    return false
  end
  return
    opts.nativeScan == true or
    option_boolean(opts, "nativescan", false) or
    os.getenv("BMF_PLAYERS_POSITIONS_NATIVE_SCAN") == "1"
end

function player_position_add_native_scan_record(players, fields, limit)
  fields = type(fields) == "table" and fields or {}
  if #players >= limit or tostring(fields.ok or "") ~= "true" then
    return false
  end
  local source_kind = tostring(fields.source_kind or fields.sourceKind or "")
  if source_kind:lower():find("observed_memory", 1, true) ~= nil and
      not player_position_native_observed_memory_source_is_usable(fields, fields) then
    return false
  end

  local position = {
    x = finite_number(fields.x, nil),
    y = finite_number(fields.y, nil),
    z = finite_number(fields.z, nil),
  }
  if position.x == nil or position.y == nil or position.z == nil then
    return false
  end

  players[#players + 1] = {
    player = {
      id = "",
      uuid = "",
      name = "",
      username = "",
      displayName = "",
      identitySource = "anonymous-native-scan",
    },
    ok = true,
    position = position,
    source = "native.BMFSocketPlayerLocation.scan." .. tostring(fields.source_kind or fields.sourceKind or ""),
    playerState = "",
    playerStateName = "",
    controllerAddress = tostring(fields.controller_address or fields.controllerAddress or ""),
    controller_address = tostring(fields.controller_address or fields.controllerAddress or ""),
    controller = tostring(fields.controller or ""),
    controllerName = tostring(fields.controller or ""),
    controllerFullName = tostring(fields.controller_full_name or fields.controllerFullName or ""),
    pawnAddress = tostring(fields.pawn_address or fields.pawnAddress or ""),
    pawn_address = tostring(fields.pawn_address or fields.pawnAddress or ""),
    pawn = tostring(fields.pawn or ""),
    pawnName = tostring(fields.pawn or ""),
    pawnFullName = tostring(fields.pawn_full_name or fields.pawnFullName or ""),
    pawnSource = tostring(fields.source_kind or fields.sourceKind or "native-scan"),
    native = fields,
  }
  return true
end

function player_position_native_scan_snapshot(opts, query, limit)
  opts = type(opts) == "table" and opts or {}
  query = trim_string(query or "")
  limit = tonumber(limit) or 32

  local lines = {
    "source=bmf.players.positions",
    "query=" .. query,
    "source_mode=native-scan",
  }
  local players = {}
  local response = ""

  if type(BMFSocketPlayerLocation) ~= "function" then
    lines[#lines + 1] = "native_available=false"
    lines[#lines + 1] = "code=POSITION_UNAVAILABLE"
    lines[#lines + 1] = "reason=BMFSocketPlayerLocation unavailable"
  else
    local ok, native_response = pcall(BMFSocketPlayerLocation, "*", query)
    response = tostring(native_response or "")
    lines[#lines + 1] = "native_available=true"
    if not ok then
      lines[#lines + 1] = "code=POSITION_UNAVAILABLE"
      lines[#lines + 1] = "reason=" .. tostring(native_response or "native scan failed")
    else
      local top_level_fields = {}
      for line in response:gmatch("[^\r\n]+") do
        lines[#lines + 1] = "native_" .. line
        local key, value = line:match("^([A-Za-z0-9_]+)=(.*)$")
        if key ~= nil then
          if key:match("^position_%d+$") then
            player_position_add_native_scan_record(
              players,
              player_position_parse_pipe_fields(value),
              limit
            )
          else
            top_level_fields[key] = value or ""
          end
        end
      end
      if #players == 0 then
        player_position_add_native_scan_record(players, top_level_fields, limit)
      end
    end
  end

  lines[#lines + 1] = "players=" .. tostring(#players)
  lines[#lines + 1] = "returned=" .. tostring(#players)
  lines[#lines + 1] = "positioned=" .. tostring(#players)

  local data = {
    source = "bmf.players.positions",
    checkedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    query = query,
    sourceMode = "native-scan",
    playerArrayCount = 0,
    liveControllerCount = 0,
    nativeAvailable = type(BMFSocketPlayerLocation) == "function",
    players = players,
    nativeResponse = response,
    counts = {
      observed = #players,
      returned = #players,
      positioned = #players,
      knownPlayers = 0,
    },
    lines = lines,
  }
  lines[#lines + 1] = "positions_json=" .. json_encode(data)
  return data
end

function player_position_controller_cache_ttl_seconds()
  local configured = tonumber(os.getenv("BMF_PLAYERS_POSITIONS_CONTROLLER_CACHE_TTL_SECONDS") or "")
  if configured ~= nil and configured > 0 then
    return configured
  end
  return tonumber(state.player_position_controller_cache.ttl_seconds) or 120
end

function player_position_controller_cache_key(value)
  local text = trim_string(tostring(value or ""))
  if text == "" then
    return ""
  end
  return string.lower(text)
end

function player_position_prefixed_source(prefix, value)
  local text = trim_string(tostring(value or ""))
  if text == "" then
    return ""
  end
  if text:match("^[A-Za-z_][A-Za-z0-9_%-]*:") then
    return text
  end
  return tostring(prefix or "uobject") .. ":" .. text
end

function player_position_controller_cache_keys(record)
  local keys = {}
  local seen = {}
  local function add(value)
    local key = player_position_controller_cache_key(value)
    if key ~= "" and not seen[key] then
      seen[key] = true
      keys[#keys + 1] = key
    end
  end

  if type(record) == "table" then
    add(record.uuid)
    add(record.id)
    add(record.playerId)
    add(record.playerID)
    add(record.username)
    add(record.playerName)
    add(record.displayName)
    add(record.name)
  end

  return keys
end

function player_position_controller_cache_lookup(player)
  local cache = state.player_position_controller_cache
  local records = cache and cache.records or {}
  local ttl_seconds = player_position_controller_cache_ttl_seconds()
  local now = os.time()
  for _, key in ipairs(player_position_controller_cache_keys(player)) do
    local record = records[key]
    if type(record) == "table" then
      local updated_epoch = tonumber(record.updatedEpoch or 0) or 0
      if updated_epoch > 0 and now >= updated_epoch and (now - updated_epoch) <= ttl_seconds then
        return record
      end
      records[key] = nil
    end
  end
  return nil
end

function player_position_from_cached_record(player)
  if type(player) ~= "table" or type(player.position) ~= "table" then
    return nil
  end

  local position = {
    x = finite_number(player.position.x or player.position.X or player.position[1], nil),
    y = finite_number(player.position.y or player.position.Y or player.position[2], nil),
    z = finite_number(player.position.z or player.position.Z or player.position[3], nil),
  }
  if position.x ~= nil and position.y ~= nil and position.z ~= nil then
    return position
  end

  return nil
end

function player_position_controller_cache_upsert(identity, target, native_detail)
  if type(native_detail) ~= "table" then
    return
  end

  local controller_address = first_string(
    native_detail.controllerAddress,
    native_detail.controller_address,
    native_detail.address,
    target and live_chat_object_key(target.controller, "") or ""
  )
  controller_address = trim_string(controller_address or "")
  if controller_address == "" then
    return
  end
  local pawn_address = trim_string(first_string(
    native_detail.pawnAddress,
    native_detail.pawn_address
  ) or "")
  local root_component_address = trim_string(first_string(
    native_detail.rootComponentAddress,
    native_detail.root_component_address
  ) or "")

  local player_name = first_string(
    identity and identity.username,
    identity and identity.playerName,
    identity and identity.displayName,
    target and target.name,
    target and target.userName,
    target and target.displayName
  ) or ""

  local record = {
    uuid = tostring(identity and (identity.uuid or identity.id) or target and target.playerId or ""),
    id = tostring(identity and (identity.uuid or identity.id) or target and target.playerId or ""),
    username = tostring(identity and identity.username or target and target.userName or player_name or ""),
    playerName = tostring(identity and identity.playerName or target and target.name or player_name or ""),
    displayName = tostring(identity and identity.displayName or target and target.displayName or player_name or ""),
    controllerAddress = controller_address,
    controllerPath = controller_address,
    controllerFullName = tostring(native_detail.controllerFullName or ""),
    pawnAddress = pawn_address,
    pawnPath = pawn_address,
    rootComponentAddress = root_component_address,
    rootComponentPath = root_component_address,
    playerStatePath = tostring(target and target.playerStatePath or ""),
    updatedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    updatedEpoch = os.time(),
  }

  local records = state.player_position_controller_cache.records
  for _, key in ipairs(player_position_controller_cache_keys(record)) do
    records[key] = record
  end
end

function player_position_known_records_snapshot(opts, query, limit)
  opts = type(opts) == "table" and opts or {}
  query = trim_string(query or "")
  limit = tonumber(limit) or 32

  local listed = BMF.players.list()
  local known_players = listed.data and type(listed.data.players) == "table" and listed.data.players or {}
  local selected = {}
  local resolve_candidates = {}
  if query ~= "" then
    local found = BMF.players.find(known_players, query)
    if found.ok and found.data and found.data.player then
      selected[#selected + 1] = found.data.player
    else
      resolve_candidates = found.data and found.data.players or {}
    end
  else
    for _, player in ipairs(known_players or {}) do
      selected[#selected + 1] = player
    end
  end

  local players = {}
  local positioned = 0
  local cached_positioned = 0
  local max_count = math.min(limit, #(selected or {}))
  local native_available = type(BMFSocketPlayerLocation) == "function"

  for index = 1, max_count do
    local player = selected[index]
    local attempts = {}
    local position = nil
    local source = ""
    local native_detail = nil
    local source_values = {}

    local controller_path = trim_string(player and player.controllerPath or "")
    local player_state_path = trim_string(player and player.playerStatePath or "")
    local pawn_path = trim_string(player and (player.pawnPath or player.pawnAddress) or "")
    local root_component_path = trim_string(player and (player.rootComponentPath or player.rootComponentAddress) or "")
    position = player_position_from_cached_record(player)
    if position ~= nil then
      cached_positioned = cached_positioned + 1
      source = trim_string(player and (player.positionSource or player.position_source) or "")
      if source == "" then
        source = "cache.position"
      end
    end
    local controller_cache_record = player_position_controller_cache_lookup(player)
    if root_component_path == "" and controller_cache_record ~= nil then
      root_component_path = trim_string(controller_cache_record.rootComponentAddress or controller_cache_record.rootComponentPath or "")
    end
    if pawn_path == "" and controller_cache_record ~= nil then
      pawn_path = trim_string(controller_cache_record.pawnAddress or controller_cache_record.pawnPath or "")
    end
    if controller_path == "" and controller_cache_record ~= nil then
      controller_path = trim_string(controller_cache_record.controllerAddress or controller_cache_record.controllerPath or "")
    end
    if player_state_path == "" and controller_cache_record ~= nil then
      player_state_path = trim_string(controller_cache_record.playerStatePath or "")
    end
    if position == nil then
      if root_component_path ~= "" then
        source_values[#source_values + 1] = {
          value = player_position_prefixed_source("component", root_component_path),
          label = "fast-cache.rootComponentAddress",
        }
      end
      if pawn_path ~= "" then
        source_values[#source_values + 1] = {
          value = player_position_prefixed_source("pawn", pawn_path),
          label = "fast-cache.pawnAddress",
        }
      end
      if controller_path ~= "" then
        source_values[#source_values + 1] = {
          value = player_position_prefixed_source("controller", controller_path),
          label = controller_cache_record ~= nil and "fast-cache.controllerAddress" or "cache.controllerPath",
        }
      end
      if player_state_path ~= "" then
        source_values[#source_values + 1] = { value = player_state_path, label = "cache.playerStatePath" }
      end

      for _, source_value in ipairs(source_values) do
        position, source, native_detail = player_position_native_from_source(
          source_value.value,
          query ~= "" and query or player and (player.username or player.playerName or player.displayName or player.uuid) or "",
          source_value.label
        )
        attempts[#attempts + 1] = native_detail
        if position ~= nil then
          break
        end
      end
    end

    if position ~= nil then
      positioned = positioned + 1
    end

    players[#players + 1] = {
      player = {
        id = tostring(player and (player.uuid or player.id) or ""),
        uuid = tostring(player and (player.uuid or player.id) or ""),
        name = tostring(player and (player.playerName or player.username or player.displayName) or ""),
        username = tostring(player and (player.username or player.playerName) or ""),
        displayName = tostring(player and (player.displayName or player.username or player.playerName) or ""),
        identitySource = "cache",
      },
      ok = position ~= nil,
      position = position,
      source = source,
      playerState = tostring(player_state_path or ""),
      playerStateName = tostring(player_state_path or ""),
      controller = native_detail and native_detail.address or tostring(controller_path or ""),
      controllerName = native_detail and native_detail.controller or tostring(controller_path or ""),
      controllerFullName = native_detail and native_detail.controllerFullName or "",
      pawn = native_detail and native_detail.pawn or "",
      pawnName = native_detail and native_detail.pawn or "",
      pawnFullName = native_detail and native_detail.pawnFullName or "",
      pawnAddress = native_detail and native_detail.pawnAddress or tostring(pawn_path or ""),
      pawn_address = native_detail and native_detail.pawn_address or tostring(pawn_path or ""),
      rootComponentAddress = native_detail and native_detail.rootComponentAddress or tostring(root_component_path or ""),
      root_component_address = native_detail and native_detail.root_component_address or tostring(root_component_path or ""),
      rootComponent = native_detail and native_detail.rootComponent or "",
      rootComponentFullName = native_detail and native_detail.rootComponentFullName or "",
      pawnSource = native_detail and native_detail.sourceKind or "",
      attempts = opts.includeMissing == true and attempts or nil,
      native = native_detail,
    }
  end

  local lines = {
    "source=bmf.players.positions",
    "query=" .. query,
    "source_mode=native-cache",
    "player_array_count=0",
    "live_controllers=0",
    "players=" .. tostring(#(selected or {})),
    "returned=" .. tostring(#players),
    "positioned=" .. tostring(positioned),
    "cached_positioned=" .. tostring(cached_positioned),
    "known_players=" .. tostring(#known_players),
    "native_available=" .. tostring(native_available),
    "adapter=" .. tostring((listed.data and listed.data.adapter) or ""),
  }
  if query ~= "" and #players == 0 then
    lines[#lines + 1] = "code=PLAYER_NOT_FOUND"
    local candidate_texts = {}
    for _, candidate in ipairs(resolve_candidates or {}) do
      if type(candidate) == "table" then
        candidate_texts[#candidate_texts + 1] = first_string(
          candidate.uuid,
          candidate.id,
          candidate.username,
          candidate.playerName,
          candidate.displayName,
          candidate.controllerPath,
          candidate.playerStatePath
        ) or ""
      else
        candidate_texts[#candidate_texts + 1] = tostring(candidate or "")
      end
    end
    lines[#lines + 1] = "candidates=" .. table.concat(candidate_texts, "|")
  end
  for index, player in ipairs(players) do
    local pos = player.position or {}
    lines[#lines + 1] =
      "position_" .. tostring(index) ..
      "=" .. tostring(player.player.name or "") ..
      "|id=" .. tostring(player.player.id or "") ..
      "|ok=" .. tostring(player.ok == true) ..
      "|x=" .. tostring(pos.x or "") ..
      "|y=" .. tostring(pos.y or "") ..
      "|z=" .. tostring(pos.z or "") ..
      "|source=" .. tostring(player.source or "") ..
      "|pawn=" .. tostring(player.pawn or "") ..
      "|pawn_source=" .. tostring(player.pawnSource or "")
  end

  local data = {
    source = "bmf.players.positions",
    checkedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    query = query,
    sourceMode = "native-cache",
    playerArrayCount = 0,
    liveControllerCount = 0,
    nativeAvailable = native_available,
    players = players,
    counts = {
      observed = #(selected or {}),
      returned = #players,
      positioned = positioned,
      knownPlayers = #known_players,
    },
    lines = lines,
  }
  lines[#lines + 1] = "positions_json=" .. json_encode(data)
  return data
end

function player_position_live_controller_snapshot(opts, query, limit)
  opts = type(opts) == "table" and opts or {}
  query = trim_string(query or "")
  limit = tonumber(limit) or 32

  local listed = BMF.players.list()
  local known_players = listed.data and type(listed.data.players) == "table" and listed.data.players or {}
  local targets = {}
  local selected = {}

  if query ~= "" then
    local target, resolved_targets = live_chat_resolve_target(query)
    targets = resolved_targets or {}
    if target ~= nil then
      selected[#selected + 1] = target
    end
  else
    targets = live_chat_collect_targets()
    for _, target in ipairs(targets or {}) do
      selected[#selected + 1] = target
    end
  end

  local players = {}
  local positioned = 0
  local max_count = math.min(limit, #(selected or {}))
  local native_available = type(BMFSocketPlayerLocation) == "function"
  local allow_lua_pawn_read =
    opts.luaPawnRead == true or
    opts.luaVectors == true or
    option_boolean(opts, "luapawnread", false) or
    option_boolean(opts, "luavectors", false)

  for index = 1, max_count do
    local target = selected[index]
    local identity, identity_source = player_position_identity_from_live_target(known_players, target, #(targets or {}))
    local pawn_candidates = {}
    local position = nil
    local source = ""
    local attempts = {}
    local pawn_record = nil
    local native_detail = nil

    position, source, native_detail = player_position_native_from_controller(
      target and target.controller or nil,
      query ~= "" and query or target and (target.name or target.userName or target.displayName or target.playerId) or ""
    )
    attempts[#attempts + 1] = native_detail or {
      source = "native.BMFSocketPlayerLocation",
      ok = false,
      detail = "native detail missing",
    }

    if position == nil and allow_lua_pawn_read then
      pawn_candidates = player_position_candidate_pawns_from_controller(target and target.controller or nil)
      for _, candidate in ipairs(pawn_candidates) do
        local lua_position, lua_source, lua_attempts = player_position_read_from_pawn(candidate.object, opts)
        for _, attempt in ipairs(lua_attempts or {}) do
          attempts[#attempts + 1] = attempt
        end
        if lua_position ~= nil then
          position = lua_position
          source = lua_source
          pawn_record = candidate
          break
        end
      end
    end

    if position ~= nil then
      positioned = positioned + 1
      player_position_controller_cache_upsert(identity, target, native_detail)
    end

    local player_name = first_string(
      identity and identity.username,
      identity and identity.playerName,
      identity and identity.displayName,
      target and target.name,
      target and target.userName,
      target and target.displayName
    ) or ""

    players[#players + 1] = {
      player = {
        id = tostring(identity and (identity.uuid or identity.id) or target and target.playerId or ""),
        uuid = tostring(identity and (identity.uuid or identity.id) or target and target.playerId or ""),
        name = tostring(player_name or ""),
        username = tostring(identity and identity.username or target and target.userName or player_name or ""),
        displayName = tostring(identity and identity.displayName or target and target.displayName or player_name or ""),
        identitySource = identity_source,
      },
      ok = position ~= nil,
      position = position,
      source = source,
      playerState = tostring(target and target.playerStatePath or ""),
      playerStateName = tostring(target and target.playerStatePath or ""),
      controllerAddress = native_detail and native_detail.controllerAddress or "",
      controller_address = native_detail and native_detail.controller_address or "",
      controller = native_detail and native_detail.address or live_chat_object_key(target and target.controller or nil, ""),
      controllerName = native_detail and native_detail.controller or live_chat_object_label(target and target.controller or nil, ""),
      controllerFullName = native_detail and native_detail.controllerFullName or live_chat_object_full_name(target and target.controller or nil),
      pawnAddress = native_detail and native_detail.pawnAddress or "",
      pawn_address = native_detail and native_detail.pawn_address or "",
      pawn = native_detail and native_detail.pawn or pawn_record and pawn_record.address or "",
      pawnName = native_detail and native_detail.pawn or pawn_record and pawn_record.objectName or "",
      pawnFullName = native_detail and native_detail.pawnFullName or "",
      rootComponentAddress = native_detail and native_detail.rootComponentAddress or "",
      root_component_address = native_detail and native_detail.root_component_address or "",
      rootComponent = native_detail and native_detail.rootComponent or "",
      rootComponentFullName = native_detail and native_detail.rootComponentFullName or "",
      pawnSource = pawn_record and pawn_record.source or "",
      pawnCandidates = pawn_candidates,
      attempts = opts.includeMissing == true and attempts or nil,
      native = native_detail,
    }
  end

  local lines = {
    "source=bmf.players.positions",
    "query=" .. query,
    "source_mode=native-controller",
    "player_array_count=0",
    "live_controllers=" .. tostring(#(targets or {})),
    "players=" .. tostring(#(selected or {})),
    "returned=" .. tostring(#players),
    "positioned=" .. tostring(positioned),
    "known_players=" .. tostring(#known_players),
    "native_available=" .. tostring(native_available),
  }
  if query ~= "" and #players == 0 then
    lines[#lines + 1] = "code=PLAYER_NOT_FOUND"
  end
  for index, player in ipairs(players) do
    local pos = player.position or {}
    lines[#lines + 1] =
      "position_" .. tostring(index) .. "=" ..
      tostring(player.player.name or "") ..
      "|id=" .. tostring(player.player.id or "") ..
      "|ok=" .. tostring(player.ok == true) ..
      "|x=" .. tostring(pos.x or "") ..
      "|y=" .. tostring(pos.y or "") ..
      "|z=" .. tostring(pos.z or "") ..
      "|source=" .. tostring(player.source or "") ..
      "|pawn=" .. tostring(player.pawn or "") ..
      "|pawn_source=" .. tostring(player.pawnSource or "")
  end

  local data = {
    source = "bmf.players.positions",
    checkedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    query = query,
    sourceMode = "native-controller",
    playerArrayCount = 0,
    liveControllerCount = #(targets or {}),
    nativeAvailable = native_available,
    players = players,
    counts = {
      observed = #(selected or {}),
      returned = #players,
      positioned = positioned,
      knownPlayers = #known_players,
    },
    lines = lines,
  }
  lines[#lines + 1] = "positions_json=" .. json_encode(data)
  return data
end

BMF.players.positions = function(options)
  local opts = type(options) == "table" and options or {}
  local query = trim_string(opts.player or opts.query or opts.name or "")
  local limit = tonumber(opts.limit) or 32
  if limit < 1 then
    limit = 1
  elseif limit > 128 then
    limit = 128
  end

  local allow_live_pawn_read =
    opts.unsafe == true or
    opts.allowLivePawnRead == true or
    option_boolean(opts, "unsafe", false) or
    option_boolean(opts, "allowlivepawnread", false)

  local allow_native_cache =
    opts.nativeController ~= false and
    opts.nativeCache ~= false and
    os.getenv("BMF_PLAYERS_POSITIONS_NATIVE_CACHE") ~= "0"
  if allow_native_cache then
    local native_cache_data = player_position_known_records_snapshot(opts, query, limit)
    local native_cache_counts = native_cache_data.counts or {}
    if tonumber(native_cache_counts.positioned) and tonumber(native_cache_counts.positioned) > 0 then
      return result(true, "OK", "Native cached player positions collected", native_cache_data)
    end

    if not allow_live_pawn_read and opts.liveController ~= true and os.getenv("BMF_PLAYERS_POSITIONS_LIVE_CONTROLLER") ~= "1" then
      native_cache_data.lines[#native_cache_data.lines + 1] = "code=POSITION_UNAVAILABLE"
      native_cache_data.lines[#native_cache_data.lines + 1] =
        "reason=native cached player position was unavailable; live Lua controller reads require livecontroller=1"
      return result(false, "POSITION_UNAVAILABLE", "Native cached player position was unavailable", native_cache_data)
    end
  end

  local allow_live_controller_read =
    opts.liveController == true or
    option_boolean(opts, "livecontroller", false) or
    os.getenv("BMF_PLAYERS_POSITIONS_LIVE_CONTROLLER") == "1"
  if allow_live_controller_read then
    local live_controller_data = player_position_live_controller_snapshot(opts, query, limit)
    local live_controller_counts = live_controller_data.counts or {}
    if tonumber(live_controller_counts.positioned) and tonumber(live_controller_counts.positioned) > 0 then
      return result(true, "OK", "Live controller player positions collected", live_controller_data)
    end

    if player_position_native_scan_enabled(opts) then
      local native_scan_data = player_position_native_scan_snapshot(opts, query, limit)
      local native_scan_counts = native_scan_data.counts or {}
      if tonumber(native_scan_counts.positioned) and tonumber(native_scan_counts.positioned) > 0 then
        return result(true, "OK", "Native scanned player positions collected", native_scan_data)
      end
      live_controller_data.nativeScan = native_scan_data
      for _, line in ipairs(native_scan_data.lines or {}) do
        live_controller_data.lines[#live_controller_data.lines + 1] = "native_scan_" .. tostring(line)
      end
    end

    if not allow_live_pawn_read then
      live_controller_data.lines[#live_controller_data.lines + 1] = "code=POSITION_UNAVAILABLE"
      live_controller_data.lines[#live_controller_data.lines + 1] =
        "reason=live controller pawn position was unavailable; broad PlayerState reads require unsafe=1"
      return result(false, "POSITION_UNAVAILABLE", "Live controller pawn position was unavailable", live_controller_data)
    end
  end

  if not allow_live_pawn_read then
    local lines = {
      "source=bmf.players.positions",
      "query=" .. query,
      "source_mode=disabled-safe-default",
      "player_array_count=0",
      "players=0",
      "returned=0",
      "positioned=0",
      "known_players=0",
      "code=POSITION_UNAVAILABLE",
      "reason=live pawn position reads require native support or unsafe=1",
    }
    local data = {
      source = "bmf.players.positions",
      checkedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
      query = query,
      sourceMode = "disabled-safe-default",
      playerArrayCount = 0,
      players = {},
      counts = {
        observed = 0,
        returned = 0,
        positioned = 0,
        knownPlayers = 0,
      },
      lines = lines,
    }
    lines[#lines + 1] = "positions_json=" .. json_encode(data)
    return result(false, "POSITION_UNAVAILABLE", "Live pawn position reads require native support or unsafe=1", data)
  end

  local player_items = {}
  local meta = {
    source = "",
    playerArrayCount = 0,
    errors = {},
  }
  local resolve_candidates = {}
  if query ~= "" then
    local item, candidates, item_meta = minigame_live_resolve_player_state_for_assignment(query)
    resolve_candidates = candidates or {}
    meta = item_meta or meta
    if item and minigame_object_valid(item.object) then
      player_items[#player_items + 1] = item
    end
  else
    player_items, meta = minigame_live_player_states({
      fallbackFindAll = opts.fallbackFindAll ~= false,
    })
  end

  local listed = BMF.players.list()
  local known_players = listed.data and listed.data.players or {}
  local players = {}
  local positioned = 0

  for _, item in ipairs(player_items or {}) do
    if #players >= limit then
      break
    end
    local player_state = item.object
    local property_values = minigame_live_collect_property_values(
      player_state,
      {
        "UserName",
        "PlayerNamePrivate",
        "PlayerName",
        "DisplayName",
      },
      0,
      false
    )
    local player_name = minigame_live_first_property_text(property_values, {
      "UserName",
      "PlayerNamePrivate",
      "PlayerName",
      "DisplayName",
    })
    local assignment_candidates = minigame_live_player_assignment_candidates(player_state)
    local identity, identity_source = player_position_identity_from_cache(known_players, player_name, assignment_candidates)
    local pawn_candidates, controller = player_position_candidate_pawns(player_state)
    local position = nil
    local source = ""
    local attempts = {}
    local pawn_record = nil

    for _, candidate in ipairs(pawn_candidates) do
      position, source, attempts = player_position_read_from_pawn(candidate.object, opts)
      if position ~= nil then
        pawn_record = candidate
        break
      end
    end

    if position ~= nil then
      positioned = positioned + 1
    end

    local record = {
      player = {
        id = tostring(identity and (identity.uuid or identity.id) or ""),
        uuid = tostring(identity and (identity.uuid or identity.id) or ""),
        name = tostring(player_name or ""),
        username = tostring(identity and identity.username or player_name or ""),
        displayName = tostring(identity and identity.displayName or player_name or ""),
        identitySource = identity_source,
      },
      ok = position ~= nil,
      position = position,
      source = source,
      playerState = minigame_object_address(player_state),
      playerStateName = minigame_object_name(player_state),
      controller = minigame_object_address(controller),
      controllerName = minigame_object_name(controller),
      pawn = pawn_record and pawn_record.address or "",
      pawnName = pawn_record and pawn_record.objectName or "",
      pawnSource = pawn_record and pawn_record.source or "",
      pawnCandidates = pawn_candidates,
      attempts = opts.includeMissing == true and attempts or nil,
    }
    players[#players + 1] = record
  end

  local lines = {
    "source=bmf.players.positions",
    "query=" .. query,
    "source_mode=" .. tostring(meta and meta.source or ""),
    "player_array_count=" .. tostring(meta and meta.playerArrayCount or 0),
    "players=" .. tostring(#(player_items or {})),
    "returned=" .. tostring(#players),
    "positioned=" .. tostring(positioned),
    "known_players=" .. tostring(#known_players),
  }

  if query ~= "" and #players == 0 then
    lines[#lines + 1] = "code=PLAYER_NOT_FOUND"
    lines[#lines + 1] = "candidates=" .. table.concat(resolve_candidates or {}, "|")
  end
  for index, error_text in ipairs((meta and meta.errors) or {}) do
    lines[#lines + 1] = "error_" .. tostring(index) .. "=" .. tostring(error_text)
  end
  for index, player in ipairs(players) do
    local pos = player.position or {}
    lines[#lines + 1] =
      "position_" .. tostring(index) .. "=" ..
      tostring(player.player.name or "") ..
      "|id=" .. tostring(player.player.id or "") ..
      "|ok=" .. tostring(player.ok == true) ..
      "|x=" .. tostring(pos.x or "") ..
      "|y=" .. tostring(pos.y or "") ..
      "|z=" .. tostring(pos.z or "") ..
      "|source=" .. tostring(player.source or "") ..
      "|pawn=" .. tostring(player.pawn or "") ..
      "|pawn_source=" .. tostring(player.pawnSource or "")
  end

  local data = {
    source = "bmf.players.positions",
    checkedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    query = query,
    sourceMode = tostring(meta and meta.source or ""),
    playerArrayCount = meta and meta.playerArrayCount or 0,
    players = players,
    counts = {
      observed = #(player_items or {}),
      returned = #players,
      positioned = positioned,
      knownPlayers = #known_players,
    },
    lines = lines,
  }
  lines[#lines + 1] = "positions_json=" .. json_encode(data)

  local ok = #players > 0 and (query == "" or positioned > 0)
  return result(ok, ok and "OK" or "POSITION_UNAVAILABLE", ok and "Live player positions collected" or "Live player positions were unavailable", data)
end

function player_position_snapshot_enabled()
  return BMF_env_bool("BMF_PLAYERS_POSITIONS_SNAPSHOT_ENABLED", false)
end

function player_position_snapshot_path()
  local configured = trim_string(BMF_env_string("BMF_PLAYERS_POSITIONS_SNAPSHOT_PATH"))
  if configured ~= "" then
    return configured
  end
  return PLAYER_POSITIONS_SNAPSHOT_PATH
end

function player_position_snapshot_interval_ms()
  local configured = BMF_env_number("BMF_PLAYERS_POSITIONS_SNAPSHOT_MS", 2000, 250)
  return math.max(1000, math.min(60000, math.floor(tonumber(configured) or 2000)))
end

function player_position_snapshot_limit()
  local configured = BMF_env_number("BMF_PLAYERS_POSITIONS_SNAPSHOT_LIMIT", 64, 1)
  return math.max(1, math.min(128, math.floor(tonumber(configured) or 64)))
end

function write_player_position_snapshot_file(path, value)
  local suffix = tostring(os.time()) .. "." .. tostring(math.random(100000, 999999))
  local temp_path = tostring(path or "") .. ".tmp." .. suffix
  if not write_file(temp_path, value) then
    return false
  end

  os.remove(path)
  if os.rename(temp_path, path) then
    return true
  end

  os.remove(temp_path)
  return write_file(path, value)
end

function player_position_snapshot_record_has_identity(record)
  local player = type(record) == "table" and type(record.player) == "table" and record.player or {}
  for _, value in ipairs({ player.id, player.uuid, player.name, player.username, player.displayName }) do
    if trim_string(value or "") ~= "" then
      return true
    end
  end
  return false
end

function player_position_snapshot_record_has_position(record)
  if type(record) ~= "table" or record.ok ~= true or type(record.position) ~= "table" then
    return false
  end
  return finite_number(record.position.x, nil) ~= nil
    and finite_number(record.position.y, nil) ~= nil
    and finite_number(record.position.z, nil) ~= nil
end

function sanitize_player_position_snapshot(data)
  data = type(data) == "table" and data or {}
  local source_players = type(data.players) == "table" and data.players or {}
  local usable = {}
  local dropped = 0
  for _, record in ipairs(source_players) do
    if player_position_snapshot_record_has_position(record) and player_position_snapshot_record_has_identity(record) then
      usable[#usable + 1] = record
    else
      dropped = dropped + 1
    end
  end

  data.players = usable
  data.counts = type(data.counts) == "table" and data.counts or {}
  data.counts.returned = #usable
  data.counts.positioned = #usable
  data.counts.droppedUnusable = dropped
  if dropped > 0 then
    data.lines = type(data.lines) == "table" and data.lines or {}
    data.lines[#data.lines + 1] = "dropped_unusable=" .. tostring(dropped)
    data.lines[#data.lines + 1] = "usable_position_records=" .. tostring(#usable)
  end
  return data, #usable, dropped
end

function write_player_position_snapshot(reason)
  local snapshot_state = state.player_position_snapshot
  snapshot_state.path = player_position_snapshot_path()
  snapshot_state.interval_ms = player_position_snapshot_interval_ms()
  snapshot_state.limit = player_position_snapshot_limit()

  local started_clock = os.clock()
  local ok, snapshot_result = pcall(BMF.players.positions, {
    limit = snapshot_state.limit,
    nativeCache = false,
    liveController = true,
    allowLivePawnRead = false,
    unsafe = false,
    includeMissing = false,
    fallbackFindAll = false,
  })
  local duration_ms = BMF_telemetry_duration_ms(started_clock)
  local data = {}
  local result_ok = false
  local result_code = "ERROR"
  local result_message = ""
  if ok and type(snapshot_result) == "table" then
    result_ok = snapshot_result.ok == true
    result_code = tostring(snapshot_result.code or (result_ok and "OK" or "ERROR"))
    result_message = tostring(snapshot_result.message or "")
    if type(snapshot_result.data) == "table" then
      data = snapshot_result.data
    end
  else
    result_message = tostring(snapshot_result or "snapshot call failed")
  end

  local usable_count = 0
  data, usable_count = sanitize_player_position_snapshot(data)
  if usable_count <= 0 then
    if result_code == "OK" then
      result_code = "POSITION_UNAVAILABLE"
    end
    result_ok = false
    if result_message == "" or result_message == "Live controller player positions collected" then
      result_message = "No usable player identity and position records are available"
    end
  end

  local generated_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  if type(data.lines) == "table" then
    local compact_lines = {}
    for _, line in ipairs(data.lines) do
      if not tostring(line or ""):match("^positions_json=") then
        compact_lines[#compact_lines + 1] = line
      end
    end
    data.lines = compact_lines
  end
  data.snapshot = {
    source = "bmf.players.positions.snapshot",
    reason = tostring(reason or ""),
    generatedAt = generated_at,
    intervalMs = snapshot_state.interval_ms,
    limit = snapshot_state.limit,
    ok = result_ok,
    code = result_code,
    message = result_message,
    durationMs = duration_ms,
  }

  local counts = type(data.counts) == "table" and data.counts or {}
  local positioned = tonumber(counts.positioned) or 0
  snapshot_state.last_duration_ms = duration_ms
  snapshot_state.last_positioned = positioned
  snapshot_state.last_ok = result_ok
  snapshot_state.last_code = result_code

  local written = false
  if snapshot_state.path ~= "" then
    written = write_player_position_snapshot_file(snapshot_state.path, json_encode(data) .. "\n")
  end

  if written then
    snapshot_state.writes = (tonumber(snapshot_state.writes) or 0) + 1
    snapshot_state.last_write_at = generated_at
    snapshot_state.last_error = ""
  else
    snapshot_state.failures = (tonumber(snapshot_state.failures) or 0) + 1
    snapshot_state.last_error = result_message ~= "" and result_message or "snapshot write failed"
  end

  BMF_telemetry_record_scheduler("snapshot", "player_positions", duration_ms, written)
  return written
end

function ensure_player_position_snapshot_worker()
  if state.player_position_snapshot_timer_id ~= nil then
    return
  end

  state.player_position_snapshot.enabled = player_position_snapshot_enabled()
  state.player_position_snapshot.path = player_position_snapshot_path()
  state.player_position_snapshot.interval_ms = player_position_snapshot_interval_ms()
  state.player_position_snapshot.limit = player_position_snapshot_limit()
  if not state.player_position_snapshot.enabled then
    return
  end

  local timer_id = BMF.timers.every(state.player_position_snapshot.interval_ms, function(id)
    if not player_position_snapshot_enabled() then
      state.player_position_snapshot.enabled = false
      state.player_position_snapshot_timer_id = nil
      BMF.timers.cancel(id)
      write_status()
      return
    end
    write_player_position_snapshot("timer")
  end)

  if timer_id then
    state.player_position_snapshot_timer_id = timer_id
    log(
      "info",
      "player position snapshot worker started path="
        .. tostring(state.player_position_snapshot.path)
        .. " interval_ms="
        .. tostring(state.player_position_snapshot.interval_ms)
    )
    write_player_position_snapshot("start")
    write_status()
  else
    state.player_position_snapshot.enabled = false
    state.player_position_snapshot.failures = (tonumber(state.player_position_snapshot.failures) or 0) + 1
    state.player_position_snapshot.last_error = "timer scheduler unavailable"
    log("warn", "player position snapshot worker could not start: timer scheduler unavailable")
  end
end

BMF.players.normalize = function(record)
  if type(record) ~= "table" then
    return result(false, "INVALID_PLAYER", "player record table is required")
  end

  local uuid = first_string(record.uuid, record.id, record.playerId, record.playerID)
  if not is_uuid(uuid) then
    return result(false, "INVALID_PLAYER_ID", "player UUID is missing or invalid")
  end

  local username = first_string(record.username, record.playerName, record.originalName, record.name)
  local display_name = first_string(record.displayName, record.display_name, record.name, username)
  local original_name = first_string(record.originalName, record.playerName, username)

  local roles = {}
  if type(record.roles) == "table" then
    for _, role in ipairs(record.roles) do
      if type(role) == "string" and trim_string(role) ~= "" then
        roles[#roles + 1] = role
      end
    end
  end

  local normalized = {
    id = uuid,
    uuid = uuid,
    username = username or "",
    playerName = first_string(record.playerName, username) or "",
    displayName = display_name or "",
    originalName = original_name or "",
    roles = roles,
    permissions = BMF.permissions.toMap(record.permissions),
    controllerAvailable = record.controllerAvailable and true or false,
  }

  if type(record.pingMs) == "number" then
    normalized.pingMs = record.pingMs
  end
  if type(record.onlineTimeMs) == "number" then
    normalized.onlineTimeMs = record.onlineTimeMs
  end
  if type(record.address) == "string" then
    normalized.address = record.address
  end
  if type(record.health) == "number" then
    normalized.health = record.health
  end
  if type(record.playerStatePath) == "string" then
    normalized.playerStatePath = record.playerStatePath
  end
  if type(record.controllerPath) == "string" then
    normalized.controllerPath = record.controllerPath
  end
  if type(record.connectionGeneration) == "number" then
    normalized.connectionGeneration = math.max(0, math.floor(record.connectionGeneration))
  end
  if type(record.snapshotGeneration) == "number" then
    normalized.snapshotGeneration = math.max(0, math.floor(record.snapshotGeneration))
  end
  if type(record.position) == "table" then
    normalized.position = {
      x = finite_number(record.position.x or record.position.X, 0),
      y = finite_number(record.position.y or record.position.Y, 0),
      z = finite_number(record.position.z or record.position.Z, 0),
    }
  end

  return result(true, "OK", "Player record normalized", { player = normalized })
end

BMF.players.normalizeList = function(records)
  if type(records) ~= "table" then
    return result(false, "INVALID_PLAYERS", "players array is required")
  end

  local players = {}
  local invalid = {}
  for index, record in ipairs(records) do
    local normalized = BMF.players.normalize(external_player_record(record))
    if normalized.ok then
      players[#players + 1] = normalized.data.player
    else
      invalid[#invalid + 1] = {
        index = index,
        code = normalized.code,
        message = normalized.message,
      }
    end
  end

  return result(true, "OK", "Player list normalized", {
    players = players,
    invalid = invalid,
  })
end

BMF.players.sync = function(records, options)
  if type(records) ~= "table" then
    return result(false, "INVALID_PLAYERS", "players array is required", {
      cachePath = PLAYER_CACHE_PATH,
    })
  end

  options = type(options) == "table" and options or {}
  local ingestion_started_clock = os.clock()
  local normalized = BMF.players.normalizeList(records)
  if not normalized.ok then
    return normalized
  end

  local players = normalized.data.players or {}
  local invalid = normalized.data.invalid or {}
  local cache = {
    schemaVersion = 1,
    adapter = tostring(options.adapter or "external-cache"),
    source = tostring(options.source or "external"),
    updatedAt = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    correlationId = trim_string(tostring(options.correlationId or options.correlation or "")),
    players = players,
    invalid = invalid,
  }

  local persist = option_boolean(options, "persist", true)
  local next_generation = (tonumber(state.player_registry.generation) or 0) + 1
  cache.generation = next_generation
  cache.snapshotGeneration = next_generation
  local synced = false
  local persisted = false
  if persist then
    synced = write_player_cache(cache)
    persisted = synced
  else
    synced = publish_player_cache(cache) ~= nil
  end
  if synced then
    state.player_registry.memory_syncs = (tonumber(state.player_registry.memory_syncs) or 0) + 1
    if persisted then
      state.player_registry.persisted_syncs = (tonumber(state.player_registry.persisted_syncs) or 0) + 1
    end
  end
  BMF_join_correlation_phase(
    cache.correlationId,
    "bmf_snapshot_ingestion",
    ingestion_started_clock,
    synced and "ok" or "error",
    { players = #players, invalid = #invalid })
  local response = result(synced, synced and (#invalid > 0 and "PARTIAL" or "OK") or "CACHE_WRITE_FAILED", synced and "Player registry snapshot synced" or "Player registry snapshot could not be published", {
    players = players,
    invalid = invalid,
    playerCount = #players,
    knownPlayerCount = #players,
    invalidCount = #invalid,
    adapter = cache.adapter,
    source = cache.source,
    updatedAt = cache.updatedAt,
    cachePath = PLAYER_CACHE_PATH,
    persisted = persisted,
    cacheGeneration = tonumber(state.player_registry.generation) or 0,
  })
  audit_record("players.sync", {
    playerCount = #players,
    invalidCount = #invalid,
    adapter = cache.adapter,
    source = cache.source,
    cachePath = PLAYER_CACHE_PATH,
    persisted = persisted,
    cacheGeneration = tonumber(state.player_registry.generation) or 0,
  }, {
    source = "framework",
    severity = response.ok and "info" or "warn",
    ok = response.ok,
    code = response.code,
  })
  return response
end

function player_query_text(query)
  if type(query) == "table" then
    return first_string(
      query.uuid,
      query.id,
      query.playerId,
      query.playerID,
      query.username,
      query.displayName,
      query.playerName,
      query.originalName,
      query.playerStatePath,
      query.controllerPath,
      query.name,
      query.query
    ) or ""
  end
  return tostring(query or "")
end

function player_matches_query(player, needle)
  local lowered = tostring(needle or ""):lower()
  if lowered == "" then
    return false, ""
  end

  local exact_fields = {
    "uuid",
    "id",
    "username",
    "playerName",
    "displayName",
    "originalName",
    "playerStatePath",
    "controllerPath",
  }
  for _, field in ipairs(exact_fields) do
    local value = tostring(player[field] or "")
    if value ~= "" and value:lower() == lowered then
      return true, field
    end
  end

  if #lowered >= 2 then
    for _, field in ipairs({ "username", "playerName", "displayName", "originalName" }) do
      local value = tostring(player[field] or "")
      if value ~= "" and value:lower():find(lowered, 1, true) then
        return true, "partial:" .. field
      end
    end
  end

  return false, ""
end

BMF.players.find = function(records, query)
  local source = "provided"
  local raw_records = records
  local raw_query = query
  local adapter = "provided"

  if query == nil then
    source = "current"
    raw_query = records
    local listed = BMF.players.list()
    if not listed.ok then
      return listed
    end
    raw_records = (listed.data and listed.data.players) or {}
    adapter = (listed.data and listed.data.adapter) or "unknown"
  end

  local normalized = BMF.players.normalizeList(raw_records)
  if not normalized.ok then
    return normalized
  end

  local needle = trim_string(player_query_text(raw_query))
  if needle == "" then
    return result(false, "PLAYER_REQUIRED", "player query is required", {
      source = source,
      adapter = adapter,
      players = normalized.data.players,
      invalid = normalized.data.invalid,
    })
  end

  for _, player in ipairs(normalized.data.players) do
    local matched, match_field = player_matches_query(player, needle)
    if matched then
      return result(true, "OK", "Player found", {
        player = player,
        query = needle,
        match = match_field,
        source = source,
        adapter = adapter,
      })
    end
  end

  return result(false, "PLAYER_NOT_FOUND", "No normalized player matched query", {
    query = needle,
    source = source,
    adapter = adapter,
    players = normalized.data.players,
    invalid = normalized.data.invalid,
  })
end

BMF.players.resolve = function(player)
  if type(player) == "table" then
    local direct = BMF.players.normalize(player)
    if direct.ok then
      direct.data.source = "direct"
      direct.data.adapter = "direct"
      return direct
    end
  end
  return BMF.players.find(player)
end

BMF.players.getName = function(player)
  local resolved = BMF.players.resolve(player)
  if not resolved.ok then
    return resolved
  end
  local record = resolved.data.player
  return result(true, "OK", "Player names resolved", {
    player = record,
    id = record.id,
    uuid = record.uuid,
    username = record.username,
    playerName = record.playerName,
    displayName = record.displayName,
    originalName = record.originalName,
    source = resolved.data.source,
    adapter = resolved.data.adapter,
  })
end

local PLAYER_LEADERBOARD_SET_FUNCTION_CANDIDATES = {
  "Function /Script/Brickadia.BRPlayerState:SetLeaderboardValue",
  "Function /Script/Brickadia.BRPlayerState.SetLeaderboardValue",
  "/Script/Brickadia.BRPlayerState:SetLeaderboardValue",
  "/Script/Brickadia.BRPlayerState.SetLeaderboardValue",
  "SetLeaderboardValue",
}

local function player_leaderboard_quote_arg(value)
  local text = tostring(value or "")
  if text:match("^[A-Za-z0-9_.:@%-]+$") then
    return text
  end
  return '"' .. text:gsub("\\", "\\\\"):gsub('"', '\\"') .. '"'
end

local function player_leaderboard_make_fname(key)
  if type(FName) ~= "function" then
    return nil, "FName helper is unavailable"
  end
  local mode = EFindName and EFindName.FNAME_Add or 1
  local ok, value = pcall(FName, tostring(key or ""), mode)
  if ok and value ~= nil then
    return value, ""
  end
  return nil, tostring(value or "FName construction failed")
end

local function player_leaderboard_find_set_function()
  if type(StaticFindObject) ~= "function" then
    return nil, "", { "StaticFindObject unavailable" }
  end
  local errors = {}
  for _, candidate in ipairs(PLAYER_LEADERBOARD_SET_FUNCTION_CANDIDATES) do
    local ok, object = pcall(StaticFindObject, candidate)
    if ok and minigame_object_valid(object) then
      return object, candidate, errors
    end
    errors[#errors + 1] = tostring(candidate) .. "=" .. tostring(ok and object or object)
  end
  return nil, "", errors
end

local function player_leaderboard_try_call_by_name(player_state, key, value)
  local attempts = {}
  if type(OmeggaCallFunctionByNameWithArguments) ~= "function" then
    return false, attempts, "OmeggaCallFunctionByNameWithArguments unavailable"
  end

  local commands = {
    "SetLeaderboardValue " .. player_leaderboard_quote_arg(key) .. " " .. tostring(value),
    "SetLeaderboardValue " .. player_leaderboard_quote_arg(key) .. " " .. player_leaderboard_quote_arg(value),
    "SetLeaderboardValue " .. tostring(key) .. " " .. tostring(value),
  }
  for index, command in ipairs(commands) do
    local ok, call_result, detail = pcall(
      OmeggaCallFunctionByNameWithArguments,
      player_state,
      command,
      player_state
    )
    attempts[#attempts + 1] = {
      method = "callbyname",
      index = index,
      command = command,
      ok = ok,
      result = call_result,
      detail = detail,
    }
    if ok and call_result ~= false then
      return true, attempts, tostring(detail or "")
    end
  end

  return false, attempts, "all CallFunctionByNameWithArguments attempts returned false"
end

local function player_leaderboard_try_direct_call(player_state, key, value)
  local attempts = {}
  if type(player_state) ~= "userdata" and type(player_state) ~= "table" then
    return false, attempts, "player state is not callable"
  end
  if type(player_state.CallFunction) ~= "function" then
    return false, attempts, "player state CallFunction helper is unavailable"
  end

  local function_object, function_source, function_errors = player_leaderboard_find_set_function()
  if not function_object then
    return false, attempts, table.concat(function_errors or {}, "|")
  end

  local fname_value, fname_error = player_leaderboard_make_fname(key)
  local key_variants = {}
  if fname_value ~= nil then
    key_variants[#key_variants + 1] = {
      label = "fname",
      value = fname_value,
    }
  else
    attempts[#attempts + 1] = {
      method = "direct",
      command = "FName(" .. tostring(key or "") .. ")",
      ok = false,
      result = false,
      detail = fname_error,
    }
  end
  key_variants[#key_variants + 1] = {
    label = "string",
    value = tostring(key or ""),
  }

  for index, key_variant in ipairs(key_variants) do
    local ok, call_result = pcall(function()
      return player_state:CallFunction(function_object, key_variant.value, value)
    end)
    attempts[#attempts + 1] = {
      method = "direct",
      index = index,
      command = "CallFunction(" .. tostring(function_source or "") .. "," .. tostring(key_variant.label) .. "," .. tostring(value) .. ")",
      ok = ok,
      result = call_result,
      detail = "",
    }
    if ok and call_result ~= false then
      return true, attempts, tostring(function_source or "")
    end
  end

  return false, attempts, "all direct CallFunction attempts returned false"
end

BMF.players.setLeaderboardValue = function(player, key, value, options)
  local started_clock = os.clock()
  local opts = type(options) == "table" and options or {}
  local query = trim_string(player_query_text(player))
  local leaderboard_key = trim_string(key or "")
  local numeric_value, value_error = normalize_integer(value, "leaderboard value")
  local dry_run = opts.dryRun == true
  local attempts = {}

  if query == "" then
    return result(false, "PLAYER_REQUIRED", "player query is required", {
      lines = {
        "code=PLAYER_REQUIRED",
        "source=bmf.players.setLeaderboardValue",
      },
    })
  end
  if leaderboard_key == "" then
    return result(false, "LEADERBOARD_KEY_REQUIRED", "leaderboard key is required", {
      player = query,
      lines = {
        "code=LEADERBOARD_KEY_REQUIRED",
        "source=bmf.players.setLeaderboardValue",
        "player=" .. query,
      },
    })
  end
  if numeric_value == nil then
    return result(false, "INVALID_LEADERBOARD_VALUE", tostring(value_error or "leaderboard value must be an integer"), {
      player = query,
      key = leaderboard_key,
      value = tostring(value or ""),
      lines = {
        "code=INVALID_LEADERBOARD_VALUE",
        "source=bmf.players.setLeaderboardValue",
        "player=" .. query,
        "key=" .. leaderboard_key,
        "value=" .. tostring(value or ""),
        "error=" .. tostring(value_error or ""),
      },
    })
  end

  local resolve_started_clock = os.clock()
  local player_item, candidates, meta = minigame_live_resolve_player_state_for_assignment(query)
  local resolve_duration_ms = math.floor(((os.clock() - resolve_started_clock) * 1000) + 0.5)
  if not player_item or not minigame_object_valid(player_item.object) then
    return result(false, "PLAYER_STATE_NOT_FOUND", "live player state was not found", {
      player = query,
      key = leaderboard_key,
      value = numeric_value,
      candidates = candidates or {},
      sourceMode = meta and meta.source or "",
      lines = {
        "code=PLAYER_STATE_NOT_FOUND",
        "source=bmf.players.setLeaderboardValue",
        "player=" .. query,
        "key=" .. leaderboard_key,
        "value=" .. tostring(numeric_value),
        "source_mode=" .. tostring(meta and meta.source or ""),
        "fast_path=" .. tostring(meta and meta.fastPath or ""),
        "resolve_ms=" .. tostring(resolve_duration_ms),
        "candidates=" .. table.concat(candidates or {}, "|"),
      },
    })
  end

  local player_state = player_item.object
  local lines = {
    "code=OK",
    "source=bmf.players.setLeaderboardValue",
    "player=" .. query,
    "key=" .. leaderboard_key,
    "value=" .. tostring(numeric_value),
    "dry_run=" .. tostring(dry_run),
    "source_mode=" .. tostring(meta and meta.source or ""),
    "fast_path=" .. tostring(meta and meta.fastPath or ""),
    "resolve_ms=" .. tostring(resolve_duration_ms),
    "player_state=" .. minigame_object_address(player_state),
    "player_state_name=" .. minigame_object_name(player_state),
    "player_state_full=" .. minigame_object_full_name(player_state),
  }

  if dry_run then
    lines[#lines + 1] = "ok=true"
    lines[#lines + 1] = "method=dry-run"
    lines[#lines + 1] = "total_ms=" .. tostring(math.floor(((os.clock() - started_clock) * 1000) + 0.5))
    return result(true, "OK", "Leaderboard write dry run completed", {
      player = query,
      key = leaderboard_key,
      value = numeric_value,
      playerState = minigame_object_address(player_state),
      lines = lines,
    })
  end

  local call_by_name_ok, call_by_name_attempts, call_by_name_detail =
    player_leaderboard_try_call_by_name(player_state, leaderboard_key, numeric_value)
  for _, attempt in ipairs(call_by_name_attempts or {}) do
    attempts[#attempts + 1] = attempt
  end
  local method = "callbyname"
  local detail = call_by_name_detail
  local write_ok = call_by_name_ok

  if not write_ok then
    local direct_ok, direct_attempts, direct_detail =
      player_leaderboard_try_direct_call(player_state, leaderboard_key, numeric_value)
    for _, attempt in ipairs(direct_attempts or {}) do
      attempts[#attempts + 1] = attempt
    end
    method = "direct"
    detail = direct_detail
    write_ok = direct_ok
  end

  for index, attempt in ipairs(attempts) do
    lines[#lines + 1] =
      "attempt_" .. tostring(index) ..
      "=method=" .. tostring(attempt.method or "") ..
      "|index=" .. tostring(attempt.index or "") ..
      "|ok=" .. tostring(attempt.ok) ..
      "|result=" .. tostring(attempt.result) ..
      "|detail=" .. tostring(attempt.detail or "") ..
      "|command=" .. tostring(attempt.command or "")
  end
  lines[#lines + 1] = "ok=" .. tostring(write_ok == true)
  lines[#lines + 1] = "method=" .. tostring(method or "")
  lines[#lines + 1] = "detail=" .. tostring(detail or "")
  lines[#lines + 1] = "total_ms=" .. tostring(math.floor(((os.clock() - started_clock) * 1000) + 0.5))

  audit_record("players.set_leaderboard", {
    player = query,
    key = leaderboard_key,
    value = numeric_value,
    method = method,
    playerState = minigame_object_address(player_state),
  }, {
    source = "framework",
    severity = write_ok and "info" or "warn",
    ok = write_ok == true,
    code = write_ok and "OK" or "LEADERBOARD_WRITE_FAILED",
  })

  return result(write_ok == true, write_ok and "OK" or "LEADERBOARD_WRITE_FAILED", write_ok and "Leaderboard value written" or "Leaderboard native write failed", {
    player = query,
    key = leaderboard_key,
    value = numeric_value,
    method = method,
    detail = detail,
    playerState = minigame_object_address(player_state),
    attempts = attempts,
    lines = lines,
  })
end

BMF.players.summary = function(player)
  local listed = BMF.players.list()
  if not listed.ok then
    return listed
  end

  local players = (listed.data and listed.data.players) or {}
  local query = trim_string(player_query_text(player))
  local found = nil
  local match = ""

  if query == "" and #players == 1 then
    found = players[1]
    match = "single-player-cache"
  elseif query ~= "" then
    local lookup = BMF.players.find(players, query)
    if lookup.ok then
      found = lookup.data.player
      match = lookup.data.match or ""
    else
      lookup.data = lookup.data or {}
      lookup.data.knownPlayerCount = #players
      lookup.data.playerCount = #players
      lookup.data.liveControllerCount = (listed.data and listed.data.liveControllerCount) or 0
      lookup.data.adapter = (listed.data and listed.data.adapter) or ""
      lookup.data.cachePath = PLAYER_CACHE_PATH
      return lookup
    end
  else
    return result(false, "PLAYER_REQUIRED", "player query is required when the cache has zero or multiple players", {
      players = players,
      knownPlayerCount = #players,
      playerCount = #players,
      liveControllerCount = (listed.data and listed.data.liveControllerCount) or 0,
      adapter = (listed.data and listed.data.adapter) or "",
      cachePath = PLAYER_CACHE_PATH,
    })
  end

  local data = {
    player = found,
    id = found.id,
    uuid = found.uuid,
    username = found.username,
    playerName = found.playerName,
    displayName = found.displayName,
    originalName = found.originalName,
    match = match,
    query = query,
    knownPlayerCount = #players,
    playerCount = #players,
    liveControllerCount = (listed.data and listed.data.liveControllerCount) or 0,
    adapter = (listed.data and listed.data.adapter) or "",
    source = (listed.data and listed.data.source) or "",
    updatedAt = (listed.data and listed.data.updatedAt) or "",
    cachePath = PLAYER_CACHE_PATH,
  }
  return result(true, "OK", "Player summary resolved", data)
end

BMF.players.formatSummary = function(summary)
  local data = summary or {}
  local player = data.player or data
  local username = first_string(player.username, player.playerName, player.originalName, player.name) or "unknown"
  local display_name = first_string(player.displayName, player.name, username) or "unknown"
  local player_id = first_string(player.uuid, player.id, player.playerId, player.playerID) or "unknown"
  local known_count = tonumber(data.knownPlayerCount or data.playerCount or 0) or 0
  local live_count = tonumber(data.liveControllerCount or 0) or 0
  return "BMF player summary: username=" .. tostring(username) ..
    " displayName=" .. tostring(display_name) ..
    " id=" .. tostring(player_id) ..
    " knownPlayers=" .. tostring(known_count) ..
    " liveControllers=" .. tostring(live_count)
end

BMF.players.whisperSummary = function(player)
  local summarized = BMF.players.summary(player)
  if not summarized.ok then
    return summarized
  end

  local message = BMF.players.formatSummary(summarized.data)
  local whispered = BMF.chat.whisper(summarized.data.player, message)
  local response = result(whispered.ok, whispered.code or (whispered.ok and "OK" or "ERROR"), whispered.ok and "Player summary whispered" or "Player summary resolved but whisper failed", {
    player = summarized.data.player,
    summary = summarized.data,
    message = message,
    delivered = whispered.ok == true and whispered.data and whispered.data.delivered == true,
    deliveredCount = whispered.data and whispered.data.deliveredCount or 0,
    attemptedCount = whispered.data and whispered.data.attemptedCount or 0,
    deliveryMode = whispered.data and whispered.data.deliveryMode or "",
    whisperCode = whispered.code,
    whisper = whispered.data,
  })
  audit_record("players.summary.whisper", {
    target = summarized.data.uuid,
    username = summarized.data.username,
    displayName = summarized.data.displayName,
    knownPlayerCount = summarized.data.knownPlayerCount,
    liveControllerCount = summarized.data.liveControllerCount,
    deliveredCount = response.data.deliveredCount,
    deliveryMode = response.data.deliveryMode,
  }, {
    source = "framework",
    severity = response.ok and "info" or "warn",
    ok = response.ok,
    code = response.code,
  })
  return response
end

BMF.interact = {}

function interact_event_player(event)
  local player = event.player
  if type(player) == "table" then
    return {
      uuid = first_string(player.uuid, player.id, player.playerId, player.playerID) or "",
      username = first_string(player.username, player.playerName, player.originalName, player.name) or "",
      displayName = first_string(player.displayName, player.name, player.username) or "",
      controller = first_string(player.controller, player.controllerName) or "",
      pawn = first_string(player.pawn, player.pawnName) or "",
    }
  end
  return {
    uuid = first_string(event.playerUuid, event.playerId, event.uuid, event.id, event.player) or "",
    username = first_string(event.username, event.playerName, event.name) or "",
    displayName = first_string(event.displayName, event.name, event.username) or "",
    controller = first_string(event.controller, event.controllerName) or "",
    pawn = first_string(event.pawn, event.pawnName) or "",
  }
end

BMF.interact.handleConsoleMessage = function(event)
  if type(event) ~= "table" then
    return result(false, "INVALID_INTERACT_EVENT", "interact event table is required")
  end

  local message = first_string(event.message, event.consoleTag, event.tag, event.value) or ""
  local player = interact_event_player(event)
  local position = event.position
  if type(position) ~= "table" then
    position = {
      tonumber(event.x) or 0,
      tonumber(event.y) or 0,
      tonumber(event.z) or 0,
    }
  end

  local payload = {
    source = first_string(event.source, event.adapter) or "unknown",
    message = tostring(message or ""),
    player = player,
    brickName = first_string(event.brickName, event.brick) or "",
    brickAsset = first_string(event.brickAsset, event.asset) or "",
    position = position,
  }

  local emitted = BMF.events.emit("interactConsole", payload)
  audit_record("interact.console", {
    source = payload.source,
    playerUuid = player.uuid,
    playerName = player.username,
    message = payload.message,
    brickName = payload.brickName,
    brickAsset = payload.brickAsset,
    handlerCount = emitted.data and emitted.data.handlers or 0,
    errorCount = emitted.data and #(emitted.data.errors or {}) or 0,
  }, {
    source = "framework",
    actor = player.uuid,
    severity = emitted.ok and "info" or "warn",
    ok = emitted.ok,
    code = emitted.code,
  })

  local lines = {
    "event=interactConsole",
    "source=" .. tostring(payload.source or ""),
    "player_uuid=" .. tostring(player.uuid or ""),
    "player_name=" .. tostring(player.username or ""),
    "message=" .. tostring(payload.message or ""),
    "handler_count=" .. tostring(emitted.data and emitted.data.handlers or 0),
    "error_count=" .. tostring(emitted.data and #(emitted.data.errors or {}) or 0),
  }

  return result(emitted.ok, emitted.code, "Interact console message forwarded", {
    event = payload,
    handlerCount = emitted.data and emitted.data.handlers or 0,
    errors = emitted.data and emitted.data.errors or {},
    lines = lines,
  })
end

function private_chat_result(kind, player, message)
  local text = tostring(message or "")
  if trim_string(text) == "" then
    return result(false, "INVALID_OPTIONS", "message is required")
  end
  if player_query_text(player) == "" then
    return result(false, "INVALID_OPTIONS", "player target is required")
  end
  local limited = rate_limit_check("chat." .. tostring(kind or "private"))
  if not limited.ok then
    return limited
  end

  if type(player) == "table" and player.strictPrivateIdentity == true then
    local registry = state.player_registry or {}
    local request_id = trim_string(tostring(player.requestId or ""))
    local deadline_ms = tonumber(player.deadlineMs) or 0
    if deadline_ms <= os.time() * 1000 then
      registry.private_delivery_dropped =
        (tonumber(registry.private_delivery_dropped) or 0) + 1
      registry.private_delivery_expired =
        (tonumber(registry.private_delivery_expired) or 0) + 1
      return result(false, "PRIVATE_DELIVERY_EXPIRED", "Private delivery deadline elapsed", {
        requestId = request_id,
        delivered = false,
        deliveredCount = 0,
        attemptedCount = 0,
        identityReason = "expired",
      })
    end

    local live_target, _, identity_reason = live_chat_resolve_target(player)
    if live_target == nil then
      registry.private_delivery_dropped =
        (tonumber(registry.private_delivery_dropped) or 0) + 1
      registry.private_delivery_stale =
        (tonumber(registry.private_delivery_stale) or 0) + 1
      local dropped = tonumber(registry.private_delivery_dropped) or 0
      if dropped <= 5 or dropped % 100 == 0 then
        log(
          "warn",
          "P0 private delivery dropped"
            .. " reason=" .. tostring(identity_reason or "identity_unproven")
            .. " request_id=" .. request_id
            .. " count=" .. tostring(dropped))
      end
      return result(false, "PRIVATE_IDENTITY_STALE", "Private recipient identity could not be proven", {
        requestId = request_id,
        delivered = false,
        deliveredCount = 0,
        attemptedCount = 0,
        identityReason = tostring(identity_reason or "identity_unproven"),
      })
    end

    -- Re-check the deadline immediately before invoking the client RPC. A
    -- request that expired in the queue is dropped, never retargeted.
    if deadline_ms <= os.time() * 1000 then
      registry.private_delivery_dropped =
        (tonumber(registry.private_delivery_dropped) or 0) + 1
      registry.private_delivery_expired =
        (tonumber(registry.private_delivery_expired) or 0) + 1
      return result(false, "PRIVATE_DELIVERY_EXPIRED", "Private delivery deadline elapsed", {
        requestId = request_id,
        delivered = false,
        deliveredCount = 0,
        attemptedCount = 0,
        identityReason = "expired",
      })
    end

    local delivered, failed = live_chat_send_to_targets({ live_target }, text)
    if #delivered > 0 then
      registry.private_delivery_delivered =
        (tonumber(registry.private_delivery_delivered) or 0) + 1
    else
      registry.private_delivery_dropped =
        (tonumber(registry.private_delivery_dropped) or 0) + 1
    end
    return result(
      #delivered > 0,
      #delivered > 0 and "OK" or "PLAYER_DELIVERY_UNAVAILABLE",
      #delivered > 0 and "Private message delivered" or "Private delivery rejected",
      {
        requestId = request_id,
        connectionGeneration = tonumber(player.connectionGeneration) or 0,
        delivered = #delivered > 0,
        deliveredCount = #delivered,
        attemptedCount = 1,
        failedCount = #failed,
        identityReason = #delivered > 0 and "exact_uuid_generation" or "client_rpc_rejected",
        executor = "player_controller.client_push_chat_message",
        deliveryMode = "strict-uuid-generation-controller",
        validation = "exact UUID, connection generation, controller and PlayerState",
      })
  end

  local registry = state.player_registry or {}
  registry.private_delivery_invalid =
    (tonumber(registry.private_delivery_invalid) or 0) + 1
  registry.private_delivery_dropped =
    (tonumber(registry.private_delivery_dropped) or 0) + 1
  return result(false, "PRIVATE_IDENTITY_REQUIRED", "Private delivery requires an exact UUID and connection generation envelope", {
    delivered = false,
    deliveredCount = 0,
    attemptedCount = 0,
    identityReason = "strict_envelope_required",
  })
end

BMF.chat.whisper = function(player, message)
  return private_chat_result("whisper", player, message)
end

BMF.chat.statusMessage = function(player, message)
  return private_chat_result("statusMessage", player, message)
end

BMF.timers = {}
local FRAMEWORK_TIMER_OWNER = "@framework"

local function timer_owner_key(owner)
  local key = tostring(owner or "")
  if key == "" then
    return FRAMEWORK_TIMER_OWNER
  end
  return key
end

local function timer_note_rejected(owner, reason)
  state.telemetry.timers.rejected = (tonumber(state.telemetry.timers.rejected) or 0) + 1
  local rejected = state.telemetry.timers.rejected
  if rejected <= 5 or rejected % 100 == 0 then
    log(
      "error",
      "timer rejected owner=" .. timer_owner_key(owner)
        .. " reason=" .. tostring(reason or "unknown")
        .. " count=" .. tostring(rejected))
  end
end

local function timer_remove(id, outcome)
  local timer = state.timers[id]
  if type(timer) ~= "table" then
    return false
  end
  local action_handle = timer.action_handle
  local release_callback = timer.release_callback
  if timer.phase == "queued" then
    state.timer_due_count = math.max(0, (tonumber(state.timer_due_count) or 0) - 1)
    state.telemetry.timers.queued = state.timer_due_count
  end
  timer.action_handle = nil
  timer.release_callback = nil
  timer.callback = nil
  timer.phase = "removed"
  state.timers[id] = nil
  if type(action_handle) == "number" and type(CancelDelayedAction) == "function" then
    local cancel_ok, cancel_result = pcall(CancelDelayedAction, action_handle)
    if not cancel_ok or cancel_result == false then
      state.telemetry.timers.cancel_action_failed = (tonumber(state.telemetry.timers.cancel_action_failed) or 0) + 1
    end
  end
  if type(release_callback) == "function" then
    pcall(release_callback)
  end
  state.timer_active_count = math.max(0, (tonumber(state.timer_active_count) or 0) - 1)
  local owner = timer_owner_key(timer.owner)
  state.timer_owner_counts[owner] = math.max(0, (tonumber(state.timer_owner_counts[owner]) or 0) - 1)
  if state.timer_owner_counts[owner] == 0 then
    state.timer_owner_counts[owner] = nil
  end
  state.telemetry.timers.active = state.timer_active_count
  if outcome == "completed" then
    state.telemetry.timers.completed = (tonumber(state.telemetry.timers.completed) or 0) + 1
  elseif outcome == "cancelled" then
    state.telemetry.timers.cancelled = (tonumber(state.telemetry.timers.cancelled) or 0) + 1
  end
  return true
end

local function timer_reserve(owner, kind, interval, callback)
  local owner_key = timer_owner_key(owner)
  local owner_count = tonumber(state.timer_owner_counts[owner_key]) or 0
  if state.timer_active_count >= TIMER_MAX_ACTIVE_FRAMEWORK then
    timer_note_rejected(owner_key, "framework active timer limit reached")
    return nil
  end
  if owner_count >= TIMER_MAX_ACTIVE_PER_OWNER then
    timer_note_rejected(owner_key, "owner active timer limit reached")
    return nil
  end

  local id = state.next_timer_id
  state.next_timer_id = state.next_timer_id + 1
  state.timers[id] = {
    id = id,
    owner = owner_key,
    kind = kind,
    interval = interval,
    count = 0,
    callback = callback,
    phase = "idle",
  }
  state.timer_active_count = state.timer_active_count + 1
  state.timer_owner_counts[owner_key] = owner_count + 1
  state.telemetry.timers.active = state.timer_active_count
  state.telemetry.timers.peak = math.max(tonumber(state.telemetry.timers.peak) or 0, state.timer_active_count)
  state.telemetry.timers.created = (tonumber(state.telemetry.timers.created) or 0) + 1
  return id
end

local function timer_queue_reset_if_empty()
  local head = tonumber(state.timer_due_head) or 1
  local tail = tonumber(state.timer_due_tail) or 0
  if head > tail then
    state.timer_due_queue = {}
    state.timer_due_head = 1
    state.timer_due_tail = 0
  end
end

local function timer_queue_append(id)
  state.timer_due_tail = (tonumber(state.timer_due_tail) or 0) + 1
  state.timer_due_queue[state.timer_due_tail] = id
end

local function timer_mark_due(id)
  local timer = state.timers[id]
  if type(timer) ~= "table" or timer.phase ~= "scheduled" then
    return
  end

  -- The retained native callback releases itself before entering this function.
  timer.action_handle = nil
  timer.release_callback = nil
  if (tonumber(state.timer_due_count) or 0) >= TIMER_MAX_ACTIVE_FRAMEWORK then
    timer.phase = "idle"
    timer_remove(id, nil)
    timer_note_rejected(timer.owner, "bounded due queue is full")
    return
  end

  timer.phase = "queued"
  timer_queue_append(id)
  state.timer_due_count = (tonumber(state.timer_due_count) or 0) + 1
  state.telemetry.timers.queued = state.timer_due_count
  state.telemetry.timers.queued_peak = math.max(
    tonumber(state.telemetry.timers.queued_peak) or 0,
    state.timer_due_count)
end

local function timer_schedule_action(id)
  local timer = state.timers[id]
  if type(timer) ~= "table" or timer.phase ~= "idle" then
    return false
  end

  timer.phase = "scheduled"
  timer.action_handle = nil
  timer.release_callback = nil
  local scheduled, action_handle, release_callback = BMF_schedule_delayed_callback(
    "timer_" .. tostring(timer.kind or "unknown") .. ":" .. tostring(timer.owner or FRAMEWORK_TIMER_OWNER),
    timer.interval,
    function()
      timer_mark_due(id)
    end,
    function(reason)
      local current = state.timers[id]
      if current == timer and current.phase == "scheduled" then
        current.action_handle = nil
        current.release_callback = nil
        current.phase = "idle"
        timer_remove(id, nil)
        timer_note_rejected(current.owner, "timer scheduler thread guard refused: " .. tostring(reason or "unknown"))
      end
    end)
  if not scheduled then
    if state.timers[id] == timer and timer.phase == "scheduled" then
      timer.phase = "idle"
    end
    return false
  end

  if state.timers[id] ~= timer then
    if type(action_handle) == "number" and type(CancelDelayedAction) == "function" then
      pcall(CancelDelayedAction, action_handle)
    end
    if type(release_callback) == "function" then
      pcall(release_callback)
    end
    return false
  end
  if timer.phase == "scheduled" then
    timer.action_handle = action_handle
    timer.release_callback = release_callback
  elseif type(release_callback) == "function" then
    -- Defensive synchronous-fire path; release is idempotent.
    pcall(release_callback)
  end
  return true
end

local function timer_queue_take_one()
  local head = tonumber(state.timer_due_head) or 1
  local tail = tonumber(state.timer_due_tail) or 0
  if head > tail then
    timer_queue_reset_if_empty()
    return nil, nil, false
  end

  local id = state.timer_due_queue[head]
  state.timer_due_queue[head] = nil
  state.timer_due_head = head + 1
  timer_queue_reset_if_empty()
  local timer = state.timers[id]
  if type(timer) ~= "table" or timer.phase ~= "queued" then
    return nil, nil, true
  end

  state.timer_due_count = math.max(0, (tonumber(state.timer_due_count) or 0) - 1)
  state.telemetry.timers.queued = state.timer_due_count
  return id, timer, true
end

local function timer_queue_requeue(id, timer)
  if state.timers[id] ~= timer or timer.phase ~= "queued" then
    return false
  end
  timer_queue_append(id)
  state.timer_due_count = (tonumber(state.timer_due_count) or 0) + 1
  state.telemetry.timers.queued = state.timer_due_count
  return true
end

local function timer_report_callback_error(timer, id, err)
  local owner = tostring(timer and timer.owner or FRAMEWORK_TIMER_OWNER)
  local kind = tostring(timer and timer.kind or "unknown")
  if owner ~= FRAMEWORK_TIMER_OWNER and type(record_plugin_error) == "function" then
    local recorded, record_error = pcall(record_plugin_error, owner, "timer:" .. kind, err, {
      timerId = id,
      count = tonumber(timer and timer.count) or 0,
    }, state.plugins[owner])
    if recorded then
      return
    end
    log("error", "timer watchdog reporting failed owner=" .. owner .. ": " .. tostring(record_error))
  end
  log("error", "timer callback failed owner=" .. owner .. ": " .. tostring(err))
end

local function BMF_timer_pump_once()
  local pump_started_clock = os.clock()
  local processed = 0
  local scanned = 0
  local owner_callbacks = {}
  state.telemetry.timers.pump_ticks = (tonumber(state.telemetry.timers.pump_ticks) or 0) + 1

  while processed < TIMER_PUMP_MAX_CALLBACKS_PER_FRAME
      and scanned < TIMER_PUMP_MAX_QUEUE_SCANS_PER_FRAME
      and (tonumber(state.timer_due_count) or 0) > 0 do
    if processed > 0 and BMF_telemetry_duration_ms(pump_started_clock) >= TIMER_PUMP_MAX_DURATION_MS then
      break
    end

    local id, timer, inspected = timer_queue_take_one()
    if not inspected then
      break
    end
    scanned = scanned + 1
    if type(timer) == "table" then
      local owner = timer_owner_key(timer.owner)
      local owner_count = tonumber(owner_callbacks[owner]) or 0
      if owner_count >= TIMER_PUMP_MAX_CALLBACKS_PER_OWNER_PER_FRAME then
        timer_queue_requeue(id, timer)
      else
        owner_callbacks[owner] = owner_count + 1
        timer.phase = "running"
        local callback = timer.callback
        local callback_started_clock = os.clock()
        local ok = true
        local callback_error = nil

        if timer.kind == "after" then
          timer_remove(id, "completed")
          ok, callback_error = pcall(callback)
        else
          timer.count = (tonumber(timer.count) or 0) + 1
          local callback_count = timer.count
          ok, callback_error = pcall(callback, id, callback_count)
          if not ok then
            if state.timers[id] == timer then
              timer_remove(id, nil)
            end
          elseif state.timers[id] == timer then
            timer.phase = "idle"
            if not timer_schedule_action(id) then
              timer_remove(id, nil)
              timer_note_rejected(owner, "game-thread timer reschedule failed")
            end
          end
        end

        local callback_duration_ms = BMF_telemetry_duration_ms(callback_started_clock)
        state.telemetry.timers.callbacks = (tonumber(state.telemetry.timers.callbacks) or 0) + 1
        state.telemetry.timers.callback_duration_ms_sum =
          (tonumber(state.telemetry.timers.callback_duration_ms_sum) or 0) + callback_duration_ms
        state.telemetry.timers.callback_duration_ms_max = math.max(
          tonumber(state.telemetry.timers.callback_duration_ms_max) or 0,
          callback_duration_ms)
        if not ok then
          state.telemetry.timers.callback_errors = (tonumber(state.telemetry.timers.callback_errors) or 0) + 1
          timer_report_callback_error(timer, id, callback_error)
        end
        processed = processed + 1
      end
    end
  end

  local pump_duration_ms = BMF_telemetry_duration_ms(pump_started_clock)
  state.telemetry.timers.pump_duration_ms_sum =
    (tonumber(state.telemetry.timers.pump_duration_ms_sum) or 0) + pump_duration_ms
  state.telemetry.timers.pump_duration_ms_max = math.max(
    tonumber(state.telemetry.timers.pump_duration_ms_max) or 0,
    pump_duration_ms)
  if (tonumber(state.timer_due_count) or 0) > 0 then
    state.telemetry.timers.deferred_frames = (tonumber(state.telemetry.timers.deferred_frames) or 0) + 1
    state.telemetry.timers.deferred_callbacks =
      (tonumber(state.telemetry.timers.deferred_callbacks) or 0) + state.timer_due_count
  end
  return false
end

local function timer_pump_fail(reason)
  state.timer_pump_started = false
  state.timer_pump_mode = "failed"
  local action_handle = state.timer_pump_action_handle
  local release_callback = state.timer_pump_release_callback
  state.timer_pump_action_handle = nil
  state.timer_pump_release_callback = nil
  if type(action_handle) == "number" and type(CancelDelayedAction) == "function" then
    pcall(CancelDelayedAction, action_handle)
  end
  if type(release_callback) == "function" then
    pcall(release_callback)
  end

  local ids = {}
  for id in pairs(state.timers) do
    ids[#ids + 1] = id
  end
  for _, id in ipairs(ids) do
    timer_remove(id, "cancelled")
  end
  log("error", "bounded timer pump failed closed: " .. tostring(reason or "unknown"))
end

local timer_pump_schedule_oneshot
timer_pump_schedule_oneshot = function()
  if state.timer_pump_started ~= true then
    return false
  end
  local scheduled, action_handle, release_callback = BMF_schedule_delayed_callback(
    "timer_pump_tick",
    TIMER_MINIMUM_INTERVAL_MS,
    function()
      state.timer_pump_action_handle = nil
      state.timer_pump_release_callback = nil
      if state.timer_pump_started ~= true then
        return
      end
      local ok, pump_error = pcall(BMF_timer_pump_once)
      if not ok then
        timer_pump_fail(pump_error)
        return
      end
      if not timer_pump_schedule_oneshot() then
        timer_pump_fail("one-shot game-thread reschedule failed")
      end
    end,
    function(reason)
      timer_pump_fail("timer pump scheduler thread guard refused: " .. tostring(reason or "unknown"))
    end)
  if scheduled then
    state.timer_pump_action_handle = action_handle
    state.timer_pump_release_callback = release_callback
    return true
  end
  return false
end

local function BMF_start_timer_pump()
  if state.timer_pump_started == true then
    return true, state.timer_pump_mode
  end

  state.timer_pump_started = true
  local loop_started, loop_mode = BMF_start_game_thread_loop(
    "timer_dispatch",
    TIMER_MINIMUM_INTERVAL_MS,
    function()
      if state.timer_pump_started ~= true then
        return true
      end
      local ok, pump_error = pcall(BMF_timer_pump_once)
      if not ok then
        timer_pump_fail(pump_error)
        return true
      end
      return false
    end,
    true)
  if loop_started then
    state.timer_pump_mode = tostring(loop_mode or "game-thread-loop")
    return true, state.timer_pump_mode
  end

  state.timer_pump_mode = "ExecuteInGameThreadAfterFramesChain"
  if timer_pump_schedule_oneshot() then
    return true, state.timer_pump_mode
  end
  state.timer_pump_started = false
  state.timer_pump_mode = "unavailable"
  log("error", "bounded timer pump unavailable: no safe game-thread scheduler")
  return false, state.timer_pump_mode
end

local function create_timer(owner, kind, ms, callback)
  if type(callback) ~= "function" then
    timer_note_rejected(owner, "callback must be a function")
    return nil
  end

  local interval = finite_number(ms, 0)
  if kind == "every" then
    interval = math.max(TIMER_MINIMUM_INTERVAL_MS, interval)
  else
    interval = math.max(0, interval)
  end
  if not state.timer_pump_started then
    timer_note_rejected(owner, "bounded game-thread timer pump is unavailable")
    return nil
  end
  local id = timer_reserve(owner, kind, interval, callback)
  if id == nil then
    return nil
  end
  local owner_key = timer_owner_key(owner)
  if not timer_schedule_action(id) then
    timer_remove(id, nil)
    timer_note_rejected(owner_key, "game-thread scheduler unavailable")
    return nil
  end
  return id
end

local function cancel_timer(id, owner)
  local timer = state.timers[id]
  if type(timer) ~= "table" then
    return false
  end
  if owner ~= nil and timer.owner ~= timer_owner_key(owner) then
    return false
  end
  return timer_remove(id, "cancelled")
end

cancel_timers_for_owner = function(owner)
  local owner_key = timer_owner_key(owner)
  local ids = {}
  for id, timer in pairs(state.timers) do
    if type(timer) == "table" and timer.owner == owner_key then
      ids[#ids + 1] = id
    end
  end
  for _, id in ipairs(ids) do
    timer_remove(id, "cancelled")
  end
  return #ids
end

BMF.timers.after = function(ms, callback)
  return create_timer(nil, "after", ms, callback)
end

BMF.timers.every = function(ms, callback)
  return create_timer(nil, "every", ms, callback)
end

BMF.timers.cancel = function(id)
  return cancel_timer(id, nil)
end

BMF.timers.activeCount = function()
  return tonumber(state.timer_active_count) or 0
end

function list_command_request_files()
  local command_dir = COMMAND_DIR:gsub("/", "\\")
  if not state.command_dir_ensured then
    os.execute('if not exist "' .. command_dir .. '" mkdir "' .. command_dir .. '"')
    state.command_dir_ensured = true
  end

  local handle = io.popen('dir /b /a-d "' .. command_dir .. '\\*.request.txt" 2>nul')
  if not handle then
    return {}
  end

  local files = {}
  for line in handle:lines() do
    if line and line:match("%.request%.txt$") then
      files[#files + 1] = line
    end
  end
  handle:close()
  table.sort(files)
  return files
end

function BMF_new_bounded_output_collector()
  local output = state.telemetry.command_output or {}
  return {
    lines = {},
    bytes = 0,
    maxLines = math.max(8, tonumber(output.max_lines) or COMMAND_OUTPUT_DEFAULT_MAX_LINES),
    maxBytes = math.max(1024, tonumber(output.max_bytes) or COMMAND_OUTPUT_DEFAULT_MAX_BYTES),
    truncated = false,
    omittedLines = 0,
    omittedBytes = 0,
  }
end

function BMF_bounded_output_add(collector, value)
  local line = tostring(value or "")
  local separator_bytes = #collector.lines > 0 and 1 or 0
  if not collector.truncated
      and #collector.lines < collector.maxLines
      and (collector.bytes + separator_bytes + #line) <= collector.maxBytes then
    collector.lines[#collector.lines + 1] = line
    collector.bytes = collector.bytes + separator_bytes + #line
    return true
  end

  collector.truncated = true
  collector.omittedLines = collector.omittedLines + 1
  collector.omittedBytes = collector.omittedBytes + #line
  return false
end

function BMF_bounded_output_marker(collector)
  return string.format(
    "[BMF_OUTPUT_TRUNCATED omitted_lines=%d omitted_bytes_at_least=%d max_lines=%d max_bytes=%d]",
    collector.omittedLines,
    collector.omittedBytes,
    collector.maxLines,
    collector.maxBytes)
end

function BMF_bounded_output_finalize(collector, command_name, transport)
  if not collector.truncated then
    return collector.lines
  end

  local marker = BMF_bounded_output_marker(collector)
  local separator_bytes = #collector.lines > 0 and 1 or 0
  while #collector.lines >= collector.maxLines
      or (collector.bytes + separator_bytes + #marker) > collector.maxBytes do
    local removed = table.remove(collector.lines)
    if removed == nil then
      break
    end
    collector.bytes = math.max(0, collector.bytes - #removed - (#collector.lines > 0 and 1 or 0))
    collector.omittedLines = collector.omittedLines + 1
    collector.omittedBytes = collector.omittedBytes + #removed
    marker = BMF_bounded_output_marker(collector)
    separator_bytes = #collector.lines > 0 and 1 or 0
  end

  collector.lines[#collector.lines + 1] = marker
  collector.bytes = collector.bytes + separator_bytes + #marker
  local output = state.telemetry.command_output
  output.truncated_commands = (tonumber(output.truncated_commands) or 0) + 1
  output.omitted_lines = (tonumber(output.omitted_lines) or 0) + collector.omittedLines
  output.omitted_bytes = (tonumber(output.omitted_bytes) or 0) + collector.omittedBytes
  output.last = {
    command = tostring(command_name or "unknown"),
    transport = tostring(transport or "unknown"),
    retained_lines = #collector.lines,
    retained_bytes = collector.bytes,
    omitted_lines = collector.omittedLines,
    omitted_bytes = collector.omittedBytes,
    at = os.date("!%Y-%m-%dT%H:%M:%SZ"),
  }
  return collector.lines
end

function BMF_dispatch_bmf_command_text(request_id, command_text, transport, operation_context)
  local process_started_clock = os.clock()
  local process_started_epoch = os.time()
  local output_collector = BMF_new_bounded_output_collector()
  local output_device = {
    suppressEventLog = true,
    Log = function(_, line)
      BMF_bounded_output_add(output_collector, line)
    end,
  }

  local command_name, args = command_text:match("^(%S+)%s*(.*)$")
  BMF_operation_update_class(operation_context, command_name or "unknown")
  BMF_operation_update_stage(operation_context, "command_dispatch")
  local ok = false
  local detail = ""
  local dispatch_started_clock = os.clock()
  if not command_name or command_name == "" then
    detail = "command name is required"
  else
    local dispatch_ok, handled_or_error = pcall(BMF.commands.dispatch, command_name, args or "", output_device)
    ok = dispatch_ok and handled_or_error and true or false
    if not dispatch_ok then
      detail = "dispatch crashed: " .. tostring(handled_or_error)
      BMF_bounded_output_add(output_collector, "BMF " .. tostring(command_name) .. " ERROR " .. detail)
    elseif not handled_or_error then
      detail = "command was not handled"
    else
      detail = "ok"
    end
  end
  local dispatch_duration_ms = math.floor(((os.clock() - dispatch_started_clock) * 1000) + 0.5)
  local total_duration_exact_ms = math.max(0, (os.clock() - process_started_clock) * 1000)
  local total_duration_ms = math.floor(total_duration_exact_ms + 0.5)
  local request_created_ms = tonumber(tostring(request_id):match("_(%d%d%d%d%d%d%d%d%d%d%d%d%d)_"))
  local processed_at_ms = tonumber(process_started_epoch) and (tonumber(process_started_epoch) * 1000) or nil
  local request_age_ms = request_created_ms and processed_at_ms and (processed_at_ms - request_created_ms) or nil
  if request_age_ms and request_age_ms < 0 then
    request_age_ms = 0
  end
  if transport == "socket" and type(BMF_socket_scheduler_record_work) == "function" then
    BMF_socket_scheduler_record_work("direct_socket", total_duration_ms, ok, total_duration_exact_ms)
  end
  BMF_telemetry_record_command(command_name or "unknown", transport or "file", ok, detail, total_duration_ms, dispatch_duration_ms, request_age_ms)
  BMF_operation_update_stage(operation_context, "command_complete")
  local lines = BMF_bounded_output_finalize(output_collector, command_name, transport)

  local response = {
    "ok=" .. tostring(ok),
    "detail=" .. tostring(detail),
    "command=" .. tostring(command_text),
    "bmf_command_request_id=" .. tostring(request_id),
    "bmf_command_transport=" .. tostring(transport or "file"),
    "bmf_command_processed_at=" .. tostring(os.date("!%Y-%m-%dT%H:%M:%SZ", process_started_epoch)),
    "bmf_command_request_age_ms=" .. tostring(request_age_ms or ""),
    "bmf_command_dispatch_ms=" .. tostring(dispatch_duration_ms),
    "bmf_command_total_ms=" .. tostring(total_duration_ms),
  }
  for _, line in ipairs(lines) do
    response[#response + 1] = tostring(line)
  end
  return table.concat(response, "\n") .. "\n", ok, detail
end

function process_command_request(file_name)
  local request_id = tostring(file_name or ""):match("^(.*)%.request%.txt$")
  if not request_id or request_id == "" then
    return false
  end

  local request_path = COMMAND_DIR .. "/" .. file_name
  local response_path = COMMAND_DIR .. "/" .. request_id .. ".response.txt"
  local command_text = trim_string(read_file(request_path) or "")

  if command_text == "" then
    local empty_reads = tonumber(state.command_empty_reads[request_id] or 0) + 1
    state.command_empty_reads[request_id] = empty_reads
    if empty_reads < COMMAND_EMPTY_READ_RETRY_LIMIT then
      return false
    end
  else
    state.command_empty_reads[request_id] = nil
  end

  os.remove(request_path)
  state.command_empty_reads[request_id] = nil

  local operation_context = BMF_operation_begin(
    BMF_operation_class_from_text(command_text, "unknown"),
    "file_worker",
    { id = request_id, serviceClass = "bulk" })
  BMF_operation_start_execution(operation_context)
  local response, ok = BMF_dispatch_bmf_command_text(
    request_id,
    command_text,
    "file",
    operation_context)
  BMF_operation_finish(operation_context, ok == true and "completed" or "known_failure")
  write_file(response_path, response)
  return true
end

poll_command_requests = nil

function BMF_command_worker_poll_interval_ms()
  return BMF_env_number(
    "BMF_COMMAND_WORKER_POLL_MS",
    BMF_COMMAND_WORKER_DEFAULT_POLL_MS,
    25
  )
end

function BMF_command_worker_fallback_poll_interval_ms()
  local fallback = BMF_env_string("BMF_COMMAND_WORKER_FALLBACK_POLL_MS")
  if fallback ~= "" then
    return BMF_env_number("BMF_COMMAND_WORKER_FALLBACK_POLL_MS", BMF_COMMAND_WORKER_FALLBACK_POLL_MS, 250)
  end
  return BMF_env_number("BMF_COMMAND_WORKER_POLL_MS", BMF_COMMAND_WORKER_FALLBACK_POLL_MS, 250)
end

function BMF_command_worker_max_files_per_poll()
  return BMF_env_number(
    "BMF_COMMAND_WORKER_MAX_FILES_PER_POLL",
    BMF_COMMAND_WORKER_DEFAULT_MAX_FILES_PER_POLL,
    1
  )
end

function BMF_command_worker_enabled()
  return BMF_env_bool("BMF_COMMAND_WORKER_ENABLED", false)
end

function BMF_status_heartbeat_interval_seconds()
  return BMF_env_number(
    "BMF_STATUS_HEARTBEAT_SECONDS",
    BMF_STATUS_HEARTBEAT_DEFAULT_SECONDS,
    5
  )
end

function write_status_heartbeat(force)
  if type(write_status) ~= "function" then
    return false
  end

  local interval = tonumber(state.status_heartbeat_interval_seconds) or BMF_STATUS_HEARTBEAT_DEFAULT_SECONDS
  local last_write_epoch = tonumber(state.status_last_write_epoch or 0) or 0
  local now_epoch = os.time()
  if not force and last_write_epoch > 0 and (now_epoch - last_write_epoch) < interval then
    return false
  end

  write_status()
  return true
end

function BMF_drain_command_worker_native_events(limit, defer_emit)
  if state.socket.started then
    return true, 0
  end

  local drain_limit = limit or 64
  local native_drained = 0
  local native_ok_all = true

  local function emit_native_events(raw_events, emit_fn, on_error)
    local function emit_now()
      local emitted, err = pcall(emit_fn, raw_events, {
        silent = true,
      })
      if not emitted then
        on_error(err)
      end
    end

    if defer_emit then
      run_on_game_thread(emit_now)
    else
      emit_now()
    end
  end

  if state.tools.tree_cut_native and state.tools.tree_cut_native.enabled == true then
    local tree_ok, tree_code, tree_message, tree_raw_events = BMF_tree_cut_native_drain_raw(drain_limit)
    if not tree_ok then
      native_ok_all = false
      state.tools.tree_cut_native.last_error = tostring(tree_message or tree_code or "native tree-cut drain failed")
    elseif type(tree_raw_events) == "table" and #tree_raw_events > 0 then
      native_drained = native_drained + #tree_raw_events
      emit_native_events(tree_raw_events, BMF_tree_cut_native_emit_raw, function(err)
        state.tools.tree_cut_native.last_error = "native tree-cut emit failed: " .. tostring(err)
      end)
    end
  end

  if BMF_zone_native_should_drain() then
    local zone_ok, zone_code, zone_message, zone_raw_events = BMF_zone_native_drain_raw(drain_limit)
    if not zone_ok then
      native_ok_all = false
      state.tools.zone_native.last_error = tostring(zone_message or zone_code or "native zone drain failed")
    elseif type(zone_raw_events) == "table" and #zone_raw_events > 0 then
      native_drained = native_drained + #zone_raw_events
      emit_native_events(zone_raw_events, BMF_zone_native_emit_raw, function(err)
        state.tools.zone_native.last_error = "native zone emit failed: " .. tostring(err)
      end)
    end
  end

  return native_ok_all, native_drained
end

function schedule_command_worker_poll(delay_ms)
  local delay = tonumber(delay_ms) or state.command_worker_fallback_poll_interval_ms or BMF_COMMAND_WORKER_FALLBACK_POLL_MS
  return BMF_schedule_delayed_callback("command_worker", delay, function()
    if poll_command_requests then
      poll_command_requests()
    end
  end)
end

function BMF_poll_command_requests_once()
  local poll_started_clock = os.clock()
  local processed_files = 0
  local native_drained = 0
  local poll_ok = true
  local max_files = state.command_worker_max_files_per_poll or BMF_COMMAND_WORKER_DEFAULT_MAX_FILES_PER_POLL
  for _, file_name in ipairs(list_command_request_files()) do
    local ok, processed_or_error = pcall(process_command_request, file_name)
    if not ok then
      poll_ok = false
      log("error", "command worker failed for " .. tostring(file_name) .. ": " .. tostring(processed_or_error))
    elseif processed_or_error == true then
      processed_files = processed_files + 1
    end
    if processed_files >= max_files then
      break
    end
  end

  if not state.socket.started then
    local native_ok, native_count = BMF_drain_command_worker_native_events(64, false)
    if not native_ok then
      poll_ok = false
    end
    native_drained = native_count or 0
  end
  if processed_files > 0 or native_drained > 0 or not poll_ok then
    BMF_telemetry_record_worker("command_polls", BMF_telemetry_duration_ms(poll_started_clock), poll_ok, "files_processed", processed_files)
  end
  write_status_heartbeat(false)
end

poll_command_requests = function()
  BMF_poll_command_requests_once()

  if state.command_worker_started then
    if not schedule_command_worker_poll(state.command_worker_fallback_poll_interval_ms) then
      state.command_worker_started = false
      state.command_worker_mode = "stopped"
      log("error", "command worker stopped: no game-thread scheduler available")
    end
  end
end

function start_command_worker()
  if state.command_worker_started then
    return
  end
  if not BMF_command_worker_enabled() then
    state.command_worker_started = false
    state.command_worker_mode = "disabled"
    state.status_heartbeat_interval_seconds = BMF_status_heartbeat_interval_seconds()
    log("info", "legacy file command worker disabled; use BMFSocket for BMF commands")
    return
  end
  state.command_worker_started = true
  state.command_worker_poll_interval_ms = BMF_command_worker_poll_interval_ms()
  state.command_worker_fallback_poll_interval_ms = BMF_command_worker_fallback_poll_interval_ms()
  state.command_worker_max_files_per_poll = BMF_command_worker_max_files_per_poll()
  state.status_heartbeat_interval_seconds = BMF_status_heartbeat_interval_seconds()
  state.command_worker_mode = "starting"
  log("info", "command worker started path=" .. COMMAND_DIR)
  if BMF_start_game_thread_loop("command_worker", state.command_worker_fallback_poll_interval_ms, function()
    if not state.command_worker_started then
      return true
    end
    BMF_poll_command_requests_once()
    return false
  end, true) then
    state.command_worker_mode = "LoopInGameThread"
    log(
      "info",
      "command worker polling via LoopInGameThread interval_ms="
        .. tostring(state.command_worker_fallback_poll_interval_ms)
        .. " max_files_per_poll="
        .. tostring(state.command_worker_max_files_per_poll)
    )
    return
  end
  if not BMF_allow_delayed_worker_fallback() then
    state.command_worker_started = false
    state.command_worker_mode = "stopped"
    log("error", "command worker unavailable: delayed fallback disabled and no loop scheduler available")
    return
  end
  state.command_worker_mode = "ExecuteInGameThreadAfterFramesChain"
  log(
    "warn",
    "command worker using game-thread delayed fallback interval_ms="
      .. tostring(state.command_worker_fallback_poll_interval_ms)
      .. " max_files_per_poll="
      .. tostring(state.command_worker_max_files_per_poll)
  )
  if not schedule_command_worker_poll(state.command_worker_fallback_poll_interval_ms) then
    state.command_worker_started = false
    state.command_worker_mode = "stopped"
    log("error", "command worker unavailable: no game-thread scheduler available")
  end
end

local BMF_game_command_tunnel_schedule
local BMF_game_command_tunnel_dequeue
local BMF_game_command_tunnel_drain_once
local BMF_game_command_tunnel_pump
local BMF_process_game_command_tunnel_request
local BMF_game_command_tunnel_send_terminal

function BMF_socket_scheduler_path(path)
  local by_path = state.telemetry.socket_scheduler.by_path
  if path == "tunnel" then
    return by_path.tunnel
  end
  return by_path.direct_socket
end

function BMF_socket_scheduler_record_admission_outcome(path, outcome)
  local item = BMF_socket_scheduler_path(path)
  local normalized = tostring(outcome or "rejected")
  if normalized == "accepted" then
    item.admitted = (tonumber(item.admitted) or 0) + 1
  elseif normalized == "expired" then
    item.expired = (tonumber(item.expired) or 0) + 1
  elseif normalized == "dropped" then
    item.dropped = (tonumber(item.dropped) or 0) + 1
  else
    item.rejected = (tonumber(item.rejected) or 0) + 1
  end
end

function BMF_socket_scheduler_record_terminal(path, result_state, send_ok)
  local item = BMF_socket_scheduler_path(path)
  local normalized = tostring(result_state or "rejected")
  if normalized == "injected" or normalized == "completed" then
    item.terminal_completed = (tonumber(item.terminal_completed) or 0) + 1
  elseif normalized == "failed" then
    item.terminal_failed = (tonumber(item.terminal_failed) or 0) + 1
  elseif normalized == "expired" then
    item.terminal_expired = (tonumber(item.terminal_expired) or 0) + 1
  elseif normalized == "outcome_unknown" then
    item.terminal_outcome_unknown = (tonumber(item.terminal_outcome_unknown) or 0) + 1
  else
    item.terminal_rejected = (tonumber(item.terminal_rejected) or 0) + 1
  end
  if send_ok == false then
    item.terminal_send_failed = (tonumber(item.terminal_send_failed) or 0) + 1
  end
end

function BMF_socket_scheduler_record_fairness(path, service_class)
  local item = BMF_socket_scheduler_path(path)
  local normalized = service_class == "bulk" and "bulk" or "interactive"
  item.fairness[normalized] = (tonumber(item.fairness[normalized]) or 0) + 1
end

function BMF_socket_scheduler_record_duplicate(path, phase)
  local item = BMF_socket_scheduler_path(path)
  if phase == "completed" then
    item.duplicate_completed = (tonumber(item.duplicate_completed) or 0) + 1
  else
    item.duplicate_active = (tonumber(item.duplicate_active) or 0) + 1
  end
end

function BMF_socket_scheduler_deadline_expired(deadline_ms, issued_at_ms, accepted_clock)
  local deadline = tonumber(deadline_ms) or 0
  local issued = tonumber(issued_at_ms) or 0
  if deadline <= 0 or issued <= 0 or deadline <= issued then
    return true
  end
  -- The embedded wall clock has one-second resolution. It can prove an old
  -- request expired, but it must not reject a short TTL merely because its
  -- deadline falls inside the current second. Queue residence is measured
  -- precisely with the monotonic clock captured at admission.
  if (os.time() * 1000) >= deadline then
    return true
  end
  local accepted = tonumber(accepted_clock)
  if accepted ~= nil then
    local elapsed_ms = math.max(0, (os.clock() - accepted) * 1000)
    return elapsed_ms >= (deadline - issued)
  end
  return false
end

function BMF_socket_scheduler_total_depth()
  return math.max(0, tonumber(state.socket_admission.direct_queued_count) or 0)
    + math.max(0, tonumber(state.game_command_tunnel.queued_count) or 0)
end

function BMF_socket_scheduler_total_bytes()
  return math.max(0, tonumber(state.socket_admission.direct_queued_bytes) or 0)
    + math.max(0, tonumber(state.game_command_tunnel.queued_bytes) or 0)
end

function BMF_socket_scheduler_record_ingress(message_type)
  local scheduler = state.telemetry.socket_scheduler
  local normalized_type = tostring(message_type or "")
  local item = scheduler.ingress_by_type.other
  if normalized_type == "command" then
    item = scheduler.ingress_by_type.command
  elseif normalized_type == "tunnel.request" then
    item = scheduler.ingress_by_type.tunnel_request
  elseif normalized_type == "ping" then
    item = scheduler.ingress_by_type.ping
  end
  item.count = (tonumber(item.count) or 0) + 1
end

function BMF_socket_scheduler_record_admission(path)
  BMF_socket_scheduler_record_admission_outcome(path, "accepted")
end

function BMF_socket_scheduler_record_work(path, duration_ms, ok, budget_duration_ms)
  local scheduler = state.telemetry.socket_scheduler
  local item = BMF_socket_scheduler_path(path)
  local elapsed_ms = math.max(0, tonumber(duration_ms) or 0)
  local budget_elapsed_ms = math.max(0, tonumber(budget_duration_ms) or elapsed_ms)
  BMF_telemetry_observe(item, elapsed_ms, ok)
  if budget_elapsed_ms > (tonumber(scheduler.budget_ms) or 3) then
    scheduler.monolithic_overrun_total = (tonumber(scheduler.monolithic_overrun_total) or 0) + 1
    item.monolithic_overruns = (tonumber(item.monolithic_overruns) or 0) + 1
  end
end

function BMF_socket_scheduler_budget_exhausted_for_admission(started_clock)
  local scheduler = state.telemetry.socket_scheduler
  if scheduler.budget_enforced ~= true then
    return false
  end
  local started = tonumber(started_clock)
  if not started then
    return false
  end
  local elapsed_ms = math.max(0, (os.clock() - started) * 1000)
  return elapsed_ms >= (tonumber(scheduler.budget_ms) or 3)
end

function BMF_socket_scheduler_record_slice(
  duration_ms,
  ok,
  ingress_count,
  direct_admitted,
  tunnel_dispatched,
  direct_dispatched,
  budget_admission_stopped,
  budget_tunnel_dispatch_skipped,
  budget_dispatch_skipped)
  local scheduler = state.telemetry.socket_scheduler
  local elapsed_ms = math.max(0, tonumber(duration_ms) or 0)
  local ingress = math.max(0, tonumber(ingress_count) or 0)
  local direct_count = math.max(0, tonumber(direct_admitted) or 0)
  local tunnel_count = math.max(0, tonumber(tunnel_dispatched) or 0)
  local direct_dispatched_count = math.max(0, tonumber(direct_dispatched) or 0)
  local stopped_for_budget = budget_admission_stopped == true
  local tunnel_skipped_for_budget = budget_tunnel_dispatch_skipped == true
  local dispatch_skipped_for_budget = budget_dispatch_skipped == true
  BMF_telemetry_observe(scheduler.slice, elapsed_ms, ok)
  scheduler.ingress_total = (tonumber(scheduler.ingress_total) or 0) + ingress
  scheduler.ingress_last = ingress
  scheduler.ingress_peak = math.max(tonumber(scheduler.ingress_peak) or 0, ingress)
  scheduler.direct_admitted_last = direct_count
  scheduler.direct_admitted_peak = math.max(tonumber(scheduler.direct_admitted_peak) or 0, direct_count)
  scheduler.tunnel_dispatched_last = tunnel_count
  scheduler.direct_dispatched_last = direct_dispatched_count
  scheduler.budget_admission_stopped_last = stopped_for_budget
  if stopped_for_budget then
    scheduler.budget_admission_stopped_total = (tonumber(scheduler.budget_admission_stopped_total) or 0) + 1
  end
  scheduler.budget_tunnel_dispatch_skipped_last = tunnel_skipped_for_budget
  if tunnel_skipped_for_budget then
    scheduler.budget_tunnel_dispatch_skipped_total = (tonumber(scheduler.budget_tunnel_dispatch_skipped_total) or 0) + 1
  end
  scheduler.budget_dispatch_skipped_last = dispatch_skipped_for_budget
  if dispatch_skipped_for_budget then
    scheduler.budget_dispatch_skipped_total = (tonumber(scheduler.budget_dispatch_skipped_total) or 0) + 1
  end
  if elapsed_ms > (tonumber(scheduler.budget_ms) or 3) then
    scheduler.budget_exhausted_total = (tonumber(scheduler.budget_exhausted_total) or 0) + 1
  end
end

function BMF_socket_queue_oldest_age_ms(queue, accepted_field)
  if type(queue) ~= "table" or #queue == 0 then
    return 0
  end
  local oldest_ms = tonumber(queue[1] and queue[1][accepted_field or "acceptedAtMs"] or 0) or 0
  if oldest_ms <= 0 then
    return 0
  end
  return math.max(0, (os.time() * 1000) - oldest_ms)
end

function BMF_socket_scheduler_refresh_queue_telemetry()
  local queues = state.telemetry.socket_scheduler.queues
  local admission = state.socket_admission
  local tunnel = state.game_command_tunnel
  local direct_interactive = admission.direct_queues.interactive or {}
  local direct_bulk = admission.direct_queues.bulk or {}
  local interactive = tunnel.queues.interactive or {}
  local bulk = tunnel.queues.bulk or {}
  local direct_interactive_age = BMF_socket_queue_oldest_age_ms(direct_interactive, "acceptedAtMs")
  local direct_bulk_age = BMF_socket_queue_oldest_age_ms(direct_bulk, "acceptedAtMs")
  local interactive_age = BMF_socket_queue_oldest_age_ms(interactive, "acceptedAtMs")
  local bulk_age = BMF_socket_queue_oldest_age_ms(bulk, "acceptedAtMs")
  queues.direct_depth = tonumber(admission.direct_queued_count) or 0
  queues.direct_interactive_depth = #direct_interactive
  queues.direct_bulk_depth = #direct_bulk
  queues.direct_interactive_oldest_age_ms = direct_interactive_age
  queues.direct_bulk_oldest_age_ms = direct_bulk_age
  queues.direct_oldest_age_ms = math.max(direct_interactive_age, direct_bulk_age)
  queues.direct_peak_depth = tonumber(admission.direct_peak_depth) or 0
  queues.direct_interactive_peak_depth = tonumber(admission.direct_peak_interactive_depth) or 0
  queues.direct_bulk_peak_depth = tonumber(admission.direct_peak_bulk_depth) or 0
  queues.tunnel_depth = tonumber(tunnel.queued_count) or 0
  queues.tunnel_interactive_depth = #interactive
  queues.tunnel_bulk_depth = #bulk
  queues.tunnel_interactive_oldest_age_ms = interactive_age
  queues.tunnel_bulk_oldest_age_ms = bulk_age
  queues.tunnel_oldest_age_ms = math.max(interactive_age, bulk_age)
  queues.tunnel_peak_depth = tonumber(tunnel.peak_depth) or 0
  queues.tunnel_interactive_peak_depth = tonumber(tunnel.peak_interactive_depth) or 0
  queues.tunnel_bulk_peak_depth = tonumber(tunnel.peak_bulk_depth) or 0
  queues.direct_completed_count = #(admission.completed_order or {})
  queues.direct_completed_bytes = tonumber(admission.completed_retained_bytes) or 0
  queues.direct_completed_max_bytes = tonumber(admission.completed_max_bytes) or 0
  queues.direct_completed_peak_bytes = tonumber(admission.completed_peak_bytes) or 0
  queues.direct_completed_evicted = tonumber(admission.completed_evicted) or 0
  queues.direct_completed_response_omitted = tonumber(admission.completed_response_omitted) or 0
  queues.tunnel_completed_count = #(tunnel.completed_order or {})
  queues.tunnel_completed_bytes = tonumber(tunnel.completed_retained_bytes) or 0
  queues.tunnel_completed_max_bytes = tonumber(tunnel.completed_max_bytes) or 0
  queues.tunnel_completed_peak_bytes = tonumber(tunnel.completed_peak_bytes) or 0
  queues.tunnel_completed_evicted = tonumber(tunnel.completed_evicted) or 0
  queues.tunnel_completed_response_omitted = tonumber(tunnel.completed_response_omitted) or 0
  return queues
end

function BMF_socket_scheduler_send_direct_json(record)
  local sent = BMF_socket_send_json(record)
  if sent then
    state.socket.sent_responses = (tonumber(state.socket.sent_responses) or 0) + 1
  end
  return sent
end

function BMF_socket_replay_record_bytes(record, identity_bytes)
  local encoded_ok, encoded = pcall(json_encode, record or {})
  if not encoded_ok or type(encoded) ~= "string" then
    return math.huge
  end
  -- Include identity strings and a conservative fixed allowance for the Lua
  -- tables/hash entries retained alongside the serialized replay payload.
  return #encoded + math.max(0, tonumber(identity_bytes) or 0) + 256
end

function BMF_socket_replay_record_for_cache(record, max_bytes, identity_bytes)
  local cached = copy_table(record or {})
  local byte_limit = math.max(65536, tonumber(max_bytes) or 65536)
  local retained_bytes = BMF_socket_replay_record_bytes(cached, identity_bytes)
  local omitted = false
  local original_response = type(cached.response) == "string" and cached.response or nil
  local original_response_bytes = original_response and #original_response or 0
  local original_detail = type(cached.detail) == "string" and cached.detail or nil
  local original_detail_bytes = original_detail and #original_detail or 0

  if retained_bytes > byte_limit and original_response ~= nil then
    cached.response = REPLAY_RESPONSE_OMITTED_MARKER
      .. " original_bytes=" .. tostring(original_response_bytes) .. "\n"
    cached.responseOmitted = true
    cached.responseOriginalBytes = original_response_bytes
    omitted = true
    retained_bytes = BMF_socket_replay_record_bytes(cached, identity_bytes)
  end

  if retained_bytes > byte_limit and original_detail ~= nil then
    cached.detail = "[BMF_REPLAY_DETAIL_OMITTED cache_entry_byte_budget] original_bytes="
      .. tostring(original_detail_bytes)
    cached.detailOmitted = true
    cached.detailOriginalBytes = original_detail_bytes
    omitted = true
    retained_bytes = BMF_socket_replay_record_bytes(cached, identity_bytes)
  end

  if retained_bytes > byte_limit then
    cached = {
      type = cached.type,
      source = cached.source,
      v = cached.v,
      ts = cached.ts,
      id = cached.id,
      ok = cached.ok,
      state = cached.state,
      code = cached.code,
      dispatchMs = cached.dispatchMs,
      detail = "[BMF_REPLAY_PAYLOAD_OMITTED cache_entry_byte_budget]",
      response = REPLAY_RESPONSE_OMITTED_MARKER .. " original_bytes="
        .. tostring(original_response_bytes) .. "\n",
      responseOmitted = true,
      responseOriginalBytes = original_response_bytes,
      replayPayloadOmitted = true,
    }
    omitted = true
    retained_bytes = BMF_socket_replay_record_bytes(cached, identity_bytes)
  end

  return cached, retained_bytes, omitted
end

function BMF_socket_replay_compact_cache_to_budget(cache, max_bytes, cache_kind)
  local byte_limit = math.max(65536, tonumber(max_bytes) or 65536)
  if (tonumber(cache.completed_retained_bytes) or 0) <= byte_limit then
    return 0
  end

  local compacted = 0
  local inspected = 0
  for _, request_id in ipairs(cache.completed_order or {}) do
    if (tonumber(cache.completed_retained_bytes) or 0) <= byte_limit then
      break
    end
    inspected = inspected + 1
    if inspected > 16 then
      break
    end
    local entry = cache.completed_by_id and cache.completed_by_id[request_id] or nil
    local record = entry and entry.record or nil
    if type(record) == "table"
        and type(record.response) == "string"
        and record.responseOmitted ~= true then
      local cached_record = copy_table(record)
      local original_response_bytes = #cached_record.response
      cached_record.response = REPLAY_RESPONSE_OMITTED_MARKER
        .. " original_bytes=" .. tostring(original_response_bytes) .. "\n"
      cached_record.responseOmitted = true
      cached_record.responseOriginalBytes = original_response_bytes
      local identity_bytes = cache_kind == "tunnel"
        and (#tostring(entry.requestId or "")
          + #tostring(entry.line or "")
          + #tostring(entry.idempotencyKey or ""))
        or #tostring(entry.command or "")
      local previous_bytes = tonumber(entry.retainedBytes) or 0
      local retained_bytes = BMF_socket_replay_record_bytes(cached_record, identity_bytes)
      if retained_bytes < previous_bytes then
        entry.record = cached_record
        entry.retainedBytes = retained_bytes
        cache.completed_retained_bytes = math.max(
          0,
          (tonumber(cache.completed_retained_bytes) or 0) - (previous_bytes - retained_bytes))
        cache.completed_response_omitted = (tonumber(cache.completed_response_omitted) or 0) + 1
        compacted = compacted + 1
      end
    end
  end
  return compacted
end

function BMF_socket_replay_evict_oldest(cache, clear_idempotency)
  if type(cache.completed_order) ~= "table" or #cache.completed_order == 0 then
    return false
  end
  local expired_id = table.remove(cache.completed_order, 1)
  local expired_entry = cache.completed_by_id and cache.completed_by_id[expired_id] or nil
  if cache.completed_by_id then
    cache.completed_by_id[expired_id] = nil
  end
  if expired_entry ~= nil then
    cache.completed_retained_bytes = math.max(
      0,
      (tonumber(cache.completed_retained_bytes) or 0) - (tonumber(expired_entry.retainedBytes) or 0))
    cache.completed_evicted = (tonumber(cache.completed_evicted) or 0) + 1
    if clear_idempotency == true
        and expired_entry.idempotencyKey ~= ""
        and cache.completed_by_idempotency_key
        and cache.completed_by_idempotency_key[expired_entry.idempotencyKey] == expired_entry then
      cache.completed_by_idempotency_key[expired_entry.idempotencyKey] = nil
    end
  end
  return true
end

function BMF_socket_scheduler_remember_direct_result(request, record)
  local admission = state.socket_admission
  local request_id = trim_string(request and request.id or "")
  if request_id == "" then
    return
  end
  local previous = admission.completed_by_id[request_id]
  if previous == nil then
    admission.completed_order[#admission.completed_order + 1] = request_id
  else
    admission.completed_retained_bytes = math.max(
      0,
      (tonumber(admission.completed_retained_bytes) or 0) - (tonumber(previous.retainedBytes) or 0))
  end
  local command = tostring(request.command or "")
  local max_bytes = math.max(
    65536,
    tonumber(admission.completed_max_bytes) or SOCKET_ADMISSION_DEFAULTS.completed_max_bytes)
  local cached_record, retained_bytes, response_omitted = BMF_socket_replay_record_for_cache(
    record,
    max_bytes,
    #command)
  admission.completed_by_id[request_id] = {
    command = command,
    record = cached_record,
    retainedBytes = retained_bytes,
  }
  admission.completed_retained_bytes = (tonumber(admission.completed_retained_bytes) or 0) + retained_bytes
  admission.completed_peak_bytes = math.max(
    tonumber(admission.completed_peak_bytes) or 0,
    admission.completed_retained_bytes)
  if response_omitted then
    admission.completed_response_omitted = (tonumber(admission.completed_response_omitted) or 0) + 1
  end
  local retention = math.max(16, tonumber(admission.completed_retention) or SOCKET_ADMISSION_DEFAULTS.completed_retention)
  while #admission.completed_order > retention do
    BMF_socket_replay_evict_oldest(admission, false)
  end
  BMF_socket_replay_compact_cache_to_budget(admission, max_bytes, "direct")
  while (tonumber(admission.completed_retained_bytes) or 0) > max_bytes do
    if not BMF_socket_replay_evict_oldest(admission, false) then
      break
    end
  end
end

function BMF_socket_scheduler_send_direct_terminal(request, result_state, code, detail, response, command_ok)
  if type(request) ~= "table" then
    return nil, false
  end
  if request.terminalSent == true then
    return request.terminalRecord, false
  end

  local normalized_state = tostring(result_state or "rejected")
  BMF_operation_finish(request.operationContext, normalized_state)
  local record = {
    type = "response",
    source = "bmf",
    ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    id = trim_string(request.id or ""),
    ok = command_ok == true,
    state = normalized_state,
    code = tostring(code or "UNKNOWN"),
    detail = tostring(detail or ""),
    response = type(response) == "string" and response or nil,
  }

  -- Mark terminal before attempting transport. A send failure may be replayed
  -- by request ID, but the command is never dispatched again in this process.
  request.terminalSent = true
  request.terminalRecord = record
  if state.socket_admission.active_by_id[record.id] == request then
    state.socket_admission.active_by_id[record.id] = nil
  end
  BMF_socket_scheduler_remember_direct_result(request, record)
  local sent = BMF_socket_scheduler_send_direct_json(record)
  BMF_socket_scheduler_record_terminal("direct_socket", normalized_state, sent)
  return record, sent
end

function BMF_socket_scheduler_reject_direct(request_id, command_text, result_state, code, detail, admission_outcome)
  local request = {
    id = trim_string(request_id or ""),
    command = tostring(command_text or ""),
  }
  BMF_socket_scheduler_record_admission_outcome(
    "direct_socket",
    admission_outcome or (result_state == "expired" and "expired" or "rejected"))
  if request.id == "" then
    state.socket.last_error = tostring(code or "INVALID_REQUEST") .. ": " .. tostring(detail or "")
    return false
  end
  BMF_socket_scheduler_send_direct_terminal(
    request,
    result_state or "rejected",
    code or "INVALID_REQUEST",
    detail or "direct socket request was rejected",
    nil,
    false)
  return false
end

function BMF_socket_scheduler_admit_direct(decoded)
  local admission = state.socket_admission
  local request_id = trim_string(decoded and decoded.id or "")
  local command_text = trim_string(decoded and decoded.command or "")
  if request_id == "" or #request_id > 128 then
    return BMF_socket_scheduler_reject_direct(
      request_id,
      command_text,
      "rejected",
      "INVALID_ID",
      "id must contain 1-128 bytes")
  end

  local active = admission.active_by_id[request_id]
  if active ~= nil then
    BMF_socket_scheduler_record_duplicate("direct_socket", "active")
    BMF_socket_scheduler_send_direct_json({
      type = "command.ack",
      source = "bmf",
      ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
      id = request_id,
      state = active.command == command_text and "accepted" or "conflict",
      duplicate = true,
      queueDepth = BMF_socket_scheduler_total_depth(),
    })
    return false
  end

  local completed = admission.completed_by_id[request_id]
  if completed ~= nil then
    BMF_socket_scheduler_record_duplicate("direct_socket", "completed")
    if completed.command == command_text then
      local replay = copy_table(completed.record)
      replay.replayed = true
      BMF_socket_scheduler_send_direct_json(replay)
      return false
    end
    BMF_socket_scheduler_send_direct_json({
      type = "command.ack",
      source = "bmf",
      ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
      id = request_id,
      state = "conflict",
      duplicate = true,
      queueDepth = BMF_socket_scheduler_total_depth(),
    })
    return false
  end

  if command_text == "" then
    return BMF_socket_scheduler_reject_direct(
      request_id,
      command_text,
      "rejected",
      "INVALID_COMMAND",
      "command must be non-empty")
  end
  if #command_text > admission.max_command_bytes then
    return BMF_socket_scheduler_reject_direct(
      request_id,
      command_text,
      "rejected",
      "COMMAND_TOO_LARGE",
      "command exceeds configured byte limit")
  end

  local service_class = tostring(decoded.serviceClass or "interactive"):lower()
  if service_class ~= "interactive" and service_class ~= "bulk" then
    return BMF_socket_scheduler_reject_direct(
      request_id,
      command_text,
      "rejected",
      "INVALID_SERVICE_CLASS",
      "serviceClass must be interactive or bulk")
  end

  local now_ms = os.time() * 1000
  local supplied_issued_at_ms = tonumber(decoded.issuedAtMs)
  local supplied_deadline_ms = tonumber(decoded.deadlineMs)
  if admission.enabled == true
      and ((supplied_issued_at_ms or 0) <= 0 or (supplied_deadline_ms or 0) <= 0) then
    return BMF_socket_scheduler_reject_direct(
      request_id,
      command_text,
      "rejected",
      "DEADLINE_REQUIRED",
      "positive issuedAtMs and absolute deadlineMs are required while bounded admission is enabled",
      "rejected")
  end
  local issued_at_ms = supplied_issued_at_ms or now_ms
  local deadline_ms = supplied_deadline_ms or (issued_at_ms + admission.default_deadline_ms)
  if deadline_ms <= issued_at_ms
      or BMF_socket_scheduler_deadline_expired(deadline_ms, issued_at_ms, nil) then
    return BMF_socket_scheduler_reject_direct(
      request_id,
      command_text,
      "expired",
      "DEADLINE_EXPIRED",
      "absolute deadlineMs has elapsed",
      "expired")
  end

  local queue = admission.direct_queues[service_class]
  local class_limit = service_class == "bulk"
    and admission.max_direct_bulk_queue
    or admission.max_direct_interactive_queue
  if BMF_socket_scheduler_total_depth() >= admission.max_queue
      or admission.direct_queued_count >= admission.max_direct_queue
      or #queue >= class_limit then
    return BMF_socket_scheduler_reject_direct(
      request_id,
      command_text,
      "rejected",
      "QUEUE_FULL",
      "bounded unified socket admission queue is full",
      "dropped")
  end

  local retained_bytes = #request_id + #command_text
  if (BMF_socket_scheduler_total_bytes() + retained_bytes) > admission.max_bytes then
    return BMF_socket_scheduler_reject_direct(
      request_id,
      command_text,
      "rejected",
      "QUEUE_BYTES_FULL",
      "bounded unified socket admission byte budget is full",
      "dropped")
  end

  local request = {
    id = request_id,
    command = command_text,
    serviceClass = service_class,
    issuedAtMs = issued_at_ms,
    deadlineMs = deadline_ms,
    acceptedAtMs = now_ms,
    acceptedClock = os.clock(),
    retainedBytes = retained_bytes,
    executionStarted = false,
    terminalSent = false,
  }
  request.operationContext = BMF_operation_begin(
    BMF_operation_class_from_text(command_text, "unknown"),
    "direct_socket",
    request)
  BMF_operation_update_stage(request.operationContext, "queued")
  queue[#queue + 1] = request
  admission.active_by_id[request_id] = request
  admission.direct_queued_count = admission.direct_queued_count + 1
  admission.direct_queued_bytes = admission.direct_queued_bytes + retained_bytes
  admission.direct_peak_depth = math.max(admission.direct_peak_depth, admission.direct_queued_count)
  admission.direct_peak_interactive_depth = math.max(
    admission.direct_peak_interactive_depth,
    #admission.direct_queues.interactive)
  admission.direct_peak_bulk_depth = math.max(
    admission.direct_peak_bulk_depth,
    #admission.direct_queues.bulk)
  BMF_socket_scheduler_record_admission("direct_socket")
  return true
end

function BMF_socket_scheduler_lane_queue(path, service_class)
  local normalized_class = service_class == "bulk" and "bulk" or "interactive"
  if path == "tunnel" then
    return state.game_command_tunnel.queues[normalized_class]
  end
  return state.socket_admission.direct_queues[normalized_class]
end

function BMF_socket_scheduler_select_next_lane()
  local admission = state.socket_admission
  local slot_count = #SOCKET_ADMISSION_FAIRNESS_SLOTS
  local start_index = math.max(1, math.min(slot_count, tonumber(admission.fairness_cursor) or 1))
  for offset = 0, slot_count - 1 do
    local index = ((start_index + offset - 1) % slot_count) + 1
    local slot = SOCKET_ADMISSION_FAIRNESS_SLOTS[index]
    local path, service_class = slot:match("^([^:]+):(.+)$")
    local tunnel_eligible = path ~= "tunnel"
      or math.max(0, tonumber(state.game_command_tunnel.cooldown_ticks) or 0) == 0
    local queue = BMF_socket_scheduler_lane_queue(path, service_class)
    if tunnel_eligible and type(queue) == "table" and #queue > 0 then
      admission.fairness_cursor = (index % slot_count) + 1
      return path, service_class
    end
  end
  return nil, nil
end

function BMF_socket_scheduler_dequeue_direct(service_class)
  local admission = state.socket_admission
  local queue = admission.direct_queues[service_class == "bulk" and "bulk" or "interactive"]
  local request = table.remove(queue, 1)
  if request ~= nil then
    admission.direct_queued_count = math.max(0, admission.direct_queued_count - 1)
    admission.direct_queued_bytes = math.max(
      0,
      admission.direct_queued_bytes - (tonumber(request.retainedBytes) or 0))
  end
  return request
end

function BMF_socket_scheduler_execute_direct(request)
  if type(request) ~= "table" then
    return false
  end
  if BMF_socket_scheduler_deadline_expired(
      request.deadlineMs,
      request.issuedAtMs,
      request.acceptedClock) then
    BMF_socket_scheduler_send_direct_terminal(
      request,
      "expired",
      "DEADLINE_EXPIRED",
      "request deadline elapsed before command dispatch",
      nil,
      false)
    return true
  end

  local work_started_clock = os.clock()
  request.executionStarted = true
  BMF_operation_start_execution(request.operationContext)
  local processing_ok, response, command_ok, detail = pcall(
    BMF_dispatch_bmf_command_text,
    request.id,
    request.command,
    "socket",
    request.operationContext)
  if processing_ok then
    local result_state = command_ok == true and "completed" or "failed"
    local result_code = command_ok == true and "OK" or "COMMAND_FAILED"
    BMF_socket_scheduler_send_direct_terminal(
      request,
      result_state,
      result_code,
      detail,
      response,
      command_ok)
  else
    local elapsed_exact_ms = math.max(0, (os.clock() - work_started_clock) * 1000)
    BMF_socket_scheduler_record_work(
      "direct_socket",
      math.floor(elapsed_exact_ms + 0.5),
      false,
      elapsed_exact_ms)
    BMF_socket_scheduler_send_direct_terminal(
      request,
      "outcome_unknown",
      "DISPATCH_OUTCOME_UNKNOWN",
      "direct command dispatch failed after execution began: " .. tostring(response),
      nil,
      false)
  end
  return true
end

function BMF_socket_scheduler_note_tunnel_tick()
  local tunnel = state.game_command_tunnel
  tunnel.worker_ticks = (tonumber(tunnel.worker_ticks) or 0) + 1
  local guard = state.reserved_chat_command_guard
  if type(guard) == "table"
      and guard.enabled == true
      and guard.installed ~= true
      and (tunnel.worker_ticks == 1 or (tunnel.worker_ticks % 40) == 1) then
    BMF_install_reserved_chat_command_guard()
  end
  if (tunnel.worker_ticks % 40) == 1 then
    tunnel.last_worker_tick_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  end
  local cooldown_ticks = math.max(0, tonumber(tunnel.cooldown_ticks) or 0)
  if cooldown_ticks > 0 then
    tunnel.cooldown_ticks = cooldown_ticks - 1
  end
end

function BMF_socket_scheduler_execute_one()
  local admission = state.socket_admission
  if admission.running == true then
    return nil
  end
  BMF_socket_scheduler_note_tunnel_tick()
  local path, service_class = BMF_socket_scheduler_select_next_lane()
  if path == nil then
    state.game_command_tunnel.worker_idle_ticks =
      (tonumber(state.game_command_tunnel.worker_idle_ticks) or 0) + 1
    return nil
  end

  admission.running = true
  local selected_request = nil
  local execution_ok, execution_error = pcall(function()
    BMF_socket_scheduler_record_fairness(path, service_class)
    if path == "tunnel" then
      selected_request = BMF_game_command_tunnel_dequeue(service_class)
      if selected_request ~= nil then
        BMF_game_command_tunnel_drain_once(selected_request)
        local poll_ms = math.max(1, tonumber(state.socket.poll_interval_ms) or SOCKET_DEFAULT_POLL_MS)
        local interval_ms = math.max(
          1,
          tonumber(state.game_command_tunnel.interval_ms) or GAME_COMMAND_TUNNEL_DEFAULT_INTERVAL_MS)
        state.game_command_tunnel.cooldown_ticks = math.max(1, math.ceil(interval_ms / poll_ms))
      end
    else
      selected_request = BMF_socket_scheduler_dequeue_direct(service_class)
      BMF_socket_scheduler_execute_direct(selected_request)
    end
  end)
  admission.running = false
  if not execution_ok then
    state.socket.last_error = "unified socket scheduler failed: " .. tostring(execution_error)
    if path == "direct_socket"
        and type(selected_request) == "table"
        and selected_request.terminalSent ~= true then
      BMF_socket_scheduler_send_direct_terminal(
        selected_request,
        selected_request.executionStarted == true and "outcome_unknown" or "rejected",
        selected_request.executionStarted == true and "SCHEDULER_OUTCOME_UNKNOWN" or "SCHEDULER_FAILED",
        state.socket.last_error,
        nil,
        false)
    end
    return nil
  end
  return path
end

function BMF_socket_scheduler_fail_closed(detail)
  local admission = state.socket_admission
  local failure_detail = tostring(detail or "unified socket scheduler is unavailable")
  for _, service_class in ipairs({ "interactive", "bulk" }) do
    while #(admission.direct_queues[service_class] or {}) > 0 do
      local request = BMF_socket_scheduler_dequeue_direct(service_class)
      BMF_socket_scheduler_send_direct_terminal(
        request,
        "rejected",
        "SCHEDULER_UNAVAILABLE",
        failure_detail,
        nil,
        false)
    end
    while #(state.game_command_tunnel.queues[service_class] or {}) > 0 do
      local request = BMF_game_command_tunnel_dequeue(service_class)
      BMF_game_command_tunnel_send_terminal(
        request,
        "rejected",
        "SCHEDULER_UNAVAILABLE",
        failure_detail,
        nil,
        0)
    end
  end
end

function BMF_reserved_chat_command_guard_snapshot()
  local guard = state.reserved_chat_command_guard or {}
  if type(BMFSocketReservedChatGuardStatus) == "function" then
    local ok, response = pcall(BMFSocketReservedChatGuardStatus)
    if ok then
      local _, fields = parse_key_value_lines(response)
      guard.native_available = tostring(fields.available or "") == "true"
      guard.installed = tostring(fields.installed or "") == "true"
      guard.source = tostring(fields.source or guard.source or "")
      guard.denied = tonumber(fields.denied) or 0
      guard.inspection_failures = tonumber(fields.inspection_failures) or 0
      guard.target = tostring(fields.target or "")
      guard.last_denied_command = tostring(fields.last_command or "")
      guard.last_error = tostring(fields.last_error or "")
    else
      guard.native_available = false
      guard.installed = false
      guard.last_error = "BMFSocketReservedChatGuardStatus failed: " .. tostring(response)
    end
  else
    guard.native_available = false
    guard.installed = false
    guard.last_error = "BMFSocketReservedChatGuardStatus is unavailable"
  end
  return {
    enabled = guard.enabled == true,
    nativeAvailable = guard.native_available == true,
    installed = guard.installed == true,
    source = tostring(guard.source or ""),
    installAttempts = tonumber(guard.install_attempts) or 0,
    maxInstallAttempts = tonumber(guard.max_install_attempts) or 0,
    denied = tonumber(guard.denied) or 0,
    inspectionFailures = tonumber(guard.inspection_failures) or 0,
    target = tostring(guard.target or ""),
    lastDeniedCommand = tostring(guard.last_denied_command or ""),
    lastError = tostring(guard.last_error or ""),
    policy = "deny-player-allow-authenticated-tunnel",
    trustedTransport = "bmf-tunnel/1 direct implementation call",
  }
end

function BMF_install_reserved_chat_command_guard()
  local guard = state.reserved_chat_command_guard
  if type(guard) ~= "table" or guard.enabled ~= true or guard.installed == true then
    return guard and guard.installed == true
  end
  local max_attempts = tonumber(guard.max_install_attempts) or 0
  if max_attempts > 0 and (tonumber(guard.install_attempts) or 0) >= max_attempts then
    return false
  end
  guard.install_attempts = (tonumber(guard.install_attempts) or 0) + 1
  if type(BMFSocketReservedChatGuardInstall) ~= "function" then
    guard.native_available = false
    guard.last_error = "BMFSocketReservedChatGuardInstall is unavailable"
    return false
  end

  local ok, native_ok, response = pcall(BMFSocketReservedChatGuardInstall)
  if not ok then
    guard.native_available = false
    guard.installed = false
    guard.last_error = "BMFSocketReservedChatGuardInstall failed: " .. tostring(native_ok)
    return false
  end

  local _, fields = parse_key_value_lines(response)
  guard.native_available = tostring(fields.available or "") == "true"
  guard.installed = native_ok == true and tostring(fields.installed or "") == "true"
  guard.source = tostring(fields.source or guard.source or "")
  guard.denied = tonumber(fields.denied) or tonumber(guard.denied) or 0
  guard.inspection_failures = tonumber(fields.inspection_failures) or tonumber(guard.inspection_failures) or 0
  guard.target = tostring(fields.target or "")
  guard.last_denied_command = tostring(fields.last_command or "")
  guard.last_error = tostring(fields.last_error or fields.detail or "")
  if not guard.installed then
    return false
  end

  log("info", "reserved CityRPG chat command native guard installed target=" .. tostring(guard.target))
  audit_record("chat.reserved_command.guard_installed", {
    source = guard.source,
    target = guard.target,
  }, {
    source = "framework",
    severity = "info",
    ok = true,
    code = "OK",
  })
  return true
end

