local function BMF_game_command_tunnel_send_json(record)
  local sent = BMF_socket_send_json(record)
  if sent then
    state.socket.sent_responses = (tonumber(state.socket.sent_responses) or 0) + 1
  end
  return sent
end

local function BMF_game_command_tunnel_remember_result(record, request)
  local tunnel = state.game_command_tunnel
  local request_id = trim_string(record and record.id or "")
  if request_id == "" then
    return
  end
  local previous = tunnel.completed_by_id[request_id]
  if previous == nil then
    tunnel.completed_order[#tunnel.completed_order + 1] = request_id
  else
    if previous.idempotencyKey ~= ""
        and tunnel.completed_by_idempotency_key[previous.idempotencyKey] == previous then
      tunnel.completed_by_idempotency_key[previous.idempotencyKey] = nil
    end
    tunnel.completed_retained_bytes = math.max(
      0,
      (tonumber(tunnel.completed_retained_bytes) or 0) - (tonumber(previous.retainedBytes) or 0))
  end
  local line = trim_string(request and request.line or "")
  local idempotency_key = trim_string(request and request.idempotencyKey or "")
  local sender_uuid = trim_string(request and request.senderUuid or ""):lower()
  local sender_name = trim_string(request and request.senderName or "")
  local operation_type = trim_string(request and request.operationType or "")
  local max_bytes = math.max(
    65536,
    tonumber(tunnel.completed_max_bytes) or GAME_COMMAND_TUNNEL_COMPLETED_DEFAULT_MAX_BYTES)
  local cached_record, retained_bytes, response_omitted = BMF_socket_replay_record_for_cache(
    record,
    max_bytes,
    #request_id + #line + #idempotency_key + #sender_uuid + #sender_name + #operation_type)
  local entry = {
    record = cached_record,
    requestId = request_id,
    line = line,
    idempotencyKey = idempotency_key,
    senderUuid = sender_uuid,
    senderName = sender_name,
    connectionGeneration = tonumber(request and request.connectionGeneration) or 0,
    operationType = operation_type,
    acceptedAtMs = tonumber(request and request.acceptedAtMs) or 0,
    retainedBytes = retained_bytes,
  }
  tunnel.completed_by_id[request_id] = entry
  tunnel.completed_retained_bytes = (tonumber(tunnel.completed_retained_bytes) or 0) + retained_bytes
  tunnel.completed_peak_bytes = math.max(
    tonumber(tunnel.completed_peak_bytes) or 0,
    tunnel.completed_retained_bytes)
  if response_omitted then
    tunnel.completed_response_omitted = (tonumber(tunnel.completed_response_omitted) or 0) + 1
  end
  if entry.idempotencyKey ~= "" then
    tunnel.completed_by_idempotency_key[entry.idempotencyKey] = entry
  end
  local retention = math.max(1, tonumber(tunnel.completed_retention) or GAME_COMMAND_TUNNEL_COMPLETED_RETENTION)
  while #tunnel.completed_order > retention do
    BMF_socket_replay_evict_oldest(tunnel, true)
  end
  BMF_socket_replay_compact_cache_to_budget(tunnel, max_bytes, "tunnel")
  while (tonumber(tunnel.completed_retained_bytes) or 0) > max_bytes do
    if not BMF_socket_replay_evict_oldest(tunnel, true) then
      break
    end
  end
end

BMF_game_command_tunnel_send_terminal = function(request, result_state, code, detail, response, dispatch_ms)
  local tunnel = state.game_command_tunnel
  if type(request) ~= "table" then
    return nil
  end
  if request.terminalSent == true then
    return request.terminalRecord
  end
  local request_id = trim_string(request and request.id or "")
  local normalized_state = tostring(result_state or "rejected")
  BMF_operation_finish(request.operationContext, normalized_state)
  local record = {
    type = "tunnel.result",
    source = "bmf",
    v = tonumber(tunnel.protocol_version) or 1,
    ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    id = request_id,
    state = normalized_state,
    code = tostring(code or "UNKNOWN"),
    detail = tostring(detail or ""),
    response = type(response) == "string" and response or nil,
    senderUuid = trim_string(request.senderUuid or ""):lower(),
    senderName = trim_string(request.senderName or ""),
    connectionGeneration = tonumber(request.connectionGeneration) or 0,
    operationType = trim_string(request.operationType or ""),
    acceptedAtMs = tonumber(request.acceptedAtMs) or 0,
    dispatchMs = tonumber(dispatch_ms) or 0,
    queueDepth = tonumber(tunnel.queued_count) or 0,
  }

  -- Commit terminal ownership before transport so a send or cleanup failure
  -- cannot cause the same accepted side effect to emit a second terminal.
  request.terminalSent = true
  request.terminalRecord = record
  local active_request = tunnel.active_by_id[request_id]
  tunnel.active_by_id[request_id] = nil
  local idempotency_key = trim_string(request and request.idempotencyKey or "")
  if idempotency_key ~= "" and tunnel.active_by_idempotency_key[idempotency_key] == active_request then
    tunnel.active_by_idempotency_key[idempotency_key] = nil
  end
  tunnel.last_result_state = normalized_state
  tunnel.last_result_code = record.code
  if normalized_state == "injected" then
    tunnel.injected = (tonumber(tunnel.injected) or 0) + 1
  elseif normalized_state == "expired" then
    tunnel.expired = (tonumber(tunnel.expired) or 0) + 1
  elseif normalized_state == "outcome_unknown" then
    tunnel.outcome_unknown = (tonumber(tunnel.outcome_unknown) or 0) + 1
  else
    tunnel.rejected = (tonumber(tunnel.rejected) or 0) + 1
  end

  BMF_game_command_tunnel_remember_result(record, request)
  local sent = BMF_game_command_tunnel_send_json(record)
  BMF_socket_scheduler_record_terminal("tunnel", normalized_state, sent)
  if not sent then
    tunnel.last_error = "failed to send terminal result id=" .. request_id .. " state=" .. normalized_state
  end
  return record
end

local function BMF_game_command_tunnel_send_rejection(request_id, result_state, code, detail, identity)
  local tunnel = state.game_command_tunnel
  local normalized_id = trim_string(request_id or "")
  if normalized_id == "" then
    state.game_command_tunnel.last_error = tostring(code or "INVALID_REQUEST") .. ": " .. tostring(detail or "")
    return false
  end
  local normalized_state = tostring(result_state or "rejected")
  if normalized_state == "expired" then
    tunnel.expired = (tonumber(tunnel.expired) or 0) + 1
    BMF_socket_scheduler_record_admission_outcome("tunnel", "expired")
  else
    tunnel.rejected = (tonumber(tunnel.rejected) or 0) + 1
    local normalized_code = tostring(code or "")
    local dropped = normalized_code == "QUEUE_FULL"
      or normalized_code == "SERVICE_CLASS_FULL"
      or normalized_code == "QUEUE_BYTES_FULL"
    BMF_socket_scheduler_record_admission_outcome("tunnel", dropped and "dropped" or "rejected")
  end
  tunnel.last_result_state = normalized_state
  tunnel.last_result_code = tostring(code or "UNKNOWN")
  local sent = BMF_game_command_tunnel_send_json({
    type = "tunnel.result",
    source = "bmf",
    v = tonumber(tunnel.protocol_version) or 1,
    ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    id = normalized_id,
    state = normalized_state,
    code = tostring(code or "UNKNOWN"),
    detail = tostring(detail or ""),
    senderUuid = trim_string(identity and identity.senderUuid or ""):lower(),
    senderName = trim_string(identity and identity.senderName or ""),
    connectionGeneration = tonumber(identity and identity.connectionGeneration) or 0,
    operationType = trim_string(identity and identity.operationType or ""),
    acceptedAtMs = tonumber(identity and identity.acceptedAtMs) or 0,
    dispatchMs = 0,
    queueDepth = tonumber(tunnel.queued_count) or 0,
  })
  BMF_socket_scheduler_record_terminal("tunnel", normalized_state, sent)
  return false
end

local function BMF_game_command_tunnel_line_allowed(line)
  local normalized = trim_string(line or ""):lower()
  return normalized == "/cityrpgremote"
    or normalized:match("^/cityrpgremote%s") ~= nil
    or normalized == "/cityrpgroute"
    or normalized:match("^/cityrpgroute%s") ~= nil
    or normalized == "/cityrpgpositionsnapshot"
    or normalized:match("^/cityrpgpositionsnapshot%s") ~= nil
end

function BMF_game_command_tunnel_identity_operation(request)
  return {
    requestId = trim_string(request and request.id or ""),
    senderUuid = trim_string(request and request.senderUuid or ""):lower(),
    senderName = trim_string(request and request.senderName or ""),
    connectionGeneration = tonumber(request and request.connectionGeneration) or 0,
    acceptedAtMs = tonumber(request and request.acceptedAtMs) or 0,
    absoluteDeadlineMs = tonumber(request and request.deadlineMs) or 0,
    operationType = trim_string(request and request.operationType or ""),
  }
end

function BMF_game_command_tunnel_requeue(request)
  if type(request) ~= "table" or request.terminalSent == true then return false end
  local tunnel = state.game_command_tunnel
  local queue = tunnel.queues[request.serviceClass]
  if type(queue) ~= "table" then return false end
  queue[#queue + 1] = request
  tunnel.queued_count = (tonumber(tunnel.queued_count) or 0) + 1
  tunnel.queued_bytes = (tonumber(tunnel.queued_bytes) or 0)
    + (tonumber(request.retainedBytes) or tonumber(request.lineBytes) or 0)
  tunnel.scheduled = true
  return true
end

function BMF_game_command_tunnel_wake_sessions(players)
  local tunnel = state.game_command_tunnel
  local sessions = {}
  for _, player in ipairs(type(players) == "table" and players or {}) do
    if type(player) == "table" then
      local uuid = trim_string(tostring(
        player.uuid or player.id or player.playerId or "")):lower()
      local generation = tonumber(player.connectionGeneration) or 0
      if uuid ~= "" and generation >= 1 and generation % 1 == 0
          and trim_string(tostring(player.controllerPath or "")) ~= ""
          and trim_string(tostring(player.playerStatePath or "")) ~= "" then
        sessions[uuid .. ":" .. tostring(generation)] = true
      end
    end
  end
  if next(sessions) == nil then return 0 end
  local woken = 0
  for _, queue in pairs(tunnel.queues or {}) do
    for _, request in ipairs(queue or {}) do
      local request_key = tostring(request.senderUuid or ""):lower()
        .. ":" .. tostring(tonumber(request.connectionGeneration) or 0)
      if sessions[request_key] == true
          and (tonumber(request.readinessNotBeforeTick) or 0) > 0 then
        request.readinessNotBeforeTick = 0
        woken = woken + 1
      end
    end
  end
  if woken > 0 then
    tunnel.readiness_event_wakeups =
      (tonumber(tunnel.readiness_event_wakeups) or 0) + woken
    tunnel.cooldown_ticks = 0
    tunnel.scheduled = true
  end
  return woken
end

function BMF_game_command_tunnel_defer_retry(request, retry_detail)
  if type(request) ~= "table" then return false end
  local tunnel = state.game_command_tunnel
  local retries = (tonumber(request.readinessRetryCount) or 0) + 1
  request.readinessRetryCount = retries
  local base_ms = math.max(
    100,
    tonumber(tunnel.readiness_retry_base_ms)
      or GAME_COMMAND_TUNNEL_DEFAULT_READINESS_RETRY_BASE_MS)
  local max_ms = math.max(
    base_ms,
    tonumber(tunnel.readiness_retry_max_ms)
      or GAME_COMMAND_TUNNEL_DEFAULT_READINESS_RETRY_MAX_MS)
  local exponential_ms = math.min(
    max_ms,
    base_ms * (2 ^ math.min(8, math.max(0, retries - 1))))
  local requested_ms = type(retry_detail) == "table"
    and math.max(0, tonumber(retry_detail.retryAfterMs) or 0)
    or 0
  local delay_ms = math.min(max_ms, math.max(exponential_ms, requested_ms))
  local poll_ms = math.max(
    1,
    tonumber(state.socket.poll_interval_ms) or SOCKET_DEFAULT_POLL_MS)
  request.readinessNotBeforeTick =
    (tonumber(tunnel.worker_ticks) or 0) + math.max(1, math.ceil(delay_ms / poll_ms))
  request.lastReadinessDelayMs = delay_ms
  tunnel.readiness_retries = (tonumber(tunnel.readiness_retries) or 0) + 1
  tunnel.max_readiness_retries_per_request = math.max(
    tonumber(tunnel.max_readiness_retries_per_request) or 0,
    retries)
  return true
end

function BMF_game_command_tunnel_readiness_probe(request)
  local tunnel = state.game_command_tunnel
  tunnel.readiness_probes = (tonumber(tunnel.readiness_probes) or 0) + 1
  local uuid = trim_string(request and request.senderUuid or ""):lower()
  local generation = tonumber(request and request.connectionGeneration) or 0
  local target, _, resolve_reason, resolve_detail = live_chat_resolve_authoritative_name_target({
    uuid = uuid,
    senderName = request and request.senderName,
    connectionGeneration = generation,
  })
  if target == nil then
    local code = "STRICT_TARGET_" .. tostring(resolve_reason or "unavailable"):upper()
    BMFConnectionReadiness.note_check(
      state.connection_readiness,
      uuid,
      generation,
      false,
      code,
      os.time() * 1000)
    tunnel.last_readiness_code = code
    return false, "", code,
      "exact UUID, current name, and connection generation are not currently resolvable",
      resolve_detail
  end

  local controller_address = type(live_chat_object_key) == "function"
    and trim_string(live_chat_object_key(target.controller, ""))
    or ""
  if controller_address == "" then
    local code = "CONTROLLER_ADDRESS_UNAVAILABLE"
    BMFConnectionReadiness.note_check(
      state.connection_readiness, uuid, generation, false, code, os.time() * 1000)
    tunnel.last_readiness_code = code
    return false, "", code, "exact controller address is unavailable"
  end
  if type(BMFSocketPlayerChatMessageImplementationReadiness) ~= "function" then
    local code = "NATIVE_READINESS_HELPER_UNAVAILABLE"
    BMFConnectionReadiness.note_check(
      state.connection_readiness, uuid, generation, false, code, os.time() * 1000)
    tunnel.last_readiness_code = code
    return false, "", code, "side-effect-free native readiness helper is unavailable"
  end

  local probe_ok, probe_text = pcall(
    BMFSocketPlayerChatMessageImplementationReadiness,
    controller_address,
    "player-chat-message-implementation-readiness")
  local _, fields = parse_key_value_lines(probe_ok and probe_text or tostring(probe_text))
  local ready = probe_ok
    and tostring(fields.ok or ""):lower() == "true"
    and tostring(fields.stage or "") == "native_callable"
    and tostring(fields.side_effect_free or ""):lower() == "true"
    and tostring(fields.controller_hint_matched or ""):lower() == "true"
    and tonumber(fields.controller_scanned) == 0
  local code = ready and "NATIVE_CALLABLE"
    or ("NATIVE_NOT_CALLABLE_" .. tostring(fields.stage or (probe_ok and "unknown" or "exception")):upper())
  BMFConnectionReadiness.note_check(
    state.connection_readiness,
    uuid,
    generation,
    ready,
    code,
    os.time() * 1000)
  tunnel.last_readiness_code = code
  return ready, ready and controller_address or "", code,
    tostring(fields.detail or (probe_ok and "native callable proof failed" or probe_text))
end

function BMF_game_command_tunnel_readiness_retryable(code)
  local normalized = tostring(code or "")
  return normalized == "STRICT_TARGET_EXACT_NAME_REPAIR_DEFERRED"
    or normalized:find("^NATIVE_NOT_CALLABLE_") ~= nil
end

function BMF_game_command_tunnel_acknowledge(request)
  if request.admissionSent == true then return true end
  local tunnel = state.game_command_tunnel
  local sent = BMF_game_command_tunnel_send_json({
    type = "tunnel.ack",
    source = "bmf",
    v = tonumber(tunnel.protocol_version) or 1,
    ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    id = request.id,
    state = "accepted",
    senderUuid = request.senderUuid,
    senderName = request.senderName,
    connectionGeneration = request.connectionGeneration,
    operationType = request.operationType,
    acceptedAtMs = request.acceptedAtMs,
    queueDepth = tonumber(tunnel.queued_count) or 0,
  })
  if not sent then
    tunnel.readiness_ack_failures = (tonumber(tunnel.readiness_ack_failures) or 0) + 1
    tunnel.last_readiness_code = "ACK_SEND_FAILED"
    return false
  end
  request.admissionSent = true
  request.brokerAcceptedAtMs = os.time() * 1000
  request.acceptedClock = os.clock()
  request.operationContext = BMF_operation_begin(request.operationType, "tunnel", request)
  BMF_operation_update_stage(request.operationContext, "native_callable")
  tunnel.accepted = (tonumber(tunnel.accepted) or 0) + 1
  BMF_socket_scheduler_record_admission("tunnel")
  return true
end

BMF_game_command_tunnel_dequeue = function(service_class)
  local tunnel = state.game_command_tunnel
  local interactive = tunnel.queues.interactive
  local bulk = tunnel.queues.bulk
  local request = nil

  if service_class == "interactive" then
    request = table.remove(interactive, 1)
  elseif service_class == "bulk" then
    request = table.remove(bulk, 1)
  elseif #interactive > 0 and (#bulk == 0 or tunnel.interactive_since_bulk < tunnel.interactive_burst) then
    request = table.remove(interactive, 1)
    tunnel.interactive_since_bulk = (tonumber(tunnel.interactive_since_bulk) or 0) + 1
  elseif #bulk > 0 then
    request = table.remove(bulk, 1)
    tunnel.interactive_since_bulk = 0
  elseif #interactive > 0 then
    request = table.remove(interactive, 1)
    tunnel.interactive_since_bulk = (tonumber(tunnel.interactive_since_bulk) or 0) + 1
  end

  if request ~= nil then
    tunnel.queued_count = math.max(0, (tonumber(tunnel.queued_count) or 0) - 1)
    tunnel.queued_bytes = math.max(0, (tonumber(tunnel.queued_bytes) or 0) - (tonumber(request.retainedBytes) or tonumber(request.lineBytes) or 0))
  end
  return request
end

local function BMF_game_command_tunnel_request_expired(request)
  local deadline_at_ms = tonumber(request and request.deadlineMs) or 0
  if deadline_at_ms <= 0 then
    return true
  end
  if state.socket_admission.enabled == true then
    return BMF_socket_scheduler_deadline_expired(
      deadline_at_ms,
      request.issuedAtMs,
      request.acceptedClock)
  end
  return (os.time() * 1000) >= deadline_at_ms
end

local function BMF_game_command_tunnel_classify_failure(invoked)
  local fields = invoked and invoked.data and invoked.data.fields or {}
  local stage = tostring(fields.stage or "")
  if stage == "implementation_call"
      or (stage == "" and tostring(invoked and invoked.code or "") == "NATIVE_PLAYER_CHAT_IMPL_FAILED") then
    return "outcome_unknown", "INJECTION_OUTCOME_UNKNOWN"
  end
  return "rejected", tostring(invoked and invoked.code or "INJECTION_REJECTED")
end

local function BMF_game_command_tunnel_compact_response(invoked)
  local collector = BMF_new_bounded_output_collector()
  collector.maxLines = math.min(64, collector.maxLines)
  local lines = invoked and invoked.data and invoked.data.lines or nil
  if type(lines) == "table" then
    for index, line in ipairs(lines) do
      if not BMF_bounded_output_add(collector, line) then
        -- Preserve the old 64-line traversal bound; the byte counter in the
        -- marker is therefore an explicit lower bound for skipped tail lines.
        collector.omittedLines = collector.omittedLines + math.max(0, #lines - index)
        break
      end
    end
  end
  if #collector.lines == 0 and not collector.truncated then
    BMF_bounded_output_add(collector, "ok=" .. tostring(invoked and invoked.ok == true))
    BMF_bounded_output_add(collector, "code=" .. tostring(invoked and invoked.code or ""))
  end
  local output = BMF_bounded_output_finalize(collector, "cityrpg.command.v1", "tunnel")
  return table.concat(output, "\n") .. "\n"
end

BMF_game_command_tunnel_schedule = function(delay_ms)
  local tunnel = state.game_command_tunnel
  if (tonumber(tunnel.queued_count) or 0) <= 0 then
    tunnel.scheduled = false
    return true
  end
  if tunnel.worker_started == true
      and state.socket_worker_started == true
      and state.socket_worker_mode == "EngineTickOneShotChain" then
    tunnel.scheduled = true
    return true
  end

  tunnel.scheduled = false
  tunnel.scheduler_failures = (tonumber(tunnel.scheduler_failures) or 0) + 1
  tunnel.last_error = "game command tunnel scheduler unavailable"
  while (tonumber(tunnel.queued_count) or 0) > 0 do
    local request = BMF_game_command_tunnel_dequeue()
    if request == nil then
      break
    end
    BMF_game_command_tunnel_send_terminal(
      request,
      "rejected",
      "SCHEDULER_UNAVAILABLE",
      tunnel.last_error,
      nil,
      0)
  end
  return false
end

BMF_game_command_tunnel_drain_once = function(request)
  local tunnel = state.game_command_tunnel
  if tunnel.running then
    return
  end
  request = request or BMF_game_command_tunnel_dequeue()
  if request == nil then
    return
  end

  local work_started_clock = os.clock()
  tunnel.running = true
  local injection_started = false
  local processing_ok, processing_error = pcall(function()
    local now_ms = os.time() * 1000
    local readiness_not_before_tick = tonumber(request.readinessNotBeforeTick) or 0
    if readiness_not_before_tick > (tonumber(tunnel.worker_ticks) or 0) then
      if BMF_game_command_tunnel_request_expired(request) then
        tunnel.readiness_expirations = (tonumber(tunnel.readiness_expirations) or 0) + 1
        tunnel.last_readiness_code = "DEADLINE_EXPIRED"
        BMF_game_command_tunnel_send_terminal(
          request,
          "expired",
          "DEADLINE_EXPIRED",
          "native readiness retry remained deferred until the absolute deadline",
          nil,
          0)
      elseif BMF_game_command_tunnel_requeue(request) then
        tunnel.readiness_deferrals = (tonumber(tunnel.readiness_deferrals) or 0) + 1
      else
        tunnel.readiness_rejections = (tonumber(tunnel.readiness_rejections) or 0) + 1
        BMF_game_command_tunnel_send_terminal(
          request,
          "rejected",
          "READINESS_REQUEUE_FAILED",
          "deferred native readiness wait could not be queued",
          nil,
          0)
      end
      return
    end
    request.readinessNotBeforeTick = 0
    local admitted, admission_code = BMFConnectionReadiness.admission(
      state.connection_readiness,
      BMF_game_command_tunnel_identity_operation(request),
      now_ms)
    if not admitted then
      local expired = admission_code == "DEADLINE_EXPIRED"
      if expired then
        tunnel.readiness_expirations = (tonumber(tunnel.readiness_expirations) or 0) + 1
      else
        tunnel.readiness_rejections = (tonumber(tunnel.readiness_rejections) or 0) + 1
      end
      tunnel.last_readiness_code = tostring(admission_code or "READINESS_REJECTED")
      BMF_game_command_tunnel_send_terminal(
        request,
        expired and "expired" or "rejected",
        tostring(admission_code or "READINESS_REJECTED"),
        "identity, lifecycle, or deadline changed before native readiness",
        nil,
        0)
    else
      local ready, controller_address, readiness_code, readiness_detail, readiness_retry_detail =
        BMF_game_command_tunnel_readiness_probe(request)
      if not ready then
        if BMF_game_command_tunnel_request_expired(request) then
          tunnel.readiness_expirations = (tonumber(tunnel.readiness_expirations) or 0) + 1
          BMF_game_command_tunnel_send_terminal(
            request,
            "expired",
            "DEADLINE_EXPIRED",
            "native callability was not proven before the absolute deadline: "
              .. tostring(readiness_code),
            nil,
            0)
        elseif not BMF_game_command_tunnel_readiness_retryable(readiness_code) then
          tunnel.readiness_rejections = (tonumber(tunnel.readiness_rejections) or 0) + 1
          BMF_game_command_tunnel_send_terminal(
            request,
            "rejected",
            tostring(readiness_code or "NATIVE_NOT_CALLABLE"),
            tostring(readiness_detail or "native callability could not be proven exactly"),
            nil,
            0)
        elseif BMF_game_command_tunnel_defer_retry(request, readiness_retry_detail)
            and BMF_game_command_tunnel_requeue(request) then
          tunnel.readiness_waits = (tonumber(tunnel.readiness_waits) or 0) + 1
          tunnel.last_readiness_code = tostring(readiness_code or "NATIVE_NOT_CALLABLE")
        else
          tunnel.readiness_rejections = (tonumber(tunnel.readiness_rejections) or 0) + 1
          BMF_game_command_tunnel_send_terminal(
            request,
            "rejected",
            "READINESS_REQUEUE_FAILED",
            tostring(readiness_detail or "native readiness wait could not be queued"),
            nil,
            0)
        end
      else
        local decision, decision_code = BMFConnectionReadiness.execution_decision(
          state.connection_readiness,
          BMF_game_command_tunnel_identity_operation(request),
          os.time() * 1000)
        local final_target, _, final_resolve_reason = live_chat_resolve_authoritative_name_target({
          uuid = request.senderUuid,
          senderName = request.senderName,
          connectionGeneration = request.connectionGeneration,
        })
        local final_controller_address = final_target ~= nil
          and trim_string(live_chat_object_key(final_target.controller, ""))
          or ""
        if decision ~= "execute"
            or final_controller_address == ""
            or final_controller_address ~= controller_address then
          local expired = decision == "expire"
          local code = expired and "DEADLINE_EXPIRED"
            or (decision ~= "execute" and tostring(decision_code) or "READINESS_CHANGED")
          if expired then
            tunnel.readiness_expirations = (tonumber(tunnel.readiness_expirations) or 0) + 1
          else
            tunnel.readiness_rejections = (tonumber(tunnel.readiness_rejections) or 0) + 1
          end
          BMFConnectionReadiness.note_check(
            state.connection_readiness,
            request.senderUuid,
            request.connectionGeneration,
            false,
            code,
            os.time() * 1000)
          tunnel.last_readiness_code = code
          BMF_game_command_tunnel_send_terminal(
            request,
            expired and "expired" or "rejected",
            code,
            "exact session changed after readiness proof: " .. tostring(final_resolve_reason or ""),
            nil,
            0)
        elseif not BMF_game_command_tunnel_acknowledge(request) then
          BMF_game_command_tunnel_send_terminal(
            request,
            "rejected",
            "ACK_SEND_FAILED",
            "native-ready operation was not executed because its acceptance ACK failed",
            nil,
            0)
        else
          BMF_operation_start_execution(request.operationContext)
          local dispatch_started_clock = os.clock()
          -- The address is derived from the exact UUID+generation and used only
          -- in this synchronous dispatch. It is never stored across a tick.
          tunnel.controller_cache_refreshes = (tonumber(tunnel.controller_cache_refreshes) or 0) + 1
          injection_started = true
          local invoked = BMF_player_message_implementation_probe(request.line, "", {
            skipRateLimit = true,
            controllerAddress = controller_address,
          })
          local controller_attempts =
            tonumber(invoked and invoked.data and invoked.data.controllerAttemptCount) or 0
          for _ = 1, controller_attempts do
            BMF_operation_note_controller_resolution(invoked and invoked.ok == true)
          end

          local dispatch_ms = BMF_telemetry_duration_ms(dispatch_started_clock)
          tunnel.dispatch_count = (tonumber(tunnel.dispatch_count) or 0) + 1
          tunnel.last_dispatch_ms = dispatch_ms
          tunnel.max_dispatch_ms = math.max(tonumber(tunnel.max_dispatch_ms) or 0, dispatch_ms)
          tunnel.dispatch_ms_sum = (tonumber(tunnel.dispatch_ms_sum) or 0) + dispatch_ms

          if invoked.ok == true then
            BMF_game_command_tunnel_send_terminal(
              request,
              "injected",
              "OK",
              tostring(invoked.message or "command injected"),
              BMF_game_command_tunnel_compact_response(invoked),
              dispatch_ms)
          else
            local result_state, code = BMF_game_command_tunnel_classify_failure(invoked)
            BMF_game_command_tunnel_send_terminal(
              request,
              result_state,
              code,
              tostring(invoked and invoked.message or "command injection failed"),
              BMF_game_command_tunnel_compact_response(invoked),
              dispatch_ms)
          end
        end
      end
    end
  end)
  tunnel.running = false

  if not processing_ok then
    tunnel.last_error = "game command tunnel drain failed id="
      .. tostring(request.id or "")
      .. ": "
      .. tostring(processing_error)
    if tunnel.active_by_id[request.id] ~= nil then
      local failure_state = injection_started and "outcome_unknown" or "rejected"
      local failure_code = injection_started and "DRAIN_OUTCOME_UNKNOWN" or "DRAIN_FAILED"
      local terminal_ok, terminal_error = pcall(
        BMF_game_command_tunnel_send_terminal,
        request,
        failure_state,
        failure_code,
        tunnel.last_error,
        nil,
        0)
      if not terminal_ok then
        tunnel.last_error = tunnel.last_error .. "; terminal send failed: " .. tostring(terminal_error)
      end
    end
  end

  local work_duration_exact_ms = math.max(0, (os.clock() - work_started_clock) * 1000)
  BMF_socket_scheduler_record_work(
    "tunnel",
    math.floor(work_duration_exact_ms + 0.5),
    processing_ok,
    work_duration_exact_ms)
  tunnel.scheduled = (tonumber(tunnel.queued_count) or 0) > 0
end

BMF_game_command_tunnel_pump = function()
  local tunnel = state.game_command_tunnel
  if tunnel.worker_started ~= true
      or state.socket_worker_started ~= true
      or state.socket_worker_mode ~= "EngineTickOneShotChain" then
    return 0
  end

  tunnel.worker_ticks = (tonumber(tunnel.worker_ticks) or 0) + 1
  local guard = state.reserved_chat_command_guard
  if type(guard) == "table"
      and guard.enabled == true
      and guard.installed ~= true
      and (tunnel.worker_ticks == 1 or (tunnel.worker_ticks % 40) == 1) then
    BMF_install_reserved_chat_command_guard()
  end
  if (tunnel.worker_ticks % 40) == 1 then
    tunnel.last_worker_tick_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  end

  local cooldown_ticks = math.max(0, tonumber(tunnel.cooldown_ticks) or 0)
  if cooldown_ticks > 0 then
    cooldown_ticks = cooldown_ticks - 1
    tunnel.cooldown_ticks = cooldown_ticks
  end

  if (tonumber(tunnel.queued_count) or 0) <= 0 then
    tunnel.worker_idle_ticks = (tonumber(tunnel.worker_idle_ticks) or 0) + 1
    tunnel.scheduled = false
    return 0
  end

  tunnel.scheduled = true
  if cooldown_ticks > 0 or tunnel.running == true then
    return 0
  end

  tunnel.scheduled = false
  BMF_game_command_tunnel_drain_once()
  local poll_ms = math.max(1, tonumber(state.socket.poll_interval_ms) or SOCKET_DEFAULT_POLL_MS)
  local interval_ms = math.max(1, tonumber(tunnel.interval_ms) or GAME_COMMAND_TUNNEL_DEFAULT_INTERVAL_MS)
  tunnel.cooldown_ticks = math.max(1, math.ceil(interval_ms / poll_ms))
  return 1
end

BMF_process_game_command_tunnel_request = function(decoded)
  local tunnel = state.game_command_tunnel
  state.socket.received_commands = (tonumber(state.socket.received_commands) or 0) + 1
  local request_id = trim_string(decoded and decoded.id or "")
  local line = trim_string(decoded.line or "")
  local idempotency_key = trim_string(decoded.idempotencyKey or "")
  local sender_uuid = trim_string(decoded.senderUuid or ""):lower()
  local sender_name = trim_string(decoded.senderName or "")
  local connection_generation = tonumber(decoded.connectionGeneration) or 0
  local accepted_at_ms = tonumber(decoded.acceptedAtMs) or 0
  local operation_type = trim_string(decoded.operationType or "")
  local supplied_issued_at_ms = tonumber(decoded.issuedAtMs)
  local supplied_deadline_ms = tonumber(decoded.deadlineMs)
  local rejection_identity = {
    senderUuid = sender_uuid,
    senderName = sender_name,
    connectionGeneration = connection_generation,
    acceptedAtMs = accepted_at_ms,
    operationType = operation_type,
  }
  local function reject(result_state, code, detail)
    return BMF_game_command_tunnel_send_rejection(
      request_id,
      result_state,
      code,
      detail,
      rejection_identity)
  end
  if request_id == "" or #request_id > 128 then
    return reject("rejected", "INVALID_ID", "id must contain 1-128 bytes")
  end
  if sender_uuid == "" or #sender_uuid > 128 then
    return reject("rejected", "SENDER_UUID_REQUIRED", "senderUuid must contain 1-128 bytes")
  end
  if sender_name == "" or #sender_name > 128 or sender_name:find("[%c]") ~= nil then
    return reject("rejected", "SENDER_NAME_REQUIRED", "senderName must contain 1-128 non-control bytes")
  end
  if connection_generation < 1 or connection_generation % 1 ~= 0 then
    return reject("rejected", "CONNECTION_GENERATION_REQUIRED", "connectionGeneration must be a positive integer")
  end
  if accepted_at_ms <= 0 then
    return reject("rejected", "ACCEPTED_AT_REQUIRED", "positive acceptedAtMs is required")
  end
  if operation_type == "" or #operation_type > 128 then
    return reject("rejected", "OPERATION_TYPE_REQUIRED", "operationType must contain 1-128 bytes")
  end
  if (supplied_deadline_ms or 0) <= 0 then
    return reject("rejected", "DEADLINE_REQUIRED", "positive absolute deadlineMs is required")
  end
  local current_session, current_session_reason = BMFConnectionReadiness.current(
    state.connection_readiness,
    sender_uuid,
    connection_generation)
  if current_session == nil then
    state.game_command_tunnel.readiness_rejections =
      (tonumber(state.game_command_tunnel.readiness_rejections) or 0) + 1
    state.game_command_tunnel.last_readiness_code = tostring(current_session_reason or "unknown_current_session")
    return reject(
      "rejected",
      tostring(current_session_reason or "unknown_current_session"):upper(),
      "sender UUID and connection generation are not the current live session")
  end
  local current_player, current_player_reason = live_chat_validate_authoritative_identity({
    uuid = sender_uuid,
    senderName = sender_name,
    connectionGeneration = connection_generation,
  })
  if current_player == nil then
    state.game_command_tunnel.readiness_rejections =
      (tonumber(state.game_command_tunnel.readiness_rejections) or 0) + 1
    state.game_command_tunnel.last_readiness_code = tostring(
      current_player_reason or "authoritative_identity_unavailable")
    return reject(
      "rejected",
      tostring(current_player_reason or "authoritative_identity_unavailable"):upper(),
      "sender UUID, current Omegga name, and connection generation did not match")
  end
  local identity_now_ms = os.time() * 1000
  if supplied_deadline_ms <= accepted_at_ms or supplied_deadline_ms <= identity_now_ms then
    state.game_command_tunnel.readiness_expirations =
      (tonumber(state.game_command_tunnel.readiness_expirations) or 0) + 1
    state.game_command_tunnel.last_readiness_code = "DEADLINE_EXPIRED"
    return reject(
      "expired",
      "DEADLINE_EXPIRED",
      "absolute deadlineMs elapsed before duplicate or admission handling")
  end
  local completed = tunnel.completed_by_id[request_id]
  if completed ~= nil then
    tunnel.duplicate_requests = (tonumber(tunnel.duplicate_requests) or 0) + 1
    if tostring(completed.line or "") ~= line
        or tostring(completed.idempotencyKey or "") ~= idempotency_key
        or tostring(completed.senderUuid or "") ~= sender_uuid
        or tostring(completed.senderName or "") ~= sender_name
        or tonumber(completed.connectionGeneration) ~= connection_generation
        or tostring(completed.operationType or "") ~= operation_type
        or tonumber(completed.acceptedAtMs) ~= accepted_at_ms then
      BMF_game_command_tunnel_send_json({
        type = "tunnel.result",
        source = "bmf",
        v = tonumber(tunnel.protocol_version) or 1,
        ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
        id = request_id,
        state = "rejected",
        code = "DUPLICATE_ID_CONFLICT",
        detail = "id was already completed with a different command or idempotency key",
        senderUuid = sender_uuid,
        senderName = sender_name,
        connectionGeneration = connection_generation,
        operationType = operation_type,
        acceptedAtMs = accepted_at_ms,
        queueDepth = tonumber(tunnel.queued_count) or 0,
      })
      return false
    end
    BMF_game_command_tunnel_send_json(completed.record)
    return true
  end

  local active = tunnel.active_by_id[request_id]
  if active ~= nil then
    tunnel.duplicate_requests = (tonumber(tunnel.duplicate_requests) or 0) + 1
    if active.line ~= line
        or tostring(active.idempotencyKey or "") ~= idempotency_key
        or tostring(active.senderUuid or "") ~= sender_uuid
        or tostring(active.senderName or "") ~= sender_name
        or tonumber(active.connectionGeneration) ~= connection_generation
        or tostring(active.operationType or "") ~= operation_type
        or tonumber(active.acceptedAtMs) ~= accepted_at_ms then
      BMF_game_command_tunnel_send_json({
        type = "tunnel.result",
        source = "bmf",
        v = tonumber(tunnel.protocol_version) or 1,
        ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
        id = request_id,
        state = "rejected",
        code = "DUPLICATE_ID_CONFLICT",
        detail = "id is already active with a different command",
        senderUuid = sender_uuid,
        senderName = sender_name,
        connectionGeneration = connection_generation,
        operationType = operation_type,
        acceptedAtMs = accepted_at_ms,
        queueDepth = tonumber(tunnel.queued_count) or 0,
      })
      return false
    end
    if active.admissionSent == true then
      BMF_game_command_tunnel_send_json({
        type = "tunnel.ack",
        source = "bmf",
        v = tonumber(tunnel.protocol_version) or 1,
        ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
        id = request_id,
        state = "accepted",
        duplicate = true,
        senderUuid = active.senderUuid,
        senderName = active.senderName,
        connectionGeneration = active.connectionGeneration,
        operationType = active.operationType,
        acceptedAtMs = active.acceptedAtMs,
        queueDepth = tonumber(tunnel.queued_count) or 0,
      })
      return true
    end
    BMF_game_command_tunnel_send_json({
      type = "tunnel.result",
      source = "bmf",
      v = tonumber(tunnel.protocol_version) or 1,
      ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
      id = request_id,
      state = "rejected",
      code = "READINESS_PENDING",
      detail = "duplicate arrived before exact native callability was proven",
      senderUuid = sender_uuid,
      senderName = sender_name,
      connectionGeneration = connection_generation,
      operationType = operation_type,
      acceptedAtMs = accepted_at_ms,
      queueDepth = tonumber(tunnel.queued_count) or 0,
    })
    return false
  end

  if #idempotency_key > GAME_COMMAND_TUNNEL_MAX_IDEMPOTENCY_KEY_BYTES then
    return reject(
      "rejected",
      "IDEMPOTENCY_KEY_TOO_LARGE",
      "idempotencyKey exceeds 128 bytes")
  end
  if idempotency_key ~= "" then
    local completed_key = tunnel.completed_by_idempotency_key[idempotency_key]
    if completed_key ~= nil then
      if tostring(completed_key.line or "") ~= line
          or tostring(completed_key.senderUuid or "") ~= sender_uuid
          or tostring(completed_key.senderName or "") ~= sender_name
          or tonumber(completed_key.connectionGeneration) ~= connection_generation
          or tostring(completed_key.operationType or "") ~= operation_type then
        BMF_game_command_tunnel_send_json({
          type = "tunnel.result",
          source = "bmf",
          v = tonumber(tunnel.protocol_version) or 1,
          ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
          id = request_id,
          state = "rejected",
          code = "IDEMPOTENCY_KEY_CONFLICT",
          detail = "idempotencyKey was already completed with a different command",
          senderUuid = sender_uuid,
          senderName = sender_name,
          connectionGeneration = connection_generation,
          operationType = operation_type,
          acceptedAtMs = accepted_at_ms,
          queueDepth = tonumber(tunnel.queued_count) or 0,
        })
        return false
      end
      local replay = copy_table(completed_key.record)
      replay.id = request_id
      replay.replayed = true
      replay.originalId = completed_key.requestId
      replay.senderUuid = sender_uuid
      replay.senderName = sender_name
      replay.connectionGeneration = connection_generation
      replay.operationType = operation_type
      replay.acceptedAtMs = accepted_at_ms
      BMF_game_command_tunnel_send_json(replay)
      return true
    end

    local active_key = tunnel.active_by_idempotency_key[idempotency_key]
    if active_key ~= nil then
      local identity_matches = tostring(active_key.senderUuid or "") == sender_uuid
        and tostring(active_key.senderName or "") == sender_name
        and tonumber(active_key.connectionGeneration) == connection_generation
        and tostring(active_key.operationType or "") == operation_type
      BMF_game_command_tunnel_send_json({
        type = "tunnel.result",
        source = "bmf",
        v = tonumber(tunnel.protocol_version) or 1,
        ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
        id = request_id,
        state = "rejected",
        code = active_key.line == line and identity_matches
          and "IDEMPOTENCY_KEY_ACTIVE" or "IDEMPOTENCY_KEY_CONFLICT",
        detail = active_key.line == line and identity_matches
          and "idempotent command is already accepted under another request id"
          or "idempotencyKey is active with a different command",
        senderUuid = sender_uuid,
        senderName = sender_name,
        connectionGeneration = connection_generation,
        operationType = operation_type,
        acceptedAtMs = accepted_at_ms,
        queueDepth = tonumber(tunnel.queued_count) or 0,
      })
      return false
    end
  end

  if tunnel.enabled ~= true then
    return reject("rejected", "TUNNEL_DISABLED", "game command tunnel is disabled")
  end
  if tunnel.worker_started ~= true
      or state.socket_worker_started ~= true
      or state.socket_worker_mode ~= "EngineTickOneShotChain" then
    return reject(
      "rejected",
      "TUNNEL_UNAVAILABLE",
      "persistent game-thread socket tunnel worker is unavailable")
  end
  if tonumber(decoded.v) ~= tonumber(tunnel.protocol_version) then
    return reject("rejected", "UNSUPPORTED_VERSION", "only tunnel protocol v1 is supported")
  end
  if tostring(decoded.channel or "") ~= tostring(tunnel.channel) then
    return reject("rejected", "UNSUPPORTED_CHANNEL", "channel must be " .. tostring(tunnel.channel))
  end
  if line == "" or line:find("\n", 1, true) or line:find("\r", 1, true) then
    return reject("rejected", "INVALID_LINE", "line must be one non-empty command")
  end
  if #line > tunnel.max_line_bytes then
    return reject("rejected", "LINE_TOO_LARGE", "line exceeds configured byte limit")
  end
  if not BMF_game_command_tunnel_line_allowed(line) then
    return reject(
      "rejected",
      "COMMAND_NOT_ALLOWED",
      "only /cityrpgRemote, /cityrpgroute, and /cityrpgPositionSnapshot are allowed")
  end

  local service_class = tostring(decoded.serviceClass or "interactive"):lower()
  if service_class ~= "interactive" and service_class ~= "bulk" then
    return reject("rejected", "INVALID_SERVICE_CLASS", "serviceClass must be interactive or bulk")
  end
  local now_ms = os.time() * 1000
  if state.socket_admission.enabled == true
      and (supplied_issued_at_ms or 0) <= 0 then
    return reject(
      "rejected",
      "DEADLINE_REQUIRED",
      "positive issuedAtMs is required while unified bounded admission is enabled")
  end
  local issued_at_ms = supplied_issued_at_ms or accepted_at_ms
  local deadline_ms = supplied_deadline_ms
  local deadline_expired = state.socket_admission.enabled == true
    and BMF_socket_scheduler_deadline_expired(deadline_ms, issued_at_ms, nil)
    or deadline_ms <= now_ms
  if deadline_ms <= issued_at_ms or deadline_ms <= accepted_at_ms or deadline_expired then
    return reject("expired", "DEADLINE_EXPIRED", "absolute deadlineMs has elapsed")
  end
  local readiness_admitted, readiness_code = BMFConnectionReadiness.admission(
    state.connection_readiness,
    {
      requestId = request_id,
      senderUuid = sender_uuid,
      connectionGeneration = connection_generation,
      acceptedAtMs = accepted_at_ms,
      absoluteDeadlineMs = deadline_ms,
      operationType = operation_type,
    },
    now_ms)
  if not readiness_admitted then
    local readiness_expired = readiness_code == "DEADLINE_EXPIRED"
    if readiness_expired then
      tunnel.readiness_expirations = (tonumber(tunnel.readiness_expirations) or 0) + 1
    else
      tunnel.readiness_rejections = (tonumber(tunnel.readiness_rejections) or 0) + 1
    end
    tunnel.last_readiness_code = tostring(readiness_code or "READINESS_REJECTED")
    return reject(
      readiness_expired and "expired" or "rejected",
      tostring(readiness_code or "READINESS_REJECTED"),
      "request identity was not admitted for the current connection generation")
  end

  local queue = tunnel.queues[service_class]
  local class_limit = service_class == "bulk" and tunnel.max_bulk_queue or tunnel.max_interactive_queue
  if state.socket_admission.enabled == true
      and BMF_socket_scheduler_total_depth() >= state.socket_admission.max_queue then
    return reject(
      "rejected",
      "QUEUE_FULL",
      "unified socket admission queue is full")
  end
  if (tonumber(tunnel.queued_count) or 0) >= tunnel.max_queue then
    return reject("rejected", "QUEUE_FULL", "game command tunnel queue is full")
  end
  if #queue >= class_limit then
    return reject("rejected", "SERVICE_CLASS_FULL", service_class .. " queue budget is full")
  end
  local retained_bytes = #line + #request_id + #idempotency_key + #sender_uuid + #sender_name + #operation_type
  if state.socket_admission.enabled == true
      and (BMF_socket_scheduler_total_bytes() + retained_bytes) > state.socket_admission.max_bytes then
    return reject(
      "rejected",
      "QUEUE_BYTES_FULL",
      "unified socket admission byte budget is full")
  end
  if ((tonumber(tunnel.queued_bytes) or 0) + retained_bytes) > tunnel.max_bytes then
    return reject("rejected", "QUEUE_BYTES_FULL", "game command tunnel byte budget is full")
  end
  local estimated_wait_ms = ((tonumber(tunnel.queued_count) or 0) + 1) * tunnel.interval_ms
  if (now_ms + estimated_wait_ms) >= deadline_ms then
    return reject("expired", "DEADLINE_EXPIRED", "estimated queue wait exceeds deadline")
  end

  local request = {
    id = request_id,
    line = line,
    lineBytes = #line,
    retainedBytes = retained_bytes,
    channel = tostring(decoded.channel),
    serviceClass = service_class,
    deadlineMs = deadline_ms,
    issuedAtMs = issued_at_ms,
    acceptedAtMs = accepted_at_ms,
    senderUuid = sender_uuid,
    senderName = sender_name,
    connectionGeneration = connection_generation,
    operationType = operation_type,
    idempotencyKey = idempotency_key,
    admissionSent = false,
    terminalSent = false,
  }
  queue[#queue + 1] = request
  tunnel.active_by_id[request_id] = request
  if idempotency_key ~= "" then
    tunnel.active_by_idempotency_key[idempotency_key] = request
  end
  tunnel.queued_count = (tonumber(tunnel.queued_count) or 0) + 1
  tunnel.queued_bytes = (tonumber(tunnel.queued_bytes) or 0) + retained_bytes
  tunnel.peak_depth = math.max(tonumber(tunnel.peak_depth) or 0, tunnel.queued_count)
  tunnel.peak_interactive_depth = math.max(
    tonumber(tunnel.peak_interactive_depth) or 0,
    #tunnel.queues.interactive)
  tunnel.peak_bulk_depth = math.max(
    tonumber(tunnel.peak_bulk_depth) or 0,
    #tunnel.queues.bulk)
  tunnel.peak_bytes = math.max(tonumber(tunnel.peak_bytes) or 0, tunnel.queued_bytes)
  tunnel.last_readiness_code = tostring(readiness_code or "waiting")
  tunnel.scheduled = true
  return true
end

function BMF_process_socket_message(line)
  local trimmed = trim_string(line)
  if trimmed == "" then
    return
  end

  state.socket.received_messages = state.socket.received_messages + 1
  local decoded, err = json_decode(trimmed)
  if type(decoded) ~= "table" then
    state.socket.last_error = "socket decode failed: " .. tostring(err or "invalid JSON")
    return
  end

  local message_type = tostring(decoded.type or "")
  BMF_socket_scheduler_record_ingress(message_type)
  if message_type == "ping" then
    BMF_socket_send_json({
      type = "pong",
      source = "bmf",
      ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
      id = decoded.id,
    })
    return "ping", true
  end

  if message_type == "tunnel.request" then
    return "tunnel", BMF_process_game_command_tunnel_request(decoded)
  end

  if message_type ~= "command" then
    return "other", false
  end

  if state.socket_admission.enabled == true then
    state.socket.received_commands = state.socket.received_commands + 1
    return "direct", BMF_socket_scheduler_admit_direct(decoded)
  end

  local request_id = trim_string(decoded.id or "")
  local command_text = trim_string(decoded.command or "")
  if request_id == "" or command_text == "" then
    state.socket.last_error = "socket command missing id or command"
    return "direct", false
  end

  state.socket.received_commands = state.socket.received_commands + 1
  BMF_socket_scheduler_record_admission("direct_socket")
  local operation_context = BMF_operation_begin(
    BMF_operation_class_from_text(command_text, "unknown"),
    "direct_socket_bypass",
    decoded)
  BMF_operation_start_execution(operation_context)
  local response, ok, detail = BMF_dispatch_bmf_command_text(
    request_id,
    command_text,
    "socket",
    operation_context)
  BMF_operation_finish(operation_context, ok == true and "completed" or "known_failure")
  local sent = BMF_socket_send_json({
    type = "response",
    source = "bmf",
    ts = os.date("!%Y-%m-%dT%H:%M:%SZ"),
    id = request_id,
    ok = ok == true,
    detail = tostring(detail or ""),
    response = response,
  })
  if sent then
    state.socket.sent_responses = state.socket.sent_responses + 1
  end
  return "direct", true
end

function BMF_socket_native_drain_source_active(source)
  if source == "tree" then
    return state.tools.tree_cut_native and state.tools.tree_cut_native.enabled == true
  end
  if source == "zone" then
    return BMF_zone_native_should_drain()
  end
  return false
end

function BMF_socket_native_drain_budget_exhausted(pump_started_clock)
  local scheduler = state.telemetry.socket_scheduler
  local native_drains = scheduler.native_drains
  if native_drains.budget_enabled ~= true then
    return false
  end
  local started = tonumber(pump_started_clock)
  if not started then
    return false
  end
  return BMF_telemetry_duration_ms(started) >= (tonumber(scheduler.budget_ms) or 3)
end

function BMF_socket_native_drain_mark_skipped(source)
  local native_drains = state.telemetry.socket_scheduler.native_drains
  local lane = native_drains.by_source[source]
  if type(lane) ~= "table" then
    return
  end
  native_drains.skipped = (tonumber(native_drains.skipped) or 0) + 1
  lane.skipped = (tonumber(lane.skipped) or 0) + 1
  lane.depth = -1
  lane.depth_available = false
end

function BMF_socket_native_drain_one(source, pump_started_clock)
  local native_drains = state.telemetry.socket_scheduler.native_drains
  local lane = native_drains.by_source[source]
  if type(lane) ~= "table" then
    return false, 0, false, true
  end
  if BMF_socket_native_drain_budget_exhausted(pump_started_clock) then
    BMF_socket_native_drain_mark_skipped(source)
    return true, 0, true, false
  end

  native_drains.attempted = (tonumber(native_drains.attempted) or 0) + 1
  lane.attempted = (tonumber(lane.attempted) or 0) + 1
  local operation_started_clock = os.clock()
  local raw_ok, code, message, raw_events
  if source == "tree" then
    raw_ok, code, message, raw_events = BMF_tree_cut_native_drain_raw(1)
  else
    raw_ok, code, message, raw_events = BMF_zone_native_drain_raw(1)
  end

  local operation_ok = raw_ok == true
  raw_events = type(raw_events) == "table" and raw_events or {}
  local drained_count = #raw_events
  if not operation_ok then
    lane.errors = (tonumber(lane.errors) or 0) + 1
  elseif drained_count == 0 then
    lane.depth = 0
    lane.depth_available = true
  else
    lane.depth = -1
    lane.depth_available = false
    local emit_ok, emit_result
    if source == "tree" then
      emit_ok, emit_result = pcall(BMF_tree_cut_native_emit_raw, raw_events, {
        silent = true,
      })
    else
      emit_ok, emit_result = pcall(BMF_zone_native_emit_raw, raw_events, {
        silent = true,
      })
    end
    if not emit_ok then
      operation_ok = false
      lane.errors = (tonumber(lane.errors) or 0) + 1
      if source == "tree" then
        state.tools.tree_cut_native.last_error = "native tree-cut emit failed: " .. tostring(emit_result)
      else
        state.tools.zone_native.last_error = "native zone emit failed: " .. tostring(emit_result)
      end
    end
    native_drains.drained = (tonumber(native_drains.drained) or 0) + drained_count
    lane.drained = (tonumber(lane.drained) or 0) + drained_count
  end

  local duration_ms = BMF_telemetry_duration_ms(operation_started_clock)
  lane.last_ms = duration_ms
  lane.duration_ms_max = math.max(tonumber(lane.duration_ms_max) or 0, duration_ms)
  local overrun = BMF_socket_native_drain_budget_exhausted(pump_started_clock)
  if overrun then
    native_drains.overruns = (tonumber(native_drains.overruns) or 0) + 1
    lane.overruns = (tonumber(lane.overruns) or 0) + 1
  end
  if not raw_ok then
    if source == "tree" then
      state.tools.tree_cut_native.last_error = "native tree-cut drain failed: " .. tostring(message or code)
    else
      state.tools.zone_native.last_error = "native zone drain failed: " .. tostring(message or code)
    end
  end
  return operation_ok, drained_count, overrun, drained_count == 0
end

function BMF_socket_native_drain_budgeted(pump_started_clock)
  local native_drains = state.telemetry.socket_scheduler.native_drains
  local tree_active = BMF_socket_native_drain_source_active("tree")
  local zone_active = BMF_socket_native_drain_source_active("zone")
  local next_source = native_drains.next_source == "zone" and "zone" or "tree"
  local max_events = math.max(1, tonumber(native_drains.max_events_per_pump) or 4)
  local drained = 0
  local operation_ok = true
  local budget_stopped = false

  while (tree_active or zone_active) and drained < max_events do
    if BMF_socket_native_drain_budget_exhausted(pump_started_clock) then
      if tree_active then
        BMF_socket_native_drain_mark_skipped("tree")
      end
      if zone_active then
        BMF_socket_native_drain_mark_skipped("zone")
      end
      budget_stopped = true
      break
    end

    local source = next_source
    if source == "tree" and not tree_active then
      source = "zone"
    elseif source == "zone" and not zone_active then
      source = "tree"
    end

    local lane_ok, lane_drained, lane_overrun, lane_empty =
      BMF_socket_native_drain_one(source, pump_started_clock)
    operation_ok = operation_ok and lane_ok
    drained = drained + (tonumber(lane_drained) or 0)
    if source == "tree" then
      if lane_empty or not lane_ok then
        tree_active = false
      end
      next_source = "zone"
    else
      if lane_empty or not lane_ok then
        zone_active = false
      end
      next_source = "tree"
    end
    native_drains.next_source = next_source

    if lane_overrun then
      if tree_active then
        BMF_socket_native_drain_mark_skipped("tree")
      end
      if zone_active then
        BMF_socket_native_drain_mark_skipped("zone")
      end
      budget_stopped = true
      break
    end
  end

  if drained >= max_events and not budget_stopped then
    if tree_active then
      BMF_socket_native_drain_mark_skipped("tree")
    end
    if zone_active then
      BMF_socket_native_drain_mark_skipped("zone")
    end
  end
  return operation_ok, drained, budget_stopped
end

function BMF_drain_socket_messages(max_count, pump_started_clock)
  if not state.socket.started or type(BMFSocketReceive) ~= "function" then
    state.socket_worker_started = false
    state.socket_worker_mode = "stopped"
    return 0, 0, 0, false
  end

  local drain_started_clock = os.clock()
  local drain_ok = true
  local scheduler = state.telemetry.socket_scheduler
  local requested_count = math.max(1, tonumber(max_count) or 64)
  if scheduler.direct_ingress_cap_enabled == true then
    requested_count = math.min(
      requested_count,
      math.max(1, tonumber(scheduler.effective_ingress_per_pump) or 1))
  end
  local admission_started_clock = tonumber(pump_started_clock) or drain_started_clock
  state.socket.poll_count = (tonumber(state.socket.poll_count) or 0) + 1
  state.socket.last_poll_epoch = os.time()
  state.socket.last_poll_at = os.date("!%Y-%m-%dT%H:%M:%SZ")

  local drained = 0
  local received_count = 0
  local direct_admitted = 0
  local budget_admission_stopped = false
  while received_count < requested_count do
    local receive_limit = requested_count - received_count
    if scheduler.budget_enforced == true then
      receive_limit = math.min(1, receive_limit)
    end
    local ok, messages_or_error = pcall(BMFSocketReceive, receive_limit)
    if not ok then
      drain_ok = false
      state.socket.last_error = "BMFSocketReceive failed: " .. tostring(messages_or_error)
      break
    end
    if type(messages_or_error) ~= "table" or #messages_or_error == 0 then
      break
    end

    received_count = received_count + #messages_or_error
    for _, line in ipairs(messages_or_error) do
      if trim_string(line) ~= "" then
        drained = drained + 1
        local processed, route_or_error, admitted = pcall(BMF_process_socket_message, line)
        if not processed then
          drain_ok = false
          state.socket.last_error = "socket message failed: " .. tostring(route_or_error)
        elseif route_or_error == "direct" and admitted == true then
          direct_admitted = direct_admitted + 1
        end
      end
    end

    if scheduler.budget_enforced == true
      and received_count < requested_count
      and BMF_socket_scheduler_budget_exhausted_for_admission(admission_started_clock)
    then
      budget_admission_stopped = true
      break
    end

    if scheduler.budget_enforced ~= true then
      break
    end
  end

  state.socket.last_drain_count = drained
  local native_drained = 0
  if scheduler.native_drains.budget_enabled == true then
    local native_ok, bounded_native_drained, native_budget_stopped =
      BMF_socket_native_drain_budgeted(admission_started_clock)
    drain_ok = drain_ok and native_ok
    native_drained = tonumber(bounded_native_drained) or 0
    budget_admission_stopped = budget_admission_stopped or native_budget_stopped == true
  else
    if state.tools.tree_cut_native and state.tools.tree_cut_native.enabled == true then
      local native_ok, native_result = pcall(BMF.tools.treeCutNative.drain, {
        limit = 64,
        silent = true,
      })
      if native_ok and native_result and native_result.data then
        native_drained = tonumber(native_result.data.drained) or 0
      elseif not native_ok then
        drain_ok = false
        state.tools.tree_cut_native.last_error = "native tree-cut drain failed: " .. tostring(native_result)
      end
    end
    if BMF_zone_native_should_drain() then
      local zone_ok, zone_result = pcall(BMF.tools.zoneNative.drain, {
        limit = 64,
        silent = true,
      })
      if zone_ok and zone_result and zone_result.data then
        native_drained = native_drained + (tonumber(zone_result.data.drained) or 0)
      elseif not zone_ok then
        drain_ok = false
        state.tools.zone_native.last_error = "native zone drain failed: " .. tostring(zone_result)
      end
    end
  end
  if drained > 0 or native_drained > 0 or not drain_ok then
    BMF_telemetry_record_worker(
      "socket_drains",
      BMF_telemetry_duration_ms(drain_started_clock),
      drain_ok,
      "messages",
      drained + native_drained)
  end
  BMF_socket_metadata_heartbeat(false)
  return drained + native_drained, drained, direct_admitted, budget_admission_stopped
end

function BMF_socket_scheduler_update_idle_backoff(has_work, has_pending)
  local scheduler = state.telemetry.socket_scheduler
  local previous_tier = tostring(scheduler.poll_tier or "active")
  local next_tier = previous_tier
  local next_interval = tonumber(scheduler.current_poll_interval_ms) or 25
  local active = has_work == true or has_pending == true
  scheduler.poll_passes_total = (tonumber(scheduler.poll_passes_total) or 0) + 1

  if active then
    if previous_tier ~= "active" then
      scheduler.work_wakeups_total = (tonumber(scheduler.work_wakeups_total) or 0) + 1
    end
    scheduler.active_passes_total = (tonumber(scheduler.active_passes_total) or 0) + 1
    scheduler.consecutive_empty_passes = 0
    scheduler.recent_work_passes_remaining = 4
    next_tier = "active"
    next_interval = 25
  elseif (tonumber(scheduler.recent_work_passes_remaining) or 0) > 0 then
    scheduler.active_passes_total = (tonumber(scheduler.active_passes_total) or 0) + 1
    scheduler.recent_work_passes_remaining = (tonumber(scheduler.recent_work_passes_remaining) or 0) - 1
    scheduler.consecutive_empty_passes = 0
    next_tier = "active"
    next_interval = 25
  else
    scheduler.idle_passes_total = (tonumber(scheduler.idle_passes_total) or 0) + 1
    scheduler.consecutive_empty_passes = (tonumber(scheduler.consecutive_empty_passes) or 0) + 1
    if scheduler.consecutive_empty_passes <= 6 then
      next_tier = "short_idle"
      next_interval = 50
    else
      next_tier = "deep_idle"
      next_interval = 100
    end
  end

  if previous_tier ~= next_tier
      or (tonumber(scheduler.current_poll_interval_ms) or 25) ~= next_interval then
    scheduler.backoff_transitions_total = (tonumber(scheduler.backoff_transitions_total) or 0) + 1
  end
  scheduler.poll_tier = next_tier
  scheduler.current_poll_interval_ms = next_interval
  return next_interval
end

function BMF_schedule_socket_worker_poll(delay_ms, generation)
  local delay = tonumber(delay_ms) or state.socket.poll_interval_ms or SOCKET_DEFAULT_POLL_MS
  return BMF_schedule_delayed_callback("socket_worker", delay, function()
    if generation ~= nil and state.socket_worker_generation ~= generation then
      return
    end
    if BMF_poll_socket_messages then
      BMF_poll_socket_messages()
    end
  end)
end

function BMF_poll_socket_messages()
  local tunnel = state.game_command_tunnel
  if not state.socket.started or type(BMFSocketReceive) ~= "function" then
    state.socket_worker_started = false
    state.socket_worker_mode = "stopped"
    tunnel.worker_started = false
    tunnel.worker_mode = "stopped"
    return
  end

  local activating = tunnel.worker_started ~= true
  if activating then
    tunnel.worker_started = true
    tunnel.worker_mode = "SocketEngineTickOneShotChain"
    tunnel.last_worker_error = ""
  end

  local pump_started_clock = os.clock()
  local ingress_count = 0
  local observed_work_count = 0
  local direct_admitted = 0
  local tunnel_dispatched = 0
  local direct_dispatched = 0
  local budget_admission_stopped = false
  local budget_tunnel_dispatch_skipped = false
  local budget_dispatch_skipped = false
  local pump_ok, pump_error = pcall(function()
    local total_drained, drained, admitted, stopped_for_budget = BMF_drain_socket_messages(
      state.telemetry.socket_scheduler.effective_ingress_per_pump,
      pump_started_clock)
    observed_work_count = tonumber(total_drained) or 0
    ingress_count = tonumber(drained) or 0
    direct_admitted = tonumber(admitted) or 0
    budget_admission_stopped = stopped_for_budget == true
    local pending_count = state.socket_admission.enabled == true
      and BMF_socket_scheduler_total_depth()
      or (tonumber(tunnel.queued_count) or 0)
    if pending_count > 0
      and (budget_admission_stopped
        or BMF_socket_scheduler_budget_exhausted_for_admission(pump_started_clock))
    then
      budget_admission_stopped = true
      BMF_operation_note_queued_budget_defer()
      if state.socket_admission.enabled == true then
        budget_dispatch_skipped = true
      else
        budget_tunnel_dispatch_skipped = true
      end
    elseif state.socket_admission.enabled == true then
      local dispatched_path = BMF_socket_scheduler_execute_one()
      if dispatched_path == "tunnel" then
        tunnel_dispatched = 1
      elseif dispatched_path == "direct_socket" then
        direct_dispatched = 1
      end
    elseif type(BMF_game_command_tunnel_pump) == "function" then
      tunnel_dispatched = tonumber(BMF_game_command_tunnel_pump()) or 0
    end
  end)
  BMF_socket_scheduler_record_slice(
    BMF_telemetry_duration_ms(pump_started_clock),
    pump_ok,
    ingress_count,
    direct_admitted,
    tunnel_dispatched,
    direct_dispatched,
    budget_admission_stopped,
    budget_tunnel_dispatch_skipped,
    budget_dispatch_skipped)
  if not pump_ok then
    state.socket_worker_started = false
    state.socket_worker_mode = "failed"
    tunnel.worker_started = false
    tunnel.worker_mode = "failed"
    tunnel.worker_errors = (tonumber(tunnel.worker_errors) or 0) + 1
    tunnel.last_worker_error = tostring(pump_error or "EngineTick socket tunnel pump failed")
    tunnel.last_error = tunnel.last_worker_error
    log("error", "EngineTick socket tunnel pump failed closed: " .. tunnel.last_worker_error)
    if state.socket_admission.enabled == true then
      BMF_socket_scheduler_fail_closed(tunnel.last_worker_error)
    end
    BMF_socket_metadata_heartbeat(true)
    return
  end

  if activating then
    log("info", "socket and tunnel worker active on EngineTick one-shot chain")
    BMF_socket_metadata_heartbeat(true)
  end

  BMF_socket_scheduler_update_idle_backoff(
    observed_work_count > 0
      or direct_admitted > 0
      or tunnel_dispatched > 0
      or direct_dispatched > 0,
    BMF_socket_scheduler_total_depth() > 0)

  if state.socket_worker_started then
    if not BMF_schedule_socket_worker_poll(
        state.telemetry.socket_scheduler.current_poll_interval_ms,
        state.socket_worker_generation)
    then
      state.socket_worker_started = false
      state.socket_worker_mode = "stopped"
      tunnel.worker_started = false
      tunnel.worker_mode = "stopped"
      log("error", "socket worker stopped: no game-thread scheduler available")
    end
  end
end

function BMF_schedule_resource_native_tool_resolve(reason, attempt)
  if not BMF_env_bool("BMF_RESOURCE_NATIVE_RESOLVE_HANDAXE_ON_START", BMF_env_bool("BMF_TREECUT_RESOLVE_HANDAXE_ON_START", true)) then
    return
  end
  local max_attempts = math.max(1, math.min(60, BMF_env_number(
    "BMF_RESOURCE_NATIVE_RESOLVE_HANDAXE_RETRY_ATTEMPTS",
    BMF_env_number("BMF_TREECUT_RESOLVE_HANDAXE_RETRY_ATTEMPTS", 24, 1),
    1)))
  local delay_ms = math.max(250, math.min(30000, BMF_env_number(
    "BMF_RESOURCE_NATIVE_RESOLVE_HANDAXE_RETRY_MS",
    BMF_env_number("BMF_TREECUT_RESOLVE_HANDAXE_RETRY_MS", 2500, 250),
    250)))
  local current_attempt = math.max(1, math.floor(tonumber(attempt) or 1))
  if current_attempt > max_attempts then
    log("warn", "resource native handaxe resolve retry limit reached reason=" .. tostring(reason or "startup"))
    return
  end

  local scheduled = BMF_schedule_delayed_callback("resource_native_tool_resolve", delay_ms, function()
    if not state.socket.started then
      return
    end
    run_on_game_thread(function()
      local resolve_ok, resolve_result = pcall(BMF.tools.treeCutNative.resolveHandaxe, {
        reason = tostring(reason or "startup") .. "-retry-" .. tostring(current_attempt),
      })
      if resolve_ok and resolve_result and resolve_result.ok == true then
        log("info", "resource native handaxe resolved after retry attempt=" .. tostring(current_attempt))
        return
      end

      local detail = resolve_ok and tostring(resolve_result and resolve_result.message or "unknown") or tostring(resolve_result)
      if current_attempt >= max_attempts then
        log("warn", "resource native handaxe resolve retries exhausted: " .. detail)
        return
      end
      BMF_schedule_resource_native_tool_resolve(reason, current_attempt + 1)
    end)
  end)
  if not scheduled then
    log("warn", "resource native handaxe resolve retry was not scheduled")
  end
end

function BMF_start_socket_worker(reason, options)
  options = type(options) == "table" and options or {}
  if not state.socket.started or type(BMFSocketReceive) ~= "function" then
    state.socket_worker_started = false
    state.socket_worker_mode = "stopped"
    return false, "socket transport is not started"
  end

  local generation = (tonumber(state.socket_worker_generation) or 0) + 1
  state.socket_worker_generation = generation
  state.socket_worker_started = true
  state.socket_worker_mode = "starting"
  state.telemetry.socket_scheduler.current_poll_interval_ms = 25
  state.telemetry.socket_scheduler.poll_tier = "active"
  state.telemetry.socket_scheduler.consecutive_empty_passes = 0
  state.telemetry.socket_scheduler.recent_work_passes_remaining = 4
  local force_delayed = options.forceDelayed == true
  local tunnel = state.game_command_tunnel
  local ingress_per_tick = math.max(
    1,
    tonumber(state.telemetry.socket_scheduler.effective_ingress_per_pump) or 2)

  local function start_game_thread_pump(default_enabled)
    tunnel.worker_started = false
    tunnel.worker_mode = "starting"
    tunnel.last_worker_error = ""
    local function game_thread_poll()
      if state.socket_worker_generation ~= generation then
        return true
      end
      if not state.socket_worker_started then
        return true
      end
      if not state.socket.started or type(BMFSocketReceive) ~= "function" then
        state.socket_worker_started = false
        tunnel.worker_started = false
        tunnel.worker_mode = "stopped"
        return true
      end

      local activating = tunnel.worker_started ~= true
      if activating then
        tunnel.worker_started = true
        tunnel.worker_mode = "SocketGameThreadLoop"
        tunnel.last_worker_error = ""
      end
      local pump_started_clock = os.clock()
      local ingress_count = 0
      local direct_admitted = 0
      local tunnel_dispatched = 0
      local direct_dispatched = 0
      local budget_admission_stopped = false
      local budget_tunnel_dispatch_skipped = false
      local budget_dispatch_skipped = false
      local pump_ok, pump_error = pcall(function()
        local _, drained, admitted, stopped_for_budget = BMF_drain_socket_messages(
          ingress_per_tick,
          pump_started_clock)
        ingress_count = tonumber(drained) or 0
        direct_admitted = tonumber(admitted) or 0
        budget_admission_stopped = stopped_for_budget == true
        local pending_count = state.socket_admission.enabled == true
          and BMF_socket_scheduler_total_depth()
          or (tonumber(tunnel.queued_count) or 0)
        if pending_count > 0
          and (budget_admission_stopped
            or BMF_socket_scheduler_budget_exhausted_for_admission(pump_started_clock))
        then
          budget_admission_stopped = true
          if state.socket_admission.enabled == true then
            budget_dispatch_skipped = true
          else
            budget_tunnel_dispatch_skipped = true
          end
        elseif state.socket_admission.enabled == true then
          local dispatched_path = BMF_socket_scheduler_execute_one()
          if dispatched_path == "tunnel" then
            tunnel_dispatched = 1
          elseif dispatched_path == "direct_socket" then
            direct_dispatched = 1
          end
        elseif type(BMF_game_command_tunnel_pump) == "function" then
          tunnel_dispatched = tonumber(BMF_game_command_tunnel_pump()) or 0
        end
      end)
      BMF_socket_scheduler_record_slice(
        BMF_telemetry_duration_ms(pump_started_clock),
        pump_ok,
        ingress_count,
        direct_admitted,
        tunnel_dispatched,
        direct_dispatched,
        budget_admission_stopped,
        budget_tunnel_dispatch_skipped,
        budget_dispatch_skipped)
      if not pump_ok then
        state.socket_worker_started = false
        state.socket_worker_mode = "failed"
        tunnel.worker_started = false
        tunnel.worker_mode = "failed"
        tunnel.worker_errors = (tonumber(tunnel.worker_errors) or 0) + 1
        tunnel.last_worker_error = tostring(pump_error or "persistent tunnel pump failed")
        tunnel.last_error = tunnel.last_worker_error
        log("error", "persistent socket tunnel pump failed closed: " .. tunnel.last_worker_error)
        if state.socket_admission.enabled == true then
          BMF_socket_scheduler_fail_closed(tunnel.last_worker_error)
        else
          BMF_game_command_tunnel_schedule(0)
        end
        BMF_socket_metadata_heartbeat(true)
        return true
      end
      if activating then
        log(
          "info",
          "socket and tunnel worker active on persistent game-thread pump"
            .. " generation=" .. tostring(generation))
        BMF_socket_metadata_heartbeat(true)
      end
      return false
    end

    local loop_started, loop_scheduler = BMF_start_game_thread_loop(
      "socket_worker",
      state.socket.poll_interval_ms,
      game_thread_poll,
      default_enabled)
    if loop_started then
      state.socket_worker_mode = "LoopInGameThread"
      tunnel.worker_mode = "starting"
      log(
        "info",
        "socket and tunnel worker scheduled via one persistent LoopInGameThread"
          .. " reason=" .. tostring(reason or "start")
          .. " generation=" .. tostring(generation)
          .. " scheduler=" .. tostring(loop_scheduler or "unknown")
          .. " ingress_per_tick=" .. tostring(ingress_per_tick))
      BMF_socket_metadata_heartbeat(true)
      return true, "LoopInGameThread"
    end

    tunnel.worker_started = false
    tunnel.worker_mode = "unavailable"
    tunnel.scheduler_failures = (tonumber(tunnel.scheduler_failures) or 0) + 1
    tunnel.last_worker_error = "persistent game-thread loop scheduler unavailable"
    return false, tunnel.last_worker_error
  end

  if not force_delayed then
    local game_thread_started, game_thread_mode = start_game_thread_pump(true)
    if game_thread_started then
      return true, game_thread_mode
    end
  end

  if not force_delayed and not BMF_allow_delayed_worker_fallback() then
    state.socket_worker_started = false
    state.socket_worker_mode = "stopped"
    log("error", "socket worker unavailable: delayed fallback disabled and no loop scheduler available")
    BMF_socket_metadata_heartbeat(true)
    return false, "delayed fallback disabled"
  end

  state.socket_worker_mode = "EngineTickOneShotChain"
  log("warn", "socket worker using delayed poller interval_ms=" .. tostring(state.socket.poll_interval_ms) .. " reason=" .. tostring(reason or "start") .. " generation=" .. tostring(generation))
  if BMF_schedule_socket_worker_poll(
      state.telemetry.socket_scheduler.current_poll_interval_ms,
      generation)
  then
    BMF_socket_metadata_heartbeat(true)
    return true, state.socket_worker_mode
  end

  state.socket_worker_started = false
  state.socket_worker_mode = "stopped"
  log("error", "socket worker unavailable: no delayed scheduler available")
  BMF_socket_metadata_heartbeat(true)
  return false, "no delayed scheduler available"
end

function BMF_restart_socket_worker(reason, options)
  if state.socket_worker_mode == "LoopInGameThread"
      and state.game_command_tunnel.worker_started == true then
    state.socket.last_watchdog_error = "persistent game-thread socket tunnel pump requires a process restart"
    return false, state.socket.last_watchdog_error
  end
  state.socket_worker_started = false
  state.socket_worker_mode = "restarting"
  return BMF_start_socket_worker(reason or "restart", options)
end

function BMF_socket_worker_is_stale()
  if not state.socket.started then
    return false, "socket transport is not started"
  end
  if not state.socket_worker_started then
    return true, "socket worker is stopped"
  end
  local age_ms = BMF_socket_poll_age_ms()
  local stale_ms = tonumber(state.socket.watchdog_stale_ms) or BMF_socket_watchdog_stale_ms()
  if age_ms > stale_ms then
    return true, "socket poll heartbeat stale age_ms=" .. tostring(age_ms) .. " stale_ms=" .. tostring(stale_ms)
  end
  return false, ""
end

function BMF_schedule_socket_worker_watchdog(delay_ms)
  local delay = tonumber(delay_ms) or state.socket.watchdog_interval_ms or BMF_socket_watchdog_interval_ms()
  return BMF_schedule_delayed_callback("socket_worker_watchdog", delay, function()
    if type(BMF_socket_worker_watchdog_poll) == "function" then
      BMF_socket_worker_watchdog_poll()
    end
  end)
end

function BMF_socket_worker_watchdog_poll()
  if not state.socket_worker_watchdog_started then
    state.socket_worker_watchdog_mode = "stopped"
    return
  end

  state.socket.watchdog_checks = (tonumber(state.socket.watchdog_checks) or 0) + 1
  state.socket.last_watchdog_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  state.socket.watchdog_interval_ms = BMF_socket_watchdog_interval_ms()
  state.socket.watchdog_stale_ms = BMF_socket_watchdog_stale_ms()

  local stale, detail = BMF_socket_worker_is_stale()
  if stale then
    state.socket.watchdog_restarts = (tonumber(state.socket.watchdog_restarts) or 0) + 1
    state.socket.watchdog_consecutive_stale = (tonumber(state.socket.watchdog_consecutive_stale) or 0) + 1
    state.socket.last_watchdog_restart_at = state.socket.last_watchdog_at
    state.socket.last_watchdog_error = tostring(detail or "socket worker stale")
    state.socket.last_error = "socket worker watchdog restarting: " .. state.socket.last_watchdog_error
    local force_delayed = state.socket.watchdog_consecutive_stale >= BMF_socket_watchdog_delayed_after_restarts()
    if force_delayed then
      state.socket.watchdog_forced_delayed_recoveries = (tonumber(state.socket.watchdog_forced_delayed_recoveries) or 0) + 1
    end
    log("warn", state.socket.last_error .. " force_delayed=" .. tostring(force_delayed))
    local restarted, mode_or_error = BMF_restart_socket_worker("watchdog", {
      forceDelayed = force_delayed,
    })
    if not restarted then
      state.socket.last_watchdog_error = "restart failed: " .. tostring(mode_or_error or "unknown")
      state.socket.last_error = state.socket.last_watchdog_error
      log("error", "socket worker watchdog restart failed: " .. tostring(mode_or_error or "unknown"))
    end
  else
    state.socket.watchdog_consecutive_stale = 0
    state.socket.last_watchdog_error = ""
  end

  BMF_socket_metadata_heartbeat(false)
  if state.socket_worker_watchdog_started then
    if not BMF_schedule_socket_worker_watchdog(state.socket.watchdog_interval_ms) then
      state.socket_worker_watchdog_started = false
      state.socket_worker_watchdog_mode = "stopped"
      state.socket.last_watchdog_error = "watchdog scheduler unavailable"
      log("error", "socket worker watchdog stopped: scheduler unavailable")
      BMF_socket_metadata_heartbeat(true)
    end
  end
end

function BMF_start_socket_worker_watchdog()
  if state.socket_worker_mode == "LoopInGameThread"
      and state.game_command_tunnel.worker_started == true then
    state.socket_worker_watchdog_started = false
    state.socket_worker_watchdog_mode = "disabled-persistent-pump"
    return false, "persistent game-thread pump is registered once per process"
  end
  if not BMF_socket_watchdog_enabled() then
    state.socket_worker_watchdog_started = false
    state.socket_worker_watchdog_mode = "disabled"
    return false, "disabled"
  end
  if state.socket_worker_watchdog_started then
    return true, state.socket_worker_watchdog_mode
  end
  state.socket.watchdog_interval_ms = BMF_socket_watchdog_interval_ms()
  state.socket.watchdog_stale_ms = BMF_socket_watchdog_stale_ms()
  state.socket_worker_watchdog_started = true
  state.socket_worker_watchdog_mode = "ExecuteInGameThreadAfterFramesChain"
  if BMF_schedule_socket_worker_watchdog(math.min(1000, state.socket.watchdog_interval_ms)) then
    log("info", "socket worker watchdog started interval_ms=" .. tostring(state.socket.watchdog_interval_ms) .. " stale_ms=" .. tostring(state.socket.watchdog_stale_ms))
    BMF_socket_metadata_heartbeat(true)
    return true, state.socket_worker_watchdog_mode
  end

  state.socket_worker_watchdog_started = false
  state.socket_worker_watchdog_mode = "stopped"
  state.socket.last_watchdog_error = "watchdog scheduler unavailable"
  log("warn", "socket worker watchdog could not start: scheduler unavailable")
  BMF_socket_metadata_heartbeat(true)
  return false, state.socket.last_watchdog_error
end

function BMF_start_socket_transport()
  BMF_socket_configure_from_env()
  if not state.socket.enabled then
    return
  end
  if state.socket.started then
    if not state.socket_worker_started then
      BMF_start_socket_worker("socket-start-existing")
    end
    if not state.socket_worker_watchdog_started then
      BMF_start_socket_worker_watchdog()
    end
    return
  end
  if not state.socket.available then
    state.socket.last_error = "BMFSocket native functions are unavailable"
    log("warn", "socket transport disabled: " .. state.socket.last_error)
    return
  end
  if state.socket.port <= 0 then
    state.socket.last_error = "OMEGGA_BMF_SOCKET_PORT is required"
    log("warn", "socket transport disabled: " .. state.socket.last_error)
    return
  end

  local ok, started_or_error, status = pcall(BMFSocketStart, state.socket.host, state.socket.port, state.socket.token)
  if not ok or started_or_error == false then
    state.socket.last_error = tostring(status or started_or_error or "BMFSocketStart failed")
    log("error", "socket transport failed: " .. state.socket.last_error)
    return
  end

  state.socket.started = true
  state.socket.last_error = ""
  state.socket.last_status = tostring(status or "")
  state.socket.last_started_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
  state.socket.last_started_epoch = os.time()
  state.socket.last_poll_epoch = 0
  state.socket.last_poll_at = ""
  BMF_socket_write_metadata()
  log("info", "socket transport started host=" .. tostring(state.socket.host) .. " port=" .. tostring(state.socket.port) .. " poll_ms=" .. tostring(state.socket.poll_interval_ms))
  if BMF_env_bool("BMF_RESOURCE_NATIVE_ENABLED", BMF_env_bool("BMF_TREECUT_NATIVE_ENABLED", true)) then
    local resource_ok, resource_result = pcall(BMF.tools.resourceNative.start, {
      reason = "socket-start",
    })
    if not resource_ok or not resource_result or resource_result.ok ~= true then
      local detail = resource_ok and tostring(resource_result and resource_result.message or "unknown") or tostring(resource_result)
      log("warn", "resource native capture did not start: " .. detail)
    elseif BMF_env_bool("BMF_RESOURCE_NATIVE_RESOLVE_HANDAXE_ON_START", BMF_env_bool("BMF_TREECUT_RESOLVE_HANDAXE_ON_START", true)) then
      local resolve_ok, resolve_result = pcall(BMF.tools.treeCutNative.resolveHandaxe, {
        reason = "socket-start",
      })
      if not resolve_ok or not resolve_result or resolve_result.ok ~= true then
        local detail = resolve_ok and tostring(resolve_result and resolve_result.message or "unknown") or tostring(resolve_result)
        log("warn", "resource native handaxe resolve did not complete: " .. detail)
        BMF_schedule_resource_native_tool_resolve("socket-start", 1)
      else
        log("info", "resource native handaxe resolved at socket start")
      end
    end
  end
  BMF_start_socket_worker("socket-start")
  BMF_start_socket_worker_watchdog()
end

function sorted_loaded_plugin_names()
  local names = {}
  for name in pairs(state.plugins) do
    names[#names + 1] = name
  end
  table.sort(names)
  return names
end

function loaded_plugin_with_tick_count()
  local count = 0
  for name, plugin in pairs(state.plugins) do
    if type(plugin) == "table" and type(plugin.onTick) == "function" and not plugin_watchdog_isolated(name) then
      count = count + 1
    end
  end
  return count
end

function dispatch_server_ready_hooks(data)
  local ready_data = copy_table(data or state.server_ready_data or {})
  for _, name in ipairs(sorted_loaded_plugin_names()) do
    run_plugin_hook(name, state.plugins[name], "onServerReady", ready_data)
  end
end

function ensure_plugin_tick_worker()
  if state.plugin_tick_timer_id ~= nil then
    return
  end
  if loaded_plugin_with_tick_count() == 0 then
    return
  end

  local timer_id = BMF.timers.every(state.plugin_tick_interval_ms, function(id, count)
    if loaded_plugin_with_tick_count() == 0 then
      state.plugin_tick_timer_id = nil
      BMF.timers.cancel(id)
      write_status()
      return
    end

    state.plugin_tick_count = tonumber(count) or (state.plugin_tick_count + 1)
    local tick_data = {
      tick = state.plugin_tick_count,
      intervalMs = state.plugin_tick_interval_ms,
      serverReady = state.server_ready and true or false,
    }
    for _, name in ipairs(sorted_loaded_plugin_names()) do
      run_plugin_hook(name, state.plugins[name], "onTick", tick_data)
    end
  end)

  if timer_id then
    state.plugin_tick_timer_id = timer_id
    log("info", "plugin tick worker started interval_ms=" .. tostring(state.plugin_tick_interval_ms))
    write_status()
  end
end

function mark_server_ready(data)
  state.server_ready = true
  state.server_ready_data = copy_table(data or {})
  BMF.events.emit("serverReady", state.server_ready_data)
  dispatch_server_ready_hooks(state.server_ready_data)
  ensure_player_position_snapshot_worker()
  write_status()
end

function list_plugin_dirs()
  local command = 'dir /b /ad "' .. PLUGINS_DIR:gsub("/", "\\") .. '" 2>nul'
  local handle = io.popen(command)
  if not handle then
    return {}
  end
  local names = {}
  for line in handle:lines() do
    if line and line ~= "" then
      names[#names + 1] = line
    end
  end
  handle:close()
  table.sort(names)
  return names
end

function parse_json_string_field(raw, field)
  if type(raw) ~= "string" then
    return nil
  end
  local pattern = '"' .. field .. '"%s*:%s*"([^"]*)"'
  return raw:match(pattern)
end

function parse_json_string_array_field(raw, field)
  if type(raw) ~= "string" then
    return {}
  end
  local body = raw:match('"' .. field .. '"%s*:%s*%[(.-)%]')
  local values = {}
  if not body then
    return values
  end
  for value in body:gmatch('"([^"]*)"') do
    values[#values + 1] = value
  end
  return values
end

function parse_json_boolean_field(raw, field)
  if type(raw) ~= "string" then
    return nil
  end
  local token = raw:match('"' .. field .. '"%s*:%s*([A-Za-z]+)')
  if not token then
    return nil
  end
  token = token:lower()
  if token == "true" then
    return true
  end
  if token == "false" then
    return false
  end
  return nil
end

function parse_json_number_field(raw, field)
  if type(raw) ~= "string" then
    return nil
  end
  local token = raw:match('"' .. field .. '"%s*:%s*([%-%.%d]+)')
  if not token then
    return nil
  end
  return tonumber(token)
end

function read_framework_config()
  local raw = read_file(CONFIG_PATH) or ""
  local jsonl_logs = parse_json_boolean_field(raw, "jsonlLogs")
  if jsonl_logs == nil then
    jsonl_logs = false
  end
  local watchdog_enabled = parse_json_boolean_field(raw, "pluginWatchdogEnabled")
  if watchdog_enabled == nil then
    watchdog_enabled = true
  end
  local watchdog_max_errors = parse_json_number_field(raw, "pluginWatchdogMaxErrors") or 3
  if watchdog_max_errors < 1 then
    watchdog_max_errors = 1
  end
  return {
    path = CONFIG_PATH,
    allowPluginServerExec = parse_json_boolean_field(raw, "allowPluginServerExec") == true,
    allowPluginServerShutdown = parse_json_boolean_field(raw, "allowPluginServerShutdown") == true,
    jsonlLogs = jsonl_logs,
    pluginWatchdogEnabled = watchdog_enabled,
    pluginWatchdogMaxErrors = math.floor(watchdog_max_errors),
    allowPluginUnsafeGlobals = parse_json_boolean_field(raw, "allowPluginUnsafeGlobals") == true,
    allowUnsafeApplicatorLuaHook = parse_json_boolean_field(raw, "allowUnsafeApplicatorLuaHook") == true,
    allowUnsafeMinigameConsoleCommands = parse_json_boolean_field(raw, "allowUnsafeMinigameConsoleCommands") == true,
    allowUnsafeMinigameObjectSnapshot = parse_json_boolean_field(raw, "allowUnsafeMinigameObjectSnapshot") == true,
    brickadiaSavedDir = parse_json_string_field(raw, "brickadiaSavedDir") or "",
  }
end

function read_plugin_manifest(name)
  local path = PLUGINS_DIR .. "/" .. name .. "/bmf.json"
  local raw = read_file(path)
  if not raw then
    return {
      path = path,
      raw = "",
      capabilities = {},
    }
  end
  return {
    path = path,
    raw = raw,
    name = parse_json_string_field(raw, "name"),
    version = parse_json_string_field(raw, "version"),
    author = parse_json_string_field(raw, "author"),
    description = parse_json_string_field(raw, "description"),
    capabilities = parse_json_string_array_field(raw, "capabilities"),
  }
end

function has_manifest_capability(manifest, capability)
  local capabilities = {}
  if type(manifest) == "table" and type(manifest.capabilities) == "table" then
    capabilities = manifest.capabilities
  end
  for _, item in ipairs(capabilities) do
    if item == capability or item == "*" then
      return true
    end
    if capability == "server.exec" and item == "server.exec.restricted" then
      return true
    end
  end
  return false
end

function plugin_can_access_unsafe_global(plugin_name, manifest, key)
  local global_name = tostring(key or "")
  if not UNSAFE_PLUGIN_GLOBALS[global_name] then
    return true
  end
  if not PLUGIN_SCHEDULER_GLOBALS[global_name]
      and state.config.allowPluginUnsafeGlobals == true
      and has_manifest_capability(manifest, "unsafe.globals") then
    return true
  end

  local denial_key = tostring(plugin_name or "") .. "|" .. global_name
  local now_epoch = os.time()
  local now = os.date("!%Y-%m-%dT%H:%M:%SZ")
  local denial = state.plugin_unsafe_global_denials[denial_key]
  if type(denial) ~= "table" then
    denial = {
      plugin = tostring(plugin_name or ""),
      global = global_name,
      count = 0,
      firstAt = now,
      lastAt = now,
    }
    state.plugin_unsafe_global_denials[denial_key] = denial
    audit_record("plugin.unsafe_global_denied", {
      plugin = denial.plugin,
      global = global_name,
      requiredCapability = "unsafe.globals",
      config = "allowPluginUnsafeGlobals",
    }, {
      source = "plugin",
      plugin = denial.plugin,
      severity = "warn",
      ok = false,
      code = "UNSAFE_GLOBAL_DENIED",
    })
    log("warn", "plugin " .. denial.plugin .. " denied unsafe global " .. global_name)
  end
  denial.count = (tonumber(denial.count) or 0) + 1
  denial.lastAt = now
  if ASYNC_PLUGIN_GLOBALS[global_name] then
    state.telemetry.scheduler.unsafe_async_denied = (tonumber(state.telemetry.scheduler.unsafe_async_denied) or 0) + 1
  end
  local last_status_write = tonumber(state.plugin_unsafe_global_status_last_write_epoch) or 0
  if last_status_write <= 0
      or now_epoch - last_status_write >= PLUGIN_UNSAFE_GLOBAL_STATUS_WRITE_INTERVAL_SECONDS then
    state.plugin_unsafe_global_status_last_write_epoch = now_epoch
    write_status()
  end
  return false
end

function plugin_global_lookup(plugin_name, manifest, key)
  local global_name = tostring(key or "")
  local safe_value = SAFE_PLUGIN_GLOBALS[global_name]
  if safe_value ~= nil then
    return safe_value
  end
  if UNSAFE_PLUGIN_GLOBALS[global_name] then
    if not plugin_can_access_unsafe_global(plugin_name, manifest, global_name) then
      return nil
    end
    return _G[global_name]
  end
  return nil
end

function capability_denied(plugin_name, capability, manifest)
  audit_record("capability.denied", {
    plugin = plugin_name,
    capability = capability,
    declared = copy_table((manifest and manifest.capabilities) or {}),
  }, {
    source = "plugin",
    plugin = plugin_name,
    severity = "warn",
    ok = false,
    code = "CAPABILITY_REQUIRED",
  })
  return result(false, "CAPABILITY_REQUIRED", "Plugin capability is required: " .. tostring(capability), {
    plugin = plugin_name,
    capability = capability,
    declared = copy_table((manifest and manifest.capabilities) or {}),
  })
end

function config_opt_in_denied(plugin_name, option)
  audit_record("config.opt_in_denied", {
    plugin = plugin_name,
    option = option,
    configPath = CONFIG_PATH,
  }, {
    source = "plugin",
    plugin = plugin_name,
    severity = "warn",
    ok = false,
    code = "CONFIG_OPT_IN_REQUIRED",
  })
  return result(false, "CONFIG_OPT_IN_REQUIRED", "BMF config option is required: " .. tostring(option), {
    plugin = plugin_name,
    option = option,
    configPath = CONFIG_PATH,
  })
end

function require_capability(plugin_name, manifest, capability, callback)
  if not has_manifest_capability(manifest, capability) then
    return capability_denied(plugin_name, capability, manifest)
  end
  return callback()
end

function plugin_storage_args(plugin_name, a, b, c)
  if c ~= nil then
    return tostring(a or ""), b, c
  end
  return plugin_name, a, b
end

local function copy_plugin_library(library)
  if type(library) ~= "table" then
    return nil
  end
  local copied = {}
  for key, value in pairs(library) do
    copied[key] = value
  end
  return copied
end

local function create_plugin_os_library()
  return {
    clock = os.clock,
    date = os.date,
    difftime = os.difftime,
    time = os.time,
  }
end

local function create_plugin_io_library(manifest)
  if not has_manifest_capability(manifest, "filesystem.raw") or type(io) ~= "table" then
    return nil
  end
  return {
    open = io.open,
    type = io.type,
  }
end

local function copy_plugin_api_value(value, seen)
  if type(value) ~= "table" then
    return value
  end
  seen = seen or {}
  if seen[value] ~= nil then
    return seen[value]
  end
  local copied = {}
  seen[value] = copied
  for key, child in pairs(value) do
    copied[copy_plugin_api_value(key, seen)] = copy_plugin_api_value(child, seen)
  end
  return copied
end

local function copy_plugin_namespace(namespace)
  if type(namespace) ~= "table" then
    return {}
  end
  return copy_plugin_api_value(namespace, {})
end

