  end

  api.capabilities = {
    has = function(capability)
      return has_manifest_capability(manifest, capability)
    end,
    require = function(capability)
      if has_manifest_capability(manifest, capability) then
        return result(true, "OK", "Capability is declared", {
          plugin = plugin_name,
          capability = capability,
        })
      end
      return capability_denied(plugin_name, capability, manifest)
    end,
    list = function()
      return result(true, "OK", "Capabilities listed", {
        plugin = plugin_name,
        capabilities = copy_table((manifest and manifest.capabilities) or {}),
      })
    end,
  }

  return api
end

function unload_plugin(name, plugin, reason)
  local unload_ok = true
  local unload_error = nil
  if type(plugin) == "table" and type(plugin.onUnload) == "function" then
    local api = plugin.bmf_api or BMF
    local ok, err = pcall(plugin.onUnload, api, reason or "unload")
    if not ok then
      record_plugin_error(name, "onUnload", err, { reason = reason or "unload" }, plugin)
      unload_ok = false
      unload_error = err
    end
  end
  BMF.events.emit("pluginUnloaded", {
    name = name,
    reason = reason or "unload",
  })
  local removed_handlers = remove_event_handlers_for_owner(name)
  local removed_commands = remove_commands_for_owner(name)
  local removed_tool_handlers = remove_tool_handlers_for_owner(name)
  local removed_timers = cancel_timers_for_owner(name)
  audit_record("plugin.unloaded", {
    plugin = name,
    reason = reason or "unload",
    eventHandlersRemoved = removed_handlers,
    commandsRemoved = removed_commands,
    toolHandlersRemoved = removed_tool_handlers,
    timersRemoved = removed_timers,
  }, {
    source = "framework",
    plugin = name,
    severity = unload_ok and "info" or "error",
    ok = unload_ok,
    code = unload_ok and "OK" or "PLUGIN_UNLOAD_FAILED",
  })
  log(
    "info",
    "unloaded plugin " .. name ..
      " event_handlers_removed=" .. tostring(removed_handlers) ..
      " commands_removed=" .. tostring(removed_commands) ..
      " tool_handlers_removed=" .. tostring(removed_tool_handlers) ..
      " timers_removed=" .. tostring(removed_timers)
  )
  return unload_ok, unload_error
end

function load_plugin(name)
  name = tostring(name or "")
  if state.plugins[name] ~= nil then
    return true, state.plugins[name], true
  end
  if state.plugin_loading[name] == true then
    return false, {
      error = "plugin load already in progress",
      code = "PLUGIN_LOAD_IN_PROGRESS",
      plugin = name,
      recorded = true,
    }
  end
  state.plugin_loading[name] = true
  local function finish_load(...)
    state.plugin_loading[name] = nil
    return ...
  end
  local plugin_path = PLUGINS_DIR .. "/" .. name .. "/main.lua"
  local manifest = read_plugin_manifest(name)
  local plugin_api = create_plugin_api(name, manifest)
  state.plugin_watchdog[name] = nil
  plugin_watchdog_state(name)
  local plugin_env = {
    BMF = plugin_api,
    print = print,
    tostring = tostring,
    tonumber = tonumber,
    type = type,
    pairs = pairs,
    ipairs = ipairs,
    pcall = pcall,
    bit32 = copy_plugin_library(bit32),
    coroutine = copy_plugin_library(coroutine),
    io = create_plugin_io_library(manifest),
    math = copy_plugin_library(math),
    os = create_plugin_os_library(),
    string = copy_plugin_library(string),
    table = copy_plugin_library(table),
    utf8 = copy_plugin_library(utf8),
  }
  plugin_env._G = plugin_env
  setmetatable(plugin_env, {
    __index = function(_, key)
      return plugin_global_lookup(name, manifest, key)
    end,
  })

  local chunk, load_error = loadfile(plugin_path, "t", plugin_env)
  if not chunk then
    return finish_load(false, load_error)
  end

  local ok, plugin_or_error = pcall(chunk)
  if not ok then
    remove_event_handlers_for_owner(name)
    remove_commands_for_owner(name)
    remove_tool_handlers_for_owner(name)
    cancel_timers_for_owner(name)
    return finish_load(false, plugin_or_error)
  end

  local plugin = plugin_or_error
  if type(plugin) ~= "table" then
    plugin = plugin_env.Plugin or {}
  end
  plugin.name = plugin.name or manifest.name or name
  plugin.manifest = manifest
  plugin.path = PLUGINS_DIR .. "/" .. name
  plugin.bmf_api = plugin_api

  local load_ok, load_error = run_plugin_hook(name, plugin, "onLoad", {
    reason = "load",
    serverReady = state.server_ready and true or false,
  })
  if not load_ok then
    remove_event_handlers_for_owner(name)
    remove_commands_for_owner(name)
    remove_tool_handlers_for_owner(name)
    cancel_timers_for_owner(name)
    return finish_load(false, {
      error = tostring(load_error),
      hook = "onLoad",
      recorded = true,
    })
  end

  state.plugins[name] = plugin
  audit_record("plugin.loaded", {
    plugin = name,
    version = manifest.version or "",
    capabilities = copy_table(manifest.capabilities or {}),
  }, {
    source = "framework",
    plugin = name,
    severity = "info",
    ok = true,
    code = "OK",
  })
  BMF.events.emit("pluginLoaded", {
    name = name,
    version = manifest.version or "",
  })
  if state.server_ready then
    run_plugin_hook(name, plugin, "onServerReady", state.server_ready_data)
  end

  return finish_load(true, plugin, false)
end

function BMF.unloadPlugins(reason)
  local names = {}
  for name in pairs(state.plugins) do
    names[#names + 1] = name
  end
  table.sort(names)

  local unloaded = 0
  local unload_errors = 0
  for _, name in ipairs(names) do
    local ok = unload_plugin(name, state.plugins[name], reason or "unload")
    if ok then
      unloaded = unloaded + 1
    else
      unload_errors = unload_errors + 1
    end
  end
  state.plugins = {}
  write_status()
  return result(true, "OK", "Plugins unloaded", {
    plugins_unloaded = unloaded,
    unload_errors = unload_errors,
  })
end

function BMF.loadPlugins()
  local loaded_now = 0
  local already_loaded = 0
  for _, name in ipairs(list_plugin_dirs()) do
    local ok, value, skipped = load_plugin(name)
    if ok then
      if skipped then
        already_loaded = already_loaded + 1
      else
        loaded_now = loaded_now + 1
        log("info", "loaded plugin " .. name)
      end
    else
      local error_text = tostring(value)
      if type(value) == "table" then
        error_text = tostring(value.error or value.message or value)
      end
      if type(value) ~= "table" or value.recorded ~= true then
        state.plugin_errors[#state.plugin_errors + 1] = { name = name, error = error_text }
      end
      log("error", "failed to load plugin " .. name .. ": " .. error_text)
    end
  end
  ensure_plugin_tick_worker()
  write_status()
  local health = BMF.health()
  health.data.plugins_loaded_now = loaded_now
  health.data.plugins_already_loaded = already_loaded
  return health
end

_G.BMF = BMF

state.config = read_framework_config()
BMF_player_registry_configure_from_env()
BMF_initial_player_cache, BMF_initial_player_cache_error = load_player_cache({ force = true })
if BMF_initial_player_cache_error ~= "" then
  log("warn", "player registry startup cache load failed: " .. tostring(BMF_initial_player_cache_error))
else
  log(
    "info",
    "player registry initialized cache_first=" .. tostring(state.player_registry.cache_first_enabled == true)
      .. " entries=" .. tostring(state.player_registry.entries or 0)
      .. " generation=" .. tostring(state.player_registry.generation or 0)
      .. " cached=" .. tostring(BMF_initial_player_cache ~= nil))
end
BMF_initial_player_cache = nil
BMF_initial_player_cache_error = nil
register_builtin_commands()
log("info", "BMF loaded version=" .. VERSION)
audit_record("framework.loaded", {
  version = VERSION,
  commandsRegistered = #command_names(),
}, {
  source = "framework",
  severity = "info",
  ok = true,
  code = "OK",
})
local timer_pump_started, timer_pump_mode = BMF_start_timer_pump()
if timer_pump_started then
  log("info", "bounded timer pump started scheduler=" .. tostring(timer_pump_mode or "unknown"))
else
  log("error", "bounded timer pump did not start; plugin timers will fail closed")
end
write_status()
BMF.loadPlugins()
BMF_install_reserved_chat_command_guard()
BMF_start_socket_transport()
start_command_worker()
mark_server_ready({
  version = VERSION,
  pluginsLoaded = plugin_count(),
  commandsRegistered = #command_names(),
})
BMF_telemetry_write(true)

end)()
